-- ═════════════ 135_portal_pitch_note.sql ═════════════
-- 135_portal_pitch_note.sql
-- Portals shaped by role: a pitch note per label, per project.
--
-- A label or A&R contact's portal frames each project as a pack and opens it
-- with the producer's pitch ("two toplines for the summer single, hooks
-- written, open to a feature"). The note belongs to the link, not the
-- project: the same pack is pitched differently to two labels, and the
-- project's own description stays the storefront copy. NULL = no pitch.
-- Read by /api/portal/[token] (lib/artist-portal/audience); the portal works
-- without it when this migration is not applied.

ALTER TABLE public.project_contacts
  ADD COLUMN IF NOT EXISTS pitch_note text;

ALTER TABLE public.project_contacts
  DROP CONSTRAINT IF EXISTS project_contacts_pitch_note_len;
ALTER TABLE public.project_contacts
  ADD CONSTRAINT project_contacts_pitch_note_len CHECK (pitch_note IS NULL OR char_length(pitch_note) <= 2000);

NOTIFY pgrst, 'reload schema';


-- ═════════════ 139_buyer_offer_email_verified.sql ═════════════
-- 139_buyer_offer_email_verified.sql
-- Which offers were made by someone who proved they own the email on them.
--
-- POST /api/store/offer is public (offers must work without an account) and
-- used to trust `buyer_email` from the request body. "My beats" lists every
-- offer stored under a signed-in buyer's address, so anyone could plant an
-- offer — a price, a status, a track title — in another person's account by
-- typing their address. The route now takes the email from the Supabase
-- session when there is one and records it here as verified; an offer from an
-- anonymous caller is stored as before (the producer still gets it and can
-- reply) but unverified, and "My beats" shows verified offers only.
--
-- DEFAULT false on purpose: every offer already stored was made on an
-- unproven address, so none of them is claimed as verified. They stay visible
-- to the producer on /sales and simply stop appearing in a buyer's My beats.
-- Idempotent. Numbered 139 because 136-138 are claimed by the label-os
-- branches (origin/label-os/*), not yet on main.

ALTER TABLE public.buyer_offers
  ADD COLUMN IF NOT EXISTS buyer_email_verified boolean NOT NULL DEFAULT false;

NOTIFY pgrst, 'reload schema';


-- ═════════════ 136_labelos_org_core.sql ═════════════
-- 136_labelos_org_core.sql
-- Label OS (LABEL-03): tenant tables and the SQL authorization helpers.
--
-- LABEL OS — NOT APPLIED. Apply at the final merge of the Label OS branch
-- into main (docs/bstudio-label-os/16-execution-runbook.md). Nothing in the
-- producer app, the store or checkout reads these tables.
--
-- Five new tables (organizations, org_members, org_invitations,
-- user_profiles, activity_events) and two helpers (org_role, has_org_cap).
-- No existing table is touched.
--
-- Tenancy here is `org_id`, not `user_id`: every policy keys on the org
-- through a SECURITY DEFINER membership helper, the pattern of
-- `public.is_producer()` in 119. The helpers run as their owner (postgres,
-- which owns these tables), so a policy on org_members that calls them does
-- not recurse into org_members' own RLS.
--
-- Writes are deliberately narrow. Every app write goes through the service
-- role (LABEL-05 onwards). Through RLS:
--   - nobody inserts an org_members row: joining an org happens ONLY through
--     the service-role invitation-accept route (LABEL-08), never by a user
--     inserting themselves;
--   - members.manage (owner/admin) may change a member's role, functions,
--     scope and per-member overrides, and remove members — but only an owner
--     may touch an owner row, since making or unmaking an owner is the
--     owner-only "ownership transfer" (15-product-decisions, LABEL-02
--     follow-up), and the user/org a membership belongs to can never be
--     rewritten (column-level UPDATE grant);
--   - activity_events is append-only: no UPDATE/DELETE policy or grant.
--
-- Idempotent: CREATE ... IF NOT EXISTS, CREATE OR REPLACE, DROP ... IF EXISTS
-- before CREATE POLICY / CREATE CONSTRAINT TRIGGER.

-- ── organizations ────────────────────────────────────────────────────────
-- The tenant. `kind` decides which roles and functions exist (D1, 06 §2.4b).
-- `settings` holds per-org switches (release gates). `deleted_at` starts the
-- 30-day grace period (D10); a soft-deleted org grants nobody anything.

CREATE TABLE IF NOT EXISTS public.organizations (
  id          uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  name        text NOT NULL CHECK (length(btrim(name)) > 0),
  slug        text NOT NULL UNIQUE CHECK (slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$'),
  kind        text NOT NULL CHECK (kind IN ('artist', 'producer', 'label')),
  settings    jsonb NOT NULL DEFAULT '{}'::jsonb,
  created_by  uuid REFERENCES auth.users(id) ON DELETE SET NULL,
  created_at  timestamptz NOT NULL DEFAULT now(),
  deleted_at  timestamptz
);

-- ── org_members ──────────────────────────────────────────────────────────
-- `functions` are the member's preset bundles (06 §2.2). `cap_grants` /
-- `cap_revokes` are the per-member switches an owner/admin sets on top of
-- them (LABEL-02 follow-up): revoke beats grant, and has_org_cap ignores
-- them for owner/admin. Values the capability model does not know grant
-- nothing, so they are not constrained here (one list to keep in parity,
-- not two).

CREATE TABLE IF NOT EXISTS public.org_members (
  org_id      uuid NOT NULL REFERENCES public.organizations(id) ON DELETE CASCADE,
  user_id     uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  role        text NOT NULL CHECK (role IN ('owner', 'admin', 'member', 'artist')),
  functions   text[] NOT NULL DEFAULT '{}',
  scope       text NOT NULL DEFAULT 'org' CHECK (scope IN ('org', 'artists')),
  cap_grants  text[] NOT NULL DEFAULT '{}',
  cap_revokes text[] NOT NULL DEFAULT '{}',
  invited_by  uuid REFERENCES auth.users(id) ON DELETE SET NULL,
  joined_at   timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (org_id, user_id),
  -- 06 §2.5: role `artist` is always artist-scoped.
  CONSTRAINT org_members_artist_is_scoped CHECK (role <> 'artist' OR scope = 'artists')
);

-- Every membership helper call is a lookup by (user, org).
CREATE INDEX IF NOT EXISTS idx_org_members_user_org
  ON public.org_members (user_id, org_id);

-- ── org_invitations ──────────────────────────────────────────────────────
-- Replaces the dormant `invites` for Label OS. Only the sha-256 of the token
-- is stored. `email` is stored normalised (lib/contacts/email.ts). The
-- create / accept / revoke flow is LABEL-08; external project invites
-- (`project_id`, `project_role`) are LABEL-21.

CREATE TABLE IF NOT EXISTS public.org_invitations (
  id           uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  org_id       uuid NOT NULL REFERENCES public.organizations(id) ON DELETE CASCADE,
  email        text NOT NULL CHECK (email = lower(btrim(email)) AND length(email) > 0),
  role         text NOT NULL CHECK (role IN ('owner', 'admin', 'member', 'artist')),
  functions    text[] NOT NULL DEFAULT '{}',
  artist_ids   uuid[] NOT NULL DEFAULT '{}',
  project_id   uuid REFERENCES public.projects(id) ON DELETE CASCADE,
  project_role text CHECK (project_role IN ('viewer', 'commenter', 'contributor', 'editor')),
  token_hash   text NOT NULL UNIQUE,
  expires_at   timestamptz NOT NULL,
  accepted_at  timestamptz,
  revoked_at   timestamptz,
  invited_by   uuid REFERENCES auth.users(id) ON DELETE SET NULL,
  created_at   timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT org_invitations_project_role_pair
    CHECK ((project_id IS NULL) = (project_role IS NULL))
);

CREATE INDEX IF NOT EXISTS idx_org_invitations_org
  ON public.org_invitations (org_id, created_at DESC);

-- ── user_profiles ────────────────────────────────────────────────────────
-- Neutral display identity for members. creator_profiles stays the
-- storefront row and the producer marker, and is not overloaded further.

CREATE TABLE IF NOT EXISTS public.user_profiles (
  user_id                uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE,
  display_name           text,
  avatar_url             text,
  last_seen_overview_at  timestamptz,
  created_at             timestamptz NOT NULL DEFAULT now(),
  updated_at             timestamptz NOT NULL DEFAULT now()
);

-- ── activity_events ──────────────────────────────────────────────────────
-- Schema only; written by LABEL-05's recordEvent, read by LABEL-08/19.
-- Append-only (05 §6 rule 6). Context keys are denormalised so feeds filter
-- by index without joins; artist/song/release have no FK yet because those
-- tables do not exist (LABEL-10 onwards adds them). `audit` rows are kept
-- for the life of the org, the rest 24 months (D9). `visibility = 'internal'`
-- is business-internal (08 §B4).

CREATE TABLE IF NOT EXISTS public.activity_events (
  id           uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  org_id       uuid NOT NULL REFERENCES public.organizations(id) ON DELETE CASCADE,
  actor_id     uuid REFERENCES auth.users(id) ON DELETE SET NULL,
  verb         text NOT NULL CHECK (verb ~ '^[a-z_]+\.[a-z_]+$'),
  artist_id    uuid,
  project_id   uuid,
  song_id      uuid,
  release_id   uuid,
  subject_type text,
  subject_id   uuid,
  payload      jsonb NOT NULL DEFAULT '{}'::jsonb,
  audit        boolean NOT NULL DEFAULT false,
  visibility   text NOT NULL DEFAULT 'internal' CHECK (visibility IN ('internal', 'artist')),
  created_at   timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS idx_activity_events_org_created
  ON public.activity_events (org_id, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_activity_events_artist_created
  ON public.activity_events (artist_id, created_at DESC)
  WHERE artist_id IS NOT NULL;

-- ── org_role(org) ────────────────────────────────────────────────────────
-- The caller's role in the org, or NULL when not a member (or the org is
-- soft-deleted). Membership test for policies: `org_role(org_id) IS NOT NULL`.

CREATE OR REPLACE FUNCTION public.org_role(p_org uuid)
RETURNS text
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
  SELECT om.role
  FROM public.org_members om
  JOIN public.organizations o ON o.id = om.org_id
  WHERE om.org_id = p_org
    AND om.user_id = auth.uid()
    AND o.deleted_at IS NULL;
$$;

-- ── has_org_cap(org, cap) ────────────────────────────────────────────────
-- Does the caller hold this capability in this org? The SQL twin of
-- capabilitiesFor() in src/lib/labelos/capabilities.ts, which is the source
-- of truth. Every grant is DATA in the constants below, never a branch, and
-- src/lib/labelos/capabilities.sql.test.ts parses them and holds them equal
-- to the TypeScript tables. Change the TypeScript first, then these arrays.
--
-- Pairs are 2-D arrays of [key, value]. Everything fails closed: an unknown
-- capability, kind, role or function grants nothing.
--
-- Algorithm (same order as capabilitiesFor):
--   1. the role must be offered by the org kind;
--   2. granted = role grants (+ each offered function's preset, for roles
--      that use functions) (+ cap_grants, for roles that take overrides);
--   3. revoked = cap_revokes plus everything that transitively implies one;
--   4. granted is closed under IMPLIES;
--   5. the cap must be granted, inside the kind's ceiling, not NEVER_GRANTABLE
--      for the role, and not revoked.

CREATE OR REPLACE FUNCTION public.has_org_cap(p_org uuid, p_cap text)
RETURNS boolean
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = public
AS $fn$
DECLARE
  -- labelos:mapping:start
  all_capabilities constant text[] := ARRAY[
    'catalog.read', 'catalog.write', 'audio.finished', 'audio.working',
    'review.write', 'review.comment', 'rights.read', 'rights.read.own_line',
    'rights.write', 'contracts.read', 'release.write',
    'release.approve.master', 'release.approve.artwork',
    'release.approve.legal', 'release.approve.marketing',
    'release.approve.metadata', 'tasks.write', 'share.external',
    'members.manage', 'org.manage', 'finance.read', 'business.read.internal'
  ];
  org_kinds constant text[] := ARRAY['artist', 'producer', 'label'];
  roles_by_org_kind constant text[] := ARRAY[
    ['artist', 'owner'], ['artist', 'admin'], ['artist', 'member'],
    ['producer', 'owner'], ['producer', 'admin'], ['producer', 'member'],
    ['label', 'owner'], ['label', 'admin'], ['label', 'member'], ['label', 'artist']
  ];
  functions_by_org_kind constant text[] := ARRAY[
    ['artist', 'artist_manager'], ['artist', 'producer'], ['artist', 'engineer'],
    ['artist', 'marketing'], ['artist', 'legal'], ['artist', 'operations'],
    ['producer', 'producer'], ['producer', 'engineer'],
    ['producer', 'artist_manager'], ['producer', 'operations'],
    ['label', 'a_and_r'], ['label', 'project_manager'], ['label', 'marketing'],
    ['label', 'legal'], ['label', 'finance'], ['label', 'artist_manager'],
    ['label', 'producer'], ['label', 'engineer'], ['label', 'operations']
  ];
  -- KIND_CEILING: kinds whose ceiling is every capability. No kind has a
  -- partial ceiling in the MVP; the parity test fails if one appears.
  kinds_with_full_ceiling constant text[] := ARRAY['artist', 'producer', 'label'];
  -- ROLE_GRANTS: roles granted every capability, then the rest as pairs.
  roles_granted_everything constant text[] := ARRAY['owner', 'admin'];
  role_grants constant text[] := ARRAY[
    ['artist', 'catalog.write'], ['artist', 'audio.finished'],
    ['artist', 'audio.working'], ['artist', 'review.comment'],
    ['artist', 'rights.read']
  ];
  roles_using_functions constant text[] := ARRAY['member'];
  roles_taking_overrides constant text[] := ARRAY['member', 'artist'];
  function_presets constant text[] := ARRAY[
    ['a_and_r', 'catalog.write'], ['a_and_r', 'audio.finished'],
    ['a_and_r', 'audio.working'], ['a_and_r', 'review.write'],
    ['a_and_r', 'rights.read'], ['a_and_r', 'release.write'],
    ['a_and_r', 'release.approve.master'], ['a_and_r', 'share.external'],
    ['a_and_r', 'tasks.write'],
    ['project_manager', 'catalog.write'], ['project_manager', 'audio.finished'],
    ['project_manager', 'audio.working'], ['project_manager', 'review.write'],
    ['project_manager', 'rights.read'], ['project_manager', 'release.write'],
    ['project_manager', 'release.approve.metadata'],
    ['project_manager', 'share.external'],
    ['project_manager', 'business.read.internal'],
    ['project_manager', 'tasks.write'],
    ['marketing', 'catalog.read'], ['marketing', 'audio.finished'],
    ['marketing', 'release.approve.artwork'],
    ['marketing', 'release.approve.marketing'],
    ['marketing', 'business.read.internal'], ['marketing', 'tasks.write'],
    ['legal', 'catalog.read'], ['legal', 'audio.finished'],
    ['legal', 'rights.write'], ['legal', 'contracts.read'],
    ['legal', 'release.approve.legal'], ['legal', 'business.read.internal'],
    ['legal', 'tasks.write'],
    ['artist_manager', 'catalog.write'], ['artist_manager', 'audio.finished'],
    ['artist_manager', 'audio.working'], ['artist_manager', 'review.write'],
    ['artist_manager', 'rights.read'], ['artist_manager', 'tasks.write'],
    ['producer', 'catalog.write'], ['producer', 'audio.finished'],
    ['producer', 'audio.working'], ['producer', 'rights.read.own_line'],
    ['producer', 'tasks.write'],
    ['engineer', 'catalog.write'], ['engineer', 'audio.finished'],
    ['engineer', 'audio.working'], ['engineer', 'rights.read.own_line'],
    ['engineer', 'tasks.write']
  ];
  -- IMPLIES: [wider, narrower].
  implies constant text[] := ARRAY[
    ['catalog.write', 'catalog.read'], ['audio.finished', 'catalog.read'],
    ['audio.working', 'catalog.read'], ['review.comment', 'catalog.read'],
    ['rights.read.own_line', 'catalog.read'], ['contracts.read', 'catalog.read'],
    ['release.write', 'catalog.read'], ['release.approve.master', 'catalog.read'],
    ['release.approve.artwork', 'catalog.read'],
    ['release.approve.legal', 'catalog.read'],
    ['release.approve.marketing', 'catalog.read'],
    ['release.approve.metadata', 'catalog.read'], ['tasks.write', 'catalog.read'],
    ['share.external', 'catalog.read'], ['business.read.internal', 'catalog.read'],
    ['rights.write', 'rights.read'], ['rights.read', 'rights.read.own_line'],
    ['review.write', 'review.comment']
  ];
  never_grantable constant text[] := ARRAY[
    ['member', 'members.manage'], ['member', 'org.manage'],
    ['artist', 'members.manage'], ['artist', 'org.manage'],
    ['artist', 'business.read.internal'], ['artist', 'contracts.read']
  ];
  -- labelos:mapping:end

  v_kind      text;
  v_role      text;
  v_functions text[];
  v_grants    text[];
  v_revokes   text[];
  granted     text[] := '{}';
  revoked     text[] := '{}';
  pair        text[];
  preset      text[];
  fn          text;
  ok          boolean;
  grown       boolean;
BEGIN
  IF p_org IS NULL OR p_cap IS NULL OR NOT (p_cap = ANY (all_capabilities)) THEN
    RETURN false;
  END IF;

  SELECT o.kind, om.role, om.functions, om.cap_grants, om.cap_revokes
    INTO v_kind, v_role, v_functions, v_grants, v_revokes
  FROM public.org_members om
  JOIN public.organizations o ON o.id = om.org_id
  WHERE om.org_id = p_org
    AND om.user_id = auth.uid()
    AND o.deleted_at IS NULL;
  IF NOT FOUND OR NOT (v_kind = ANY (org_kinds)) THEN
    RETURN false;
  END IF;

  -- 1. The role must be one the org kind offers.
  ok := false;
  FOREACH pair SLICE 1 IN ARRAY roles_by_org_kind LOOP
    IF pair[1] = v_kind AND pair[2] = v_role THEN ok := true; END IF;
  END LOOP;
  IF NOT ok THEN RETURN false; END IF;

  -- 2. Role grants, function presets, per-member grants.
  IF v_role = ANY (roles_granted_everything) THEN
    granted := all_capabilities;
  ELSE
    FOREACH pair SLICE 1 IN ARRAY role_grants LOOP
      IF pair[1] = v_role THEN granted := granted || pair[2]; END IF;
    END LOOP;
  END IF;

  IF v_role = ANY (roles_using_functions) THEN
    FOREACH fn IN ARRAY coalesce(v_functions, '{}') LOOP
      FOREACH pair SLICE 1 IN ARRAY functions_by_org_kind LOOP
        IF pair[1] = v_kind AND pair[2] = fn THEN
          FOREACH preset SLICE 1 IN ARRAY function_presets LOOP
            IF preset[1] = fn THEN granted := granted || preset[2]; END IF;
          END LOOP;
        END IF;
      END LOOP;
    END LOOP;
  END IF;

  IF v_role = ANY (roles_taking_overrides) THEN
    granted := granted || ARRAY(
      SELECT c FROM unnest(coalesce(v_grants, '{}')) AS c WHERE c = ANY (all_capabilities)
    );
    revoked := ARRAY(
      SELECT c FROM unnest(coalesce(v_revokes, '{}')) AS c WHERE c = ANY (all_capabilities)
    );
    -- 3. Revoking a capability also revokes everything that needs it.
    LOOP
      grown := false;
      FOREACH pair SLICE 1 IN ARRAY implies LOOP
        IF pair[2] = ANY (revoked) AND NOT (pair[1] = ANY (revoked)) THEN
          revoked := revoked || pair[1];
          grown := true;
        END IF;
      END LOOP;
      EXIT WHEN NOT grown;
    END LOOP;
  END IF;

  -- 4. Close the grants under IMPLIES.
  LOOP
    grown := false;
    FOREACH pair SLICE 1 IN ARRAY implies LOOP
      IF pair[1] = ANY (granted) AND NOT (pair[2] = ANY (granted)) THEN
        granted := granted || pair[2];
        grown := true;
      END IF;
    END LOOP;
    EXIT WHEN NOT grown;
  END LOOP;

  -- 5. Granted, inside the ceiling, not a hard limit, not revoked.
  IF NOT (p_cap = ANY (granted)) OR NOT (v_kind = ANY (kinds_with_full_ceiling)) THEN
    RETURN false;
  END IF;
  FOREACH pair SLICE 1 IN ARRAY never_grantable LOOP
    IF pair[1] = v_role AND pair[2] = p_cap THEN RETURN false; END IF;
  END LOOP;
  RETURN NOT (p_cap = ANY (revoked));
END;
$fn$;

ALTER FUNCTION public.org_role(uuid) OWNER TO postgres;
ALTER FUNCTION public.has_org_cap(uuid, text) OWNER TO postgres;
REVOKE ALL ON FUNCTION public.org_role(uuid) FROM PUBLIC;
REVOKE ALL ON FUNCTION public.has_org_cap(uuid, text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.org_role(uuid) TO authenticated, anon;
GRANT EXECUTE ON FUNCTION public.has_org_cap(uuid, text) TO authenticated, anon;

-- ── ≥1 owner per org ─────────────────────────────────────────────────────
-- Deferred to commit, so a service-role ownership transfer can demote the
-- old owner before promoting the new one inside one transaction. (Through
-- RLS the order is forced the other way: once demoted, the old owner may no
-- longer write owner rows.) Skipped when the org itself is gone (deleting an
-- org cascades to its members).

CREATE OR REPLACE FUNCTION public.org_members_keep_an_owner()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  IF OLD.role = 'owner'
     AND EXISTS (SELECT 1 FROM public.organizations WHERE id = OLD.org_id)
     AND NOT EXISTS (
       SELECT 1 FROM public.org_members
       WHERE org_id = OLD.org_id AND role = 'owner'
     ) THEN
    RAISE EXCEPTION 'organization % must keep at least one owner', OLD.org_id
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NULL;
END;
$$;

ALTER FUNCTION public.org_members_keep_an_owner() OWNER TO postgres;
REVOKE ALL ON FUNCTION public.org_members_keep_an_owner() FROM PUBLIC;

DROP TRIGGER IF EXISTS org_members_keep_an_owner ON public.org_members;
CREATE CONSTRAINT TRIGGER org_members_keep_an_owner
  AFTER UPDATE OR DELETE ON public.org_members
  DEFERRABLE INITIALLY DEFERRED
  FOR EACH ROW EXECUTE FUNCTION public.org_members_keep_an_owner();

-- ── RLS ──────────────────────────────────────────────────────────────────

ALTER TABLE public.organizations   ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.org_members     ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.org_invitations ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.user_profiles   ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.activity_events ENABLE ROW LEVEL SECURITY;

-- Members read their orgs. Org writes (create, rename, settings, delete) go
-- through service-role routes; a member-writable row would let anyone with
-- org.manage flip `kind` or `deleted_at` straight through PostgREST.
DROP POLICY IF EXISTS organizations_member_read ON public.organizations;
CREATE POLICY organizations_member_read ON public.organizations
  FOR SELECT
  USING ((SELECT public.org_role(id)) IS NOT NULL);

-- Members read their co-members.
DROP POLICY IF EXISTS org_members_member_read ON public.org_members;
CREATE POLICY org_members_member_read ON public.org_members
  FOR SELECT
  USING ((SELECT public.org_role(org_id)) IS NOT NULL);

-- members.manage changes and removes members. An owner row (before or
-- after the change) needs an owner. There is NO insert policy: see header.
DROP POLICY IF EXISTS org_members_manage_update ON public.org_members;
CREATE POLICY org_members_manage_update ON public.org_members
  FOR UPDATE
  USING (
    (SELECT public.has_org_cap(org_id, 'members.manage'))
    AND (role <> 'owner' OR (SELECT public.org_role(org_id)) = 'owner')
  )
  WITH CHECK (
    (SELECT public.has_org_cap(org_id, 'members.manage'))
    AND (role <> 'owner' OR (SELECT public.org_role(org_id)) = 'owner')
  );

DROP POLICY IF EXISTS org_members_manage_delete ON public.org_members;
CREATE POLICY org_members_manage_delete ON public.org_members
  FOR DELETE
  USING (
    (SELECT public.has_org_cap(org_id, 'members.manage'))
    AND (role <> 'owner' OR (SELECT public.org_role(org_id)) = 'owner')
  );

-- Belt and braces for "no self-join": the table grant is gone too, and an
-- UPDATE may only touch the columns an owner/admin manages — never org_id
-- or user_id, or rewriting user_id would add a person without consent.
REVOKE INSERT ON public.org_members FROM anon, authenticated;
REVOKE UPDATE ON public.org_members FROM anon, authenticated;
GRANT UPDATE (role, functions, scope, cap_grants, cap_revokes)
  ON public.org_members TO authenticated;

-- Invitations are visible to whoever may manage members. Create / revoke /
-- accept are service-role routes (LABEL-08).
DROP POLICY IF EXISTS org_invitations_manage_read ON public.org_invitations;
CREATE POLICY org_invitations_manage_read ON public.org_invitations
  FOR SELECT
  USING ((SELECT public.has_org_cap(org_id, 'members.manage')));

-- A profile is visible to its user and to anyone sharing a live org with
-- them. Writes go through service-role routes.
DROP POLICY IF EXISTS user_profiles_self_or_co_member_read ON public.user_profiles;
CREATE POLICY user_profiles_self_or_co_member_read ON public.user_profiles
  FOR SELECT
  USING (
    user_id = (SELECT auth.uid())
    OR EXISTS (
      SELECT 1 FROM public.org_members them
      WHERE them.user_id = user_profiles.user_id
        AND (SELECT public.org_role(them.org_id)) IS NOT NULL
    )
  );

-- Members who can see the catalogue read its history (08 §B4); business-
-- internal events additionally need business.read.internal. Scope (which
-- artists) narrows this further once LABEL-10 exists. No INSERT, UPDATE or
-- DELETE policy: events are written by the service role and never changed.
DROP POLICY IF EXISTS activity_events_member_read ON public.activity_events;
CREATE POLICY activity_events_member_read ON public.activity_events
  FOR SELECT
  USING (
    (SELECT public.has_org_cap(org_id, 'catalog.read'))
    AND (visibility = 'artist' OR (SELECT public.has_org_cap(org_id, 'business.read.internal')))
  );

REVOKE UPDATE, DELETE ON public.activity_events FROM anon, authenticated;

NOTIFY pgrst, 'reload schema';


-- ═════════════ 137_labelos_producer_org.sql ═════════════
-- 137_labelos_producer_org.sql
-- Label OS (LABEL-07): a personal `producer` org for the existing producer.
--
-- LABEL OS — NOT APPLIED. Apply at the final merge of the Label OS branch
-- into main, after 136 (docs/bstudio-label-os/16-execution-runbook.md).
--
-- Data only (11-migration-strategy.md M2). Every creator_profiles owner — the
-- producer, never a buyer (buyers have no creator_profiles row) — gets one
-- `organizations` row (kind `producer`, name = display_name or "My studio")
-- and an `owner` row in `org_members`. No org_id is written to any existing
-- table: backfilling tracks / projects / contacts is M7, out of scope.
--
-- One function does it, for both callers:
--   - this migration, once per existing creator_profiles row (below);
--   - POST /api/profile, through `ensurePersonalOrg`
--     (src/lib/labelos/personal-org.ts), so a producer created later gets
--     one too.
-- It is idempotent and safe under concurrency: a transaction-scoped advisory
-- lock per user serialises two simultaneous calls, and the second sees the
-- first one's org and creates nothing. "Already has an org" means OWNS or
-- CREATED any producer-kind org (created: an ownership transfer must not
-- trigger a second org; soft-deleted included: an org in its 30-day grace
-- period is not replaced behind the producer's back).
--
-- The function runs as postgres (the owner of 136's tables), so 136's
-- column-level grants and the absence of an org_members INSERT policy do not
-- apply to it. Only service_role may execute it; a signed-in user cannot
-- call it through PostgREST. 136's "≥1 owner" trigger fires on UPDATE and
-- DELETE only, so the inserts here never trip it.
--
-- Idempotent: CREATE OR REPLACE; the backfill skips producers that already
-- own a producer org, so a replay inserts nothing.

-- ── labelos_slugify(text) ───────────────────────────────────────────────
-- Lower-case ASCII words joined by single dashes, at most 40 characters,
-- matching organizations.slug's CHECK. Empty when nothing usable is left
-- (e.g. a name written only in non-Latin script); the caller falls back.

CREATE OR REPLACE FUNCTION public.labelos_slugify(p_text text)
RETURNS text
LANGUAGE sql
IMMUTABLE
SET search_path = public
AS $$
  SELECT btrim(
    left(
      btrim(regexp_replace(lower(coalesce(p_text, '')), '[^a-z0-9]+', '-', 'g'), '-'),
      40
    ),
    '-'
  );
$$;

-- ── labelos_ensure_producer_org(user) ───────────────────────────────────
-- Returns jsonb:
--   {"org_id": "<uuid>", "created": true|false}   the producer's org
--   {"skipped": "not_producer"}                    no creator_profiles row

CREATE OR REPLACE FUNCTION public.labelos_ensure_producer_org(p_user uuid)
RETURNS jsonb
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path = public
AS $fn$
DECLARE
  v_profile_slug text;
  v_display_name text;
  v_org          uuid;
  v_name         text;
  v_base         text;
  v_slug         text;
  v_try          int := 1;
BEGIN
  IF p_user IS NULL THEN
    RETURN jsonb_build_object('skipped', 'not_producer');
  END IF;

  -- Serialise per user. Two concurrent profile saves (or a save racing this
  -- migration) queue here; the second then sees the first one's org below,
  -- since each statement in a READ COMMITTED plpgsql function takes a new
  -- snapshot.
  PERFORM pg_advisory_xact_lock(hashtextextended('labelos.producer_org:' || p_user::text, 0));

  SELECT cp.slug, cp.display_name
    INTO v_profile_slug, v_display_name
  FROM public.creator_profiles cp
  WHERE cp.user_id = p_user;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('skipped', 'not_producer');
  END IF;

  -- Owns a producer org, or created one: a producer who transferred their
  -- org's ownership (136 allows it) must not get a second org on the next
  -- profile save.
  SELECT o.id INTO v_org
  FROM public.organizations o
  WHERE o.kind = 'producer'
    AND (
      o.created_by = p_user
      OR EXISTS (
        SELECT 1 FROM public.org_members om
        WHERE om.org_id = o.id AND om.user_id = p_user AND om.role = 'owner'
      )
    )
  ORDER BY (o.deleted_at IS NULL) DESC, o.created_at, o.id
  LIMIT 1;
  IF FOUND THEN
    RETURN jsonb_build_object('org_id', v_org, 'created', false);
  END IF;

  v_name := coalesce(nullif(btrim(v_display_name), ''), 'My studio');
  v_base := coalesce(
    nullif(public.labelos_slugify(v_profile_slug), ''),
    nullif(public.labelos_slugify(v_display_name), ''),
    'studio'
  );

  -- organizations.slug is unique across every org. Try the base, then
  -- base-2, base-3 …; catching unique_violation also covers another user's
  -- org claiming the same slug between the check and the insert.
  LOOP
    v_slug := CASE WHEN v_try = 1 THEN v_base ELSE v_base || '-' || v_try END;
    IF NOT EXISTS (SELECT 1 FROM public.organizations WHERE slug = v_slug) THEN
      BEGIN
        INSERT INTO public.organizations (name, slug, kind, created_by)
        VALUES (v_name, v_slug, 'producer', p_user)
        RETURNING id INTO v_org;
        EXIT;
      EXCEPTION WHEN unique_violation THEN
        NULL; -- taken meanwhile: next candidate
      END;
    END IF;
    v_try := v_try + 1;
    IF v_try > 1000 THEN
      RAISE EXCEPTION 'no free organization slug for base %', v_base;
    END IF;
  END LOOP;

  INSERT INTO public.org_members (org_id, user_id, role, scope)
  VALUES (v_org, p_user, 'owner', 'org');

  RETURN jsonb_build_object('org_id', v_org, 'created', true);
END;
$fn$;

ALTER FUNCTION public.labelos_slugify(text) OWNER TO postgres;
ALTER FUNCTION public.labelos_ensure_producer_org(uuid) OWNER TO postgres;
REVOKE ALL ON FUNCTION public.labelos_slugify(text) FROM PUBLIC;
REVOKE ALL ON FUNCTION public.labelos_ensure_producer_org(uuid) FROM PUBLIC;
-- Supabase grants EXECUTE on new public functions to anon/authenticated by
-- default privileges; take it back explicitly.
REVOKE ALL ON FUNCTION public.labelos_slugify(text) FROM anon, authenticated;
REVOKE ALL ON FUNCTION public.labelos_ensure_producer_org(uuid) FROM anon, authenticated;
GRANT EXECUTE ON FUNCTION public.labelos_ensure_producer_org(uuid) TO service_role;

-- ── Backfill ─────────────────────────────────────────────────────────────
-- Every existing producer. A replay finds each one's org and inserts nothing.

DO $$
BEGIN
  PERFORM public.labelos_ensure_producer_org(cp.user_id)
  FROM public.creator_profiles cp
  ORDER BY cp.created_at, cp.user_id;
END $$;

NOTIFY pgrst, 'reload schema';


-- ═════════════ 138_labelos_invitation_accept.sql ═════════════
-- 138_labelos_invitation_accept.sql
-- Label OS (LABEL-08): accepting an org invitation.
--
-- LABEL OS — NOT APPLIED. Apply at the final merge of the Label OS branch
-- into main, after 136 and 137 (docs/bstudio-label-os/16-execution-runbook.md).
--
-- One function, no table change. 136 deliberately has no INSERT policy (and
-- no INSERT grant) on org_members: "joining an org happens ONLY through the
-- service-role invitation-accept route". This is that path, kept in SQL so
-- every check and both writes happen in one transaction:
--
--   1. the invitation is looked up by the sha-256 of its token and LOCKED
--      (FOR UPDATE), so two simultaneous accepts serialise;
--   2. the accepting user's email (read from auth.users, never from the
--      caller) must be VERIFIED (`email_confirmed_at`) and equal the invited
--      email, normalised as lib/contacts/email.ts normalises (trim +
--      lower-case). An unverified address proves nothing about who holds
--      the inbox;
--   3. revoked → refused; already accepted → idempotent for a user who is a
--      member, "used" for anyone else; expired → refused; an inviter who no
--      longer holds members.manage in the org (removed, demoted — only owner
--      and admin can hold it, NEVER_GRANTABLE) → refused as withdrawn: an
--      invitation does not outlive the authority that issued it;
--   4. org_members is written (scope `artists` for an artist or anyone
--      limited to named artists, 06 §2.5), the invitation is marked accepted
--      and the `member.joined` audit event is recorded.
--
-- A user who is already a member keeps their membership exactly as it is
-- (an invitation never changes an existing role); the invitation is still
-- consumed. Owner invitations and project invitations (LABEL-21) are not
-- accepted here.
--
-- Answers are jsonb codes the route maps to HTTP (lib/labelos/invitations.ts
-- `interpretAcceptResult`). The invited email is never part of an answer.
--
-- Runs as postgres (owner of 136's tables); only service_role may execute
-- it. Idempotent: CREATE OR REPLACE.

CREATE OR REPLACE FUNCTION public.labelos_accept_invitation(p_token_hash text, p_user uuid)
RETURNS jsonb
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path = public
AS $fn$
DECLARE
  v_email     text;
  v_confirmed timestamptz;
  v_inv       public.org_invitations%ROWTYPE;
  v_rows      int;
BEGIN
  IF p_token_hash IS NULL OR p_token_hash !~ '^[0-9a-f]{64}$' OR p_user IS NULL THEN
    RETURN jsonb_build_object('error', 'not_found');
  END IF;

  SELECT lower(btrim(u.email)), u.email_confirmed_at INTO v_email, v_confirmed
  FROM auth.users u WHERE u.id = p_user;
  IF v_email IS NULL OR v_email = '' THEN
    RETURN jsonb_build_object('error', 'email_mismatch');
  END IF;

  SELECT i.* INTO v_inv
  FROM public.org_invitations i
  JOIN public.organizations o ON o.id = i.org_id
  WHERE i.token_hash = p_token_hash
    AND o.deleted_at IS NULL
  FOR UPDATE OF i;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('error', 'not_found');
  END IF;

  IF v_inv.email <> v_email THEN
    RETURN jsonb_build_object('error', 'email_mismatch');
  END IF;
  IF v_confirmed IS NULL THEN
    RETURN jsonb_build_object('error', 'email_unverified');
  END IF;
  IF v_inv.project_id IS NOT NULL OR v_inv.role = 'owner' THEN
    RETURN jsonb_build_object('error', 'unsupported');
  END IF;
  IF v_inv.revoked_at IS NOT NULL THEN
    RETURN jsonb_build_object('error', 'revoked');
  END IF;
  IF v_inv.accepted_at IS NOT NULL THEN
    IF EXISTS (SELECT 1 FROM public.org_members WHERE org_id = v_inv.org_id AND user_id = p_user) THEN
      RETURN jsonb_build_object('status', 'already_member', 'org_id', v_inv.org_id);
    END IF;
    RETURN jsonb_build_object('error', 'used');
  END IF;
  IF v_inv.expires_at <= now() THEN
    RETURN jsonb_build_object('error', 'expired');
  END IF;
  IF v_inv.invited_by IS NULL OR NOT EXISTS (
    SELECT 1 FROM public.org_members m
    WHERE m.org_id = v_inv.org_id AND m.user_id = v_inv.invited_by AND m.role IN ('owner', 'admin')
  ) THEN
    RETURN jsonb_build_object('error', 'revoked');
  END IF;

  INSERT INTO public.org_members (org_id, user_id, role, functions, scope, invited_by)
  VALUES (
    v_inv.org_id,
    p_user,
    v_inv.role,
    CASE WHEN v_inv.role = 'member' THEN v_inv.functions ELSE '{}'::text[] END,
    CASE WHEN v_inv.role = 'artist' OR cardinality(v_inv.artist_ids) > 0 THEN 'artists' ELSE 'org' END,
    v_inv.invited_by
  )
  ON CONFLICT (org_id, user_id) DO NOTHING;
  GET DIAGNOSTICS v_rows = ROW_COUNT;

  UPDATE public.org_invitations SET accepted_at = now() WHERE id = v_inv.id;

  IF v_rows = 0 THEN
    RETURN jsonb_build_object('status', 'already_member', 'org_id', v_inv.org_id);
  END IF;

  -- 06 §6: membership changes are audit events. Same transaction as the
  -- membership, so one never exists without the other. `artist_ids` holds
  -- roster CONTACT ids (17 R3); the column keeps 136's name.
  INSERT INTO public.activity_events (org_id, actor_id, verb, subject_type, subject_id, payload, audit, visibility)
  VALUES (
    v_inv.org_id,
    p_user,
    'member.joined',
    'member',
    p_user,
    jsonb_build_object(
      'invitation_id', v_inv.id,
      'role', v_inv.role,
      'functions', to_jsonb(CASE WHEN v_inv.role = 'member' THEN v_inv.functions ELSE '{}'::text[] END),
      'contact_ids', to_jsonb(v_inv.artist_ids),
      'invited_by', v_inv.invited_by
    ),
    true,
    'internal'
  );

  RETURN jsonb_build_object('status', 'joined', 'org_id', v_inv.org_id);
END;
$fn$;

ALTER FUNCTION public.labelos_accept_invitation(text, uuid) OWNER TO postgres;
REVOKE ALL ON FUNCTION public.labelos_accept_invitation(text, uuid) FROM PUBLIC;
-- Supabase grants EXECUTE on new public functions to anon/authenticated by
-- default privileges; take it back explicitly (as 137 does).
REVOKE ALL ON FUNCTION public.labelos_accept_invitation(text, uuid) FROM anon, authenticated;
GRANT EXECUTE ON FUNCTION public.labelos_accept_invitation(text, uuid) TO service_role;

NOTIFY pgrst, 'reload schema';


-- ═════════════ 139_labelos_org_contacts.sql ═════════════
-- 139_labelos_org_contacts.sql
-- Label OS (LABEL-10): org-scoped contacts as the artist roster, plus
-- artist scopes for members.
--
-- LABEL OS — NOT APPLIED. Apply at the final merge of the Label OS branch
-- into main, after 136–138 (docs/bstudio-label-os/16-execution-runbook.md).
--
-- 17-reconciliation R3: an artist is a contact in workspace mode, so the
-- roster is an org's contacts — no `artists` table. Q2 (answered yes,
-- 2026-10-02): a label org keeps its OWN contacts directory and sees nothing
-- of the producer's CRM.
--
-- Expand only:
--   - contacts.org_id (nullable FK, indexed). The producer's rows keep
--     org_id IS NULL (M7, org-scoping them, is out of scope);
--   - contacts_org_or_owner: an org contact never has a user_id, so it can
--     never match a producer route's `user_id = <producer>` filter or the
--     producer's owner_only policy. M7 drops this when it backfills;
--   - an org contact's org never changes (scope rows and events point at it);
--   - member_artist_scopes(org_id, user_id, contact_id) + a same-org trigger;
--   - can_see_artist(org, contact), the SQL twin of artistScopeAllows in
--     src/lib/auth/org-access.ts;
--   - ONE additive SELECT policy on contacts, org_member_read.
--   - labelos_accept_invitation (138) also writes the invitation's artist
--     list into member_artist_scopes, in the same transaction; members who
--     joined before this migration are backfilled.
--   - an artist-kind org gets its single roster contact when it is created
--     (D1, R3).
--
-- R-04: contacts' existing policy (owner_only, 097) is NOT touched. Postgres
-- OR-combines permissive policies, so org_member_read must never admit a
-- row the producer or a buyer could not already see: it requires
-- `org_id IS NOT NULL` (producer rows are NULL), membership with
-- catalog.read in THAT org, and the artist scope. Proven as anon /
-- authenticated users in supabase/local/checks/139_labelos_org_contacts.sql
-- and held by src/lib/security/rls-final-state.test.ts.
--
-- Writes stay on the service role (/api/org/[orgId]/contacts): there is no
-- org write policy on contacts and none at all on member_artist_scopes.
--
-- Idempotent: IF NOT EXISTS, CREATE OR REPLACE, DROP ... IF EXISTS first.

-- ── contacts.org_id ─────────────────────────────────────────────────────

ALTER TABLE public.contacts
  ADD COLUMN IF NOT EXISTS org_id uuid REFERENCES public.organizations(id) ON DELETE CASCADE;

CREATE INDEX IF NOT EXISTS idx_contacts_org
  ON public.contacts (org_id)
  WHERE org_id IS NOT NULL;

-- One person once per org directory, matched as lib/contacts/email.ts
-- normalises (the routes store emails normalised). The producer's own
-- uniqueness is 096's (user_id, email); org rows have no user_id.
CREATE UNIQUE INDEX IF NOT EXISTS contacts_org_email_uniq
  ON public.contacts (org_id, email)
  WHERE org_id IS NOT NULL AND email IS NOT NULL;

DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_constraint
    WHERE conname = 'contacts_org_or_owner' AND conrelid = 'public.contacts'::regclass
  ) THEN
    ALTER TABLE public.contacts
      ADD CONSTRAINT contacts_org_or_owner CHECK (org_id IS NULL OR user_id IS NULL);
  END IF;
END $$;

-- An org contact stays in its org. Producer rows (OLD.org_id IS NULL) are
-- not affected by this trigger at all.
CREATE OR REPLACE FUNCTION public.contacts_org_is_fixed()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  IF OLD.org_id IS NOT NULL AND NEW.org_id IS DISTINCT FROM OLD.org_id THEN
    RAISE EXCEPTION 'an organization contact cannot move to another organization'
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;

ALTER FUNCTION public.contacts_org_is_fixed() OWNER TO postgres;
REVOKE ALL ON FUNCTION public.contacts_org_is_fixed() FROM PUBLIC;

DROP TRIGGER IF EXISTS contacts_org_is_fixed ON public.contacts;
CREATE TRIGGER contacts_org_is_fixed
  BEFORE UPDATE OF org_id ON public.contacts
  FOR EACH ROW EXECUTE FUNCTION public.contacts_org_is_fixed();

-- ── member_artist_scopes ────────────────────────────────────────────────
-- 06 §2.5: a member with scope `artists` (always, for role `artist`) sees
-- only the roster contacts listed here. A row goes when the membership or
-- the contact does. An artists-scoped member with no rows sees nothing.
--
-- No FK of its own to organizations: the composite FK to org_members
-- already ties the row to its org (and cascades when the org goes, through
-- org_members). A second FK would make this table a junction between
-- org_members and organizations in PostgREST's eyes, and every
-- `org_members → organizations!inner(…)` embed (org-access readMembership)
-- would fail as ambiguous. 139's local check asserts it stays that way.

CREATE TABLE IF NOT EXISTS public.member_artist_scopes (
  org_id     uuid NOT NULL,
  user_id    uuid NOT NULL,
  contact_id uuid NOT NULL REFERENCES public.contacts(id) ON DELETE CASCADE,
  created_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (org_id, user_id, contact_id),
  FOREIGN KEY (org_id, user_id) REFERENCES public.org_members (org_id, user_id) ON DELETE CASCADE
);

CREATE INDEX IF NOT EXISTS idx_member_artist_scopes_contact
  ON public.member_artist_scopes (contact_id);

-- Same org: the contact must be in the org the scope row names. Refuses a
-- producer contact (org_id IS NULL) and another org's contact alike.
CREATE OR REPLACE FUNCTION public.member_artist_scopes_same_org()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM public.contacts c
    WHERE c.id = NEW.contact_id AND c.org_id = NEW.org_id
  ) THEN
    RAISE EXCEPTION 'artist scope contact % is not a contact of organization %', NEW.contact_id, NEW.org_id
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;

ALTER FUNCTION public.member_artist_scopes_same_org() OWNER TO postgres;
REVOKE ALL ON FUNCTION public.member_artist_scopes_same_org() FROM PUBLIC;

DROP TRIGGER IF EXISTS member_artist_scopes_same_org ON public.member_artist_scopes;
CREATE TRIGGER member_artist_scopes_same_org
  BEFORE INSERT OR UPDATE ON public.member_artist_scopes
  FOR EACH ROW EXECUTE FUNCTION public.member_artist_scopes_same_org();

-- ── can_see_artist(org, contact) ────────────────────────────────────────
-- Is this roster contact inside the caller's artist scope in this org?
-- False for a non-member, a soft-deleted org, a contact of another org or
-- a producer contact. A member with scope `org` (never role `artist`, which
-- is always scoped) sees every contact of the org; anyone else only those
-- in member_artist_scopes. Capabilities are has_org_cap's job, not this.
-- SECURITY DEFINER as postgres, so the contacts lookup inside contacts'
-- own policy does not recurse into contacts' RLS.

CREATE OR REPLACE FUNCTION public.can_see_artist(p_org uuid, p_contact uuid)
RETURNS boolean
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
  SELECT EXISTS (
    SELECT 1
    FROM public.org_members om
    JOIN public.organizations o ON o.id = om.org_id
    JOIN public.contacts c ON c.id = p_contact AND c.org_id = om.org_id
    WHERE om.org_id = p_org
      AND om.user_id = auth.uid()
      AND o.deleted_at IS NULL
      AND (
        (om.scope = 'org' AND om.role <> 'artist')
        OR EXISTS (
          SELECT 1 FROM public.member_artist_scopes s
          WHERE s.org_id = om.org_id
            AND s.user_id = om.user_id
            AND s.contact_id = p_contact
        )
      )
  );
$$;

ALTER FUNCTION public.can_see_artist(uuid, uuid) OWNER TO postgres;
REVOKE ALL ON FUNCTION public.can_see_artist(uuid, uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.can_see_artist(uuid, uuid) TO authenticated, anon;

-- ── RLS ──────────────────────────────────────────────────────────────────

ALTER TABLE public.member_artist_scopes ENABLE ROW LEVEL SECURITY;

-- A member reads their own scope; whoever manages members reads everyone's.
DROP POLICY IF EXISTS member_artist_scopes_read ON public.member_artist_scopes;
CREATE POLICY member_artist_scopes_read ON public.member_artist_scopes
  FOR SELECT
  TO authenticated
  USING (
    (SELECT public.has_org_cap(org_id, 'members.manage'))
    OR (user_id = (SELECT auth.uid()) AND (SELECT public.org_role(org_id)) IS NOT NULL)
  );

-- Scope is changed only by the service-role members route (members.manage)
-- and the accept function. A member who could write here could widen
-- their own scope.
REVOKE INSERT, UPDATE, DELETE ON public.member_artist_scopes FROM anon, authenticated;

-- The additive contacts policy. owner_only (097) is untouched; producer
-- rows are org_id IS NULL and so never match this one.
DROP POLICY IF EXISTS org_member_read ON public.contacts;
CREATE POLICY org_member_read ON public.contacts
  FOR SELECT
  TO authenticated
  USING (
    org_id IS NOT NULL
    AND (SELECT public.has_org_cap(org_id, 'catalog.read'))
    AND (SELECT public.can_see_artist(org_id, id))
  );

-- ── labelos_accept_invitation (138, extended) ───────────────────────────
-- Identical to 138 except step 4: a membership limited to named artists
-- now gets one member_artist_scopes row per invitation contact that is
-- still a contact of the org (a contact deleted since the invitation is
-- skipped, never an error), in the same transaction as the membership. The
-- audit event's contact_ids are the rows actually written.

CREATE OR REPLACE FUNCTION public.labelos_accept_invitation(p_token_hash text, p_user uuid)
RETURNS jsonb
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path = public
AS $fn$
DECLARE
  v_email     text;
  v_confirmed timestamptz;
  v_inv       public.org_invitations%ROWTYPE;
  v_rows      int;
  v_scope     text;
  v_scoped    uuid[] := '{}';
BEGIN
  IF p_token_hash IS NULL OR p_token_hash !~ '^[0-9a-f]{64}$' OR p_user IS NULL THEN
    RETURN jsonb_build_object('error', 'not_found');
  END IF;

  SELECT lower(btrim(u.email)), u.email_confirmed_at INTO v_email, v_confirmed
  FROM auth.users u WHERE u.id = p_user;
  IF v_email IS NULL OR v_email = '' THEN
    RETURN jsonb_build_object('error', 'email_mismatch');
  END IF;

  SELECT i.* INTO v_inv
  FROM public.org_invitations i
  JOIN public.organizations o ON o.id = i.org_id
  WHERE i.token_hash = p_token_hash
    AND o.deleted_at IS NULL
  FOR UPDATE OF i;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('error', 'not_found');
  END IF;

  IF v_inv.email <> v_email THEN
    RETURN jsonb_build_object('error', 'email_mismatch');
  END IF;
  IF v_confirmed IS NULL THEN
    RETURN jsonb_build_object('error', 'email_unverified');
  END IF;
  IF v_inv.project_id IS NOT NULL OR v_inv.role = 'owner' THEN
    RETURN jsonb_build_object('error', 'unsupported');
  END IF;
  IF v_inv.revoked_at IS NOT NULL THEN
    RETURN jsonb_build_object('error', 'revoked');
  END IF;
  IF v_inv.accepted_at IS NOT NULL THEN
    IF EXISTS (SELECT 1 FROM public.org_members WHERE org_id = v_inv.org_id AND user_id = p_user) THEN
      RETURN jsonb_build_object('status', 'already_member', 'org_id', v_inv.org_id);
    END IF;
    RETURN jsonb_build_object('error', 'used');
  END IF;
  IF v_inv.expires_at <= now() THEN
    RETURN jsonb_build_object('error', 'expired');
  END IF;
  IF v_inv.invited_by IS NULL OR NOT EXISTS (
    SELECT 1 FROM public.org_members m
    WHERE m.org_id = v_inv.org_id AND m.user_id = v_inv.invited_by AND m.role IN ('owner', 'admin')
  ) THEN
    RETURN jsonb_build_object('error', 'revoked');
  END IF;

  v_scope := CASE WHEN v_inv.role = 'artist' OR cardinality(v_inv.artist_ids) > 0 THEN 'artists' ELSE 'org' END;

  INSERT INTO public.org_members (org_id, user_id, role, functions, scope, invited_by)
  VALUES (
    v_inv.org_id,
    p_user,
    v_inv.role,
    CASE WHEN v_inv.role = 'member' THEN v_inv.functions ELSE '{}'::text[] END,
    v_scope,
    v_inv.invited_by
  )
  ON CONFLICT (org_id, user_id) DO NOTHING;
  GET DIAGNOSTICS v_rows = ROW_COUNT;

  UPDATE public.org_invitations SET accepted_at = now() WHERE id = v_inv.id;

  IF v_rows = 0 THEN
    RETURN jsonb_build_object('status', 'already_member', 'org_id', v_inv.org_id);
  END IF;

  -- LABEL-10: the artist list becomes the member's scope. `artist_ids` holds
  -- roster CONTACT ids (17 R3); the column keeps 136's name. Only contacts
  -- still in this org; the same-org trigger would refuse anything else.
  IF v_scope = 'artists' AND cardinality(v_inv.artist_ids) > 0 THEN
    WITH written AS (
      INSERT INTO public.member_artist_scopes (org_id, user_id, contact_id)
      SELECT v_inv.org_id, p_user, c.id
      FROM public.contacts c
      WHERE c.id = ANY (v_inv.artist_ids)
        AND c.org_id = v_inv.org_id
      ON CONFLICT DO NOTHING
      RETURNING contact_id
    )
    SELECT coalesce(array_agg(contact_id ORDER BY contact_id), '{}') INTO v_scoped FROM written;
  END IF;

  -- 06 §6: membership changes are audit events. Same transaction as the
  -- membership, so one never exists without the other.
  INSERT INTO public.activity_events (org_id, actor_id, verb, subject_type, subject_id, payload, audit, visibility)
  VALUES (
    v_inv.org_id,
    p_user,
    'member.joined',
    'member',
    p_user,
    jsonb_build_object(
      'invitation_id', v_inv.id,
      'role', v_inv.role,
      'functions', to_jsonb(CASE WHEN v_inv.role = 'member' THEN v_inv.functions ELSE '{}'::text[] END),
      'contact_ids', to_jsonb(v_scoped),
      'invited_by', v_inv.invited_by
    ),
    true,
    'internal'
  );

  RETURN jsonb_build_object('status', 'joined', 'org_id', v_inv.org_id);
END;
$fn$;

ALTER FUNCTION public.labelos_accept_invitation(text, uuid) OWNER TO postgres;
REVOKE ALL ON FUNCTION public.labelos_accept_invitation(text, uuid) FROM PUBLIC;
REVOKE ALL ON FUNCTION public.labelos_accept_invitation(text, uuid) FROM anon, authenticated;
GRANT EXECUTE ON FUNCTION public.labelos_accept_invitation(text, uuid) TO service_role;

-- ── Backfill (LABEL-08 carried note) ────────────────────────────────────
-- Members who accepted an artist-limited invitation before this migration:
-- their member.joined event names the invitation, whose artist_ids become
-- scope rows — only contacts of that org, only for memberships that are
-- still artist-scoped. contacts.org_id is new in this file, so on a first
-- apply no contact qualifies yet; the statement is here so the rule is
-- written once and a replay stays a no-op (ON CONFLICT DO NOTHING).

INSERT INTO public.member_artist_scopes (org_id, user_id, contact_id)
SELECT DISTINCT m.org_id, m.user_id, c.id
FROM public.activity_events e
JOIN public.org_invitations i
  ON i.org_id = e.org_id
 AND i.id::text = e.payload ->> 'invitation_id'
JOIN public.org_members m
  ON m.org_id = e.org_id
 AND m.user_id = e.subject_id
 AND m.scope = 'artists'
JOIN public.contacts c
  ON c.id = ANY (i.artist_ids)
 AND c.org_id = e.org_id
WHERE e.verb = 'member.joined'
  AND e.subject_type = 'member'
ON CONFLICT DO NOTHING;

-- ── Artist orgs: one roster contact, created with the org (D1, R3) ──────
-- An artist org's roster is the artist themselves. The contact is named
-- after the org (the org IS the artist) and carries the creator's email.
-- No user_id: it is an org contact (contacts_org_or_owner).

CREATE OR REPLACE FUNCTION public.labelos_artist_org_self_contact()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_email text;
BEGIN
  IF NEW.kind <> 'artist' THEN
    RETURN NULL;
  END IF;
  IF EXISTS (SELECT 1 FROM public.contacts WHERE org_id = NEW.id) THEN
    RETURN NULL;
  END IF;
  SELECT nullif(lower(btrim(u.email)), '') INTO v_email
  FROM auth.users u WHERE u.id = NEW.created_by;
  INSERT INTO public.contacts (org_id, user_id, name, email, category)
  VALUES (NEW.id, NULL, NEW.name, v_email, 'artist');
  RETURN NULL;
END;
$$;

ALTER FUNCTION public.labelos_artist_org_self_contact() OWNER TO postgres;
REVOKE ALL ON FUNCTION public.labelos_artist_org_self_contact() FROM PUBLIC;

DROP TRIGGER IF EXISTS labelos_artist_org_self_contact ON public.organizations;
CREATE TRIGGER labelos_artist_org_self_contact
  AFTER INSERT ON public.organizations
  FOR EACH ROW EXECUTE FUNCTION public.labelos_artist_org_self_contact();

-- Artist orgs created before this migration (none are created by any route
-- yet; this keeps the rule true for any made by hand).
INSERT INTO public.contacts (org_id, user_id, name, email, category)
SELECT o.id, NULL, o.name, nullif(lower(btrim(u.email)), ''), 'artist'
FROM public.organizations o
LEFT JOIN auth.users u ON u.id = o.created_by
WHERE o.kind = 'artist'
  AND NOT EXISTS (SELECT 1 FROM public.contacts c WHERE c.org_id = o.id);

NOTIFY pgrst, 'reload schema';


-- ═════════════ 140_labelos_song_fields.sql ═════════════
-- 140_labelos_song_fields.sql (LABEL-11)
-- Songs on tracks (17 R1): a Label OS song is a `tracks` row with
-- type = 'song'. No songs / song_recordings / project_songs tables.
--
-- 1. tracks.song_stage — the A&R stage (04 W3). Nullable, NO default: the app
--    sets 'inbox' on org songs only (lib/labelos/song-stage#initialSongStage),
--    so every existing row and every producer song stays NULL and reads as
--    before. 'released' is derived from releases, never stored. The value
--    list is held equal to SONG_STAGES by song-stage.test.ts.
-- 2. tracks.iswc — the song's musical-work code. Nullable; the CHECK is the
--    05 §7 format (validation/normalisation helpers arrive with LABEL-16).
-- 3. track_links.relation gains 'master' and 'demo' (a song's mastered file
--    and its early idea). Additive: every existing row satisfies the wider
--    check. The producer's link route still accepts only its original
--    relations (TrackLinkBodySchema), so nothing producer-facing can write
--    the new two.
--
-- tracks RLS is untouched (that is LABEL-12); no member gains a read path.
-- Written without DO blocks so it pastes safely into the Supabase SQL editor:
-- each constraint is dropped-if-present and re-added, so a replay leaves
-- exactly one of each (supabase/local/checks/140_labelos_song_fields.sql).

ALTER TABLE public.tracks ADD COLUMN IF NOT EXISTS song_stage text;
ALTER TABLE public.tracks ADD COLUMN IF NOT EXISTS iswc text;

ALTER TABLE public.tracks DROP CONSTRAINT IF EXISTS tracks_song_stage_check;
ALTER TABLE public.tracks ADD CONSTRAINT tracks_song_stage_check
  CHECK (song_stage IS NULL OR song_stage IN ('inbox', 'in_review', 'shortlisted', 'in_development', 'selected', 'on_hold', 'passed', 'archived'));

ALTER TABLE public.tracks DROP CONSTRAINT IF EXISTS tracks_iswc_format;
ALTER TABLE public.tracks ADD CONSTRAINT tracks_iswc_format
  CHECK (iswc IS NULL OR iswc ~ '^T-?[0-9]{3}\.?[0-9]{3}\.?[0-9]{3}-?[0-9]$');

ALTER TABLE public.track_links DROP CONSTRAINT IF EXISTS track_links_relation_check;
ALTER TABLE public.track_links ADD CONSTRAINT track_links_relation_check
  CHECK (relation IN ('instrumental', 'loop', 'topline', 'version', 'master', 'demo'));

NOTIFY pgrst, 'reload schema';


-- ═════════════ 141_labelos_org_catalog.sql ═════════════
-- 141_labelos_org_catalog.sql
-- Label OS (LABEL-12): org songs, projects and their #44 material in the
-- existing tables, readable by members (17 R1, R11).
--
-- LABEL OS — NOT APPLIED. Apply at the final merge of the Label OS branch
-- into main, after 140 (docs/bstudio-label-os/16-execution-runbook.md).
--
-- Expand only. No backfill: every existing row keeps org_id IS NULL (M7 is
-- out of scope), so no producer route, the store or the portal changes.
--
--   1. Columns: tracks.org_id / created_by / isrc, projects.org_id and
--      projects.inbox_for_contact_id (the artist an Inbox project belongs to,
--      Q1 — one per artist, unique). Indexed (org_id, created_at DESC). A
--      row's org is fixed once written: a producer row is never moved into an
--      org (D6 copies, M7 is its own plan), an org row never leaves.
--   2. Read helpers (SECURITY DEFINER, as postgres):
--        can_see_org_project(org, project) — artist scope of a project: the
--          whole org (scope `org`, never role `artist`), or its inbox artist /
--          any project_contacts contact passes can_see_artist (139).
--        can_see_org_track(org, track) — the whole org, or a project OF THE
--          SAME ORG the track is in (project_tracks) is in scope.
--        can_read_org_track(org, track) — catalog.read + can_see_org_track +
--          the audio class (D4): working material needs audio.working,
--          finished material audio.finished (or working).
--      The class is the NARROWER row rule in src/lib/labelos/org-read.ts
--      (`labelos_track_is_finished`): finished only for a selected song's own
--      audio or a song's master / instrumental, and only when nothing links
--      to the track as working material. Everything else reads as working.
--      The routes keep the finer per-recording split (LABEL-13/16).
--   3. ONE additive SELECT policy `org_member_read` per table, TO
--      authenticated, on tracks, projects and the #44 tables project_contacts,
--      artist_portals, project_assets, song_beats, track_links,
--      artist_messages, contact_track_states and project_comments. Each
--      requires `org_id IS NOT NULL` on its row or, inside EXISTS, on its
--      parent's. No write policy: org writes go through the service role in
--      /api/org/*. No existing policy is altered or dropped (R-04).
--      Narrowed beyond "parent readable" where the row itself carries more:
--        artist_portals  — the token is a bearer credential to the portal's
--                          working audio: + share.external + audio.working;
--        project_assets  — only artwork / lyrics without audio.working
--                          (sensitivity and business kinds are LABEL-15);
--        project_comments — a comment naming a share token needs
--                          share.external; its track and portal artist must
--                          be readable too.
--   3b. A RESTRICTIVE SELECT guard `org_member_guard` on tracks, projects and
--      the seven #44 tables keyed on their own user_id: a producer row passes
--      untouched, an org row only with the org_member_read predicate. Org
--      rows still carry a user_id (NOT NULL columns; the routes write the
--      acting member), and the producer-era owner policies would otherwise
--      keep that member reading it after leaving the org, after a soft
--      delete, or outside their scope / audio class. Still SELECT only.
--      The same guard (an org row is hidden, project_comments keeps its
--      predicate) sits on every table whose producer policy keys through a
--      track's / project's user_id: project_comments, project_tracks,
--      project_shares, track_versions, track_collaborators, track_licenses,
--      play_head_pings, store_free_downloads, project_tags,
--      project_folder_items, project_access_links.
--   3c. Org rows are written by the service role only: a BEFORE INSERT /
--      UPDATE / DELETE trigger refuses an org row to the API roles
--      (authenticated, anon) on tracks, projects and every table above that
--      the producer can write through RLS. Producer rows are unaffected.
--   4. The #44 same-owner triggers also accept same-ORG rows. The owner case
--      is the same check as before, and now also requires every parent to be
--      a producer row (org_id IS NULL), so it can never join an org row to a
--      producer row. The org case: every parent is in the same non-null org.
--      "Different owner, no org" is refused exactly as before
--      (supabase/local/checks/141_labelos_org_catalog.sql).
--
-- Proven as anon / authenticated users in
-- supabase/local/checks/141_labelos_org_catalog.sql and held by
-- src/lib/security/rls-final-state.test.ts.
--
-- Idempotent: IF NOT EXISTS, CREATE OR REPLACE, DROP ... IF EXISTS first.

-- ── 1. Columns ──────────────────────────────────────────────────────────

ALTER TABLE public.tracks
  ADD COLUMN IF NOT EXISTS org_id uuid REFERENCES public.organizations(id) ON DELETE CASCADE;
ALTER TABLE public.tracks
  ADD COLUMN IF NOT EXISTS created_by uuid REFERENCES auth.users(id) ON DELETE SET NULL;
ALTER TABLE public.tracks ADD COLUMN IF NOT EXISTS isrc text;

-- 05 §7: CC-XXX-YY-NNNNN, hyphens optional. Normalisation is LABEL-16's.
ALTER TABLE public.tracks DROP CONSTRAINT IF EXISTS tracks_isrc_format;
ALTER TABLE public.tracks ADD CONSTRAINT tracks_isrc_format
  CHECK (isrc IS NULL OR isrc ~ '^[A-Z]{2}-?[A-Z0-9]{3}-?[0-9]{2}-?[0-9]{5}$');

ALTER TABLE public.projects
  ADD COLUMN IF NOT EXISTS org_id uuid REFERENCES public.organizations(id) ON DELETE CASCADE;
ALTER TABLE public.projects
  ADD COLUMN IF NOT EXISTS inbox_for_contact_id uuid REFERENCES public.contacts(id) ON DELETE SET NULL;

CREATE INDEX IF NOT EXISTS idx_tracks_org_created
  ON public.tracks (org_id, created_at DESC)
  WHERE org_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_projects_org_created
  ON public.projects (org_id, created_at DESC)
  WHERE org_id IS NOT NULL;

-- One Inbox per artist (Q1). A contact belongs to one org, so the contact
-- alone is the key; ensureInboxProject (LABEL-14) relies on the conflict.
CREATE UNIQUE INDEX IF NOT EXISTS projects_inbox_for_contact_uniq
  ON public.projects (inbox_for_contact_id)
  WHERE inbox_for_contact_id IS NOT NULL;

-- The row's org never changes after insert (both directions).
CREATE OR REPLACE FUNCTION public.labelos_org_is_fixed()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  IF NEW.org_id IS DISTINCT FROM OLD.org_id THEN
    RAISE EXCEPTION '%: a row''s organization cannot change', TG_TABLE_NAME
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;

ALTER FUNCTION public.labelos_org_is_fixed() OWNER TO postgres;
REVOKE ALL ON FUNCTION public.labelos_org_is_fixed() FROM PUBLIC;

DROP TRIGGER IF EXISTS tracks_org_is_fixed ON public.tracks;
CREATE TRIGGER tracks_org_is_fixed
  BEFORE UPDATE OF org_id ON public.tracks
  FOR EACH ROW EXECUTE FUNCTION public.labelos_org_is_fixed();

DROP TRIGGER IF EXISTS projects_org_is_fixed ON public.projects;
CREATE TRIGGER projects_org_is_fixed
  BEFORE UPDATE OF org_id ON public.projects
  FOR EACH ROW EXECUTE FUNCTION public.labelos_org_is_fixed();

-- An Inbox is an org project, for a contact of that org.
CREATE OR REPLACE FUNCTION public.projects_inbox_same_org()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  IF NEW.inbox_for_contact_id IS NOT NULL AND (
    NEW.org_id IS NULL
    OR NOT EXISTS (SELECT 1 FROM public.contacts c WHERE c.id = NEW.inbox_for_contact_id AND c.org_id = NEW.org_id)
  ) THEN
    RAISE EXCEPTION 'projects: inbox contact % is not a contact of the project''s organization', NEW.inbox_for_contact_id
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;

ALTER FUNCTION public.projects_inbox_same_org() OWNER TO postgres;
REVOKE ALL ON FUNCTION public.projects_inbox_same_org() FROM PUBLIC;

DROP TRIGGER IF EXISTS projects_inbox_same_org ON public.projects;
CREATE TRIGGER projects_inbox_same_org
  BEFORE INSERT OR UPDATE OF inbox_for_contact_id, org_id ON public.projects
  FOR EACH ROW EXECUTE FUNCTION public.projects_inbox_same_org();

-- ── 2. Read helpers ─────────────────────────────────────────────────────
-- SECURITY DEFINER as postgres, so the lookups inside a policy do not
-- recurse into the same tables' RLS. auth.uid() is still the caller.

-- Does the caller see the whole org? (06 §2.5; role artist is always scoped.)
-- Internal: no grant; only the helpers below call it.
CREATE OR REPLACE FUNCTION public.labelos_sees_whole_org(p_org uuid)
RETURNS boolean
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
  SELECT EXISTS (
    SELECT 1
    FROM public.org_members om
    JOIN public.organizations o ON o.id = om.org_id
    WHERE om.org_id = p_org
      AND om.user_id = auth.uid()
      AND o.deleted_at IS NULL
      AND om.scope = 'org'
      AND om.role <> 'artist'
  );
$$;

ALTER FUNCTION public.labelos_sees_whole_org(uuid) OWNER TO postgres;
REVOKE ALL ON FUNCTION public.labelos_sees_whole_org(uuid) FROM PUBLIC;
REVOKE ALL ON FUNCTION public.labelos_sees_whole_org(uuid) FROM anon, authenticated;

-- Is this org project inside the caller's artist scope? Scope only; the
-- capability is has_org_cap's job. False for a producer project, a project
-- of another org, and a non-member.
CREATE OR REPLACE FUNCTION public.can_see_org_project(p_org uuid, p_project uuid)
RETURNS boolean
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
  SELECT EXISTS (
    SELECT 1
    FROM public.projects p
    WHERE p.id = p_project
      AND p.org_id IS NOT NULL
      AND p.org_id = p_org
      AND (
        public.labelos_sees_whole_org(p_org)
        OR (p.inbox_for_contact_id IS NOT NULL AND public.can_see_artist(p_org, p.inbox_for_contact_id))
        OR EXISTS (
          SELECT 1 FROM public.project_contacts pc
          WHERE pc.project_id = p.id
            AND public.can_see_artist(p_org, pc.contact_id)
        )
      )
  );
$$;

ALTER FUNCTION public.can_see_org_project(uuid, uuid) OWNER TO postgres;
REVOKE ALL ON FUNCTION public.can_see_org_project(uuid, uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.can_see_org_project(uuid, uuid) TO authenticated, anon;

-- Is this org track inside the caller's artist scope? Through a project of
-- the SAME org it sits in; a track in no project is whole-org only.
CREATE OR REPLACE FUNCTION public.can_see_org_track(p_org uuid, p_track uuid)
RETURNS boolean
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
  SELECT EXISTS (
    SELECT 1
    FROM public.tracks t
    WHERE t.id = p_track
      AND t.org_id IS NOT NULL
      AND t.org_id = p_org
      AND (
        public.labelos_sees_whole_org(p_org)
        OR EXISTS (
          SELECT 1
          FROM public.project_tracks pt
          JOIN public.projects p ON p.id = pt.project_id AND p.org_id = t.org_id
          WHERE pt.track_id = t.id
            AND public.can_see_org_project(p_org, p.id)
        )
      )
  );
$$;

ALTER FUNCTION public.can_see_org_track(uuid, uuid) OWNER TO postgres;
REVOKE ALL ON FUNCTION public.can_see_org_track(uuid, uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.can_see_org_track(uuid, uuid) TO authenticated, anon;

-- The audio class of an org track for ROW reads (lib/labelos/org-read.ts,
-- orgTrackReadClass): finished only when it is a selected song's own audio
-- or a song's master / instrumental, and nothing links to it as working
-- material. Internal: no grant.
CREATE OR REPLACE FUNCTION public.labelos_track_is_finished(p_track uuid)
RETURNS boolean
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
  SELECT NOT EXISTS (
      SELECT 1 FROM public.track_links l
      WHERE l.to_track_id = p_track AND l.relation NOT IN ('master', 'instrumental')
    )
    AND NOT EXISTS (SELECT 1 FROM public.song_beats sb WHERE sb.beat_track_id = p_track)
    AND (
      EXISTS (
        SELECT 1
        FROM public.track_links l
        JOIN public.tracks s ON s.id = l.from_track_id AND s.type = 'song'
        JOIN public.tracks t ON t.id = l.to_track_id AND t.org_id = s.org_id
        WHERE l.to_track_id = p_track AND l.relation IN ('master', 'instrumental')
      )
      OR EXISTS (
        SELECT 1 FROM public.tracks t
        WHERE t.id = p_track AND t.type = 'song' AND t.song_stage = 'selected'
      )
    );
$$;

ALTER FUNCTION public.labelos_track_is_finished(uuid) OWNER TO postgres;
REVOKE ALL ON FUNCTION public.labelos_track_is_finished(uuid) FROM PUBLIC;
REVOKE ALL ON FUNCTION public.labelos_track_is_finished(uuid) FROM anon, authenticated;

-- May the caller read this org track's row? catalog.read, artist scope and
-- the audio class (D4: marketing never reads working material).
CREATE OR REPLACE FUNCTION public.can_read_org_track(p_org uuid, p_track uuid)
RETURNS boolean
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
  SELECT p_org IS NOT NULL
    AND public.has_org_cap(p_org, 'catalog.read')
    AND public.can_see_org_track(p_org, p_track)
    AND (
      public.has_org_cap(p_org, 'audio.working')
      OR (public.has_org_cap(p_org, 'audio.finished') AND public.labelos_track_is_finished(p_track))
    );
$$;

ALTER FUNCTION public.can_read_org_track(uuid, uuid) OWNER TO postgres;
REVOKE ALL ON FUNCTION public.can_read_org_track(uuid, uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.can_read_org_track(uuid, uuid) TO authenticated, anon;

-- ── 3. Additive read policies ───────────────────────────────────────────
-- owner_only (097/119) and every #44 owner policy are untouched. Producer
-- rows are org_id IS NULL, and every policy below requires org_id IS NOT
-- NULL on its row or its parent's, so none of them can match one.

DROP POLICY IF EXISTS org_member_read ON public.tracks;
CREATE POLICY org_member_read ON public.tracks
  FOR SELECT
  TO authenticated
  USING (
    org_id IS NOT NULL
    AND public.can_read_org_track(org_id, id)
  );

DROP POLICY IF EXISTS org_member_read ON public.projects;
CREATE POLICY org_member_read ON public.projects
  FOR SELECT
  TO authenticated
  USING (
    org_id IS NOT NULL
    AND (SELECT public.has_org_cap(org_id, 'catalog.read'))
    AND public.can_see_org_project(org_id, id)
  );

DROP POLICY IF EXISTS org_member_read ON public.project_contacts;
CREATE POLICY org_member_read ON public.project_contacts
  FOR SELECT
  TO authenticated
  USING (
    EXISTS (
      SELECT 1 FROM public.projects p
      WHERE p.id = project_contacts.project_id
        AND p.org_id IS NOT NULL
        AND public.has_org_cap(p.org_id, 'catalog.read')
        AND public.can_see_org_project(p.org_id, p.id)
        AND public.can_see_artist(p.org_id, project_contacts.contact_id)
    )
  );

DROP POLICY IF EXISTS org_member_read ON public.artist_portals;
CREATE POLICY org_member_read ON public.artist_portals
  FOR SELECT
  TO authenticated
  USING (
    EXISTS (
      SELECT 1 FROM public.contacts c
      WHERE c.id = artist_portals.contact_id
        AND c.org_id IS NOT NULL
        AND public.has_org_cap(c.org_id, 'catalog.read')
        AND public.can_see_artist(c.org_id, c.id)
        AND public.has_org_cap(c.org_id, 'share.external')
        AND public.has_org_cap(c.org_id, 'audio.working')
    )
  );

DROP POLICY IF EXISTS org_member_read ON public.project_assets;
CREATE POLICY org_member_read ON public.project_assets
  FOR SELECT
  TO authenticated
  USING (
    EXISTS (
      SELECT 1 FROM public.projects p
      WHERE p.id = project_assets.project_id
        AND p.org_id IS NOT NULL
        AND public.has_org_cap(p.org_id, 'catalog.read')
        AND public.can_see_org_project(p.org_id, p.id)
        AND (project_assets.kind IN ('artwork', 'lyrics') OR public.has_org_cap(p.org_id, 'audio.working'))
    )
  );

DROP POLICY IF EXISTS org_member_read ON public.song_beats;
CREATE POLICY org_member_read ON public.song_beats
  FOR SELECT
  TO authenticated
  USING (
    EXISTS (
      SELECT 1 FROM public.tracks s
      WHERE s.id = song_beats.song_track_id
        AND s.org_id IS NOT NULL
        AND public.can_read_org_track(s.org_id, s.id)
    )
    AND EXISTS (
      SELECT 1 FROM public.tracks b
      WHERE b.id = song_beats.beat_track_id
        AND b.org_id IS NOT NULL
        AND public.can_read_org_track(b.org_id, b.id)
    )
  );

DROP POLICY IF EXISTS org_member_read ON public.track_links;
CREATE POLICY org_member_read ON public.track_links
  FOR SELECT
  TO authenticated
  USING (
    EXISTS (
      SELECT 1 FROM public.tracks f
      WHERE f.id = track_links.from_track_id
        AND f.org_id IS NOT NULL
        AND public.can_read_org_track(f.org_id, f.id)
    )
    AND EXISTS (
      SELECT 1 FROM public.tracks t
      WHERE t.id = track_links.to_track_id
        AND t.org_id IS NOT NULL
        AND public.can_read_org_track(t.org_id, t.id)
    )
  );

DROP POLICY IF EXISTS org_member_read ON public.artist_messages;
CREATE POLICY org_member_read ON public.artist_messages
  FOR SELECT
  TO authenticated
  USING (
    EXISTS (
      SELECT 1 FROM public.contacts c
      WHERE c.id = artist_messages.contact_id
        AND c.org_id IS NOT NULL
        AND public.has_org_cap(c.org_id, 'catalog.read')
        AND public.can_see_artist(c.org_id, c.id)
        AND (
          artist_messages.project_id IS NULL
          OR public.can_see_org_project(c.org_id, artist_messages.project_id)
        )
    )
  );

DROP POLICY IF EXISTS org_member_read ON public.contact_track_states;
CREATE POLICY org_member_read ON public.contact_track_states
  FOR SELECT
  TO authenticated
  USING (
    EXISTS (
      SELECT 1 FROM public.contacts c
      WHERE c.id = contact_track_states.contact_id
        AND c.org_id IS NOT NULL
        AND public.has_org_cap(c.org_id, 'catalog.read')
        AND public.can_see_artist(c.org_id, c.id)
        AND public.can_read_org_track(c.org_id, contact_track_states.track_id)
        AND (
          contact_track_states.project_id IS NULL
          OR public.can_see_org_project(c.org_id, contact_track_states.project_id)
        )
    )
  );

DROP POLICY IF EXISTS org_member_read ON public.project_comments;
CREATE POLICY org_member_read ON public.project_comments
  FOR SELECT
  TO authenticated
  USING (
    EXISTS (
      SELECT 1 FROM public.projects p
      WHERE p.id = project_comments.project_id
        AND p.org_id IS NOT NULL
        AND public.has_org_cap(p.org_id, 'catalog.read')
        AND public.can_see_org_project(p.org_id, p.id)
        AND (project_comments.track_id IS NULL OR public.can_read_org_track(p.org_id, project_comments.track_id))
        AND (project_comments.contact_id IS NULL OR public.can_see_artist(p.org_id, project_comments.contact_id))
        AND (project_comments.share_token IS NULL OR public.has_org_cap(p.org_id, 'share.external'))
    )
  );

-- ── 3b. Restrictive read guards ─────────────────────────────────────────
-- An org row still has a user_id (projects.user_id and every #44 user_id
-- are NOT NULL; the org routes write the acting member there). The
-- producer-era owner policies key on user_id = auth.uid(), so without a
-- guard that member would keep reading the row through them after leaving
-- the org, after the org is soft-deleted, or outside their scope / audio
-- class — exactly what the routes refuse. Each guard is RESTRICTIVE (ANDed
-- with every permissive policy) and passes producer rows untouched:
--   producer row → true; org row → the org_member_read predicate.
-- tracks and projects are enough for every table keyed through them
-- (project_tracks, track_versions, project_comments, track_collaborators,
-- project_shares, …): their policies read tracks / projects under the
-- caller's RLS, so a guarded parent hides the child. The #44 tables keyed on
-- their OWN user_id get their own guard. "Is this an org row?" is asked
-- through SECURITY DEFINER helpers: an EXISTS under the caller's RLS would
-- answer "no" for an org parent the caller cannot see, and pass the guard.

CREATE OR REPLACE FUNCTION public.labelos_is_org_project(p_project uuid)
RETURNS boolean
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
  SELECT EXISTS (SELECT 1 FROM public.projects WHERE id = p_project AND org_id IS NOT NULL);
$$;

CREATE OR REPLACE FUNCTION public.labelos_is_org_track(p_track uuid)
RETURNS boolean
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
  SELECT EXISTS (SELECT 1 FROM public.tracks WHERE id = p_track AND org_id IS NOT NULL);
$$;

CREATE OR REPLACE FUNCTION public.labelos_is_org_contact(p_contact uuid)
RETURNS boolean
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
  SELECT EXISTS (SELECT 1 FROM public.contacts WHERE id = p_contact AND org_id IS NOT NULL);
$$;

ALTER FUNCTION public.labelos_is_org_project(uuid) OWNER TO postgres;
ALTER FUNCTION public.labelos_is_org_track(uuid) OWNER TO postgres;
ALTER FUNCTION public.labelos_is_org_contact(uuid) OWNER TO postgres;
REVOKE ALL ON FUNCTION public.labelos_is_org_project(uuid) FROM PUBLIC;
REVOKE ALL ON FUNCTION public.labelos_is_org_track(uuid) FROM PUBLIC;
REVOKE ALL ON FUNCTION public.labelos_is_org_contact(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.labelos_is_org_project(uuid), public.labelos_is_org_track(uuid),
  public.labelos_is_org_contact(uuid) TO authenticated, anon;

DROP POLICY IF EXISTS org_member_guard ON public.tracks;
CREATE POLICY org_member_guard ON public.tracks
  AS RESTRICTIVE
  FOR SELECT
  USING (
    org_id IS NULL
    OR (
      org_id IS NOT NULL
      AND public.can_read_org_track(org_id, id)
    )
  );

DROP POLICY IF EXISTS org_member_guard ON public.projects;
CREATE POLICY org_member_guard ON public.projects
  AS RESTRICTIVE
  FOR SELECT
  USING (
    org_id IS NULL
    OR (
      org_id IS NOT NULL
      AND (SELECT public.has_org_cap(org_id, 'catalog.read'))
      AND public.can_see_org_project(org_id, id)
    )
  );

DROP POLICY IF EXISTS org_member_guard ON public.project_contacts;
CREATE POLICY org_member_guard ON public.project_contacts
  AS RESTRICTIVE
  FOR SELECT
  USING (
    NOT public.labelos_is_org_project(project_id)
    OR EXISTS (
      SELECT 1 FROM public.projects p
      WHERE p.id = project_contacts.project_id
        AND p.org_id IS NOT NULL
        AND public.has_org_cap(p.org_id, 'catalog.read')
        AND public.can_see_org_project(p.org_id, p.id)
        AND public.can_see_artist(p.org_id, project_contacts.contact_id)
    )
  );

DROP POLICY IF EXISTS org_member_guard ON public.artist_portals;
CREATE POLICY org_member_guard ON public.artist_portals
  AS RESTRICTIVE
  FOR SELECT
  USING (
    NOT public.labelos_is_org_contact(contact_id)
    OR EXISTS (
      SELECT 1 FROM public.contacts c
      WHERE c.id = artist_portals.contact_id
        AND c.org_id IS NOT NULL
        AND public.has_org_cap(c.org_id, 'catalog.read')
        AND public.can_see_artist(c.org_id, c.id)
        AND public.has_org_cap(c.org_id, 'share.external')
        AND public.has_org_cap(c.org_id, 'audio.working')
    )
  );

DROP POLICY IF EXISTS org_member_guard ON public.project_assets;
CREATE POLICY org_member_guard ON public.project_assets
  AS RESTRICTIVE
  FOR SELECT
  USING (
    NOT public.labelos_is_org_project(project_id)
    OR EXISTS (
      SELECT 1 FROM public.projects p
      WHERE p.id = project_assets.project_id
        AND p.org_id IS NOT NULL
        AND public.has_org_cap(p.org_id, 'catalog.read')
        AND public.can_see_org_project(p.org_id, p.id)
        AND (project_assets.kind IN ('artwork', 'lyrics') OR public.has_org_cap(p.org_id, 'audio.working'))
    )
  );

DROP POLICY IF EXISTS org_member_guard ON public.song_beats;
CREATE POLICY org_member_guard ON public.song_beats
  AS RESTRICTIVE
  FOR SELECT
  USING (
    NOT public.labelos_is_org_track(song_track_id)
    OR (
      EXISTS (
        SELECT 1 FROM public.tracks s
        WHERE s.id = song_beats.song_track_id
          AND s.org_id IS NOT NULL
          AND public.can_read_org_track(s.org_id, s.id)
      )
      AND EXISTS (
        SELECT 1 FROM public.tracks b
        WHERE b.id = song_beats.beat_track_id
          AND b.org_id IS NOT NULL
          AND public.can_read_org_track(b.org_id, b.id)
      )
    )
  );

DROP POLICY IF EXISTS org_member_guard ON public.track_links;
CREATE POLICY org_member_guard ON public.track_links
  AS RESTRICTIVE
  FOR SELECT
  USING (
    NOT public.labelos_is_org_track(from_track_id)
    OR (
      EXISTS (
        SELECT 1 FROM public.tracks f
        WHERE f.id = track_links.from_track_id
          AND f.org_id IS NOT NULL
          AND public.can_read_org_track(f.org_id, f.id)
      )
      AND EXISTS (
        SELECT 1 FROM public.tracks t
        WHERE t.id = track_links.to_track_id
          AND t.org_id IS NOT NULL
          AND public.can_read_org_track(t.org_id, t.id)
      )
    )
  );

DROP POLICY IF EXISTS org_member_guard ON public.artist_messages;
CREATE POLICY org_member_guard ON public.artist_messages
  AS RESTRICTIVE
  FOR SELECT
  USING (
    NOT public.labelos_is_org_contact(contact_id)
    OR EXISTS (
      SELECT 1 FROM public.contacts c
      WHERE c.id = artist_messages.contact_id
        AND c.org_id IS NOT NULL
        AND public.has_org_cap(c.org_id, 'catalog.read')
        AND public.can_see_artist(c.org_id, c.id)
        AND (
          artist_messages.project_id IS NULL
          OR public.can_see_org_project(c.org_id, artist_messages.project_id)
        )
    )
  );

DROP POLICY IF EXISTS org_member_guard ON public.contact_track_states;
CREATE POLICY org_member_guard ON public.contact_track_states
  AS RESTRICTIVE
  FOR SELECT
  USING (
    NOT public.labelos_is_org_contact(contact_id)
    OR EXISTS (
      SELECT 1 FROM public.contacts c
      WHERE c.id = contact_track_states.contact_id
        AND c.org_id IS NOT NULL
        AND public.has_org_cap(c.org_id, 'catalog.read')
        AND public.can_see_artist(c.org_id, c.id)
        AND public.can_read_org_track(c.org_id, contact_track_states.track_id)
        AND (
          contact_track_states.project_id IS NULL
          OR public.can_see_org_project(c.org_id, contact_track_states.project_id)
        )
    )
  );

-- A member who authored an org project / track (its user_id) would also
-- read every child row keyed through it — project_comments, project_shares
-- (bearer tokens), project_tracks, versions, credits … — past the narrowing
-- org_member_read applies, because those policies match p.user_id =
-- auth.uid() on a parent the member can still see. project_comments keeps
-- its org_member_read predicate; the rest have no org read path at all, so
-- an org row there is never readable through PostgREST (the routes serve
-- them). One-sided: an org child's other parent is in the same org.

DROP POLICY IF EXISTS org_member_guard ON public.project_comments;
CREATE POLICY org_member_guard ON public.project_comments
  AS RESTRICTIVE
  FOR SELECT
  USING (
    NOT public.labelos_is_org_project(project_id)
    OR EXISTS (
      SELECT 1 FROM public.projects p
      WHERE p.id = project_comments.project_id
        AND p.org_id IS NOT NULL
        AND public.has_org_cap(p.org_id, 'catalog.read')
        AND public.can_see_org_project(p.org_id, p.id)
        AND (project_comments.track_id IS NULL OR public.can_read_org_track(p.org_id, project_comments.track_id))
        AND (project_comments.contact_id IS NULL OR public.can_see_artist(p.org_id, project_comments.contact_id))
        AND (project_comments.share_token IS NULL OR public.has_org_cap(p.org_id, 'share.external'))
    )
  );

DROP POLICY IF EXISTS org_member_guard ON public.project_tracks;
CREATE POLICY org_member_guard ON public.project_tracks
  AS RESTRICTIVE FOR SELECT
  USING (NOT public.labelos_is_org_project(project_id) AND NOT public.labelos_is_org_track(track_id));

DROP POLICY IF EXISTS org_member_guard ON public.project_shares;
CREATE POLICY org_member_guard ON public.project_shares
  AS RESTRICTIVE FOR SELECT
  USING (NOT public.labelos_is_org_project(project_id) AND NOT public.labelos_is_org_track(track_id));

DROP POLICY IF EXISTS org_member_guard ON public.track_versions;
CREATE POLICY org_member_guard ON public.track_versions
  AS RESTRICTIVE FOR SELECT
  USING (NOT public.labelos_is_org_track(track_id));

DROP POLICY IF EXISTS org_member_guard ON public.track_collaborators;
CREATE POLICY org_member_guard ON public.track_collaborators
  AS RESTRICTIVE FOR SELECT
  USING (NOT public.labelos_is_org_track(track_id));

DROP POLICY IF EXISTS org_member_guard ON public.track_licenses;
CREATE POLICY org_member_guard ON public.track_licenses
  AS RESTRICTIVE FOR SELECT
  USING (NOT public.labelos_is_org_track(track_id));

DROP POLICY IF EXISTS org_member_guard ON public.play_head_pings;
CREATE POLICY org_member_guard ON public.play_head_pings
  AS RESTRICTIVE FOR SELECT
  USING (NOT public.labelos_is_org_track(track_id));

DROP POLICY IF EXISTS org_member_guard ON public.store_free_downloads;
CREATE POLICY org_member_guard ON public.store_free_downloads
  AS RESTRICTIVE FOR SELECT
  USING (NOT public.labelos_is_org_track(track_id));

DROP POLICY IF EXISTS org_member_guard ON public.project_tags;
CREATE POLICY org_member_guard ON public.project_tags
  AS RESTRICTIVE FOR SELECT
  USING (NOT public.labelos_is_org_project(project_id));

DROP POLICY IF EXISTS org_member_guard ON public.project_folder_items;
CREATE POLICY org_member_guard ON public.project_folder_items
  AS RESTRICTIVE FOR SELECT
  USING (NOT public.labelos_is_org_project(project_id));

DROP POLICY IF EXISTS org_member_guard ON public.project_access_links;
CREATE POLICY org_member_guard ON public.project_access_links
  AS RESTRICTIVE FOR SELECT
  USING (NOT public.labelos_is_org_project(project_id));

-- ── 3c. Org rows are written by the service role only ───────────────────
-- The producer-era write policies (owner_only, *_owner_write, owner_via_*)
-- key on user_id = auth.uid() (plus is_producer() on some), and know nothing
-- of orgs: through them a producer could insert a row INTO an org, a
-- producer who is also a scoped member could link a project to their own
-- artist (widening their scope), and an org row's author could update or
-- delete it without catalog.write — or after leaving. Rather than a write
-- POLICY (none is added), one trigger refuses any insert, update or delete
-- of an org row by the API roles; the service role and postgres (every
-- /api/org route, every migration) pass straight through. Producer rows are
-- unaffected: their keys are never org rows.
--
-- Arguments are (kind, column) pairs: kind `self` = the row's own org_id,
-- `project` / `track` / `contact` = that parent column is an org row.

CREATE OR REPLACE FUNCTION public.labelos_org_rows_service_only()
RETURNS trigger
LANGUAGE plpgsql
SET search_path = public
AS $$
DECLARE
  r jsonb;
  i int;
  v text;
BEGIN
  IF current_user NOT IN ('authenticated', 'anon') THEN
    RETURN COALESCE(NEW, OLD);
  END IF;
  FOREACH r IN ARRAY ARRAY[
    CASE WHEN TG_OP <> 'INSERT' THEN to_jsonb(OLD) END,
    CASE WHEN TG_OP <> 'DELETE' THEN to_jsonb(NEW) END
  ] LOOP
    CONTINUE WHEN r IS NULL;
    i := 0;
    WHILE i < TG_NARGS LOOP
      v := r ->> TG_ARGV[i + 1];
      IF v IS NOT NULL AND (
        TG_ARGV[i] = 'self'
        OR (TG_ARGV[i] = 'project' AND public.labelos_is_org_project(v::uuid))
        OR (TG_ARGV[i] = 'track' AND public.labelos_is_org_track(v::uuid))
        OR (TG_ARGV[i] = 'contact' AND public.labelos_is_org_contact(v::uuid))
      ) THEN
        RAISE EXCEPTION '%: organization rows are written through /api/org only', TG_TABLE_NAME
          USING ERRCODE = 'insufficient_privilege';
      END IF;
      i := i + 2;
    END LOOP;
  END LOOP;
  RETURN COALESCE(NEW, OLD);
END;
$$;

ALTER FUNCTION public.labelos_org_rows_service_only() OWNER TO postgres;
REVOKE ALL ON FUNCTION public.labelos_org_rows_service_only() FROM PUBLIC;

DROP TRIGGER IF EXISTS labelos_org_rows_service_only ON public.tracks;
CREATE TRIGGER labelos_org_rows_service_only BEFORE INSERT OR UPDATE OR DELETE ON public.tracks
  FOR EACH ROW EXECUTE FUNCTION public.labelos_org_rows_service_only('self', 'org_id');
DROP TRIGGER IF EXISTS labelos_org_rows_service_only ON public.projects;
CREATE TRIGGER labelos_org_rows_service_only BEFORE INSERT OR UPDATE OR DELETE ON public.projects
  FOR EACH ROW EXECUTE FUNCTION public.labelos_org_rows_service_only('self', 'org_id');
DROP TRIGGER IF EXISTS labelos_org_rows_service_only ON public.project_contacts;
CREATE TRIGGER labelos_org_rows_service_only BEFORE INSERT OR UPDATE OR DELETE ON public.project_contacts
  FOR EACH ROW EXECUTE FUNCTION public.labelos_org_rows_service_only('project', 'project_id', 'contact', 'contact_id');
DROP TRIGGER IF EXISTS labelos_org_rows_service_only ON public.artist_portals;
CREATE TRIGGER labelos_org_rows_service_only BEFORE INSERT OR UPDATE OR DELETE ON public.artist_portals
