  IF NOT EXISTS (
    SELECT 1 FROM public.projects p
    JOIN public.contacts c ON c.user_id = p.user_id AND c.org_id IS NULL
    WHERE p.id = NEW.project_id AND c.id = NEW.contact_id AND p.org_id IS NULL
