END $$;

-- 133
CREATE OR REPLACE FUNCTION public.track_links_same_owner()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
BEGIN
  IF EXISTS (
    SELECT 1 FROM public.tracks f
    JOIN public.tracks t ON t.id = NEW.to_track_id AND t.org_id = f.org_id
    WHERE f.id = NEW.from_track_id AND f.org_id IS NOT NULL
  ) THEN
    RETURN NEW;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.tracks t WHERE t.id = NEW.from_track_id AND t.user_id = NEW.user_id AND t.org_id IS NULL)
     OR NOT EXISTS (SELECT 1 FROM public.tracks t WHERE t.id = NEW.to_track_id AND t.user_id = NEW.user_id AND t.org_id IS NULL) THEN
    RAISE EXCEPTION 'track_links: both tracks must be owned by %', NEW.user_id;
  END IF;
  RETURN NEW;
END $$;

NOTIFY pgrst, 'reload schema';


-- ═════════════ 142_labelos_project_tracks_same_org.sql ═════════════
-- 142_labelos_project_tracks_same_org.sql
-- Label OS (LABEL-14): org rows carry NO user_id on tracks, projects and
-- track_links (the rule 139 set for contacts), and `project_tracks` gets the
-- same-owner / same-org trigger every #44 junction already has (141 §4).
--
-- LABEL OS — NOT APPLIED. Apply at the final merge of the Label OS branch
-- into main, after 141 (docs/bstudio-label-os/16-execution-runbook.md).
--
-- Why now: LABEL-14's org upload writes the first org `project_tracks` rows
-- (a demo into its artist's Inbox, a master into its song's projects). The
-- table never had a parent check (pre-existing, carried from LABEL-12 #68):
-- its RLS policy (097 `owner_via_project`) checks only the PROJECT's owner,
-- and the service-role routes check nothing about the track. 141's scope
-- path (`can_see_org_track`) already ignores a row joining an org track to
-- another org's project, but a row joining an org track to a PRODUCER
-- project (or the reverse) is what puts Label OS material into the
-- producer's library views — the exact boundary 141 §4 holds everywhere
-- else.
--
-- The rule, 141 §4's shape:
--   org case   — project and track in the same non-null org (org rows have
--                no user_id, see below);
--   owner case — project and track owned by the same user, both producer
--                rows (org_id IS NULL). The project's owner is the row's
--                owner: project_tracks has no user_id of its own.
-- Anything else raises. "Different owner, no org" is refused too, which the
-- producer app never does (one producer; every producer route adds the
-- producer's own tracks to the producer's own projects).
--
-- Only INSERT and an UPDATE that MOVES a row (project_id / track_id) are
-- checked. A reorder (position / role) of an existing row is not, so no
-- row written before this migration can start failing an ordinary edit.
--
-- Proven as anon / authenticated / service_role in
-- supabase/local/checks/142_labelos_project_tracks_same_org.sql.
--
-- Org rows have no owner (orchestrator decision on #70, 2026-10-02). Every
-- producer route — the service-role ones included — filters on user_id, so an
-- org row whose user_id is the uploading member would reach that member's
-- producer library, search, store editor and /api/audio whenever the member
-- is the producer. With user_id NULL it matches none of them, the same rule
-- as 139's contacts_org_or_owner. The uploader is recorded in created_by.
--   - projects.user_id DROP NOT NULL + CHECK projects_org_or_owner
--     ((org_id IS NULL) = (user_id IS NOT NULL)): a producer project still
--     must have its owner (every existing row has one since 049 and org_id
--     NULL, so it validates on production);
--   - tracks.user_id is already nullable (002; production may hold legacy
--     NULL-owner producer tracks), so only CHECK tracks_org_or_owner
--     (org_id IS NULL OR user_id IS NULL);
--   - track_links.user_id DROP NOT NULL; its same-owner trigger's org path
--     now requires NEW.user_id IS NULL, the owner path is unchanged (both
--     tracks owned by NEW.user_id, both producer rows), so a producer link
--     without a user_id is refused.
-- The other #44 tables keep their NOT NULL user_id until a task first writes
-- org rows there.
--
-- Idempotent: CREATE OR REPLACE, DROP TRIGGER IF EXISTS first, CHECKs guarded
-- by a pg_constraint lookup (as 139 does).

-- ── Org rows have no owner ──────────────────────────────────────────────

ALTER TABLE public.projects ALTER COLUMN user_id DROP NOT NULL;
ALTER TABLE public.track_links ALTER COLUMN user_id DROP NOT NULL;

DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_constraint
    WHERE conname = 'projects_org_or_owner' AND conrelid = 'public.projects'::regclass
  ) THEN
    ALTER TABLE public.projects
      ADD CONSTRAINT projects_org_or_owner CHECK ((org_id IS NULL) = (user_id IS NOT NULL));
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM pg_constraint
    WHERE conname = 'tracks_org_or_owner' AND conrelid = 'public.tracks'::regclass
  ) THEN
    ALTER TABLE public.tracks
      ADD CONSTRAINT tracks_org_or_owner CHECK (org_id IS NULL OR user_id IS NULL);
  END IF;
END $$;

-- 133 / 141 §4: same org, and then no owner; or the unchanged owner case.
CREATE OR REPLACE FUNCTION public.track_links_same_owner()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
BEGIN
  IF NEW.user_id IS NULL AND EXISTS (
    SELECT 1 FROM public.tracks f
    JOIN public.tracks t ON t.id = NEW.to_track_id AND t.org_id = f.org_id
    WHERE f.id = NEW.from_track_id AND f.org_id IS NOT NULL
  ) THEN
    RETURN NEW;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.tracks t WHERE t.id = NEW.from_track_id AND t.user_id = NEW.user_id AND t.org_id IS NULL)
     OR NOT EXISTS (SELECT 1 FROM public.tracks t WHERE t.id = NEW.to_track_id AND t.user_id = NEW.user_id AND t.org_id IS NULL) THEN
    RAISE EXCEPTION 'track_links: both tracks must be owned by %', NEW.user_id;
  END IF;
  RETURN NEW;
END $$;

-- ── project_tracks: same owner or same org ──────────────────────────────

CREATE OR REPLACE FUNCTION public.project_tracks_same_owner()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
BEGIN
  IF EXISTS (
    SELECT 1 FROM public.projects p
    JOIN public.tracks t ON t.id = NEW.track_id AND t.org_id = p.org_id
    WHERE p.id = NEW.project_id AND p.org_id IS NOT NULL
  ) THEN
    RETURN NEW;
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.projects p
    JOIN public.tracks t ON t.id = NEW.track_id AND t.user_id = p.user_id AND t.org_id IS NULL
    WHERE p.id = NEW.project_id AND p.org_id IS NULL AND p.user_id IS NOT NULL
  ) THEN
    RAISE EXCEPTION 'project_tracks: track % and project % must have the same owner or the same organization',
      NEW.track_id, NEW.project_id
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END $$;

ALTER FUNCTION public.project_tracks_same_owner() OWNER TO postgres;
REVOKE ALL ON FUNCTION public.project_tracks_same_owner() FROM PUBLIC;

DROP TRIGGER IF EXISTS project_tracks_same_owner ON public.project_tracks;
CREATE TRIGGER project_tracks_same_owner
  BEFORE INSERT OR UPDATE OF project_id, track_id ON public.project_tracks
  FOR EACH ROW EXECUTE FUNCTION public.project_tracks_same_owner();

NOTIFY pgrst, 'reload schema';


-- ═════════════ 143_labelos_org_assets.sql ═════════════
-- 143_labelos_org_assets.sql
-- Label OS (LABEL-15): org files on `project_assets` (17 R2). No new table.
--
-- LABEL OS — NOT APPLIED. Apply at the final merge of the Label OS branch
-- into main, after 142 (docs/bstudio-label-os/16-execution-runbook.md).
--
-- Expand only. Every existing row is a producer row (org_id NULL, user_id
-- set, sensitivity 'normal', one of the six 127 kinds), so every CHECK below
-- validates on production and the producer's project files, portal Files tab
-- and Notify counts read exactly what they read before (they all filter on
-- user_id, which an org file does not have).
--
--   1. Columns: project_assets.org_id (FK, fixed by trigger from the project,
--      never set by hand), created_by (the uploader — org rows have no owner,
--      the rule 139 / 142 set), sensitivity ('normal' | 'restricted', default
--      'normal').
--   2. Org rows have no owner: user_id DROP NOT NULL +
--      CHECK project_assets_org_or_owner ((org_id IS NULL) = (user_id IS NOT NULL)).
--   3. Kinds: the 127 CHECK is widened with photo, video, contract,
--      split_sheet, session (dropped + re-added, so a replay leaves one).
--      contract and split_sheet are always restricted
--      (project_assets_restricted_kinds), and a restricted file is never in
--      a portal (project_assets_restricted_not_in_portal) — a portal is a
--      bearer link, and contracts.read is checked per person.
--   4. The 127/141 same-owner trigger now also DERIVES org_id from the
--      project: an org project's file gets its org and must have no user_id;
--      a producer project's file keeps the 127 rule (same owner, producer
--      project). A file never moves between orgs, nor between an org and the
--      producer. It fires on INSERT and UPDATE OF user_id, project_id, org_id.
--   5. Reads: `labelos_org_asset_allowed(org, kind, sensitivity)` (SECURITY
--      DEFINER, the SQL twin of src/lib/labelos/org-assets.ts, held equal by
--      org-assets.test.ts) replaces 141's "artwork / lyrics, else
--      audio.working" in project_assets' org_member_read and org_member_guard:
--        visual (artwork, lyrics, photo, video) — catalog.read;
--        legal (contract, split_sheet)          — catalog.read (+ restricted);
--        anything else (working material)        — + audio.working;
--        restricted                              — + contracts.read.
--      Both policies keep 141's shape (EXISTS on the org project, scope via
--      can_see_org_project). Still SELECT only; org writes stay service-role
--      (141's labelos_org_rows_service_only on project_assets is unchanged).
--   6. Carried from LABEL-13 (#69): `track_stem_files` (080) gets 141 §3b's
--      RESTRICTIVE org_member_guard (an org track's stem files are hidden from
--      every API role) and §3c's service-only write trigger, before any org
--      surface lists stem files.
--
-- Proven as anon / authenticated / service_role in
-- supabase/local/checks/143_labelos_org_assets.sql.
--
-- Idempotent: IF NOT EXISTS, CREATE OR REPLACE, DROP ... IF EXISTS first,
-- CHECKs dropped and re-added.

-- ── 1. Columns ──────────────────────────────────────────────────────────

ALTER TABLE public.project_assets
  ADD COLUMN IF NOT EXISTS org_id uuid REFERENCES public.organizations(id) ON DELETE CASCADE;
ALTER TABLE public.project_assets
  ADD COLUMN IF NOT EXISTS created_by uuid REFERENCES auth.users(id) ON DELETE SET NULL;
ALTER TABLE public.project_assets
  ADD COLUMN IF NOT EXISTS sensitivity text NOT NULL DEFAULT 'normal';

CREATE INDEX IF NOT EXISTS idx_project_assets_org
  ON public.project_assets (org_id, project_id, position)
  WHERE org_id IS NOT NULL;

-- ── 2 + 3. Ownerless org rows, kinds, sensitivity ───────────────────────

ALTER TABLE public.project_assets ALTER COLUMN user_id DROP NOT NULL;

ALTER TABLE public.project_assets DROP CONSTRAINT IF EXISTS project_assets_org_or_owner;
ALTER TABLE public.project_assets ADD CONSTRAINT project_assets_org_or_owner
  CHECK ((org_id IS NULL) = (user_id IS NOT NULL));

ALTER TABLE public.project_assets DROP CONSTRAINT IF EXISTS project_assets_kind_check;
ALTER TABLE public.project_assets ADD CONSTRAINT project_assets_kind_check
  CHECK (kind IN ('reference', 'artwork', 'lyrics', 'document', 'audio', 'other', 'photo', 'video', 'contract', 'split_sheet', 'session'));

ALTER TABLE public.project_assets DROP CONSTRAINT IF EXISTS project_assets_sensitivity_check;
ALTER TABLE public.project_assets ADD CONSTRAINT project_assets_sensitivity_check
  CHECK (sensitivity IN ('normal', 'restricted'));

ALTER TABLE public.project_assets DROP CONSTRAINT IF EXISTS project_assets_restricted_kinds;
ALTER TABLE public.project_assets ADD CONSTRAINT project_assets_restricted_kinds
  CHECK (kind NOT IN ('contract', 'split_sheet') OR sensitivity = 'restricted');

ALTER TABLE public.project_assets DROP CONSTRAINT IF EXISTS project_assets_restricted_not_in_portal;
ALTER TABLE public.project_assets ADD CONSTRAINT project_assets_restricted_not_in_portal
  CHECK (sensitivity = 'normal' OR NOT in_portal);

-- ── 4. Same owner, or same org (and then no owner) ──────────────────────

CREATE OR REPLACE FUNCTION public.project_assets_same_owner()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE
  v_org uuid;
  v_owner uuid;
BEGIN
  SELECT p.org_id, p.user_id INTO v_org, v_owner FROM public.projects p WHERE p.id = NEW.project_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'project_assets: project % is not owned by %', NEW.project_id, NEW.user_id;
  END IF;
  IF TG_OP = 'UPDATE' AND v_org IS DISTINCT FROM OLD.org_id THEN
    RAISE EXCEPTION 'project_assets: a file cannot move between organizations'
      USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.org_id IS NOT NULL AND NEW.org_id IS DISTINCT FROM v_org THEN
    RAISE EXCEPTION 'project_assets: org_id must be the project''s organization'
      USING ERRCODE = 'check_violation';
  END IF;
  NEW.org_id := v_org;
  IF v_org IS NOT NULL THEN
    IF NEW.user_id IS NOT NULL THEN
      RAISE EXCEPTION 'project_assets: an organization file has no owner'
        USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
  END IF;
  IF NEW.user_id IS NULL OR v_owner IS DISTINCT FROM NEW.user_id THEN
    RAISE EXCEPTION 'project_assets: project % is not owned by %', NEW.project_id, NEW.user_id;
  END IF;
  RETURN NEW;
END $$;

DROP TRIGGER IF EXISTS project_assets_same_owner ON public.project_assets;
CREATE TRIGGER project_assets_same_owner
  BEFORE INSERT OR UPDATE OF user_id, project_id, org_id ON public.project_assets
  FOR EACH ROW EXECUTE FUNCTION public.project_assets_same_owner();

-- ── 5. Who reads an org file ────────────────────────────────────────────
-- Kind classes and sensitivity only; catalog.read and the project scope stay
-- in the policies (as 141 wrote them). auth.uid() is still the caller.

CREATE OR REPLACE FUNCTION public.labelos_org_asset_allowed(p_org uuid, p_kind text, p_sensitivity text)
RETURNS boolean
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_visual text[] := ARRAY['artwork', 'lyrics', 'photo', 'video'];
  v_legal text[] := ARRAY['contract', 'split_sheet'];
BEGIN
  IF p_org IS NULL OR NOT public.has_org_cap(p_org, 'catalog.read') THEN
    RETURN false;
  END IF;
  IF NOT (p_kind = ANY (v_visual) OR p_kind = ANY (v_legal))
     AND NOT public.has_org_cap(p_org, 'audio.working') THEN
    RETURN false;
  END IF;
  IF p_sensitivity IS DISTINCT FROM 'normal' AND NOT public.has_org_cap(p_org, 'contracts.read') THEN
    RETURN false;
  END IF;
  RETURN true;
END;
$$;

ALTER FUNCTION public.labelos_org_asset_allowed(uuid, text, text) OWNER TO postgres;
REVOKE ALL ON FUNCTION public.labelos_org_asset_allowed(uuid, text, text) FROM PUBLIC;
-- anon too: the RESTRICTIVE guard applies to every role and Postgres does
-- not promise to short-circuit its OR. Without a session it is always false.
GRANT EXECUTE ON FUNCTION public.labelos_org_asset_allowed(uuid, text, text) TO authenticated, anon;

DROP POLICY IF EXISTS org_member_read ON public.project_assets;
CREATE POLICY org_member_read ON public.project_assets
  FOR SELECT
  TO authenticated
  USING (
    EXISTS (
      SELECT 1 FROM public.projects p
      WHERE p.id = project_assets.project_id
        AND p.org_id IS NOT NULL
        AND public.has_org_cap(p.org_id, 'catalog.read')
        AND public.can_see_org_project(p.org_id, p.id)
        AND public.labelos_org_asset_allowed(p.org_id, project_assets.kind, project_assets.sensitivity)
    )
  );

DROP POLICY IF EXISTS org_member_guard ON public.project_assets;
CREATE POLICY org_member_guard ON public.project_assets
  AS RESTRICTIVE
  FOR SELECT
  USING (
    NOT public.labelos_is_org_project(project_id)
    OR EXISTS (
      SELECT 1 FROM public.projects p
      WHERE p.id = project_assets.project_id
        AND p.org_id IS NOT NULL
        AND public.has_org_cap(p.org_id, 'catalog.read')
        AND public.can_see_org_project(p.org_id, p.id)
        AND public.labelos_org_asset_allowed(p.org_id, project_assets.kind, project_assets.sensitivity)
    )
  );

-- ── 6. track_stem_files (carried from LABEL-13) ─────────────────────────

DROP POLICY IF EXISTS org_member_guard ON public.track_stem_files;
CREATE POLICY org_member_guard ON public.track_stem_files
  AS RESTRICTIVE FOR SELECT
  USING (NOT public.labelos_is_org_track(track_id));

DROP TRIGGER IF EXISTS labelos_org_rows_service_only ON public.track_stem_files;
CREATE TRIGGER labelos_org_rows_service_only BEFORE INSERT OR UPDATE OR DELETE ON public.track_stem_files
  FOR EACH ROW EXECUTE FUNCTION public.labelos_org_rows_service_only('track', 'track_id');

NOTIFY pgrst, 'reload schema';


-- ═════════════ 144_labelos_releases.sql ═════════════
-- 144_labelos_releases.sql
-- Label OS (LABEL-16): releases and their tracklists, built on song tracks
-- (17 R1 / R2 / R9). Two new org-only tables.
--
-- LABEL OS — NOT APPLIED. Apply at the final merge of the Label OS branch
-- into main, after 143 (docs/bstudio-label-os/16-execution-runbook.md).
--
-- Expand only. No existing row changes; the producer app never reads or
-- writes either table.
--
--   1. `releases` — org_id NOT NULL, NO user_id (the 139 / 142 / 143 rule:
--      no producer route, all of which filter on user_id, can reach one).
--      Always has a project (R2: its artwork and documents are that
--      project's files); the route creates one when none is given. The 05
--      fields, with `artist_id` → `contact_id` (R3) and `artwork_file_id` →
--      `artwork_asset_id` (R2). Only terminal / manual facts are stored
--      (state, delivered_at, store_listed); gates and "released" are derived
--      (LABEL-32 / 33). CHECKs: type and state lists, the UPC format
--      (lib/labelos/identifiers — the route also verifies the check digit),
--      delivered ⇒ delivered_at, listed ⇒ listed_at, and only a delivered or
--      imported-as-released release may be listed (15: unreleased music
--      stays private).
--   2. `release_items(release_id, position, song_track_id, master_track_id,
--      version_title, explicit)` + org_id (taken from the release by the
--      trigger, so policies and list reads key on the tenant directly).
--      UNIQUE (release_id, position) is DEFERRABLE INITIALLY DEFERRED, and a
--      deferred constraint trigger holds positions at exactly 1..n at COMMIT,
--      so a reorder or a remove-and-close-the-gap runs as one transaction
--      (§5's functions) and nothing commits a gap.
--   3. Integrity triggers:
--        releases_integrity — org and project are fixed once written; the
--          project and the artist contact are of the release's org; the
--          artwork is an artwork / photo file of the release's own project.
--        release_items_integrity — the release fixes the item's org; the song
--          is a `type = 'song'` track of that org; the master is the song
--          itself, or a track of that org the song links to (track_links,
--          from the song) as master, instrumental or version.
--      And three guards keep those true afterwards: an artwork file of a
--      release cannot change kind or project; a song on a release cannot
--      change type; the link that makes a track an item's master cannot be
--      removed or turned into another relation. (A link or track deleted by
--      a cascade from its parent track passes: the item's own foreign keys
--      decide that case at the end of the statement.)
--   4. RLS on both, ONE SELECT policy each, TO authenticated: catalog.read +
--      project scope (`can_see_org_project` on the release's project), the
--      rule of 141 / 143. No write policy: writes go through the service
--      role only, and 141's `labelos_org_rows_service_only` trigger refuses
--      the API roles outright.
--   5. `labelos_release_items_reorder(org, release, item ids[])` and
--      `labelos_release_item_remove(org, release, item)`: the two
--      multi-row tracklist writes, each atomic, service_role only.
--   6. `project_contacts.user_id` DROP NOT NULL: the route links a release's
--      new project to its artist, and an org link has no owner (the 142 / 143
--      rule) — a producer route that lists project_contacts by user_id must
--      never pick it up. The producer path of 141's same-owner trigger still
--      requires user_id = the project's owner, so a producer link without
--      one is refused as before. (Not enforced as NULL for org links: 141 –
--      143's local checks write org links with the acting member.)
--   7. "On a release" makes a mix finished (06 §2.3, carried from LABEL-13):
--      `labelos_track_is_finished` (141) is replaced with the same rule plus
--      one arm — a song's own audio is finished when the song is an item of
--      a release that is not cancelled. Its TS twins move with it:
--      lib/labelos/org-read#orgTrackReadClass (rows) and
--      lib/labelos/org-audio#recordingContexts (the audio route).
--
-- Proven as anon / authenticated / service_role in
-- supabase/local/checks/144_labelos_releases.sql and held by
-- src/lib/security/rls-final-state.test.ts.
--
-- Idempotent: IF NOT EXISTS, CREATE OR REPLACE, DROP ... IF EXISTS first.

-- ── 1 + 2. Tables ───────────────────────────────────────────────────────

CREATE TABLE IF NOT EXISTS public.releases (
  id                uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  org_id            uuid NOT NULL REFERENCES public.organizations(id) ON DELETE CASCADE,
  project_id        uuid NOT NULL REFERENCES public.projects(id),
  contact_id        uuid NOT NULL REFERENCES public.contacts(id),
  title             text NOT NULL,
  type              text NOT NULL DEFAULT 'single',
  upc               text,
  label_name        text,
  c_line            text,
  p_line            text,
  primary_genre     text,
  target_date       date,
  release_date      date,
  artwork_asset_id  uuid REFERENCES public.project_assets(id) ON DELETE SET NULL,
  state             text NOT NULL DEFAULT 'draft',
  delivered_at      timestamptz,
  delivered_to      text,
  imported_released boolean NOT NULL DEFAULT false,
  store_listed      boolean NOT NULL DEFAULT false,
  store_listed_at   timestamptz,
  created_by        uuid REFERENCES auth.users(id) ON DELETE SET NULL,
  created_at        timestamptz NOT NULL DEFAULT now(),
  updated_at        timestamptz NOT NULL DEFAULT now()
);

ALTER TABLE public.releases DROP CONSTRAINT IF EXISTS releases_type_check;
ALTER TABLE public.releases ADD CONSTRAINT releases_type_check
  CHECK (type IN ('single', 'ep', 'album', 'mixtape', 'compilation'));
ALTER TABLE public.releases DROP CONSTRAINT IF EXISTS releases_state_check;
ALTER TABLE public.releases ADD CONSTRAINT releases_state_check
  CHECK (state IN ('draft', 'delivered', 'cancelled'));
ALTER TABLE public.releases DROP CONSTRAINT IF EXISTS releases_upc_format;
ALTER TABLE public.releases ADD CONSTRAINT releases_upc_format
  CHECK (upc IS NULL OR upc ~ '^[0-9]{12,13}$');
ALTER TABLE public.releases DROP CONSTRAINT IF EXISTS releases_title_length;
ALTER TABLE public.releases ADD CONSTRAINT releases_title_length
  CHECK (char_length(btrim(title)) BETWEEN 1 AND 300);
ALTER TABLE public.releases DROP CONSTRAINT IF EXISTS releases_delivered_at;
ALTER TABLE public.releases ADD CONSTRAINT releases_delivered_at
  CHECK (state <> 'delivered' OR delivered_at IS NOT NULL);
ALTER TABLE public.releases DROP CONSTRAINT IF EXISTS releases_store_listed_at;
ALTER TABLE public.releases ADD CONSTRAINT releases_store_listed_at
  CHECK (NOT store_listed OR store_listed_at IS NOT NULL);
ALTER TABLE public.releases DROP CONSTRAINT IF EXISTS releases_store_listed_released;
ALTER TABLE public.releases ADD CONSTRAINT releases_store_listed_released
  CHECK (NOT store_listed OR state = 'delivered' OR imported_released);

CREATE INDEX IF NOT EXISTS idx_releases_org ON public.releases (org_id, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_releases_project ON public.releases (project_id);
CREATE INDEX IF NOT EXISTS idx_releases_contact ON public.releases (contact_id);
CREATE INDEX IF NOT EXISTS idx_releases_artwork ON public.releases (artwork_asset_id) WHERE artwork_asset_id IS NOT NULL;

CREATE TABLE IF NOT EXISTS public.release_items (
  id              uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  release_id      uuid NOT NULL REFERENCES public.releases(id) ON DELETE CASCADE,
  org_id          uuid NOT NULL REFERENCES public.organizations(id) ON DELETE CASCADE,
  position        int NOT NULL,
  song_track_id   uuid NOT NULL REFERENCES public.tracks(id),
  master_track_id uuid NOT NULL REFERENCES public.tracks(id),
  version_title   text,
  explicit        boolean NOT NULL DEFAULT false,
  created_at      timestamptz NOT NULL DEFAULT now(),
  updated_at      timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT release_items_position_key UNIQUE (release_id, position) DEFERRABLE INITIALLY DEFERRED
);

ALTER TABLE public.release_items DROP CONSTRAINT IF EXISTS release_items_position_positive;
ALTER TABLE public.release_items ADD CONSTRAINT release_items_position_positive CHECK (position >= 1);
ALTER TABLE public.release_items DROP CONSTRAINT IF EXISTS release_items_version_title_length;
ALTER TABLE public.release_items ADD CONSTRAINT release_items_version_title_length
  CHECK (version_title IS NULL OR char_length(version_title) <= 200);

CREATE INDEX IF NOT EXISTS idx_release_items_song ON public.release_items (song_track_id);
CREATE INDEX IF NOT EXISTS idx_release_items_master ON public.release_items (master_track_id);
CREATE INDEX IF NOT EXISTS idx_release_items_org ON public.release_items (org_id);

-- ── 3. Integrity ────────────────────────────────────────────────────────

CREATE OR REPLACE FUNCTION public.releases_integrity()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
BEGIN
  IF TG_OP = 'UPDATE' THEN
    IF NEW.org_id IS DISTINCT FROM OLD.org_id THEN
      RAISE EXCEPTION 'releases: a release cannot move between organizations' USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.project_id IS DISTINCT FROM OLD.project_id THEN
      RAISE EXCEPTION 'releases: a release keeps its project' USING ERRCODE = 'check_violation';
    END IF;
    NEW.updated_at := now();
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.projects p WHERE p.id = NEW.project_id AND p.org_id = NEW.org_id) THEN
    RAISE EXCEPTION 'releases: the project must be of the release''s organization' USING ERRCODE = 'check_violation';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.contacts c WHERE c.id = NEW.contact_id AND c.org_id = NEW.org_id) THEN
    RAISE EXCEPTION 'releases: the artist must be a contact of the release''s organization' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.artwork_asset_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.project_assets a
    WHERE a.id = NEW.artwork_asset_id
      AND a.org_id = NEW.org_id
      AND a.project_id = NEW.project_id
      AND a.kind IN ('artwork', 'photo')
  ) THEN
    RAISE EXCEPTION 'releases: the artwork must be an artwork or photo file of the release''s project' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END $$;

ALTER FUNCTION public.releases_integrity() OWNER TO postgres;
REVOKE ALL ON FUNCTION public.releases_integrity() FROM PUBLIC;

DROP TRIGGER IF EXISTS releases_integrity ON public.releases;
CREATE TRIGGER releases_integrity BEFORE INSERT OR UPDATE ON public.releases
  FOR EACH ROW EXECUTE FUNCTION public.releases_integrity();

CREATE OR REPLACE FUNCTION public.release_items_integrity()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE
  v_org uuid;
BEGIN
  IF TG_OP = 'UPDATE' THEN
    IF NEW.release_id IS DISTINCT FROM OLD.release_id THEN
      RAISE EXCEPTION 'release_items: an item stays on its release' USING ERRCODE = 'check_violation';
    END IF;
    NEW.updated_at := now();
  END IF;
  SELECT r.org_id INTO v_org FROM public.releases r WHERE r.id = NEW.release_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'release_items: release % does not exist', NEW.release_id USING ERRCODE = 'foreign_key_violation';
  END IF;
  IF NEW.org_id IS NOT NULL AND NEW.org_id IS DISTINCT FROM v_org THEN
    RAISE EXCEPTION 'release_items: org_id must be the release''s organization' USING ERRCODE = 'check_violation';
  END IF;
  NEW.org_id := v_org;
  IF NOT EXISTS (
    SELECT 1 FROM public.tracks s WHERE s.id = NEW.song_track_id AND s.org_id = v_org AND s.type = 'song'
  ) THEN
    RAISE EXCEPTION 'release_items: only a song of the release''s organization goes on a release' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.master_track_id IS DISTINCT FROM NEW.song_track_id AND NOT EXISTS (
    SELECT 1
    FROM public.track_links l
    JOIN public.tracks m ON m.id = l.to_track_id AND m.org_id = v_org
    WHERE l.from_track_id = NEW.song_track_id
      AND l.to_track_id = NEW.master_track_id
      AND l.relation IN ('master', 'instrumental', 'version')
  ) THEN
    RAISE EXCEPTION 'release_items: the master must be the song itself or linked to it as its master, instrumental or version'
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END $$;

ALTER FUNCTION public.release_items_integrity() OWNER TO postgres;
REVOKE ALL ON FUNCTION public.release_items_integrity() FROM PUBLIC;

DROP TRIGGER IF EXISTS release_items_integrity ON public.release_items;
CREATE TRIGGER release_items_integrity BEFORE INSERT OR UPDATE ON public.release_items
  FOR EACH ROW EXECUTE FUNCTION public.release_items_integrity();

-- Positions are exactly 1..n at COMMIT (deferred, so one transaction may
-- pass through a gap on its way to a contiguous list).
CREATE OR REPLACE FUNCTION public.release_items_contiguous()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE
  v_release uuid := COALESCE(NEW.release_id, OLD.release_id);
  v_count int;
  v_distinct int;
  v_min int;
  v_max int;
BEGIN
  SELECT count(*), count(DISTINCT position), min(position), max(position)
    INTO v_count, v_distinct, v_min, v_max
  FROM public.release_items WHERE release_id = v_release;
  IF v_count > 0 AND (v_distinct <> v_count OR v_min <> 1 OR v_max <> v_count) THEN
    RAISE EXCEPTION 'release_items: the positions of release % must be 1..n with no gap', v_release
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NULL;
END $$;

ALTER FUNCTION public.release_items_contiguous() OWNER TO postgres;
REVOKE ALL ON FUNCTION public.release_items_contiguous() FROM PUBLIC;

DROP TRIGGER IF EXISTS release_items_contiguous ON public.release_items;
CREATE CONSTRAINT TRIGGER release_items_contiguous
  AFTER INSERT OR UPDATE OR DELETE ON public.release_items
  DEFERRABLE INITIALLY DEFERRED
  FOR EACH ROW EXECUTE FUNCTION public.release_items_contiguous();

-- Guards that keep the two triggers above true after the fact.

CREATE OR REPLACE FUNCTION public.project_assets_release_artwork()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
BEGIN
  IF EXISTS (
    SELECT 1 FROM public.releases r
    WHERE r.artwork_asset_id = NEW.id
      AND (NEW.kind NOT IN ('artwork', 'photo') OR NEW.project_id IS DISTINCT FROM r.project_id)
  ) THEN
    RAISE EXCEPTION 'project_assets: this file is a release''s artwork; clear it there first' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END $$;

ALTER FUNCTION public.project_assets_release_artwork() OWNER TO postgres;
REVOKE ALL ON FUNCTION public.project_assets_release_artwork() FROM PUBLIC;

DROP TRIGGER IF EXISTS project_assets_release_artwork ON public.project_assets;
CREATE TRIGGER project_assets_release_artwork BEFORE UPDATE OF kind, project_id ON public.project_assets
  FOR EACH ROW EXECUTE FUNCTION public.project_assets_release_artwork();

CREATE OR REPLACE FUNCTION public.tracks_release_song_type()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
BEGIN
  IF NEW.type IS DISTINCT FROM 'song'
     AND EXISTS (SELECT 1 FROM public.release_items ri WHERE ri.song_track_id = NEW.id) THEN
    RAISE EXCEPTION 'tracks: this song is on a release and stays a song' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END $$;

ALTER FUNCTION public.tracks_release_song_type() OWNER TO postgres;
REVOKE ALL ON FUNCTION public.tracks_release_song_type() FROM PUBLIC;

DROP TRIGGER IF EXISTS tracks_release_song_type ON public.tracks;
CREATE TRIGGER tracks_release_song_type BEFORE UPDATE OF type ON public.tracks
  FOR EACH ROW WHEN (OLD.type = 'song' AND NEW.type IS DISTINCT FROM 'song')
  EXECUTE FUNCTION public.tracks_release_song_type();

CREATE OR REPLACE FUNCTION public.track_links_release_master()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
BEGIN
  IF TG_OP = 'UPDATE'
     AND NEW.from_track_id = OLD.from_track_id
     AND NEW.to_track_id = OLD.to_track_id
     AND NEW.relation IN ('master', 'instrumental', 'version') THEN
    RETURN NEW;
  END IF;
  IF EXISTS (
    SELECT 1 FROM public.release_items ri
    WHERE ri.song_track_id = OLD.from_track_id
      AND ri.master_track_id = OLD.to_track_id
      AND EXISTS (SELECT 1 FROM public.tracks t WHERE t.id = OLD.from_track_id)
      AND EXISTS (SELECT 1 FROM public.tracks t WHERE t.id = OLD.to_track_id)
  ) THEN
    RAISE EXCEPTION 'track_links: this link makes a track a release master; change the release first' USING ERRCODE = 'check_violation';
  END IF;
  RETURN COALESCE(NEW, OLD);
END $$;

ALTER FUNCTION public.track_links_release_master() OWNER TO postgres;
REVOKE ALL ON FUNCTION public.track_links_release_master() FROM PUBLIC;

DROP TRIGGER IF EXISTS track_links_release_master ON public.track_links;
CREATE TRIGGER track_links_release_master BEFORE UPDATE OR DELETE ON public.track_links
  FOR EACH ROW EXECUTE FUNCTION public.track_links_release_master();

-- ── 4. Reads ────────────────────────────────────────────────────────────

ALTER TABLE public.releases ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.release_items ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS org_member_read ON public.releases;
CREATE POLICY org_member_read ON public.releases
  FOR SELECT
  TO authenticated
  USING (
    org_id IS NOT NULL
    AND public.has_org_cap(org_id, 'catalog.read')
    AND public.can_see_org_project(org_id, project_id)
  );

DROP POLICY IF EXISTS org_member_read ON public.release_items;
CREATE POLICY org_member_read ON public.release_items
  FOR SELECT
  TO authenticated
  USING (
    EXISTS (
      SELECT 1 FROM public.releases r
      WHERE r.id = release_items.release_id
        AND r.org_id IS NOT NULL
        AND r.org_id = release_items.org_id
        AND public.has_org_cap(r.org_id, 'catalog.read')
        AND public.can_see_org_project(r.org_id, r.project_id)
    )
  );

-- Writes: service role only (141 §3c's trigger; no write policy exists).
DROP TRIGGER IF EXISTS labelos_org_rows_service_only ON public.releases;
CREATE TRIGGER labelos_org_rows_service_only BEFORE INSERT OR UPDATE OR DELETE ON public.releases
  FOR EACH ROW EXECUTE FUNCTION public.labelos_org_rows_service_only('self', 'org_id');
DROP TRIGGER IF EXISTS labelos_org_rows_service_only ON public.release_items;
CREATE TRIGGER labelos_org_rows_service_only BEFORE INSERT OR UPDATE OR DELETE ON public.release_items
  FOR EACH ROW EXECUTE FUNCTION public.labelos_org_rows_service_only('self', 'org_id');

-- ── 5. Tracklist writes ─────────────────────────────────────────────────
-- SECURITY INVOKER, service_role only: the route has authorised the member
-- and the release; these only make a multi-row change atomic. Both check
-- the release is of p_org, so a wrong pair from the route changes nothing.

CREATE OR REPLACE FUNCTION public.labelos_release_items_reorder(p_org uuid, p_release uuid, p_items uuid[])
RETURNS void
LANGUAGE plpgsql
SET search_path = public
AS $$
DECLARE
  v_count int;
BEGIN
  PERFORM 1 FROM public.releases WHERE id = p_release AND org_id = p_org FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'release % not found', p_release USING ERRCODE = 'no_data_found';
  END IF;
  SELECT count(*) INTO v_count FROM public.release_items WHERE release_id = p_release;
  IF coalesce(array_length(p_items, 1), 0) <> v_count
     OR (SELECT count(DISTINCT x) FROM unnest(p_items) x) <> v_count
     OR EXISTS (
       SELECT 1 FROM unnest(p_items) x
       WHERE NOT EXISTS (SELECT 1 FROM public.release_items ri WHERE ri.id = x AND ri.release_id = p_release)
     ) THEN
    RAISE EXCEPTION 'order must list every item of the release exactly once' USING ERRCODE = 'invalid_parameter_value';
  END IF;
  UPDATE public.release_items ri
  SET position = o.ord
  FROM unnest(p_items) WITH ORDINALITY AS o(id, ord)
  WHERE ri.id = o.id AND ri.release_id = p_release AND ri.position IS DISTINCT FROM o.ord::int;
END;
$$;

CREATE OR REPLACE FUNCTION public.labelos_release_item_remove(p_org uuid, p_release uuid, p_item uuid)
RETURNS boolean
LANGUAGE plpgsql
SET search_path = public
AS $$
DECLARE
  v_position int;
BEGIN
  PERFORM 1 FROM public.releases WHERE id = p_release AND org_id = p_org FOR UPDATE;
  IF NOT FOUND THEN
    RETURN false;
  END IF;
  DELETE FROM public.release_items WHERE id = p_item AND release_id = p_release RETURNING position INTO v_position;
  IF NOT FOUND THEN
    RETURN false;
  END IF;
  UPDATE public.release_items SET position = position - 1 WHERE release_id = p_release AND position > v_position;
  RETURN true;
END;
$$;

ALTER FUNCTION public.labelos_release_items_reorder(uuid, uuid, uuid[]) OWNER TO postgres;
ALTER FUNCTION public.labelos_release_item_remove(uuid, uuid, uuid) OWNER TO postgres;
REVOKE ALL ON FUNCTION public.labelos_release_items_reorder(uuid, uuid, uuid[]) FROM PUBLIC, anon, authenticated;
REVOKE ALL ON FUNCTION public.labelos_release_item_remove(uuid, uuid, uuid) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.labelos_release_items_reorder(uuid, uuid, uuid[]) TO service_role;
GRANT EXECUTE ON FUNCTION public.labelos_release_item_remove(uuid, uuid, uuid) TO service_role;

-- ── 6. Ownerless org links ──────────────────────────────────────────────

ALTER TABLE public.project_contacts ALTER COLUMN user_id DROP NOT NULL;

-- ── 7. "On a release" makes a mix finished ──────────────────────────────
-- 141's rule, unchanged, plus the release arm (lib/labelos/org-read,
-- lib/labelos/org-audio, lib/labelos/releases#countsAsOnRelease).

CREATE OR REPLACE FUNCTION public.labelos_track_is_finished(p_track uuid)
RETURNS boolean
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
  SELECT NOT EXISTS (
      SELECT 1 FROM public.track_links l
      WHERE l.to_track_id = p_track AND l.relation NOT IN ('master', 'instrumental')
    )
    AND NOT EXISTS (SELECT 1 FROM public.song_beats sb WHERE sb.beat_track_id = p_track)
    AND (
      EXISTS (
        SELECT 1
        FROM public.track_links l
        JOIN public.tracks s ON s.id = l.from_track_id AND s.type = 'song'
        JOIN public.tracks t ON t.id = l.to_track_id AND t.org_id = s.org_id
        WHERE l.to_track_id = p_track AND l.relation IN ('master', 'instrumental')
      )
      OR EXISTS (
        SELECT 1 FROM public.tracks t
        WHERE t.id = p_track AND t.type = 'song' AND t.song_stage = 'selected'
      )
      OR EXISTS (
        SELECT 1
        FROM public.tracks t
        JOIN public.release_items ri ON ri.song_track_id = t.id
        JOIN public.releases r ON r.id = ri.release_id AND r.org_id = t.org_id
        WHERE t.id = p_track AND t.type = 'song' AND r.state NOT IN ('cancelled')
      )
    );
$$;

ALTER FUNCTION public.labelos_track_is_finished(uuid) OWNER TO postgres;
REVOKE ALL ON FUNCTION public.labelos_track_is_finished(uuid) FROM PUBLIC;
REVOKE ALL ON FUNCTION public.labelos_track_is_finished(uuid) FROM anon, authenticated;

NOTIFY pgrst, 'reload schema';


-- ═════════════ 145_labelos_ownerless_workspace_rows.sql ═════════════
-- 145_labelos_ownerless_workspace_rows.sql
-- Label OS (LABEL-17): org rows have NO owner on the rest of the #44 tables.
--
-- LABEL OS — NOT APPLIED. Apply at the final merge of the Label OS branch
-- into main, after 144 (docs/bstudio-label-os/16-execution-runbook.md).
--
-- The rule 139 set for contacts, 142 for projects / tracks / track_links,
-- 143 for project_assets and 144 started for project_contacts: an org row
-- carries no user_id, so no producer route — every one filters on user_id —
-- and no producer-era owner policy (user_id = auth.uid()) can ever reach it.
-- Carried from LABEL-14 (#70) and LABEL-16 (#72): before the org artist
-- workspace writes these tables, the database must refuse an OWNED org row
-- and keep producer rows owned.
--
-- Tables (each has a #44 same-owner trigger that 141 §4 gave an org path):
--   project_contacts      (122; user_id already nullable since 144)
--   contact_track_states  (123)
--   artist_portals        (125)
--   artist_messages       (130)
--   song_beats            (132)
-- track_links (142) and project_assets (143) already hold the rule.
-- project_comments is not one of them: its user_id is the commenter, a
-- nullable author column since 011, not an owner.
--
-- A CHECK cannot see the parent row, so the rule lives in each trigger:
--   org path   — every parent in one non-null org AND NEW.user_id IS NULL,
--                else "an org row has no owner";
--   owner path — unchanged (every parent owned by NEW.user_id, all producer
--                rows), which already refuses a producer row with no
--                user_id: NULL equals nothing.
-- The triggers fire on INSERT and on UPDATE OF user_id (and the parent
-- columns), as 122–132 declared them, so setting an owner on an org row
-- later is refused too.
--
-- Data: any org row written with an owner before this migration (only the
-- local check fixtures ever did; nothing is applied on production) is made
-- ownerless first, so the triggers' new rule describes every row.
--
-- Proven as anon / authenticated / service_role in
-- supabase/local/checks/145_labelos_ownerless_workspace_rows.sql.
--
-- Idempotent: CREATE OR REPLACE; the UPDATEs and DROP NOT NULL are no-ops
-- on a replay.

-- ── Nullable owners ─────────────────────────────────────────────────────

ALTER TABLE public.contact_track_states ALTER COLUMN user_id DROP NOT NULL;
ALTER TABLE public.artist_portals ALTER COLUMN user_id DROP NOT NULL;
ALTER TABLE public.artist_messages ALTER COLUMN user_id DROP NOT NULL;
ALTER TABLE public.song_beats ALTER COLUMN user_id DROP NOT NULL;
ALTER TABLE public.project_contacts ALTER COLUMN user_id DROP NOT NULL;

-- ── Triggers: the org path requires no owner ────────────────────────────

-- 122
CREATE OR REPLACE FUNCTION public.project_contacts_same_owner()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
BEGIN
  IF EXISTS (
    SELECT 1 FROM public.projects p
    JOIN public.contacts c ON c.id = NEW.contact_id AND c.org_id = p.org_id
    WHERE p.id = NEW.project_id AND p.org_id IS NOT NULL
  ) THEN
    IF NEW.user_id IS NOT NULL THEN
      RAISE EXCEPTION 'project_contacts: an org row has no owner (user_id must be NULL)';
    END IF;
    RETURN NEW;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.projects p WHERE p.id = NEW.project_id AND p.user_id = NEW.user_id AND p.org_id IS NULL) THEN
    RAISE EXCEPTION 'project_contacts: project % is not owned by %', NEW.project_id, NEW.user_id;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.contacts c WHERE c.id = NEW.contact_id AND c.user_id = NEW.user_id AND c.org_id IS NULL) THEN
    RAISE EXCEPTION 'project_contacts: contact % is not owned by %', NEW.contact_id, NEW.user_id;
  END IF;
  RETURN NEW;
END $$;

-- 123
CREATE OR REPLACE FUNCTION public.contact_track_states_same_owner()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
BEGIN
  IF EXISTS (
    SELECT 1 FROM public.contacts c
    JOIN public.tracks t ON t.id = NEW.track_id AND t.org_id = c.org_id
    WHERE c.id = NEW.contact_id AND c.org_id IS NOT NULL
      AND (NEW.project_id IS NULL OR EXISTS (
        SELECT 1 FROM public.projects p WHERE p.id = NEW.project_id AND p.org_id = c.org_id
      ))
  ) THEN
    IF NEW.user_id IS NOT NULL THEN
      RAISE EXCEPTION 'contact_track_states: an org row has no owner (user_id must be NULL)';
    END IF;
    RETURN NEW;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.contacts c WHERE c.id = NEW.contact_id AND c.user_id = NEW.user_id AND c.org_id IS NULL) THEN
    RAISE EXCEPTION 'contact_track_states: contact % is not owned by %', NEW.contact_id, NEW.user_id;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.tracks t WHERE t.id = NEW.track_id AND t.user_id = NEW.user_id AND t.org_id IS NULL) THEN
    RAISE EXCEPTION 'contact_track_states: track % is not owned by %', NEW.track_id, NEW.user_id;
  END IF;
  RETURN NEW;
END $$;

-- 125
CREATE OR REPLACE FUNCTION public.artist_portals_same_owner()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
BEGIN
  IF EXISTS (SELECT 1 FROM public.contacts c WHERE c.id = NEW.contact_id AND c.org_id IS NOT NULL) THEN
    IF NEW.user_id IS NOT NULL THEN
      RAISE EXCEPTION 'artist_portals: an org row has no owner (user_id must be NULL)';
    END IF;
    RETURN NEW;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.contacts c WHERE c.id = NEW.contact_id AND c.user_id = NEW.user_id AND c.org_id IS NULL) THEN
    RAISE EXCEPTION 'artist_portals: contact % is not owned by %', NEW.contact_id, NEW.user_id;
  END IF;
  RETURN NEW;
END $$;

-- 130
CREATE OR REPLACE FUNCTION public.artist_messages_same_owner()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
BEGIN
  IF EXISTS (
    SELECT 1 FROM public.contacts c
    WHERE c.id = NEW.contact_id AND c.org_id IS NOT NULL
      AND (NEW.project_id IS NULL OR EXISTS (
        SELECT 1 FROM public.projects p WHERE p.id = NEW.project_id AND p.org_id = c.org_id
      ))
  ) THEN
    IF NEW.user_id IS NOT NULL THEN
      RAISE EXCEPTION 'artist_messages: an org row has no owner (user_id must be NULL)';
    END IF;
    RETURN NEW;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.contacts c WHERE c.id = NEW.contact_id AND c.user_id = NEW.user_id AND c.org_id IS NULL) THEN
    RAISE EXCEPTION 'artist_messages: contact % is not owned by %', NEW.contact_id, NEW.user_id;
  END IF;
  IF NEW.project_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.projects p WHERE p.id = NEW.project_id AND p.user_id = NEW.user_id AND p.org_id IS NULL
  ) THEN
    RAISE EXCEPTION 'artist_messages: project % is not owned by %', NEW.project_id, NEW.user_id;
  END IF;
  RETURN NEW;
END $$;

-- 132
CREATE OR REPLACE FUNCTION public.song_beats_same_owner()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
BEGIN
  IF EXISTS (
    SELECT 1 FROM public.tracks s
    JOIN public.tracks b ON b.id = NEW.beat_track_id AND b.org_id = s.org_id
    WHERE s.id = NEW.song_track_id AND s.org_id IS NOT NULL
  ) THEN
    IF NEW.user_id IS NOT NULL THEN
      RAISE EXCEPTION 'song_beats: an org row has no owner (user_id must be NULL)';
    END IF;
    RETURN NEW;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.tracks t WHERE t.id = NEW.song_track_id AND t.user_id = NEW.user_id AND t.org_id IS NULL) THEN
    RAISE EXCEPTION 'song_beats: song % is not owned by %', NEW.song_track_id, NEW.user_id;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.tracks t WHERE t.id = NEW.beat_track_id AND t.user_id = NEW.user_id AND t.org_id IS NULL) THEN
    RAISE EXCEPTION 'song_beats: beat % is not owned by %', NEW.beat_track_id, NEW.user_id;
  END IF;
  RETURN NEW;
END $$;

-- ── Data: owned org rows become ownerless ───────────────────────────────
-- Each UPDATE sets user_id on rows the org path accepts, so the new
-- triggers pass them.

UPDATE public.project_contacts pc SET user_id = NULL
  FROM public.projects p
 WHERE p.id = pc.project_id AND p.org_id IS NOT NULL AND pc.user_id IS NOT NULL;
UPDATE public.contact_track_states s SET user_id = NULL
  FROM public.contacts c
 WHERE c.id = s.contact_id AND c.org_id IS NOT NULL AND s.user_id IS NOT NULL;
UPDATE public.artist_portals ap SET user_id = NULL
  FROM public.contacts c
 WHERE c.id = ap.contact_id AND c.org_id IS NOT NULL AND ap.user_id IS NOT NULL;
UPDATE public.artist_messages m SET user_id = NULL
  FROM public.contacts c
 WHERE c.id = m.contact_id AND c.org_id IS NOT NULL AND m.user_id IS NOT NULL;
UPDATE public.song_beats sb SET user_id = NULL
  FROM public.tracks s
 WHERE s.id = sb.song_track_id AND s.org_id IS NOT NULL AND sb.user_id IS NOT NULL;

NOTIFY pgrst, 'reload schema';


-- ═════════════ 146_labelos_audit_rpc.sql ═════════════
-- 146_labelos_audit_rpc.sql
-- Label OS (LABEL-19): audit-class mutations that commit WITH their event.
--
-- LABEL OS — NOT APPLIED. Apply at the final merge of the Label OS branch
-- into main, after 136–145 (docs/bstudio-label-os/16-execution-runbook.md).
-- Never part of supabase/apply/pending.sql.
--
-- SQL functions only; no table or column changes. Until now an audit event
-- (06 §6) was written by the route AFTER the mutation, and a failed write
-- was undone by a best-effort compensating write that could itself fail.
-- Each function below does the mutation AND the activity_events insert in
-- one transaction: if the audit insert fails, the mutation rolls back, and
-- no compensation code exists to get wrong.
--
--   labelos_audit_member_update        role / functions / scope / abilities
--                                      (+ clearing the artist list when the
--                                      member ends up seeing the whole org —
--                                      decided here, under the row lock)
--   labelos_audit_member_remove        remove a member
--   labelos_audit_member_artists_set   replace an artists-scoped member's list
--   labelos_audit_invitation_create    create an invitation (one pending per
--                                      address, decided under a lock)
--   labelos_audit_invitation_revoke    revoke a pending invitation
--
-- (Accepting an invitation is 138's labelos_accept_invitation, which already
-- writes `member.joined` in its own transaction.) Split transitions,
-- approvals and delivery have no mutating route yet (LABEL-30/32/33); each
-- adds its function here-style when its route lands.
--
-- Security: SECURITY DEFINER, owned by postgres (owner of 136's tables),
-- EXECUTE for service_role ONLY — `authenticated` and `anon` have none,
-- asserted in supabase/local/checks/146_labelos_audit_rpc.sql. The functions
-- do not re-derive who may act: the route has already run requireOrgCapability
-- and planMemberChange, and the service role is the only caller. They do
-- refuse what the database can know for itself (unknown verb, a payload that
-- looks like a secret, a row of another org).
--
-- Also here, because the activity feed needs a complete history (08 §B5):
-- orgs created by 137's backfill never got an `org.created` event (only
-- POST /api/profile records one). One is written for each org without one,
-- stamped with the org's own created_at and marked `source: 'backfill'`.
--
-- Idempotent: CREATE OR REPLACE; the backfill inserts only where missing.

-- ── private helper: the one event insert ─────────────────────────────────
-- Not callable by anyone but the functions below (owner-only EXECUTE).

CREATE OR REPLACE FUNCTION public.labelos_audit_insert(
  p_org uuid,
  p_actor uuid,
  p_verb text,
  p_subject_type text,
  p_subject_id uuid,
  p_payload jsonb
) RETURNS uuid
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path = public
AS $fn$
DECLARE
  v_id uuid;
BEGIN
  IF p_payload IS NULL OR jsonb_typeof(p_payload) <> 'object' THEN
    RAISE EXCEPTION 'audit payload must be an object' USING ERRCODE = '22023';
  END IF;
  -- Same rule as recordEvent: a bearer secret never lands in the log (06 §5).
  IF p_payload::text ~* '"[^"]*(token|password|secret)[^"]*"\s*:' THEN
    RAISE EXCEPTION 'audit payload carries a secret-looking key' USING ERRCODE = '22023';
  END IF;
  IF pg_column_size(p_payload) > 16384 THEN
    RAISE EXCEPTION 'audit payload is too large' USING ERRCODE = '22023';
  END IF;

  INSERT INTO public.activity_events (org_id, actor_id, verb, subject_type, subject_id, payload, audit, visibility)
  VALUES (p_org, p_actor, p_verb, p_subject_type, p_subject_id, p_payload, true, 'internal')
  RETURNING id INTO v_id;
  RETURN v_id;
END;
$fn$;

ALTER FUNCTION public.labelos_audit_insert(uuid, uuid, text, text, uuid, jsonb) OWNER TO postgres;
REVOKE ALL ON FUNCTION public.labelos_audit_insert(uuid, uuid, text, text, uuid, jsonb) FROM PUBLIC, anon, authenticated, service_role;

-- ── member update ────────────────────────────────────────────────────────
-- p_patch holds only the keys that change: role, functions, scope,
-- cap_grants, cap_revokes. A member who ends up seeing the whole org (role
-- other than `artist` AND scope `org`, 06 §2.5) has their artist list
-- dropped, so a later limit starts from none; the dropped ids are added to
-- the payload as contact_ids {from, to: []}. That decision is made here from
-- the row as it is under the lock, not from what the route read earlier.
-- Answers {"member": <row>} or {"error": "not_found"}.
-- A change that would leave the org without an owner is refused by 136's
-- deferred trigger at COMMIT, which rolls the event back with it.

CREATE OR REPLACE FUNCTION public.labelos_audit_member_update(
  p_org uuid,
  p_actor uuid,
  p_user uuid,
  p_patch jsonb,
  p_verb text,
  p_payload jsonb
) RETURNS jsonb
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path = public
AS $fn$
DECLARE
  v_row     public.org_members%ROWTYPE;
  v_cleared uuid[] := '{}';
  v_payload jsonb := p_payload;
BEGIN
  IF p_verb NOT IN ('member.role_changed', 'member.capabilities_changed', 'member.scope_changed') THEN
    RAISE EXCEPTION 'unknown member verb %', p_verb USING ERRCODE = '22023';
  END IF;
  IF p_patch IS NULL OR jsonb_typeof(p_patch) <> 'object' OR p_patch = '{}'::jsonb THEN
    RAISE EXCEPTION 'empty member patch' USING ERRCODE = '22023';
  END IF;

  PERFORM 1 FROM public.org_members WHERE org_id = p_org AND user_id = p_user FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('error', 'not_found');
  END IF;

  UPDATE public.org_members m
  SET role        = COALESCE(p_patch->>'role', m.role),
      functions   = CASE WHEN p_patch ? 'functions'   THEN ARRAY(SELECT jsonb_array_elements_text(p_patch->'functions'))   ELSE m.functions END,
      scope       = COALESCE(p_patch->>'scope', m.scope),
      cap_grants  = CASE WHEN p_patch ? 'cap_grants'  THEN ARRAY(SELECT jsonb_array_elements_text(p_patch->'cap_grants'))  ELSE m.cap_grants END,
      cap_revokes = CASE WHEN p_patch ? 'cap_revokes' THEN ARRAY(SELECT jsonb_array_elements_text(p_patch->'cap_revokes')) ELSE m.cap_revokes END
  WHERE m.org_id = p_org AND m.user_id = p_user
  RETURNING m.* INTO v_row;

  IF v_row.role <> 'artist' AND v_row.scope <> 'artists' THEN
    WITH gone AS (
      DELETE FROM public.member_artist_scopes s
      WHERE s.org_id = p_org AND s.user_id = p_user
      RETURNING s.contact_id
    )
    SELECT COALESCE(array_agg(contact_id ORDER BY contact_id), '{}') INTO v_cleared FROM gone;
    IF cardinality(v_cleared) > 0 THEN
      v_payload := v_payload || jsonb_build_object('contact_ids', jsonb_build_object('from', to_jsonb(v_cleared), 'to', '[]'::jsonb));
    END IF;
  END IF;

  PERFORM public.labelos_audit_insert(p_org, p_actor, p_verb, 'member', p_user, v_payload);

  RETURN jsonb_build_object('member', jsonb_build_object(
    'user_id', v_row.user_id,
    'role', v_row.role,
    'functions', to_jsonb(v_row.functions),
    'scope', v_row.scope,
    'cap_grants', to_jsonb(v_row.cap_grants),
    'cap_revokes', to_jsonb(v_row.cap_revokes),
    'joined_at', v_row.joined_at,
    'invited_by', v_row.invited_by
  ));
END;
$fn$;

ALTER FUNCTION public.labelos_audit_member_update(uuid, uuid, uuid, jsonb, text, jsonb) OWNER TO postgres;
REVOKE ALL ON FUNCTION public.labelos_audit_member_update(uuid, uuid, uuid, jsonb, text, jsonb) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.labelos_audit_member_update(uuid, uuid, uuid, jsonb, text, jsonb) TO service_role;

-- ── member remove ────────────────────────────────────────────────────────
-- The membership's artist list goes with it (FK cascade) and comes back with
-- it if anything below fails: it is one transaction.

CREATE OR REPLACE FUNCTION public.labelos_audit_member_remove(
  p_org uuid,
  p_actor uuid,
  p_user uuid,
  p_payload jsonb
) RETURNS jsonb
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path = public
AS $fn$
DECLARE
  v_gone int;
BEGIN
  DELETE FROM public.org_members WHERE org_id = p_org AND user_id = p_user;
  GET DIAGNOSTICS v_gone = ROW_COUNT;
  IF v_gone = 0 THEN
    RETURN jsonb_build_object('error', 'not_found');
  END IF;
  PERFORM public.labelos_audit_insert(p_org, p_actor, 'member.removed', 'member', p_user, p_payload);
  RETURN jsonb_build_object('removed', true);
END;
$fn$;

ALTER FUNCTION public.labelos_audit_member_remove(uuid, uuid, uuid, jsonb) OWNER TO postgres;
REVOKE ALL ON FUNCTION public.labelos_audit_member_remove(uuid, uuid, uuid, jsonb) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.labelos_audit_member_remove(uuid, uuid, uuid, jsonb) TO service_role;

-- ── member artists ───────────────────────────────────────────────────────
-- Make the list exactly p_contact_ids (139's same-org trigger still judges
-- each row). Only for a member limited to some artists — checked here under
-- the row lock, so a widening that lands first is not undone by a stale list.
-- Answers {"contact_ids": [...]}, {"error": "not_found"} or
-- {"error": "not_scoped"}.

CREATE OR REPLACE FUNCTION public.labelos_audit_member_artists_set(
  p_org uuid,
  p_actor uuid,
  p_user uuid,
  p_contact_ids uuid[],
  p_payload jsonb
) RETURNS jsonb
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path = public
AS $fn$
DECLARE
  v_ids   uuid[];
  v_role  text;
  v_scope text;
BEGIN
  SELECT m.role, m.scope INTO v_role, v_scope
  FROM public.org_members m WHERE m.org_id = p_org AND m.user_id = p_user FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('error', 'not_found');
  END IF;
  IF v_role <> 'artist' AND v_scope <> 'artists' THEN
    RETURN jsonb_build_object('error', 'not_scoped');
  END IF;
  v_ids := COALESCE(ARRAY(SELECT DISTINCT c FROM unnest(p_contact_ids) AS c ORDER BY c), '{}');

  DELETE FROM public.member_artist_scopes s
  WHERE s.org_id = p_org AND s.user_id = p_user AND NOT (s.contact_id = ANY (v_ids));
  INSERT INTO public.member_artist_scopes (org_id, user_id, contact_id)
  SELECT p_org, p_user, c FROM unnest(v_ids) AS c
  ON CONFLICT (org_id, user_id, contact_id) DO NOTHING;

  PERFORM public.labelos_audit_insert(p_org, p_actor, 'member.artists_changed', 'member', p_user, p_payload);
  RETURN jsonb_build_object('contact_ids', to_jsonb(v_ids));
END;
$fn$;

ALTER FUNCTION public.labelos_audit_member_artists_set(uuid, uuid, uuid, uuid[], jsonb) OWNER TO postgres;
REVOKE ALL ON FUNCTION public.labelos_audit_member_artists_set(uuid, uuid, uuid, uuid[], jsonb) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.labelos_audit_member_artists_set(uuid, uuid, uuid, uuid[], jsonb) TO service_role;

-- ── invitation create ────────────────────────────────────────────────────
-- One pending invitation per address per org, decided HERE under a
-- transaction-scoped advisory lock — the route no longer has to insert,
-- re-check and delete to survive two simultaneous requests (a delete would
-- leave an `invitation.created` event with nothing behind it).
-- Answers {"invitation": <row>} or {"error": "pending", "id": <existing>}.
-- The token hash (never the token) is stored, exactly as before.

CREATE OR REPLACE FUNCTION public.labelos_audit_invitation_create(
  p_org uuid,
  p_actor uuid,
  p_email text,
  p_role text,
  p_functions text[],
  p_artist_ids uuid[],
  p_token_hash text,
  p_expires_at timestamptz,
  p_payload jsonb
) RETURNS jsonb
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path = public
AS $fn$
DECLARE
  v_pending uuid;
  v_inv     public.org_invitations%ROWTYPE;
BEGIN
  PERFORM pg_advisory_xact_lock(hashtextextended(p_org::text || ':' || p_email, 0));

  SELECT i.id INTO v_pending
  FROM public.org_invitations i
  WHERE i.org_id = p_org AND i.email = p_email
    AND i.accepted_at IS NULL AND i.revoked_at IS NULL AND i.expires_at > now()
  ORDER BY i.created_at ASC, i.id ASC
  LIMIT 1;
  IF v_pending IS NOT NULL THEN
    RETURN jsonb_build_object('error', 'pending', 'id', v_pending);
  END IF;

  INSERT INTO public.org_invitations (org_id, email, role, functions, artist_ids, token_hash, expires_at, invited_by)
  VALUES (p_org, p_email, p_role, COALESCE(p_functions, '{}'), COALESCE(p_artist_ids, '{}'), p_token_hash, p_expires_at, p_actor)
  RETURNING * INTO v_inv;

  PERFORM public.labelos_audit_insert(p_org, p_actor, 'invitation.created', 'invitation', v_inv.id, p_payload);

  RETURN jsonb_build_object('invitation', jsonb_build_object(
    'id', v_inv.id,
    'email', v_inv.email,
    'role', v_inv.role,
    'functions', to_jsonb(v_inv.functions),
    'artist_ids', to_jsonb(v_inv.artist_ids),
    'expires_at', v_inv.expires_at,
    'accepted_at', v_inv.accepted_at,
    'revoked_at', v_inv.revoked_at,
    'created_at', v_inv.created_at
  ));
END;
$fn$;

ALTER FUNCTION public.labelos_audit_invitation_create(uuid, uuid, text, text, text[], uuid[], text, timestamptz, jsonb) OWNER TO postgres;
REVOKE ALL ON FUNCTION public.labelos_audit_invitation_create(uuid, uuid, text, text, text[], uuid[], text, timestamptz, jsonb) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.labelos_audit_invitation_create(uuid, uuid, text, text, text[], uuid[], text, timestamptz, jsonb) TO service_role;

-- ── invitation revoke ────────────────────────────────────────────────────
-- Only a still-pending row. Answers {"revoked_at": ...} or
-- {"error": "not_pending"} (the route reads the row to say which of
-- already-revoked / accepted / missing it is).

CREATE OR REPLACE FUNCTION public.labelos_audit_invitation_revoke(
  p_org uuid,
  p_actor uuid,
  p_id uuid,
  p_payload jsonb
) RETURNS jsonb
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path = public
AS $fn$
DECLARE
  v_at timestamptz;
BEGIN
  UPDATE public.org_invitations i
  SET revoked_at = now()
  WHERE i.org_id = p_org AND i.id = p_id AND i.accepted_at IS NULL AND i.revoked_at IS NULL
  RETURNING i.revoked_at INTO v_at;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('error', 'not_pending');
  END IF;
  PERFORM public.labelos_audit_insert(p_org, p_actor, 'invitation.revoked', 'invitation', p_id, p_payload);
  RETURN jsonb_build_object('revoked_at', v_at);
END;
$fn$;

ALTER FUNCTION public.labelos_audit_invitation_revoke(uuid, uuid, uuid, jsonb) OWNER TO postgres;
REVOKE ALL ON FUNCTION public.labelos_audit_invitation_revoke(uuid, uuid, uuid, jsonb) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.labelos_audit_invitation_revoke(uuid, uuid, uuid, jsonb) TO service_role;

-- ── org.created backfill ─────────────────────────────────────────────────
-- Orgs 137 created for existing producers have no `org.created`. Everyday
-- (non-audit) event, internal, dated to the org's own creation.

INSERT INTO public.activity_events (org_id, actor_id, verb, subject_type, subject_id, payload, audit, visibility, created_at)
SELECT o.id, o.created_by, 'org.created', 'org', o.id,
       jsonb_build_object('kind', o.kind, 'source', 'backfill'),
       false, 'internal', o.created_at
FROM public.organizations o
WHERE NOT EXISTS (
  SELECT 1 FROM public.activity_events e WHERE e.org_id = o.id AND e.verb = 'org.created'
);

NOTIFY pgrst, 'reload schema';


-- ═════════════ 147_labelos_activity_feeds.sql ═════════════
-- 147_labelos_activity_feeds.sql
-- Label OS (LABEL-20): the activity feeds, and the artist-scope predicate the
-- activity_events read policy was missing.
--
-- LABEL OS — NOT APPLIED. Apply at the final merge of the Label OS branch
-- into main, after 146 (docs/bstudio-label-os/16-execution-runbook.md).
-- Never part of supabase/apply/pending.sql.
--
-- What changes:
--
--  1. user_profiles.last_seen_overview_at — already created by 136 (it is
--     in the table's CREATE). The ADD COLUMN IF NOT EXISTS below is a no-op
--     there and only keeps this migration true on its own. It is written by
--     the member's own session through the service-role route that
--     `POST /api/org/[orgId]/overview/seen` is, never through PostgREST:
--     136 gave user_profiles a SELECT policy and no write policy, and this
--     migration adds none. Who may READ it is unchanged: the user, and
--     co-members under 136's existing policy.
--
--  2. activity_events_member_read gains the artist-scope predicate (carried
--     from LABEL-19: 136's policy had none, so a member limited to some
--     artists — or a roster artist — reading the table with their own JWT saw
--     `artist` events of artists outside their scope, `song.created` carries
--     a title). The rule (the SQL twin of
--     lib/labelos/activity-feed.ts#eventVisibleTo, held equal by the local
--     check and by `can_see_artist` / `can_see_org_project`):
--
--       whole-org member                       → every event of the org
--       event names an artist (artist_id)      → that artist is in the scope
--       else event names a project (project_id)→ that project is in the scope
--       else                                   → NOBODY scoped
--
--     An event naming neither — member and invitation changes, org settings,
--     contact removals — is the organization's own business and is read by
--     whole-org members only. A song_id alone does not place an event (the
--     song events carry their artist or project). When an event names an
--     artist the artist alone decides, so a project the member can see does
--     not widen it.
--     Capability and visibility are unchanged from 136: catalog.read, and
--     business.read.internal for `internal` rows. Producer-era behaviour is
--     untouched: no producer table, policy or function is edited.
--
--     Cost (R-08). The policy adds NO per-row SECURITY DEFINER call. Every
--     scope disjunct is an uncorrelated subquery the planner hashes once per
--     statement: the caller's whole-org memberships, their own
--     member_artist_scopes rows (readable under 139's policy), and
--     `labelos_scoped_projects()` — the projects their scope reaches, one
--     set-returning call per statement — instead of can_see_artist /
--     can_see_org_project once per event. 139's trigger keeps a scope row's
--     contact inside its org, which is what lets the artist test stay a
--     plain lookup. (A per-row version measured 816 ms against 13 ms for the
--     newest 100 events of a scoped member at 100k events.)
--
--  3. Two partial indexes so the project and song feeds filter by index
--     (08 §B3) like the artist feed already does.
--
-- Idempotent: ADD COLUMN IF NOT EXISTS, CREATE OR REPLACE, DROP POLICY IF
-- EXISTS before CREATE POLICY, CREATE INDEX IF NOT EXISTS.

ALTER TABLE public.user_profiles
  ADD COLUMN IF NOT EXISTS last_seen_overview_at timestamptz;

-- ── labelos_scoped_projects ──────────────────────────────────────────────
-- The org projects the caller's artist scope reaches: a project that is an
-- in-scope artist's Inbox, or that links an in-scope artist through
-- project_contacts, and only a project OF THE ORG the scope row names — the
-- rule of can_see_org_project (141) for a member limited to some artists,
-- written as one set instead of a per-project test. Empty for a whole-org
-- member (who needs no scope). Scope only: capabilities are has_org_cap's job.
-- SECURITY DEFINER because project_contacts has no member policy.
-- EXECUTE for authenticated and anon, like can_see_artist / can_see_org_project:
-- the policy runs as the invoker for every role, and anon must evaluate it to
-- an empty result, not a permission error.

CREATE OR REPLACE FUNCTION public.labelos_scoped_projects()
RETURNS TABLE (org_id uuid, project_id uuid)
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
  SELECT p.org_id, p.id
  FROM public.member_artist_scopes s
  JOIN public.projects p ON p.org_id = s.org_id AND p.inbox_for_contact_id = s.contact_id
  WHERE s.user_id = auth.uid()
  UNION
  SELECT p.org_id, p.id
  FROM public.member_artist_scopes s
  JOIN public.project_contacts pc ON pc.contact_id = s.contact_id
  JOIN public.projects p ON p.id = pc.project_id AND p.org_id = s.org_id
  WHERE s.user_id = auth.uid();
$$;

ALTER FUNCTION public.labelos_scoped_projects() OWNER TO postgres;
REVOKE ALL ON FUNCTION public.labelos_scoped_projects() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.labelos_scoped_projects() TO authenticated, anon;

-- ── The policy ───────────────────────────────────────────────────────────
-- 136's two conditions, unchanged, plus scope. Each scope disjunct is
-- uncorrelated (no reference to the outer row inside its subquery), so each
-- is planned as a hashed subplan evaluated once.

DROP POLICY IF EXISTS activity_events_member_read ON public.activity_events;
CREATE POLICY activity_events_member_read ON public.activity_events
  FOR SELECT
  USING (
    (SELECT public.has_org_cap(org_id, 'catalog.read'))
    AND (visibility = 'artist' OR (SELECT public.has_org_cap(org_id, 'business.read.internal')))
    AND (
      org_id IN (
        SELECT om.org_id
        FROM public.org_members om
        WHERE om.user_id = (SELECT auth.uid())
          AND om.scope = 'org'
          AND om.role <> 'artist'
      )
      OR (
        artist_id IS NOT NULL
        AND (org_id, artist_id) IN (
          SELECT s.org_id, s.contact_id
          FROM public.member_artist_scopes s
          WHERE s.user_id = (SELECT auth.uid())
        )
      )
      OR (
        artist_id IS NULL
        AND project_id IS NOT NULL
        AND (org_id, project_id) IN (SELECT sp.org_id, sp.project_id FROM public.labelos_scoped_projects() sp)
      )
    )
  );

-- ── Feed indexes ─────────────────────────────────────────────────────────

CREATE INDEX IF NOT EXISTS idx_activity_events_project_created
  ON public.activity_events (project_id, created_at DESC)
  WHERE project_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_activity_events_song_created
  ON public.activity_events (song_id, created_at DESC)
  WHERE song_id IS NOT NULL;

NOTIFY pgrst, 'reload schema';


-- ═════════════ 148_labelos_project_members.sql ═════════════
-- 148_labelos_project_members.sql
-- Label OS (LABEL-21): external project members ("Shared with me").
--
-- LABEL OS — NOT APPLIED. Apply at the final merge of the Label OS branch
-- into main, after 136–146 (docs/bstudio-label-os/16-execution-runbook.md).
-- Never part of supabase/apply/pending.sql. (147 is LABEL-20's.)
--
-- A person with their OWN account is admitted to ONE org project as viewer,
-- commenter, contributor or editor (06 §2.6, W4). They are not an org member:
-- they hold a row in `project_members` and nothing else, so every org-level
-- check (`org_members`, `has_org_cap`) answers "no" for them by itself. The
-- SQL here is the database half; the routes are the real boundary (service
-- role), exactly like the rest of /api/org.
--
--   1. `project_members` (one table): who, which project, which role, whether
--      a viewer / commenter may download (`allow_downloads`, §2.6 "per
--      project"), an optional expiry. UNIQUE (project_id, user_id). A member's
--      project must be a project OF THE ROW'S ORG (trigger, like 141/142);
--      who / where never change after insert (trigger). Org rows: service role
--      only — no INSERT / UPDATE / DELETE grant for the API roles.
--   2. `org_invitations.project_allow_downloads`: the column an invitation
--      carries for `allow_downloads`. 136 already gave the table `project_id`
--      + `project_role` (both or neither).
--   3. `can_see_project(project)` — the SQL twin of the TypeScript project
--      reach: an org member who passes `catalog.read` + `can_see_org_project`
--      (scope), OR a live external membership (not expired, org not deleted).
--      SECURITY DEFINER STABLE, like the 141 helpers; called as
--      `(SELECT public.can_see_project(project_id))` so it runs once per
--      statement, never once per row of a big table.
--   4. RLS on `project_members`: SELECT only. A person reads their OWN row
--      while it is live (`can_see_project`); an org member with `share.external`
--      reads those of the projects their artist scope reaches (the whole
--      org for a member who sees it). No policy anywhere gives an external
--      member the project's tracks, files or comments: those are read through
--      the service-role routes, which apply `externalCan` (lib/labelos/
--      capabilities). tracks / projects / … keep 141's org_member_read +
--      org_member_guard untouched, so an external member's own JWT reads none
--      of them (asserted in supabase/local/checks/148_*.sql).
--   5. Audit functions (service_role only, one transaction each with their
--      `activity_events` row, the 146 pattern):
--        labelos_audit_project_invitation_create  invitation.created
--        labelos_audit_project_member_update      project.member_changed
--        labelos_audit_project_member_remove      project.member_removed
--      `labelos_audit_invitation_revoke` (146) already revokes a project
--      invitation unchanged.
--   6. `labelos_accept_invitation` (138/139) is REPLACED (same signature, so
--      a true replacement): a project invitation writes `project_members`,
--      never `org_members`, and records `project.member_added`. The invitee
--      is admitted to the project only; they are not made an org member. The
--      inviter must STILL hold `share.external` in the org at accept time
--      (an invitation does not outlive the authority that issued it) — read
--      through `labelos_user_has_cap`, which asks the one `has_org_cap`
--      definition about another user instead of copying its tables.
--      The org path is byte-for-byte 139's.
--   7. `labelos_audit_invitation_create` (146) is replaced with the same
--      signature, ignoring project invitations when it looks for a pending
--      org invitation, so an open project invite does not block (or get
--      mistaken for) an org one for the same address.
--
-- Proven as anon / authenticated users in
-- supabase/local/checks/148_labelos_project_members.sql and held by
-- src/lib/security/rls-final-state.test.ts.
--
-- Idempotent: IF NOT EXISTS, CREATE OR REPLACE, DROP ... IF EXISTS first.

-- ── 1. project_members ──────────────────────────────────────────────────

CREATE TABLE IF NOT EXISTS public.project_members (
  id              uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  org_id          uuid NOT NULL REFERENCES public.organizations(id) ON DELETE CASCADE,
  project_id      uuid NOT NULL REFERENCES public.projects(id) ON DELETE CASCADE,
  user_id         uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  role            text NOT NULL CHECK (role IN ('viewer', 'commenter', 'contributor', 'editor')),
  -- 06 §2.6: a viewer / commenter downloads masters only when the project
  -- allows it; contributors and editors always may.
  allow_downloads boolean NOT NULL DEFAULT false,
  -- Access ends on the next request after this passes (W4 step 6).
  expires_at      timestamptz,
  invited_by      uuid REFERENCES auth.users(id) ON DELETE SET NULL,
  invitation_id   uuid REFERENCES public.org_invitations(id) ON DELETE SET NULL,
  created_at      timestamptz NOT NULL DEFAULT now(),
  updated_at      timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT project_members_project_user_uniq UNIQUE (project_id, user_id)
);

CREATE INDEX IF NOT EXISTS idx_project_members_user ON public.project_members (user_id, org_id);
CREATE INDEX IF NOT EXISTS idx_project_members_org_project ON public.project_members (org_id, project_id);

ALTER TABLE public.org_invitations
  ADD COLUMN IF NOT EXISTS project_allow_downloads boolean NOT NULL DEFAULT false;

-- The member's project is a project OF THE ROW'S ORG (an org project, never
-- a producer one); and who / where never change after insert — a membership
-- is changed (role, downloads, expiry) or removed, never moved.
CREATE OR REPLACE FUNCTION public.project_members_integrity()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  IF TG_OP = 'UPDATE' AND (
    NEW.org_id IS DISTINCT FROM OLD.org_id
    OR NEW.project_id IS DISTINCT FROM OLD.project_id
    OR NEW.user_id IS DISTINCT FROM OLD.user_id
  ) THEN
    RAISE EXCEPTION 'project_members: org, project and user of a membership cannot change'
      USING ERRCODE = 'check_violation';
  END IF;
  IF TG_OP = 'INSERT' AND NOT EXISTS (
    SELECT 1 FROM public.projects p WHERE p.id = NEW.project_id AND p.org_id IS NOT NULL AND p.org_id = NEW.org_id
  ) THEN
    RAISE EXCEPTION 'project_members: project % is not a project of organization %', NEW.project_id, NEW.org_id
      USING ERRCODE = 'check_violation';
  END IF;
  IF TG_OP = 'UPDATE' THEN
    NEW.updated_at := now();
  END IF;
  RETURN NEW;
END;
$$;

ALTER FUNCTION public.project_members_integrity() OWNER TO postgres;
REVOKE ALL ON FUNCTION public.project_members_integrity() FROM PUBLIC;

DROP TRIGGER IF EXISTS project_members_integrity ON public.project_members;
CREATE TRIGGER project_members_integrity
  BEFORE INSERT OR UPDATE ON public.project_members
  FOR EACH ROW EXECUTE FUNCTION public.project_members_integrity();

-- ── 3. can_see_project ──────────────────────────────────────────────────
-- Does the caller reach this org project at all? An org member inside their
-- artist scope with catalog.read, or a live external member. False for a
-- producer project, a deleted org, an expired membership and anyone else.

CREATE OR REPLACE FUNCTION public.can_see_project(p_project uuid)
RETURNS boolean
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
  SELECT EXISTS (
    SELECT 1
    FROM public.projects p
    JOIN public.organizations o ON o.id = p.org_id AND o.deleted_at IS NULL
    WHERE p.id = p_project
      AND p.org_id IS NOT NULL
      AND (
        EXISTS (
          SELECT 1 FROM public.project_members m
          WHERE m.project_id = p.id
            AND m.org_id = p.org_id
            AND m.user_id = auth.uid()
            AND (m.expires_at IS NULL OR m.expires_at > now())
        )
        OR (
          public.has_org_cap(p.org_id, 'catalog.read')
          AND public.can_see_org_project(p.org_id, p.id)
        )
      )
  );
$$;

ALTER FUNCTION public.can_see_project(uuid) OWNER TO postgres;
REVOKE ALL ON FUNCTION public.can_see_project(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.can_see_project(uuid) TO authenticated, anon;

-- Is this user's capability in this org met? The one has_org_cap, asked
-- about another person: it reads auth.uid(), so the caller's identity is set
-- for the call and put back (transaction-local either way). Both places
-- Supabase's auth.uid() reads are set — `request.jwt.claims` (PostgREST 10+)
-- and the legacy `request.jwt.claim.sub` it prefers when present — so the
-- answer is the same on either. Both are put back exactly as they were; an
-- unset setting reads back as '{}' / '' for the rest of the transaction
-- (set_config cannot unset), which auth.uid() treats as no user, as before,
-- and which reverts when the transaction ends. service_role only: nobody who
-- can run it can pick whose answer the API roles get.
CREATE OR REPLACE FUNCTION public.labelos_user_has_cap(p_org uuid, p_user uuid, p_cap text)
RETURNS boolean
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_claims text := coalesce(current_setting('request.jwt.claims', true), '{}');
  v_sub    text := coalesce(current_setting('request.jwt.claim.sub', true), '');
  v_ok     boolean;
BEGIN
  IF p_org IS NULL OR p_user IS NULL OR p_cap IS NULL THEN
    RETURN false;
  END IF;
  PERFORM set_config('request.jwt.claims', json_build_object('sub', p_user::text, 'role', 'authenticated')::text, true);
  PERFORM set_config('request.jwt.claim.sub', p_user::text, true);
  v_ok := public.has_org_cap(p_org, p_cap);
  PERFORM set_config('request.jwt.claims', v_claims, true);
  PERFORM set_config('request.jwt.claim.sub', v_sub, true);
  RETURN coalesce(v_ok, false);
EXCEPTION WHEN OTHERS THEN
  PERFORM set_config('request.jwt.claims', v_claims, true);
  PERFORM set_config('request.jwt.claim.sub', v_sub, true);
  RAISE;
END;
$$;

ALTER FUNCTION public.labelos_user_has_cap(uuid, uuid, text) OWNER TO postgres;
REVOKE ALL ON FUNCTION public.labelos_user_has_cap(uuid, uuid, text) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.labelos_user_has_cap(uuid, uuid, text) TO service_role;

-- ── 4. RLS ──────────────────────────────────────────────────────────────

ALTER TABLE public.project_members ENABLE ROW LEVEL SECURITY;

-- A person reads their OWN membership while it is live (this is what the
-- proxy's coarse gate reads on the caller's own session); an org member who
-- may share externally reads the memberships of the projects their artist
-- scope reaches (`can_see_org_project`, 141 — the whole org for a member who
-- sees the whole org).
DROP POLICY IF EXISTS project_members_self_read ON public.project_members;
CREATE POLICY project_members_self_read ON public.project_members
  FOR SELECT
  TO authenticated
  USING (
    user_id = (SELECT auth.uid())
    AND (SELECT public.can_see_project(project_id))
  );

DROP POLICY IF EXISTS project_members_manage_read ON public.project_members;
CREATE POLICY project_members_manage_read ON public.project_members
  FOR SELECT
  TO authenticated
  USING (
    (SELECT public.has_org_cap(org_id, 'share.external'))
    AND (SELECT public.can_see_org_project(org_id, project_id))
  );

-- Writes are the service role's (the routes and the functions below).
REVOKE ALL ON public.project_members FROM anon, authenticated;
GRANT SELECT ON public.project_members TO authenticated;

-- ── 5. Audit functions ──────────────────────────────────────────────────

-- Private helper: one audit event WITH its project. 146's labelos_audit_insert
-- carries no project column; this one does (the feed filters by it). Same
-- guards on the payload. No EXECUTE for anyone but its owner.
CREATE OR REPLACE FUNCTION public.labelos_audit_insert_project(
  p_org uuid,
  p_actor uuid,
  p_verb text,
  p_subject_type text,
  p_subject_id uuid,
  p_project uuid,
  p_payload jsonb
) RETURNS uuid
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path = public
AS $fn$
DECLARE
  v_id uuid;
BEGIN
  IF p_payload IS NULL OR jsonb_typeof(p_payload) <> 'object' THEN
    RAISE EXCEPTION 'audit payload must be an object' USING ERRCODE = '22023';
  END IF;
  IF p_payload::text ~* '"[^"]*(token|password|secret)[^"]*"\s*:' THEN
    RAISE EXCEPTION 'audit payload carries a secret-looking key' USING ERRCODE = '22023';
  END IF;
  IF pg_column_size(p_payload) > 16384 THEN
    RAISE EXCEPTION 'audit payload is too large' USING ERRCODE = '22023';
  END IF;

  INSERT INTO public.activity_events (org_id, actor_id, verb, subject_type, subject_id, project_id, payload, audit, visibility)
  VALUES (p_org, p_actor, p_verb, p_subject_type, p_subject_id, p_project, p_payload, true, 'internal')
  RETURNING id INTO v_id;
  RETURN v_id;
END;
$fn$;

ALTER FUNCTION public.labelos_audit_insert_project(uuid, uuid, text, text, uuid, uuid, jsonb) OWNER TO postgres;
REVOKE ALL ON FUNCTION public.labelos_audit_insert_project(uuid, uuid, text, text, uuid, uuid, jsonb) FROM PUBLIC, anon, authenticated, service_role;

-- Invite someone to ONE project. One pending invitation per address per
-- project, decided under a lock (the 146 rule, per project). The project
-- must be a project of the org. Answers {"invitation": <row>},
-- {"error": "pending", "id": <existing>} or {"error": "not_found"}.
CREATE OR REPLACE FUNCTION public.labelos_audit_project_invitation_create(
  p_org uuid,
  p_actor uuid,
  p_project uuid,
  p_email text,
  p_role text,
  p_allow_downloads boolean,
  p_token_hash text,
  p_expires_at timestamptz,
  p_payload jsonb
) RETURNS jsonb
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path = public
AS $fn$
DECLARE
  v_pending uuid;
  v_inv     public.org_invitations%ROWTYPE;
BEGIN
  IF p_role NOT IN ('viewer', 'commenter', 'contributor', 'editor') THEN
    RAISE EXCEPTION 'unknown project role %', p_role USING ERRCODE = '22023';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.projects p WHERE p.id = p_project AND p.org_id = p_org) THEN
    RETURN jsonb_build_object('error', 'not_found');
  END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended(p_org::text || ':' || p_project::text || ':' || p_email, 0));

  SELECT i.id INTO v_pending
  FROM public.org_invitations i
  WHERE i.org_id = p_org AND i.project_id = p_project AND i.email = p_email
    AND i.accepted_at IS NULL AND i.revoked_at IS NULL AND i.expires_at > now()
  ORDER BY i.created_at ASC, i.id ASC
  LIMIT 1;
  IF v_pending IS NOT NULL THEN
    RETURN jsonb_build_object('error', 'pending', 'id', v_pending);
  END IF;

  -- `role` is the ORG role column (NOT NULL); a project invitation never
  -- becomes an org membership (labelos_accept_invitation branches on
  -- project_id first), so the least one is stored.
  INSERT INTO public.org_invitations
    (org_id, email, role, functions, artist_ids, project_id, project_role, project_allow_downloads, token_hash, expires_at, invited_by)
  VALUES
    (p_org, p_email, 'member', '{}', '{}', p_project, p_role, coalesce(p_allow_downloads, false), p_token_hash, p_expires_at, p_actor)
  RETURNING * INTO v_inv;

  PERFORM public.labelos_audit_insert_project(p_org, p_actor, 'invitation.created', 'invitation', v_inv.id, p_project, p_payload);

  RETURN jsonb_build_object('invitation', jsonb_build_object(
    'id', v_inv.id,
    'email', v_inv.email,
    'project_id', v_inv.project_id,
    'project_role', v_inv.project_role,
    'allow_downloads', v_inv.project_allow_downloads,
    'expires_at', v_inv.expires_at,
    'accepted_at', v_inv.accepted_at,
    'revoked_at', v_inv.revoked_at,
    'created_at', v_inv.created_at
  ));
END;
$fn$;

ALTER FUNCTION public.labelos_audit_project_invitation_create(uuid, uuid, uuid, text, text, boolean, text, timestamptz, jsonb) OWNER TO postgres;
REVOKE ALL ON FUNCTION public.labelos_audit_project_invitation_create(uuid, uuid, uuid, text, text, boolean, text, timestamptz, jsonb) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.labelos_audit_project_invitation_create(uuid, uuid, uuid, text, text, boolean, text, timestamptz, jsonb) TO service_role;

-- Change one membership. p_patch holds only the keys that change: role,
-- allow_downloads, expires_at (null clears it). Answers {"member": <row>} or
-- {"error": "not_found"}.
CREATE OR REPLACE FUNCTION public.labelos_audit_project_member_update(
  p_org uuid,
  p_actor uuid,
  p_project uuid,
  p_user uuid,
  p_patch jsonb,
  p_payload jsonb
) RETURNS jsonb
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path = public
AS $fn$
DECLARE
  v_row public.project_members%ROWTYPE;
BEGIN
  IF p_patch IS NULL OR jsonb_typeof(p_patch) <> 'object' OR p_patch = '{}'::jsonb THEN
    RAISE EXCEPTION 'empty project member patch' USING ERRCODE = '22023';
  END IF;

  PERFORM 1 FROM public.project_members
  WHERE org_id = p_org AND project_id = p_project AND user_id = p_user FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('error', 'not_found');
  END IF;

  UPDATE public.project_members m
  SET role            = COALESCE(p_patch->>'role', m.role),
      allow_downloads = CASE WHEN p_patch ? 'allow_downloads' THEN (p_patch->>'allow_downloads')::boolean ELSE m.allow_downloads END,
      expires_at      = CASE WHEN p_patch ? 'expires_at' THEN nullif(p_patch->>'expires_at', '')::timestamptz ELSE m.expires_at END
  WHERE m.org_id = p_org AND m.project_id = p_project AND m.user_id = p_user
  RETURNING m.* INTO v_row;

  PERFORM public.labelos_audit_insert_project(p_org, p_actor, 'project.member_changed', 'member', p_user, p_project, p_payload);

  RETURN jsonb_build_object('member', jsonb_build_object(
    'user_id', v_row.user_id,
    'role', v_row.role,
    'allow_downloads', v_row.allow_downloads,
    'expires_at', v_row.expires_at,
    'created_at', v_row.created_at
  ));
END;
$fn$;

ALTER FUNCTION public.labelos_audit_project_member_update(uuid, uuid, uuid, uuid, jsonb, jsonb) OWNER TO postgres;
REVOKE ALL ON FUNCTION public.labelos_audit_project_member_update(uuid, uuid, uuid, uuid, jsonb, jsonb) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.labelos_audit_project_member_update(uuid, uuid, uuid, uuid, jsonb, jsonb) TO service_role;

-- Remove one membership. What the person uploaded stays in the project with
-- their name on it (D3): uploads carry `tracks.created_by`, not this row.
CREATE OR REPLACE FUNCTION public.labelos_audit_project_member_remove(
  p_org uuid,
  p_actor uuid,
  p_project uuid,
  p_user uuid,
  p_payload jsonb
) RETURNS jsonb
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path = public
AS $fn$
DECLARE
  v_gone int;
BEGIN
  DELETE FROM public.project_members
  WHERE org_id = p_org AND project_id = p_project AND user_id = p_user;
  GET DIAGNOSTICS v_gone = ROW_COUNT;
  IF v_gone = 0 THEN
    RETURN jsonb_build_object('error', 'not_found');
  END IF;
  PERFORM public.labelos_audit_insert_project(p_org, p_actor, 'project.member_removed', 'member', p_user, p_project, p_payload);
  RETURN jsonb_build_object('removed', true);
END;
$fn$;

ALTER FUNCTION public.labelos_audit_project_member_remove(uuid, uuid, uuid, uuid, jsonb) OWNER TO postgres;
REVOKE ALL ON FUNCTION public.labelos_audit_project_member_remove(uuid, uuid, uuid, uuid, jsonb) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.labelos_audit_project_member_remove(uuid, uuid, uuid, uuid, jsonb) TO service_role;

-- ── 7. labelos_audit_invitation_create (146, replaced) ──────────────────
-- Identical to 146 except the pending lookup, which now ignores project
-- invitations: an open invitation to one PROJECT is not an open invitation
-- to the ORG (and must not be mistaken for one).

CREATE OR REPLACE FUNCTION public.labelos_audit_invitation_create(
  p_org uuid,
  p_actor uuid,
  p_email text,
  p_role text,
  p_functions text[],
  p_artist_ids uuid[],
  p_token_hash text,
  p_expires_at timestamptz,
  p_payload jsonb
) RETURNS jsonb
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path = public
AS $fn$
DECLARE
  v_pending uuid;
  v_inv     public.org_invitations%ROWTYPE;
BEGIN
  PERFORM pg_advisory_xact_lock(hashtextextended(p_org::text || ':' || p_email, 0));

  SELECT i.id INTO v_pending
  FROM public.org_invitations i
  WHERE i.org_id = p_org AND i.email = p_email AND i.project_id IS NULL
    AND i.accepted_at IS NULL AND i.revoked_at IS NULL AND i.expires_at > now()
  ORDER BY i.created_at ASC, i.id ASC
  LIMIT 1;
  IF v_pending IS NOT NULL THEN
    RETURN jsonb_build_object('error', 'pending', 'id', v_pending);
  END IF;

  INSERT INTO public.org_invitations (org_id, email, role, functions, artist_ids, token_hash, expires_at, invited_by)
  VALUES (p_org, p_email, p_role, COALESCE(p_functions, '{}'), COALESCE(p_artist_ids, '{}'), p_token_hash, p_expires_at, p_actor)
  RETURNING * INTO v_inv;

  PERFORM public.labelos_audit_insert(p_org, p_actor, 'invitation.created', 'invitation', v_inv.id, p_payload);

  RETURN jsonb_build_object('invitation', jsonb_build_object(
    'id', v_inv.id,
    'email', v_inv.email,
    'role', v_inv.role,
    'functions', to_jsonb(v_inv.functions),
    'artist_ids', to_jsonb(v_inv.artist_ids),
    'expires_at', v_inv.expires_at,
    'accepted_at', v_inv.accepted_at,
    'revoked_at', v_inv.revoked_at,
    'created_at', v_inv.created_at
  ));
END;
$fn$;

ALTER FUNCTION public.labelos_audit_invitation_create(uuid, uuid, text, text, text[], uuid[], text, timestamptz, jsonb) OWNER TO postgres;
REVOKE ALL ON FUNCTION public.labelos_audit_invitation_create(uuid, uuid, text, text, text[], uuid[], text, timestamptz, jsonb) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.labelos_audit_invitation_create(uuid, uuid, text, text, text[], uuid[], text, timestamptz, jsonb) TO service_role;

-- ── 6. labelos_accept_invitation (139, replaced) ────────────────────────
-- 139's function with one new branch. A project invitation (project_id set)
-- admits the invitee to that project through `project_members` and records
-- `project.member_added`; org_members is never touched for it. Everything
-- else — and every org invitation — is exactly 139. Answers carry
-- `project_id` for the project path so the route can open the right page.

CREATE OR REPLACE FUNCTION public.labelos_accept_invitation(p_token_hash text, p_user uuid)
RETURNS jsonb
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path = public
AS $fn$
DECLARE
  v_email     text;
  v_confirmed timestamptz;
  v_inv       public.org_invitations%ROWTYPE;
  v_rows      int;
  v_scope     text;
  v_scoped    uuid[] := '{}';
  v_renewed   boolean := false;
BEGIN
  IF p_token_hash IS NULL OR p_token_hash !~ '^[0-9a-f]{64}$' OR p_user IS NULL THEN
    RETURN jsonb_build_object('error', 'not_found');
  END IF;

  SELECT lower(btrim(u.email)), u.email_confirmed_at INTO v_email, v_confirmed
  FROM auth.users u WHERE u.id = p_user;
  IF v_email IS NULL OR v_email = '' THEN
    RETURN jsonb_build_object('error', 'email_mismatch');
  END IF;

  SELECT i.* INTO v_inv
  FROM public.org_invitations i
  JOIN public.organizations o ON o.id = i.org_id
  WHERE i.token_hash = p_token_hash
    AND o.deleted_at IS NULL
  FOR UPDATE OF i;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('error', 'not_found');
  END IF;

  IF v_inv.email <> v_email THEN
    RETURN jsonb_build_object('error', 'email_mismatch');
  END IF;
  IF v_confirmed IS NULL THEN
    RETURN jsonb_build_object('error', 'email_unverified');
  END IF;
  IF v_inv.role = 'owner' THEN
    RETURN jsonb_build_object('error', 'unsupported');
  END IF;
  IF v_inv.revoked_at IS NOT NULL THEN
    RETURN jsonb_build_object('error', 'revoked');
  END IF;

  -- ── A project invitation: a project_members row, never org_members ────
  IF v_inv.project_id IS NOT NULL THEN
    IF v_inv.accepted_at IS NOT NULL THEN
      -- Only a LIVE membership is "already a member": someone whose access has
      -- expired and who clicks the spent link again is told it is used, not
      -- that they still have access.
      IF EXISTS (
        SELECT 1 FROM public.project_members
        WHERE project_id = v_inv.project_id AND user_id = p_user AND (expires_at IS NULL OR expires_at > now())
      ) THEN
        RETURN jsonb_build_object('status', 'already_member', 'org_id', v_inv.org_id, 'project_id', v_inv.project_id);
      END IF;
      RETURN jsonb_build_object('error', 'used');
    END IF;
    IF v_inv.expires_at <= now() THEN
      RETURN jsonb_build_object('error', 'expired');
    END IF;
    -- The inviter must still be able to share outside the org, and the
    -- project must still be a project of it.
    IF v_inv.invited_by IS NULL
       OR NOT public.labelos_user_has_cap(v_inv.org_id, v_inv.invited_by, 'share.external')
       OR NOT EXISTS (SELECT 1 FROM public.projects p WHERE p.id = v_inv.project_id AND p.org_id = v_inv.org_id) THEN
      RETURN jsonb_build_object('error', 'revoked');
    END IF;

    v_renewed := EXISTS (SELECT 1 FROM public.project_members WHERE project_id = v_inv.project_id AND user_id = p_user);
    -- A person who is already on the project keeps what they have (an
    -- invitation never changes a live membership), EXCEPT one whose access
    -- has EXPIRED: a new invitation is how the producer brings them back, so
    -- it renews the row with the invited role and downloads setting and
    -- clears the expiry. v_rows = 1 then, and the event says `renewed`.
    INSERT INTO public.project_members (org_id, project_id, user_id, role, allow_downloads, invited_by, invitation_id)
    VALUES (v_inv.org_id, v_inv.project_id, p_user, v_inv.project_role, v_inv.project_allow_downloads, v_inv.invited_by, v_inv.id)
    ON CONFLICT (project_id, user_id) DO UPDATE
      SET role = EXCLUDED.role,
          allow_downloads = EXCLUDED.allow_downloads,
          expires_at = NULL,
          invited_by = EXCLUDED.invited_by,
          invitation_id = EXCLUDED.invitation_id
      WHERE public.project_members.expires_at IS NOT NULL
        AND public.project_members.expires_at <= now();
    GET DIAGNOSTICS v_rows = ROW_COUNT;

    UPDATE public.org_invitations SET accepted_at = now() WHERE id = v_inv.id;

    IF v_rows = 0 THEN
      RETURN jsonb_build_object('status', 'already_member', 'org_id', v_inv.org_id, 'project_id', v_inv.project_id);
    END IF;

    PERFORM public.labelos_audit_insert_project(
      v_inv.org_id, p_user, 'project.member_added', 'member', p_user, v_inv.project_id,
      jsonb_build_object(
        'invitation_id', v_inv.id,
        'role', v_inv.project_role,
        'allow_downloads', v_inv.project_allow_downloads,
        'invited_by', v_inv.invited_by,
        'renewed', v_renewed
      )
    );
    RETURN jsonb_build_object('status', 'joined', 'org_id', v_inv.org_id, 'project_id', v_inv.project_id);
  END IF;

  -- ── An org invitation: 139's function, unchanged ──────────────────────
  IF v_inv.accepted_at IS NOT NULL THEN
    IF EXISTS (SELECT 1 FROM public.org_members WHERE org_id = v_inv.org_id AND user_id = p_user) THEN
      RETURN jsonb_build_object('status', 'already_member', 'org_id', v_inv.org_id);
    END IF;
    RETURN jsonb_build_object('error', 'used');
  END IF;
  IF v_inv.expires_at <= now() THEN
    RETURN jsonb_build_object('error', 'expired');
  END IF;
  IF v_inv.invited_by IS NULL OR NOT EXISTS (
    SELECT 1 FROM public.org_members m
    WHERE m.org_id = v_inv.org_id AND m.user_id = v_inv.invited_by AND m.role IN ('owner', 'admin')
  ) THEN
    RETURN jsonb_build_object('error', 'revoked');
  END IF;

  v_scope := CASE WHEN v_inv.role = 'artist' OR cardinality(v_inv.artist_ids) > 0 THEN 'artists' ELSE 'org' END;

  INSERT INTO public.org_members (org_id, user_id, role, functions, scope, invited_by)
  VALUES (
    v_inv.org_id,
    p_user,
    v_inv.role,
    CASE WHEN v_inv.role = 'member' THEN v_inv.functions ELSE '{}'::text[] END,
    v_scope,
    v_inv.invited_by
  )
  ON CONFLICT (org_id, user_id) DO NOTHING;
  GET DIAGNOSTICS v_rows = ROW_COUNT;

  UPDATE public.org_invitations SET accepted_at = now() WHERE id = v_inv.id;

  IF v_rows = 0 THEN
    RETURN jsonb_build_object('status', 'already_member', 'org_id', v_inv.org_id);
  END IF;

  IF v_scope = 'artists' AND cardinality(v_inv.artist_ids) > 0 THEN
    WITH written AS (
      INSERT INTO public.member_artist_scopes (org_id, user_id, contact_id)
      SELECT v_inv.org_id, p_user, c.id
      FROM public.contacts c
      WHERE c.id = ANY (v_inv.artist_ids)
        AND c.org_id = v_inv.org_id
      ON CONFLICT DO NOTHING
      RETURNING contact_id
    )
    SELECT coalesce(array_agg(contact_id ORDER BY contact_id), '{}') INTO v_scoped FROM written;
  END IF;

  INSERT INTO public.activity_events (org_id, actor_id, verb, subject_type, subject_id, payload, audit, visibility)
  VALUES (
    v_inv.org_id,
    p_user,
    'member.joined',
    'member',
    p_user,
    jsonb_build_object(
      'invitation_id', v_inv.id,
      'role', v_inv.role,
      'functions', to_jsonb(CASE WHEN v_inv.role = 'member' THEN v_inv.functions ELSE '{}'::text[] END),
      'contact_ids', to_jsonb(v_scoped),
      'invited_by', v_inv.invited_by
    ),
    true,
    'internal'
  );

  RETURN jsonb_build_object('status', 'joined', 'org_id', v_inv.org_id);
END;
$fn$;

ALTER FUNCTION public.labelos_accept_invitation(text, uuid) OWNER TO postgres;
REVOKE ALL ON FUNCTION public.labelos_accept_invitation(text, uuid) FROM PUBLIC;
REVOKE ALL ON FUNCTION public.labelos_accept_invitation(text, uuid) FROM anon, authenticated;
GRANT EXECUTE ON FUNCTION public.labelos_accept_invitation(text, uuid) TO service_role;

NOTIFY pgrst, 'reload schema';


-- ═════════════ 149_labelos_song_reviews.sql ═════════════
-- 149_labelos_song_reviews.sql
-- Label OS (LABEL-25): per-reviewer ratings and verdicts on a song — the A&R
-- side of 04 W3 (17 R7: keyed by the song's track_id; distinct from
-- contact_track_states, which is the RECIPIENT's decision on a beat).
--
-- LABEL OS — NOT APPLIED. Apply at the final merge of the Label OS branch
-- into main, after 148. Never part of supabase/apply/pending.sql.
--
-- One new table, org-only (no user_id, the 139/142/143/144 rule):
--
--   song_reviews (track_id, reviewer_id) — one row per reviewer per song, so two
--   A&Rs never overwrite each other (upsert by that key). A rating 1–5 and a
--   verdict (shortlist | hold | pass | changes_requested), either may be
--   absent (a keystroke rating has no verdict yet), plus an optional note.
--   At least one of the three is set: an empty review is not a row.
--
-- Who reads (the security core; D5 + 06):
--
--   review.comment (implied by review.write, and implying catalog.read) AND
--     whole-org member (scope 'org', not a roster artist)  → every review of the org
--     else the song is in the member's scope → that is, in a project the
--       member's artist scope reaches (labelos_scoped_projects(), 147): an
--       artist's Inbox or a project linking them. A roster artist's scope is
--       their own contact, so THEY read every review of THEIR songs (D5);
--       another artist of the same label has a different scope and reads none.
--   An external project member (LABEL-21) is not an org member: the policy is
--   keyed on org membership only, so they read nothing.
--
--   No per-row SECURITY DEFINER call (R-08, measured in #76): the scope
--   disjunct is an uncorrelated subquery over labelos_scoped_tracks(), the
--   songs of the scoped projects, planned as a hashed subplan evaluated once
--   per statement. The capability is asked of the caller's own memberships
--   (`org_id IN (SELECT … FROM org_members WHERE has_org_cap(...))`), also an
--   uncorrelated hashed subplan: has_org_cap(org_id, …) on the ROW would be
--   correlated and run once per review (measured: 564 ms vs 13 ms for the
--   newest 100 of 6,000 reviews).
--
-- Writes: service role only. No INSERT/UPDATE/DELETE policy, and 141's
-- labelos_org_rows_service_only trigger refuses any write by the API roles.
-- A BEFORE trigger keeps a row inside its song's org and fixes its identity.
--
-- Idempotent: IF NOT EXISTS, CREATE OR REPLACE, DROP ... IF EXISTS first.

CREATE TABLE IF NOT EXISTS public.song_reviews (
  org_id      uuid NOT NULL REFERENCES public.organizations(id) ON DELETE CASCADE,
  track_id    uuid NOT NULL REFERENCES public.tracks(id) ON DELETE CASCADE,
  reviewer_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  rating      smallint,
  verdict     text,
  note        text,
  created_at  timestamptz NOT NULL DEFAULT now(),
  updated_at  timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (track_id, reviewer_id),
  CONSTRAINT song_reviews_rating_check CHECK (rating IS NULL OR rating BETWEEN 1 AND 5),
  CONSTRAINT song_reviews_verdict_check CHECK (verdict IS NULL OR verdict IN ('shortlist', 'hold', 'pass', 'changes_requested')),
  CONSTRAINT song_reviews_note_check CHECK (note IS NULL OR (length(note) BETWEEN 1 AND 2000)),
  CONSTRAINT song_reviews_not_empty CHECK (rating IS NOT NULL OR verdict IS NOT NULL OR note IS NOT NULL)
);

CREATE INDEX IF NOT EXISTS idx_song_reviews_org_updated ON public.song_reviews (org_id, updated_at DESC);

ALTER TABLE public.song_reviews ENABLE ROW LEVEL SECURITY;

-- ── Integrity ────────────────────────────────────────────────────────────
-- The song is a track of the row's own org (never a producer track, never
-- another org's), and a row's identity never changes: a reviewer's review is
-- rewritten in place, not re-pointed.

CREATE OR REPLACE FUNCTION public.song_reviews_integrity()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  IF TG_OP = 'UPDATE' AND (NEW.org_id <> OLD.org_id OR NEW.track_id <> OLD.track_id OR NEW.reviewer_id <> OLD.reviewer_id) THEN
    RAISE EXCEPTION 'song_reviews: a review keeps its organization, song and reviewer'
      USING ERRCODE = 'check_violation';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.tracks t
    WHERE t.id = NEW.track_id AND t.org_id IS NOT NULL AND t.org_id = NEW.org_id AND t.type = 'song'
  ) THEN
    RAISE EXCEPTION 'song_reviews: the song must be a song of the same organization'
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;

ALTER FUNCTION public.song_reviews_integrity() OWNER TO postgres;
REVOKE ALL ON FUNCTION public.song_reviews_integrity() FROM PUBLIC;

DROP TRIGGER IF EXISTS song_reviews_integrity ON public.song_reviews;
CREATE TRIGGER song_reviews_integrity BEFORE INSERT OR UPDATE ON public.song_reviews
  FOR EACH ROW EXECUTE FUNCTION public.song_reviews_integrity();

DROP TRIGGER IF EXISTS labelos_org_rows_service_only ON public.song_reviews;
CREATE TRIGGER labelos_org_rows_service_only BEFORE INSERT OR UPDATE OR DELETE ON public.song_reviews
  FOR EACH ROW EXECUTE FUNCTION public.labelos_org_rows_service_only('self', 'org_id');

-- ── labelos_scoped_tracks ────────────────────────────────────────────────
-- The org tracks that sit in a project the caller's artist scope reaches
-- (labelos_scoped_projects, 147): can_see_org_track (141) for a member
-- limited to some artists, written as one set instead of a per-track test.
-- Empty for a whole-org member. Scope only; capabilities are has_org_cap's.
-- SECURITY DEFINER because project_tracks has no member policy. EXECUTE for
-- authenticated and anon, like labelos_scoped_projects: the policy runs as the
-- invoker for every role and anon must evaluate it to an empty result.

CREATE OR REPLACE FUNCTION public.labelos_scoped_tracks()
RETURNS TABLE (org_id uuid, track_id uuid)
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
  SELECT sp.org_id, pt.track_id
  FROM public.labelos_scoped_projects() sp
  JOIN public.project_tracks pt ON pt.project_id = sp.project_id
  JOIN public.tracks t ON t.id = pt.track_id AND t.org_id = sp.org_id;
$$;

ALTER FUNCTION public.labelos_scoped_tracks() OWNER TO postgres;
REVOKE ALL ON FUNCTION public.labelos_scoped_tracks() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.labelos_scoped_tracks() TO authenticated, anon;

-- ── The policy ───────────────────────────────────────────────────────────

DROP POLICY IF EXISTS song_reviews_member_read ON public.song_reviews;
CREATE POLICY song_reviews_member_read ON public.song_reviews
  FOR SELECT
  USING (
    -- review.comment (which review.write implies, and which implies catalog.read) in the
    -- row's org, asked of the caller's few memberships (not of every review row:
    -- has_org_cap(org_id, …) on the row would run once per row). Marketing, legal and
    -- engineers read the catalogue but hold no review ability, so they read no review:
    -- a rating of a working demo is not theirs, and the routes' D4 row rule is not the
    -- only line of defence against a member's own JWT on PostgREST.
    org_id IN (
      SELECT cm.org_id
      FROM public.org_members cm
      WHERE cm.user_id = (SELECT auth.uid())
        AND public.has_org_cap(cm.org_id, 'review.comment')
    )
    AND (
      org_id IN (
        SELECT om.org_id
        FROM public.org_members om
        WHERE om.user_id = (SELECT auth.uid())
          AND om.scope = 'org'
          AND om.role <> 'artist'
      )
      OR (org_id, track_id) IN (SELECT st.org_id, st.track_id FROM public.labelos_scoped_tracks() st)
    )
  );

NOTIFY pgrst, 'reload schema';


-- ═════════════ 150_labelos_org_comments.sql ═════════════
-- 150_labelos_org_comments.sql
-- LABEL-22: org comments on `project_comments` (17 R5). No new comments table.
--
-- A comment on an org project is a `project_comments` row, exactly like a
-- share-page or portal one, with three new columns:
--   org_id       the project's org, FIXED BY A TRIGGER from the project (never
--                by the caller) and NULL on every producer project;
--   visibility   'artist' (default: what the project's artist may read, as
--                before) | 'internal' (the team only);
--   resolved_at  set when a thread is resolved (on the thread's root);
--   resolved_by  who resolved it.
-- Every existing row is a producer / share / portal comment: org_id NULL,
-- visibility 'artist', not resolved. Nothing is backfilled.
--
-- The rule the whole task exists for: an `internal` comment NEVER reaches a
-- portal, a share page, a roster-artist member (role `artist`) or an external
-- project member. Enforced in four places, each sufficient on its own:
--   1. CHECK: an internal comment has no share_token and no contact_id (so no
--      portal thread and no share-link thread can ever hold one) and belongs
--      to an org project;
--   2. trigger: a reply to an internal comment is internal;
--   3. RLS: 141's org_member_read / org_member_guard on project_comments gain
--      `visibility = 'artist' OR labelos_can_read_internal_comments(org)`, so
--      a role-`artist` member's own JWT cannot read one. An external project
--      member has no policy on this table at all (148);
--   4. the routes (portal, share, org) filter on visibility as well.
--
-- Writes stay service-role only (141's labelos_org_rows_service_only is
-- already on this table); no write policy is added.

-- ── 1. Columns ──────────────────────────────────────────────────────────

ALTER TABLE public.project_comments
  ADD COLUMN IF NOT EXISTS org_id      uuid REFERENCES public.organizations(id) ON DELETE CASCADE,
  ADD COLUMN IF NOT EXISTS visibility  text NOT NULL DEFAULT 'artist',
  ADD COLUMN IF NOT EXISTS resolved_at timestamptz,
  ADD COLUMN IF NOT EXISTS resolved_by uuid REFERENCES auth.users(id) ON DELETE SET NULL;

DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'project_comments_visibility_check') THEN
    ALTER TABLE public.project_comments
      ADD CONSTRAINT project_comments_visibility_check CHECK (visibility IN ('internal', 'artist'));
  END IF;
  -- Internal comments are org-team notes: never a share-link or portal thread.
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'project_comments_internal_private') THEN
    ALTER TABLE public.project_comments
      ADD CONSTRAINT project_comments_internal_private
      CHECK (visibility = 'artist' OR (org_id IS NOT NULL AND share_token IS NULL AND contact_id IS NULL));
  END IF;
END $$;

CREATE INDEX IF NOT EXISTS idx_project_comments_org_project
  ON public.project_comments (org_id, project_id, created_at)
  WHERE org_id IS NOT NULL;

-- ── 2. org_id comes from the project; thread integrity ──────────────────

CREATE OR REPLACE FUNCTION public.project_comments_org_fields()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE
  parent record;
BEGIN
  -- The org is the project's, whatever the caller wrote.
  SELECT p.org_id INTO NEW.org_id FROM public.projects p WHERE p.id = NEW.project_id;

  IF NEW.parent_id IS NOT NULL AND NEW.org_id IS NOT NULL THEN
    SELECT c.project_id, c.visibility INTO parent FROM public.project_comments c WHERE c.id = NEW.parent_id;
    IF NOT FOUND OR parent.project_id <> NEW.project_id THEN
      RAISE EXCEPTION 'project_comments: parent % is not a comment of project %', NEW.parent_id, NEW.project_id;
    END IF;
    -- A reply under a team-only comment is team-only: the artist must not
    -- see an answer to something they cannot read.
    IF parent.visibility = 'internal' AND NEW.visibility <> 'internal' THEN
      RAISE EXCEPTION 'project_comments: a reply to an internal comment is internal';
    END IF;
  END IF;
  RETURN NEW;
END $$;

DROP TRIGGER IF EXISTS project_comments_org_fields ON public.project_comments;
CREATE TRIGGER project_comments_org_fields
  BEFORE INSERT OR UPDATE OF project_id, org_id, parent_id, visibility ON public.project_comments
  FOR EACH ROW EXECUTE FUNCTION public.project_comments_org_fields();

-- ── 3. Who reads an internal comment ────────────────────────────────────
-- Everyone in the org's team (owner / admin / member). A roster artist (role
-- `artist`) never does (D5: no business-internal notes), whatever overrides
-- they hold; an external project member is not an org member at all.

CREATE OR REPLACE FUNCTION public.labelos_can_read_internal_comments(p_org uuid)
RETURNS boolean
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
  SELECT coalesce(public.org_role(p_org) IN ('owner', 'admin', 'member'), false);
$$;

ALTER FUNCTION public.labelos_can_read_internal_comments(uuid) OWNER TO postgres;
REVOKE ALL ON FUNCTION public.labelos_can_read_internal_comments(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.labelos_can_read_internal_comments(uuid) TO authenticated, anon;

-- 141's two policies, unchanged but for the visibility line.
DROP POLICY IF EXISTS org_member_read ON public.project_comments;
CREATE POLICY org_member_read ON public.project_comments
  FOR SELECT
  TO authenticated
  USING (
    EXISTS (
      SELECT 1 FROM public.projects p
      WHERE p.id = project_comments.project_id
        AND p.org_id IS NOT NULL
        AND public.has_org_cap(p.org_id, 'catalog.read')
        AND public.can_see_org_project(p.org_id, p.id)
        AND (project_comments.track_id IS NULL OR public.can_read_org_track(p.org_id, project_comments.track_id))
        AND (project_comments.contact_id IS NULL OR public.can_see_artist(p.org_id, project_comments.contact_id))
        AND (project_comments.share_token IS NULL OR public.has_org_cap(p.org_id, 'share.external'))
        AND (project_comments.visibility = 'artist' OR public.labelos_can_read_internal_comments(p.org_id))
    )
  );

DROP POLICY IF EXISTS org_member_guard ON public.project_comments;
CREATE POLICY org_member_guard ON public.project_comments
  AS RESTRICTIVE
  FOR SELECT
  USING (
    NOT public.labelos_is_org_project(project_id)
    OR EXISTS (
      SELECT 1 FROM public.projects p
      WHERE p.id = project_comments.project_id
        AND p.org_id IS NOT NULL
        AND public.has_org_cap(p.org_id, 'catalog.read')
        AND public.can_see_org_project(p.org_id, p.id)
        AND (project_comments.track_id IS NULL OR public.can_read_org_track(p.org_id, project_comments.track_id))
        AND (project_comments.contact_id IS NULL OR public.can_see_artist(p.org_id, project_comments.contact_id))
        AND (project_comments.share_token IS NULL OR public.has_org_cap(p.org_id, 'share.external'))
        AND (project_comments.visibility = 'artist' OR public.labelos_can_read_internal_comments(p.org_id))
    )
  );

NOTIFY pgrst, 'reload schema';


-- ═════════════ 151_labelos_tasks_notifications.sql ═════════════
-- 151_labelos_tasks_notifications.sql
-- Label OS (LABEL-23): assignable org tasks, and org-scoped direct-ask
-- notifications (04 W5, 08 §B6, 13 R-19).
--
-- LABEL OS — NOT APPLIED. Apply at the final merge of the Label OS branch
-- into main, after 149 (150 is LABEL-22's). Never part of
-- supabase/apply/pending.sql.
--
-- 1. `tasks` — org-only (no user_id, the 139/142/143/144 rule). A task hangs
--    on AT MOST ONE of an artist (a roster contact), a project, a song (a
--    track) or a release, through four typed nullable foreign keys — never a
--    polymorphic (type, id) pair, so each key is a real FK and cascades with
--    its object. None set = an org-level task. `contact_tasks` (095) is the
--    producer's CRM follow-up and is untouched.
--
--    Who reads a task (D1: "each side its own tasks"):
--      - its creator and its assignee,
--      - an owner or admin of the org (they hold everything),
--      and always only while the caller is STILL a member of the task's org
--      and, for a member limited to some artists, still reaches the task's
--      object (the same scope the rest of Label OS applies). An external
--      project member (LABEL-21) is not an org member, so reads nothing.
--    Writes: service role only (141's labelos_org_rows_service_only; no write
--    policy). Routes decide who may create / complete / delete.
--
--    No per-row SECURITY DEFINER call (R-08): every disjunct is an
--    uncorrelated subquery over the caller's own few memberships or over a
--    set-returning scope function evaluated once per statement.
--
-- 2. `notifications.org_id` — nullable. NULL = a producer notification
--    (064), which behaves exactly as before. Set = an org notification, a
--    direct ask addressed to one recipient (`user_id`) within one org:
--      - a RESTRICTIVE SELECT policy: an org notification is readable only
--        while its recipient is still a member of that org (a removed member
--        loses the history, the title of a task they were given included);
--      - 141's service-only trigger: only the service role writes a row with
--        an org_id (the API roles keep their producer-era rights over rows
--        without one), so nobody can forge an org notification for themself
--        or mark one read through PostgREST — reading goes through the route.
--
-- Idempotent: IF NOT EXISTS, CREATE OR REPLACE, DROP ... IF EXISTS first.

-- ── 1. tasks ─────────────────────────────────────────────────────────────

CREATE TABLE IF NOT EXISTS public.tasks (
  id          uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  org_id      uuid NOT NULL REFERENCES public.organizations(id) ON DELETE CASCADE,
  title       text NOT NULL,
  notes       text,
  due_at      timestamptz,
  done_at     timestamptz,
  done_by     uuid REFERENCES auth.users(id) ON DELETE SET NULL,
  assignee_id uuid REFERENCES auth.users(id) ON DELETE SET NULL,
  created_by  uuid REFERENCES auth.users(id) ON DELETE SET NULL,
  -- At most one object (a roster artist is a contact — 17 R3).
  artist_id   uuid REFERENCES public.contacts(id) ON DELETE CASCADE,
  project_id  uuid REFERENCES public.projects(id) ON DELETE CASCADE,
  song_id     uuid REFERENCES public.tracks(id) ON DELETE CASCADE,
  release_id  uuid REFERENCES public.releases(id) ON DELETE CASCADE,
  created_at  timestamptz NOT NULL DEFAULT now(),
  updated_at  timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT tasks_title_check CHECK (length(btrim(title)) BETWEEN 1 AND 200),
  CONSTRAINT tasks_notes_check CHECK (notes IS NULL OR length(notes) BETWEEN 1 AND 2000),
  CONSTRAINT tasks_one_object CHECK (num_nonnulls(artist_id, project_id, song_id, release_id) <= 1)
);

-- "My work": the open tasks assigned to me, soonest first.
CREATE INDEX IF NOT EXISTS idx_tasks_assignee_open
  ON public.tasks (org_id, assignee_id, due_at NULLS LAST)
  WHERE done_at IS NULL;
-- Tasks inline on an object.
CREATE INDEX IF NOT EXISTS idx_tasks_song ON public.tasks (song_id) WHERE song_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_tasks_release ON public.tasks (release_id) WHERE release_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_tasks_project ON public.tasks (project_id) WHERE project_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_tasks_artist ON public.tasks (artist_id) WHERE artist_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_tasks_org_created ON public.tasks (org_id, created_at DESC);

ALTER TABLE public.tasks ENABLE ROW LEVEL SECURITY;

-- ── Integrity ────────────────────────────────────────────────────────────
-- The object is of the task's own org (a task never points at a producer row
-- or another org's), the assignee is a member of the org when assigned, and a
-- task's org never changes. The assignee test runs only when the assignee is
-- set or changed, so a member who left does not make their old tasks
-- uneditable.

CREATE OR REPLACE FUNCTION public.tasks_integrity()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  IF TG_OP = 'UPDATE' AND NEW.org_id <> OLD.org_id THEN
    RAISE EXCEPTION 'tasks: a task keeps its organization' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.artist_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.contacts c WHERE c.id = NEW.artist_id AND c.org_id = NEW.org_id
  ) THEN
    RAISE EXCEPTION 'tasks: the artist must belong to the same organization' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.project_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.projects p WHERE p.id = NEW.project_id AND p.org_id = NEW.org_id
  ) THEN
    RAISE EXCEPTION 'tasks: the project must belong to the same organization' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.song_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.tracks t WHERE t.id = NEW.song_id AND t.org_id = NEW.org_id
  ) THEN
    RAISE EXCEPTION 'tasks: the song must belong to the same organization' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.release_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.releases r WHERE r.id = NEW.release_id AND r.org_id = NEW.org_id
  ) THEN
    RAISE EXCEPTION 'tasks: the release must belong to the same organization' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.assignee_id IS NOT NULL
     AND (TG_OP = 'INSERT' OR NEW.assignee_id IS DISTINCT FROM OLD.assignee_id)
     AND NOT EXISTS (
       SELECT 1 FROM public.org_members m WHERE m.org_id = NEW.org_id AND m.user_id = NEW.assignee_id
     ) THEN
    RAISE EXCEPTION 'tasks: the assignee must be a member of the organization' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;

ALTER FUNCTION public.tasks_integrity() OWNER TO postgres;
REVOKE ALL ON FUNCTION public.tasks_integrity() FROM PUBLIC;

DROP TRIGGER IF EXISTS tasks_integrity ON public.tasks;
CREATE TRIGGER tasks_integrity BEFORE INSERT OR UPDATE ON public.tasks
  FOR EACH ROW EXECUTE FUNCTION public.tasks_integrity();

DROP TRIGGER IF EXISTS labelos_org_rows_service_only ON public.tasks;
CREATE TRIGGER labelos_org_rows_service_only BEFORE INSERT OR UPDATE OR DELETE ON public.tasks
  FOR EACH ROW EXECUTE FUNCTION public.labelos_org_rows_service_only('self', 'org_id');

-- ── labelos_scoped_releases ──────────────────────────────────────────────
-- The org releases whose project the caller's artist scope reaches
-- (labelos_scoped_projects, 147): a release is read through its project, as
-- 144's policy does. Written as one set so the tasks policy stays a hashed
-- subplan instead of running releases' own policy once per row. Empty for a
-- whole-org member. SECURITY DEFINER because releases' own policy is
-- per-row; EXECUTE like its two siblings (anon must evaluate to empty).

CREATE OR REPLACE FUNCTION public.labelos_scoped_releases()
RETURNS TABLE (org_id uuid, release_id uuid)
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
  SELECT sp.org_id, r.id
  FROM public.labelos_scoped_projects() sp
  JOIN public.releases r ON r.project_id = sp.project_id AND r.org_id = sp.org_id;
$$;

ALTER FUNCTION public.labelos_scoped_releases() OWNER TO postgres;
REVOKE ALL ON FUNCTION public.labelos_scoped_releases() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.labelos_scoped_releases() TO authenticated, anon;

-- ── The policy ───────────────────────────────────────────────────────────

DROP POLICY IF EXISTS tasks_member_read ON public.tasks;
CREATE POLICY tasks_member_read ON public.tasks
  FOR SELECT
  USING (
    -- a LIVE member of the task's org (asked of the caller's few memberships)
    org_id IN (
      SELECT m.org_id FROM public.org_members m WHERE m.user_id = (SELECT auth.uid())
    )
    AND (
      -- whose own task it is …
      assignee_id = (SELECT auth.uid())
      OR created_by = (SELECT auth.uid())
      -- … or who holds everything
      OR org_id IN (
        SELECT m.org_id FROM public.org_members m
        WHERE m.user_id = (SELECT auth.uid()) AND m.role IN ('owner', 'admin')
      )
    )
    AND (
      -- scope: a whole-org member, or a task with no object, or an object the
      -- caller's artist scope reaches
      org_id IN (
        SELECT m.org_id FROM public.org_members m
        WHERE m.user_id = (SELECT auth.uid()) AND m.scope = 'org' AND m.role <> 'artist'
      )
      OR (artist_id IS NULL AND project_id IS NULL AND song_id IS NULL AND release_id IS NULL)
      OR (org_id, artist_id) IN (
        SELECT s.org_id, s.contact_id FROM public.member_artist_scopes s WHERE s.user_id = (SELECT auth.uid())
      )
      OR (org_id, project_id) IN (SELECT sp.org_id, sp.project_id FROM public.labelos_scoped_projects() sp)
      OR (org_id, song_id) IN (SELECT st.org_id, st.track_id FROM public.labelos_scoped_tracks() st)
      OR (org_id, release_id) IN (SELECT sr.org_id, sr.release_id FROM public.labelos_scoped_releases() sr)
    )
  );

-- ── 2. notifications.org_id ──────────────────────────────────────────────

ALTER TABLE public.notifications
  ADD COLUMN IF NOT EXISTS org_id uuid REFERENCES public.organizations(id) ON DELETE CASCADE;

-- The bell under an org: this user's rows of that org, newest first.
CREATE INDEX IF NOT EXISTS idx_notifications_user_org
  ON public.notifications (user_id, org_id, created_at DESC)
  WHERE org_id IS NOT NULL;

-- Producer rows (org_id IS NULL) are untouched. An org row is also readable
-- only by a LIVE member of its org. RESTRICTIVE: ANDed with the owner policy
-- (064), which keeps keying the row on its recipient.
DROP POLICY IF EXISTS notifications_org_member_only ON public.notifications;
CREATE POLICY notifications_org_member_only ON public.notifications
  AS RESTRICTIVE
  FOR SELECT
  USING (
    org_id IS NULL
    OR org_id IN (SELECT m.org_id FROM public.org_members m WHERE m.user_id = (SELECT auth.uid()))
  );

DROP TRIGGER IF EXISTS labelos_org_rows_service_only ON public.notifications;
CREATE TRIGGER labelos_org_rows_service_only BEFORE INSERT OR UPDATE OR DELETE ON public.notifications
  FOR EACH ROW EXECUTE FUNCTION public.labelos_org_rows_service_only('self', 'org_id');

NOTIFY pgrst, 'reload schema';


-- ═════════════ 152_labelos_creative_direction.sql ═════════════
-- 152_labelos_creative_direction.sql
-- Label OS (LABEL-26): a per-artist memory of creative direction and
-- references (04 W6, 17 R3: keyed by the roster contact, no `artists` table).
--
-- LABEL OS — NOT APPLIED. Apply at the final merge of the Label OS branch
-- into main, after 151. Never part of supabase/apply/pending.sql.
--
-- 1. `artist_direction (contact_id PK, org_id, direction jsonb, updated_by,
--    updated_at)` — ONE structured document per roster artist. The shape of
--    `direction` (a handful of short text fields) is validated by the route
--    (lib/labelos/direction.ts); the database only insists on a JSON object of
--    sane size. There is no free-form wiki (UX: structured fields + a list).
--
-- 2. `artist_references (id, org_id, contact_id, kind, title, note, url,
--    track_id, asset_id, visibility, position, created_by, …)` — the list.
--    A reference is exactly one of: a track of the org (`track`), a link
--    (`link`, https only), a visual file already on an org project
--    (`file` → project_assets, LABEL-15), or a written note (`note`).
--    `visibility` is 'artist' (default: the artist may read it) or 'internal'
--    (the team only — an A&R's candid read of where the artist should go).
--
--    THE RULE this task exists for: an INTERNAL reference is never readable by
--    a member whose role is `artist`, whatever abilities were switched on for
--    them. Enforced in the RLS policy (their own JWT reads nothing internal)
--    and again by the routes.
--
-- Both tables are org-only (no user_id — the 139/142/143/144/151 rule), RLS on,
-- and written by the service role only (141's labelos_org_rows_service_only;
-- no write policy exists). Reads: a LIVE member of the org with `catalog.read`
-- whose artist scope reaches the contact (a whole-org member, or the contact
-- is in member_artist_scopes). External project members (148) are not org
-- members and read nothing.
--
-- No per-row SECURITY DEFINER call (R-08): every disjunct is an uncorrelated
-- subquery over the caller's own few memberships, hashed once per statement.
--
-- Idempotent: IF NOT EXISTS, CREATE OR REPLACE, DROP ... IF EXISTS first.

-- ── 1. artist_direction ──────────────────────────────────────────────────

CREATE TABLE IF NOT EXISTS public.artist_direction (
  contact_id uuid PRIMARY KEY REFERENCES public.contacts(id) ON DELETE CASCADE,
  org_id     uuid NOT NULL REFERENCES public.organizations(id) ON DELETE CASCADE,
  direction  jsonb NOT NULL DEFAULT '{}'::jsonb,
  updated_by uuid REFERENCES auth.users(id) ON DELETE SET NULL,
  updated_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT artist_direction_is_object CHECK (jsonb_typeof(direction) = 'object'),
  CONSTRAINT artist_direction_size CHECK (pg_column_size(direction) <= 16384)
);

CREATE INDEX IF NOT EXISTS idx_artist_direction_org ON public.artist_direction (org_id);

ALTER TABLE public.artist_direction ENABLE ROW LEVEL SECURITY;

-- ── 2. artist_references ─────────────────────────────────────────────────

CREATE TABLE IF NOT EXISTS public.artist_references (
  id         uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  org_id     uuid NOT NULL REFERENCES public.organizations(id) ON DELETE CASCADE,
  contact_id uuid NOT NULL REFERENCES public.contacts(id) ON DELETE CASCADE,
  kind       text NOT NULL,
  title      text NOT NULL,
  note       text,
  url        text,
  track_id   uuid REFERENCES public.tracks(id) ON DELETE CASCADE,
  asset_id   uuid REFERENCES public.project_assets(id) ON DELETE CASCADE,
  visibility text NOT NULL DEFAULT 'artist',
  position   integer NOT NULL DEFAULT 0,
  created_by uuid REFERENCES auth.users(id) ON DELETE SET NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT artist_references_kind_check CHECK (kind IN ('track', 'link', 'file', 'note')),
  CONSTRAINT artist_references_visibility_check CHECK (visibility IN ('artist', 'internal')),
  CONSTRAINT artist_references_title_check CHECK (length(btrim(title)) BETWEEN 1 AND 200),
  CONSTRAINT artist_references_note_check CHECK (note IS NULL OR length(note) BETWEEN 1 AND 2000),
  CONSTRAINT artist_references_url_check CHECK (url IS NULL OR (url ~* '^https://' AND length(url) <= 2000)),
  -- Each kind carries exactly its own pointer.
  CONSTRAINT artist_references_shape CHECK (
    (kind = 'track' AND track_id IS NOT NULL AND url IS NULL AND asset_id IS NULL)
    OR (kind = 'link' AND url IS NOT NULL AND track_id IS NULL AND asset_id IS NULL)
    OR (kind = 'file' AND asset_id IS NOT NULL AND url IS NULL AND track_id IS NULL)
    OR (kind = 'note' AND note IS NOT NULL AND url IS NULL AND track_id IS NULL AND asset_id IS NULL)
  )
);

CREATE INDEX IF NOT EXISTS idx_artist_references_contact
  ON public.artist_references (org_id, contact_id, position, created_at);
CREATE INDEX IF NOT EXISTS idx_artist_references_track ON public.artist_references (track_id) WHERE track_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_artist_references_asset ON public.artist_references (asset_id) WHERE asset_id IS NOT NULL;

ALTER TABLE public.artist_references ENABLE ROW LEVEL SECURITY;

-- ── Integrity ────────────────────────────────────────────────────────────
-- The artist is a roster contact of the row's own org; a track reference
-- points at a track of that org; a file reference at a VISUAL, non-restricted
-- file of an org project of that org (a contract or a working stem must not
-- become readable by a team-wide, artist-visible list). The org and the
-- contact never change.

CREATE OR REPLACE FUNCTION public.labelos_direction_integrity()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  IF TG_OP = 'UPDATE' AND (NEW.org_id <> OLD.org_id OR NEW.contact_id <> OLD.contact_id) THEN
    RAISE EXCEPTION '%: the organization and the artist of a row never change', TG_TABLE_NAME
      USING ERRCODE = 'check_violation';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.contacts c WHERE c.id = NEW.contact_id AND c.org_id = NEW.org_id) THEN
    RAISE EXCEPTION '%: the artist must belong to the same organization', TG_TABLE_NAME
      USING ERRCODE = 'check_violation';
  END IF;
  IF TG_TABLE_NAME = 'artist_references' THEN
    IF NEW.track_id IS NOT NULL AND NOT EXISTS (
      SELECT 1 FROM public.tracks t WHERE t.id = NEW.track_id AND t.org_id = NEW.org_id
    ) THEN
      RAISE EXCEPTION 'artist_references: the track must belong to the same organization'
        USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.asset_id IS NOT NULL AND NOT EXISTS (
      SELECT 1 FROM public.project_assets a
      WHERE a.id = NEW.asset_id
        AND a.org_id = NEW.org_id
        AND a.sensitivity = 'normal'
        AND a.kind IN ('artwork', 'photo', 'video', 'lyrics')
    ) THEN
      RAISE EXCEPTION 'artist_references: the file must be a visible artwork, photo, video or lyrics file of the same organization'
        USING ERRCODE = 'check_violation';
    END IF;
  END IF;
  RETURN NEW;
END;
$$;

ALTER FUNCTION public.labelos_direction_integrity() OWNER TO postgres;
REVOKE ALL ON FUNCTION public.labelos_direction_integrity() FROM PUBLIC;

DROP TRIGGER IF EXISTS artist_direction_integrity ON public.artist_direction;
CREATE TRIGGER artist_direction_integrity BEFORE INSERT OR UPDATE ON public.artist_direction
  FOR EACH ROW EXECUTE FUNCTION public.labelos_direction_integrity();
DROP TRIGGER IF EXISTS artist_references_integrity ON public.artist_references;
CREATE TRIGGER artist_references_integrity BEFORE INSERT OR UPDATE ON public.artist_references
  FOR EACH ROW EXECUTE FUNCTION public.labelos_direction_integrity();

-- Writes are the service role's (141): the API roles can neither forge nor edit.
DROP TRIGGER IF EXISTS labelos_org_rows_service_only ON public.artist_direction;
CREATE TRIGGER labelos_org_rows_service_only BEFORE INSERT OR UPDATE OR DELETE ON public.artist_direction
  FOR EACH ROW EXECUTE FUNCTION public.labelos_org_rows_service_only('self', 'org_id');
DROP TRIGGER IF EXISTS labelos_org_rows_service_only ON public.artist_references;
CREATE TRIGGER labelos_org_rows_service_only BEFORE INSERT OR UPDATE OR DELETE ON public.artist_references
  FOR EACH ROW EXECUTE FUNCTION public.labelos_org_rows_service_only('self', 'org_id');

-- ── Policies ─────────────────────────────────────────────────────────────

DROP POLICY IF EXISTS artist_direction_member_read ON public.artist_direction;
CREATE POLICY artist_direction_member_read ON public.artist_direction
  FOR SELECT
  USING (
    -- catalog.read in the row's org, asked of the caller's few memberships
    org_id IN (
      SELECT cm.org_id FROM public.org_members cm
      WHERE cm.user_id = (SELECT auth.uid()) AND public.has_org_cap(cm.org_id, 'catalog.read')
    )
    AND (
      -- a whole-org member, or an artist the caller's scope reaches
      org_id IN (
        SELECT om.org_id FROM public.org_members om
        WHERE om.user_id = (SELECT auth.uid()) AND om.scope = 'org' AND om.role <> 'artist'
      )
      OR (org_id, contact_id) IN (
        SELECT s.org_id, s.contact_id FROM public.member_artist_scopes s WHERE s.user_id = (SELECT auth.uid())
      )
    )
  );

DROP POLICY IF EXISTS artist_references_member_read ON public.artist_references;
CREATE POLICY artist_references_member_read ON public.artist_references
  FOR SELECT
  USING (
    org_id IN (
      SELECT cm.org_id FROM public.org_members cm
      WHERE cm.user_id = (SELECT auth.uid()) AND public.has_org_cap(cm.org_id, 'catalog.read')
    )
    AND (
      org_id IN (
        SELECT om.org_id FROM public.org_members om
        WHERE om.user_id = (SELECT auth.uid()) AND om.scope = 'org' AND om.role <> 'artist'
      )
      OR (org_id, contact_id) IN (
        SELECT s.org_id, s.contact_id FROM public.member_artist_scopes s WHERE s.user_id = (SELECT auth.uid())
      )
    )
    AND (
      visibility = 'artist'
      -- internal: the team (owner / admin / member) — never role `artist`
      OR org_id IN (
        SELECT tm.org_id FROM public.org_members tm
        WHERE tm.user_id = (SELECT auth.uid()) AND tm.role IN ('owner', 'admin', 'member')
      )
    )
  );

NOTIFY pgrst, 'reload schema';


-- ═════════════ 153_labelos_parties_credits.sql ═════════════
-- 153_labelos_parties_credits.sql
-- Label OS (LABEL-27): rights-holder parties, and legal-grade credits by
-- EXTENDING `track_collaborators` (17 R8; no `credits` table).
--
-- LABEL OS — NOT APPLIED. Apply at the final merge of the Label OS branch
-- into main, after 152. Never part of supabase/apply/pending.sql.
-- (Migration 115, `track_collaborators`, IS applied on production: D7.)
--
-- 1. `parties` — a rights identity (05 §3): who wrote / published / owns a
--    master. NOT `contacts`: buyers and leads never have an IPI or a PRO, and
--    legal identifiers must not sit in a CRM table that hundreds of buyers
--    flow into. `contact_id` links the same person to the CRM, `user_id` to
--    their account. Org-only (no user_id owner, the 139/142/143/144 rule):
--    every producer route filters on a producer's `user_id`, so none can
--    reach a party. Written by the service role only.
--
-- 2. `track_collaborators` gains org_id, party_id, scope, status, role_detail,
--    created_by, confirmed_by, confirmed_at, dispute_note. EVERY EXISTING ROW
--    READS UNCHANGED: org_id / party_id / scope stay NULL, status defaults to
--    'confirmed', and the producer routes (PATCH /api/tracks/[id]/collaborators)
--    select and write the same columns as before. The unique index
--    (track_id, lower(name), role) is untouched, which keeps the filename
--    re-parse idempotent.
--
--    A BEFORE trigger is the only place the two worlds meet:
--      · a credit on a PRODUCER track (tracks.org_id IS NULL) can carry no
--        org_id and no party — the producer app never writes Label OS data;
--      · a credit on an ORG track takes that track's org_id (a different one
--        is refused), defaults to scope 'recording', and a credit read from a
--        FILENAME arrives 'proposed': a name parsed out of a file is not a
--        legal credit until someone confirms it;
--      · the party and the contact must belong to the same org.
--
-- 3. Who reads (the security core; D2 + 06 §2.3):
--      rights.read (whole org, or the song is in the member's artist scope —
--        the 149 rule, labelos_scoped_tracks) → every credit of the org's songs
--      rights.read.own_line → only a credit whose party is the caller's own
--        (parties.user_id = the caller), while still an org member
--    An external member (LABEL-21) is not an org member and reads nothing
--    through PostgREST; the route serves their own line. Legal name, IPI, ISNI
--    and PRO sit on `parties`, whose policy asks rights.read AND (whole-org
--    member, or the party is credited on a song in the caller's artist scope —
--    06 §3, labelos_scoped_parties()) or "this party is me", so a marketing or
--    A&R-without-rights member's JWT never sees them.
--    No per-row SECURITY DEFINER call (R-08): the capability and the scope are
--    asked of the caller's own few memberships in uncorrelated subplans, the
--    149 pattern (proved with EXPLAIN in supabase/local/checks/153_*.sql).
--
-- 4. Writes: service role only (141's labelos_org_rows_service_only is
--    already on track_collaborators; it is added to parties here). The two
--    audit decisions — confirm and dispute (06 §6) — are ONE SECURITY DEFINER
--    function that changes the credit and inserts the `activity_events` row in
--    one transaction (the 146 pattern): EXECUTE for service_role only.
--
-- Idempotent: IF NOT EXISTS, CREATE OR REPLACE, DROP ... IF EXISTS first.

-- ── 1. parties ───────────────────────────────────────────────────────────

CREATE TABLE IF NOT EXISTS public.parties (
  id              uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  org_id          uuid NOT NULL REFERENCES public.organizations(id) ON DELETE CASCADE,
  kind            text NOT NULL DEFAULT 'person',
  display_name    text NOT NULL,
  legal_name      text,
  email           text,
  ipi             text,
  isni            text,
  pro             text,
  pro_affiliation text NOT NULL DEFAULT 'unknown',
  publisher_name  text,
  publisher_ipi   text,
  contact_id      uuid REFERENCES public.contacts(id) ON DELETE SET NULL,
  user_id         uuid REFERENCES auth.users(id) ON DELETE SET NULL,
  created_by      uuid REFERENCES auth.users(id) ON DELETE SET NULL,
  created_at      timestamptz NOT NULL DEFAULT now(),
  updated_at      timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT parties_kind_check CHECK (kind IN ('person', 'company')),
  CONSTRAINT parties_pro_affiliation_check CHECK (pro_affiliation IN ('affiliated', 'not_affiliated', 'unknown')),
  CONSTRAINT parties_display_name_check CHECK (length(btrim(display_name)) BETWEEN 1 AND 200),
  -- Same shapes lib/labelos/identifiers.ts normalises to (9-11 digits).
  CONSTRAINT parties_ipi_format CHECK (ipi IS NULL OR ipi ~ '^[0-9]{9,11}$'),
  CONSTRAINT parties_publisher_ipi_format CHECK (publisher_ipi IS NULL OR publisher_ipi ~ '^[0-9]{9,11}$'),
  CONSTRAINT parties_isni_format CHECK (isni IS NULL OR isni ~ '^[0-9]{15}[0-9X]$')
);

CREATE INDEX IF NOT EXISTS idx_parties_org_name ON public.parties (org_id, lower(display_name));
-- One rights identity per account per org: "themselves" is a single row.
CREATE UNIQUE INDEX IF NOT EXISTS idx_parties_org_user
  ON public.parties (org_id, user_id) WHERE user_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_parties_contact ON public.parties (contact_id) WHERE contact_id IS NOT NULL;

ALTER TABLE public.parties ENABLE ROW LEVEL SECURITY;

CREATE OR REPLACE FUNCTION public.parties_integrity()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  IF TG_OP = 'UPDATE' AND NEW.org_id <> OLD.org_id THEN
    RAISE EXCEPTION 'parties: a party keeps its organization' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.contact_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.contacts c WHERE c.id = NEW.contact_id AND c.org_id = NEW.org_id
  ) THEN
    RAISE EXCEPTION 'parties: the contact must be a contact of the same organization'
      USING ERRCODE = 'check_violation';
  END IF;
  NEW.updated_at := now();
  RETURN NEW;
END;
$$;

ALTER FUNCTION public.parties_integrity() OWNER TO postgres;
REVOKE ALL ON FUNCTION public.parties_integrity() FROM PUBLIC;

DROP TRIGGER IF EXISTS parties_integrity ON public.parties;
CREATE TRIGGER parties_integrity BEFORE INSERT OR UPDATE ON public.parties
  FOR EACH ROW EXECUTE FUNCTION public.parties_integrity();

DROP TRIGGER IF EXISTS labelos_org_rows_service_only ON public.parties;
CREATE TRIGGER labelos_org_rows_service_only BEFORE INSERT OR UPDATE OR DELETE ON public.parties
  FOR EACH ROW EXECUTE FUNCTION public.labelos_org_rows_service_only('self', 'org_id');

-- ── 2. track_collaborators: the Label OS columns ─────────────────────────

ALTER TABLE public.track_collaborators ADD COLUMN IF NOT EXISTS org_id       uuid REFERENCES public.organizations(id) ON DELETE CASCADE;
ALTER TABLE public.track_collaborators ADD COLUMN IF NOT EXISTS party_id     uuid REFERENCES public.parties(id) ON DELETE RESTRICT;
ALTER TABLE public.track_collaborators ADD COLUMN IF NOT EXISTS scope        text;
ALTER TABLE public.track_collaborators ADD COLUMN IF NOT EXISTS status       text NOT NULL DEFAULT 'confirmed';
ALTER TABLE public.track_collaborators ADD COLUMN IF NOT EXISTS role_detail  text;
ALTER TABLE public.track_collaborators ADD COLUMN IF NOT EXISTS created_by   uuid REFERENCES auth.users(id) ON DELETE SET NULL;
ALTER TABLE public.track_collaborators ADD COLUMN IF NOT EXISTS confirmed_by uuid REFERENCES auth.users(id) ON DELETE SET NULL;
ALTER TABLE public.track_collaborators ADD COLUMN IF NOT EXISTS confirmed_at timestamptz;
ALTER TABLE public.track_collaborators ADD COLUMN IF NOT EXISTS dispute_note text;

ALTER TABLE public.track_collaborators DROP CONSTRAINT IF EXISTS track_collaborators_scope_check;
ALTER TABLE public.track_collaborators ADD CONSTRAINT track_collaborators_scope_check
  CHECK (scope IS NULL OR scope IN ('composition', 'recording'));
ALTER TABLE public.track_collaborators DROP CONSTRAINT IF EXISTS track_collaborators_status_check;
ALTER TABLE public.track_collaborators ADD CONSTRAINT track_collaborators_status_check
  CHECK (status IN ('proposed', 'confirmed', 'disputed'));
ALTER TABLE public.track_collaborators DROP CONSTRAINT IF EXISTS track_collaborators_role_detail_check;
ALTER TABLE public.track_collaborators ADD CONSTRAINT track_collaborators_role_detail_check
  CHECK (role_detail IS NULL OR length(role_detail) BETWEEN 1 AND 200);
ALTER TABLE public.track_collaborators DROP CONSTRAINT IF EXISTS track_collaborators_dispute_note_check;
ALTER TABLE public.track_collaborators ADD CONSTRAINT track_collaborators_dispute_note_check
  CHECK (dispute_note IS NULL OR length(dispute_note) BETWEEN 1 AND 1000);
-- Label OS data lives on org rows only; a producer row carries none of it.
ALTER TABLE public.track_collaborators DROP CONSTRAINT IF EXISTS track_collaborators_org_columns;
ALTER TABLE public.track_collaborators ADD CONSTRAINT track_collaborators_org_columns
  CHECK (org_id IS NOT NULL OR (party_id IS NULL AND scope IS NULL AND status = 'confirmed'));

CREATE INDEX IF NOT EXISTS idx_track_collaborators_org_track
  ON public.track_collaborators (org_id, track_id) WHERE org_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_track_collaborators_party
  ON public.track_collaborators (party_id) WHERE party_id IS NOT NULL;

CREATE OR REPLACE FUNCTION public.track_collaborators_org_integrity()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_org uuid;
BEGIN
  SELECT t.org_id INTO v_org FROM public.tracks t WHERE t.id = NEW.track_id;

  IF v_org IS NULL THEN
    -- A producer track: nothing of Label OS may ride on its credits.
    IF NEW.org_id IS NOT NULL OR NEW.party_id IS NOT NULL OR NEW.scope IS NOT NULL OR NEW.status <> 'confirmed' THEN
      RAISE EXCEPTION 'track_collaborators: a producer track takes no organization, party, scope or status'
        USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
  END IF;

  IF NEW.org_id IS NOT NULL AND NEW.org_id <> v_org THEN
    RAISE EXCEPTION 'track_collaborators: the credit must belong to the track''s organization'
      USING ERRCODE = 'check_violation';
  END IF;
  NEW.org_id := v_org;

  IF TG_OP = 'UPDATE' AND (NEW.track_id <> OLD.track_id OR (OLD.org_id IS NOT NULL AND NEW.org_id <> OLD.org_id)) THEN
    RAISE EXCEPTION 'track_collaborators: a credit keeps its track and organization'
      USING ERRCODE = 'check_violation';
  END IF;

  IF NEW.scope IS NULL THEN
    -- The legacy producer / feature / collaborator roles are production credits.
    NEW.scope := 'recording';
  END IF;

  IF TG_OP = 'INSERT' AND NEW.source = 'filename' AND NEW.status = 'confirmed' AND NEW.confirmed_by IS NULL THEN
    NEW.status := 'proposed';
  END IF;

  IF NEW.party_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.parties p WHERE p.id = NEW.party_id AND p.org_id = v_org
  ) THEN
    RAISE EXCEPTION 'track_collaborators: the party must belong to the same organization'
      USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.contact_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.contacts c WHERE c.id = NEW.contact_id AND c.org_id = v_org
  ) THEN
    RAISE EXCEPTION 'track_collaborators: the contact must belong to the same organization'
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;

ALTER FUNCTION public.track_collaborators_org_integrity() OWNER TO postgres;
REVOKE ALL ON FUNCTION public.track_collaborators_org_integrity() FROM PUBLIC;

DROP TRIGGER IF EXISTS track_collaborators_org_integrity ON public.track_collaborators;
CREATE TRIGGER track_collaborators_org_integrity BEFORE INSERT OR UPDATE ON public.track_collaborators
  FOR EACH ROW EXECUTE FUNCTION public.track_collaborators_org_integrity();

-- Org members read org credits; the producer policy (via the parent track's
-- owner) is untouched and cannot match an org track (user_id NULL).
DROP POLICY IF EXISTS track_collaborators_org_member_read ON public.track_collaborators;
CREATE POLICY track_collaborators_org_member_read ON public.track_collaborators
  FOR SELECT
  USING (
    org_id IS NOT NULL
    AND (
      (
        org_id IN (
          SELECT cm.org_id
          FROM public.org_members cm
          WHERE cm.user_id = (SELECT auth.uid())
            AND public.has_org_cap(cm.org_id, 'rights.read')
        )
        AND (
          org_id IN (
            SELECT om.org_id
            FROM public.org_members om
            WHERE om.user_id = (SELECT auth.uid())
              AND om.scope = 'org'
              AND om.role <> 'artist'
          )
          OR (org_id, track_id) IN (SELECT st.org_id, st.track_id FROM public.labelos_scoped_tracks() st)
        )
      )
      OR (
        party_id IN (SELECT mp.id FROM public.parties mp WHERE mp.user_id = (SELECT auth.uid()))
        AND org_id IN (SELECT mm.org_id FROM public.org_members mm WHERE mm.user_id = (SELECT auth.uid()))
      )
    )
  );

-- ── 2b. Parties: who reads them ──────────────────────────────────────────
-- 06 §3: org-level parties (no artist) are for whole-org members, EXCEPT the
-- parties named by credits on songs in the caller's artist scope. So:
--   rights.read AND (a whole-org member, OR the party is credited on a song of
--     the caller's scope — labelos_scoped_parties(), below)
--   OR the party is the caller's own identity (parties.user_id), while they are
--     still a member of that org (this is also what lets the own-line branch of
--     the credits policy find "my party" without the credits policy and this
--     one calling each other: a policy that reads a table whose policy reads
--     back is "infinite recursion" in Postgres).
-- No per-row SECURITY DEFINER call: every disjunct is an uncorrelated subplan.

CREATE OR REPLACE FUNCTION public.labelos_scoped_parties()
RETURNS TABLE (org_id uuid, party_id uuid)
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
  SELECT DISTINCT c.org_id, c.party_id
  FROM public.labelos_scoped_tracks() st
  JOIN public.track_collaborators c ON c.track_id = st.track_id AND c.org_id = st.org_id
  WHERE c.party_id IS NOT NULL;
$$;

ALTER FUNCTION public.labelos_scoped_parties() OWNER TO postgres;
REVOKE ALL ON FUNCTION public.labelos_scoped_parties() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.labelos_scoped_parties() TO authenticated, anon;

DROP POLICY IF EXISTS parties_member_read ON public.parties;
CREATE POLICY parties_member_read ON public.parties
  FOR SELECT
  USING (
    (
      org_id IN (
        SELECT cm.org_id
        FROM public.org_members cm
        WHERE cm.user_id = (SELECT auth.uid())
          AND public.has_org_cap(cm.org_id, 'rights.read')
      )
      AND (
        org_id IN (
          SELECT om.org_id
          FROM public.org_members om
          WHERE om.user_id = (SELECT auth.uid())
            AND om.scope = 'org'
            AND om.role <> 'artist'
        )
        OR (org_id, id) IN (SELECT sp.org_id, sp.party_id FROM public.labelos_scoped_parties() sp)
      )
    )
    OR (
      user_id = (SELECT auth.uid())
      AND org_id IN (SELECT mm.org_id FROM public.org_members mm WHERE mm.user_id = (SELECT auth.uid()))
    )
  );

-- 141 put a RESTRICTIVE guard on this table, `NOT labelos_is_org_track(track_id)`,
-- so no producer-era policy could reach a credit of an org track. It would also
-- hide the org policy above from every member. It is replaced (same name, still
-- RESTRICTIVE / SELECT) by: a row that carries an org_id is an org credit, which
-- only the org policy can admit; anything else is held to the old rule. The
-- trigger above stamps org_id on every credit of an org track, so a credit of an
-- org track WITHOUT one cannot exist, and the producer policy still cannot match
-- one (org tracks have no user_id). `org_id IS NOT NULL` is tested first, so org
-- rows never pay for the per-row helper.
DROP POLICY IF EXISTS org_member_guard ON public.track_collaborators;
CREATE POLICY org_member_guard ON public.track_collaborators
  AS RESTRICTIVE FOR SELECT
  USING (org_id IS NOT NULL OR NOT public.labelos_is_org_track(track_id));

-- ── 3. Confirm / dispute: the audit decision ─────────────────────────────
-- p_decision: 'confirmed' | 'disputed'. The route has already decided WHO may
-- (rights.write, or the credited person for their own line); this function
-- does what the database can know for itself: the credit is a credit of the
-- org, a decision is a change, and the event is written in the same
-- transaction. p_subject carries the song's context keys the route resolved
-- ({artist_id, project_id, song_id}, each a uuid or null).
-- Answers {"credit": <row>}, {"error": "not_found"} or {"error": "unchanged"}.

CREATE OR REPLACE FUNCTION public.labelos_audit_credit_decide(
  p_org uuid,
  p_actor uuid,
  p_credit uuid,
  p_decision text,
  p_note text,
  p_subject jsonb,
  p_payload jsonb
) RETURNS jsonb
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path = public
AS $fn$
DECLARE
  v_row   public.track_collaborators%ROWTYPE;
  v_verb  text;
  v_art   uuid;
  v_proj  uuid;
  v_song  uuid;
BEGIN
  IF p_decision NOT IN ('confirmed', 'disputed') THEN
    RAISE EXCEPTION 'unknown credit decision %', p_decision USING ERRCODE = '22023';
  END IF;
  IF p_payload IS NULL OR jsonb_typeof(p_payload) <> 'object' THEN
    RAISE EXCEPTION 'audit payload must be an object' USING ERRCODE = '22023';
  END IF;
  IF p_payload::text ~* '"[^"]*(token|password|secret)[^"]*"\s*:' THEN
    RAISE EXCEPTION 'audit payload carries a secret-looking key' USING ERRCODE = '22023';
  END IF;
  IF pg_column_size(p_payload) > 16384 THEN
    RAISE EXCEPTION 'audit payload is too large' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_row FROM public.track_collaborators
  WHERE id = p_credit AND org_id = p_org
  FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('error', 'not_found');
  END IF;
  IF v_row.status = p_decision THEN
    RETURN jsonb_build_object('error', 'unchanged');
  END IF;

  IF p_decision = 'confirmed' THEN
    UPDATE public.track_collaborators
    SET status = 'confirmed', confirmed_by = p_actor, confirmed_at = now(), dispute_note = NULL
    WHERE id = p_credit
    RETURNING * INTO v_row;
    v_verb := 'credit.confirmed';
  ELSE
    UPDATE public.track_collaborators
    SET status = 'disputed', confirmed_by = NULL, confirmed_at = NULL, dispute_note = p_note
    WHERE id = p_credit
    RETURNING * INTO v_row;
    v_verb := 'credit.disputed';
  END IF;

  v_art  := NULLIF(p_subject->>'artist_id', '')::uuid;
  v_proj := NULLIF(p_subject->>'project_id', '')::uuid;
  v_song := NULLIF(p_subject->>'song_id', '')::uuid;

  -- The creative record (DEFAULT_VISIBILITY: 'artist'), kept for the life of
  -- the org (audit = true).
  INSERT INTO public.activity_events (org_id, actor_id, verb, subject_type, subject_id, artist_id, project_id, song_id, payload, audit, visibility)
  VALUES (p_org, p_actor, v_verb, 'credit', v_row.id, v_art, v_proj, v_song, p_payload, true, 'artist');

  RETURN jsonb_build_object('credit', to_jsonb(v_row));
END;
$fn$;

ALTER FUNCTION public.labelos_audit_credit_decide(uuid, uuid, uuid, text, text, jsonb, jsonb) OWNER TO postgres;
REVOKE ALL ON FUNCTION public.labelos_audit_credit_decide(uuid, uuid, uuid, text, text, jsonb, jsonb) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.labelos_audit_credit_decide(uuid, uuid, uuid, text, text, jsonb, jsonb) TO service_role;

NOTIFY pgrst, 'reload schema';


-- ═════════════ 154_labelos_artist_label_connection.sql ═════════════
-- 154_labelos_artist_label_connection.sql
-- Label OS (LABEL-41): the artist ↔ label connection (D1, D6, 17 R3).
--
-- LABEL OS — NOT APPLIED. Apply at the final merge of the Label OS branch
-- into main, after 136–151 (docs/bstudio-label-os/16-execution-runbook.md).
-- Never part of supabase/apply/pending.sql. (152 is LABEL-26's, 153
-- LABEL-27's.)
--
-- An ARTIST org connects to a LABEL org and shares its whole catalogue or
-- chosen projects; the label sees that music through ONE roster contact,
-- under its own staff permissions (D1). This is the most sensitive Label OS
-- boundary after external project members (148), so the database half keeps
-- the same shape: the tables and the audit functions live here, the reads go
-- through service-role routes that apply the rule in TypeScript
-- (lib/labelos/connections, lib/auth/org-access#requireConnectedTrack), and
-- NO policy anywhere gives a label member the artist org's projects, tracks,
-- files, comments, members, contacts or activity. `can_see_via_connection`
-- is the SQL twin of the route rule, proven as an `authenticated` user in
-- supabase/local/checks/154_*.sql; deliberately not used by any policy.
--
--   1. `org_connections` — (label org, artist org, status requested | active
--      | declined | ended, who initiated, the label's roster contact, the
--      share mode, whether the label may copy). A partial unique index allows
--      ONE open (requested or active) connection per pair. Integrity trigger:
--      the sides are a live label org and a live artist org, who/where never
--      change, the status only moves requested → active | declined | ended and
--      active → ended (terminal after that), an active connection has a
--      roster contact of the LABEL org. Writes: the audit functions only.
--   2. `connection_projects` — the artist org's projects shared under a
--      `selected` connection. A trigger refuses a project of any other org.
--   3. `contacts.artist_org_id` (17 R3) — the label's roster contact points
--      at the connected artist org. Only for an org contact, one per
--      (label, artist org); a trigger refuses a value with no open connection
--      between exactly those two orgs (so no contact route can forge one).
--   4. `tracks.provenance` — nullable jsonb on a COPIED recording (D6):
--      `source_org_id`, `source_track_id`, `copied_at`, `copied_by`. Org rows
--      only; immutable once set. No live cross-org reference: the copy is its
--      own track.
--   5. `can_see_via_connection(project)`.
--   6. RLS: SELECT only. `org_connections` is read by the owners / admins of
--      either side, `connection_projects` by those of the artist side. No
--      per-row SECURITY DEFINER call (R-08): the caller's few memberships are
--      one uncorrelated subplan. Writes are service role only.
--   7. Audit functions (service_role only, mutation + `activity_events` row(s)
--      in ONE transaction, the 146 pattern; the event is recorded in BOTH
--      orgs, because both are parties):
--        labelos_audit_connection_request   connection.requested
--        labelos_audit_connection_accept    connection.accepted
--        labelos_audit_connection_end       connection.ended
--        labelos_audit_connection_share     share.created | share.revoked
--
-- Idempotent: IF NOT EXISTS, CREATE OR REPLACE, DROP ... IF EXISTS first.

-- ── 1. org_connections ──────────────────────────────────────────────────

CREATE TABLE IF NOT EXISTS public.org_connections (
  id               uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  label_org_id     uuid NOT NULL REFERENCES public.organizations(id) ON DELETE CASCADE,
  artist_org_id    uuid NOT NULL REFERENCES public.organizations(id) ON DELETE CASCADE,
  status           text NOT NULL DEFAULT 'requested' CHECK (status IN ('requested', 'active', 'declined', 'ended')),
  initiated_by     text NOT NULL CHECK (initiated_by IN ('label', 'artist')),
  requested_by     uuid REFERENCES auth.users(id) ON DELETE SET NULL,
  -- The label's roster contact for this artist (17 R3). Chosen by the label
  -- when it asks, else created when the connection is accepted.
  label_contact_id uuid REFERENCES public.contacts(id) ON DELETE RESTRICT,
  -- What the label may reach: `selected` = the projects in connection_projects
  -- (none until the artist side picks), `all` = every project of the artist org.
  share_mode       text NOT NULL DEFAULT 'selected' CHECK (share_mode IN ('selected', 'all')),
  -- D6: may the label COPY a shared recording into its own org? Off until the
  -- artist side says so; listening never implies it.
  allow_copies     boolean NOT NULL DEFAULT false,
  accepted_by      uuid REFERENCES auth.users(id) ON DELETE SET NULL,
  accepted_at      timestamptz,
  ended_by         uuid REFERENCES auth.users(id) ON DELETE SET NULL,
  ended_at         timestamptz,
  ended_side       text CHECK (ended_side IN ('label', 'artist')),
  created_at       timestamptz NOT NULL DEFAULT now(),
  updated_at       timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT org_connections_distinct_orgs CHECK (label_org_id <> artist_org_id),
  CONSTRAINT org_connections_active_has_contact CHECK (status <> 'active' OR label_contact_id IS NOT NULL)
);

-- ONE open connection per (label, artist) pair: requested and active both
-- count, so a second request cannot be stacked on a pending or live one.
CREATE UNIQUE INDEX IF NOT EXISTS org_connections_one_open
  ON public.org_connections (label_org_id, artist_org_id)
  WHERE status IN ('requested', 'active');
CREATE INDEX IF NOT EXISTS idx_org_connections_artist
  ON public.org_connections (artist_org_id, status);
CREATE INDEX IF NOT EXISTS idx_org_connections_label
  ON public.org_connections (label_org_id, status);

CREATE TABLE IF NOT EXISTS public.connection_projects (
  connection_id uuid NOT NULL REFERENCES public.org_connections(id) ON DELETE CASCADE,
  project_id    uuid NOT NULL REFERENCES public.projects(id) ON DELETE CASCADE,
  -- The artist org (denormalised so the policy needs no join).
  org_id        uuid NOT NULL REFERENCES public.organizations(id) ON DELETE CASCADE,
  created_at    timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (connection_id, project_id)
);
CREATE INDEX IF NOT EXISTS idx_connection_projects_project ON public.connection_projects (project_id);

-- ── 2. integrity ────────────────────────────────────────────────────────

CREATE OR REPLACE FUNCTION public.org_connections_integrity()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NOT EXISTS (SELECT 1 FROM public.organizations o WHERE o.id = NEW.label_org_id AND o.kind = 'label' AND o.deleted_at IS NULL) THEN
      RAISE EXCEPTION 'org_connections: % is not a label organization', NEW.label_org_id USING ERRCODE = 'check_violation';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM public.organizations o WHERE o.id = NEW.artist_org_id AND o.kind = 'artist' AND o.deleted_at IS NULL) THEN
      RAISE EXCEPTION 'org_connections: % is not an artist organization', NEW.artist_org_id USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.status <> 'requested' THEN
      RAISE EXCEPTION 'org_connections: a connection starts as a request' USING ERRCODE = 'check_violation';
    END IF;
  ELSE
    IF NEW.label_org_id IS DISTINCT FROM OLD.label_org_id
       OR NEW.artist_org_id IS DISTINCT FROM OLD.artist_org_id
       OR NEW.initiated_by IS DISTINCT FROM OLD.initiated_by THEN
      RAISE EXCEPTION 'org_connections: the two sides of a connection cannot change' USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.status IS DISTINCT FROM OLD.status AND NOT (
      (OLD.status = 'requested' AND NEW.status IN ('active', 'declined', 'ended'))
      OR (OLD.status = 'active' AND NEW.status = 'ended')
    ) THEN
      RAISE EXCEPTION 'org_connections: % → % is not a valid move', OLD.status, NEW.status USING ERRCODE = 'check_violation';
    END IF;
    NEW.updated_at := now();
  END IF;
  -- The roster contact is a contact of the LABEL org.
  IF NEW.label_contact_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.contacts c WHERE c.id = NEW.label_contact_id AND c.org_id = NEW.label_org_id
  ) THEN
    RAISE EXCEPTION 'org_connections: contact % is not a contact of the label organization', NEW.label_contact_id
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;

ALTER FUNCTION public.org_connections_integrity() OWNER TO postgres;
REVOKE ALL ON FUNCTION public.org_connections_integrity() FROM PUBLIC;

DROP TRIGGER IF EXISTS org_connections_integrity ON public.org_connections;
CREATE TRIGGER org_connections_integrity
  BEFORE INSERT OR UPDATE ON public.org_connections
  FOR EACH ROW EXECUTE FUNCTION public.org_connections_integrity();

CREATE OR REPLACE FUNCTION public.connection_projects_integrity()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  IF NOT EXISTS (
    SELECT 1
    FROM public.org_connections c
    JOIN public.projects p ON p.id = NEW.project_id
    WHERE c.id = NEW.connection_id
      AND p.org_id IS NOT NULL
      AND p.org_id = c.artist_org_id
      AND NEW.org_id = c.artist_org_id
  ) THEN
    RAISE EXCEPTION 'connection_projects: project % is not a project of the connection''s artist organization', NEW.project_id
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;

ALTER FUNCTION public.connection_projects_integrity() OWNER TO postgres;
REVOKE ALL ON FUNCTION public.connection_projects_integrity() FROM PUBLIC;

DROP TRIGGER IF EXISTS connection_projects_integrity ON public.connection_projects;
CREATE TRIGGER connection_projects_integrity
  BEFORE INSERT OR UPDATE ON public.connection_projects
  FOR EACH ROW EXECUTE FUNCTION public.connection_projects_integrity();

-- ── 3. contacts.artist_org_id ───────────────────────────────────────────

ALTER TABLE public.contacts
  ADD COLUMN IF NOT EXISTS artist_org_id uuid REFERENCES public.organizations(id) ON DELETE SET NULL;

DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_constraint
    WHERE conname = 'contacts_artist_org_is_org_contact' AND conrelid = 'public.contacts'::regclass
  ) THEN
    ALTER TABLE public.contacts
      ADD CONSTRAINT contacts_artist_org_is_org_contact CHECK (artist_org_id IS NULL OR org_id IS NOT NULL);
  END IF;
END $$;

-- A label connects to an artist org through ONE roster contact.
CREATE UNIQUE INDEX IF NOT EXISTS contacts_org_artist_org_uniq
  ON public.contacts (org_id, artist_org_id)
  WHERE artist_org_id IS NOT NULL;

-- artist_org_id can only name an artist org this contact's label has an open
-- connection with — so no contact route (service role included) can point a
-- roster contact at an org it is not connected to.
CREATE OR REPLACE FUNCTION public.contacts_artist_org_connected()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  IF NEW.artist_org_id IS NULL THEN
    RETURN NEW;
  END IF;
  IF TG_OP = 'UPDATE' AND NEW.artist_org_id IS NOT DISTINCT FROM OLD.artist_org_id THEN
    RETURN NEW;
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.org_connections c
    WHERE c.label_org_id = NEW.org_id
      AND c.artist_org_id = NEW.artist_org_id
      AND c.status IN ('requested', 'active')
  ) THEN
    RAISE EXCEPTION 'contacts: artist_org_id needs an open connection between the two organizations'
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;

ALTER FUNCTION public.contacts_artist_org_connected() OWNER TO postgres;
REVOKE ALL ON FUNCTION public.contacts_artist_org_connected() FROM PUBLIC;

DROP TRIGGER IF EXISTS contacts_artist_org_connected ON public.contacts;
CREATE TRIGGER contacts_artist_org_connected
  BEFORE INSERT OR UPDATE OF artist_org_id ON public.contacts
  FOR EACH ROW EXECUTE FUNCTION public.contacts_artist_org_connected();

-- ── 4. tracks.provenance ────────────────────────────────────────────────

ALTER TABLE public.tracks
  ADD COLUMN IF NOT EXISTS provenance jsonb;

DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_constraint
    WHERE conname = 'tracks_provenance_shape' AND conrelid = 'public.tracks'::regclass
  ) THEN
    ALTER TABLE public.tracks
      ADD CONSTRAINT tracks_provenance_shape CHECK (
        provenance IS NULL
        OR (
          org_id IS NOT NULL
          AND jsonb_typeof(provenance) = 'object'
          AND provenance ? 'source_track_id'
          AND provenance ? 'copied_at'
          AND provenance ? 'copied_by'
        )
      );
  END IF;
END $$;

-- A copy's origin is a fact about the copy: it is never rewritten or removed.
CREATE OR REPLACE FUNCTION public.tracks_provenance_fixed()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  IF OLD.provenance IS NOT NULL AND NEW.provenance IS DISTINCT FROM OLD.provenance THEN
    RAISE EXCEPTION 'tracks: the provenance of a copied recording cannot change'
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;

ALTER FUNCTION public.tracks_provenance_fixed() OWNER TO postgres;
REVOKE ALL ON FUNCTION public.tracks_provenance_fixed() FROM PUBLIC;

DROP TRIGGER IF EXISTS tracks_provenance_fixed ON public.tracks;
CREATE TRIGGER tracks_provenance_fixed
  BEFORE UPDATE OF provenance ON public.tracks
  FOR EACH ROW EXECUTE FUNCTION public.tracks_provenance_fixed();

-- ── 5. can_see_via_connection ───────────────────────────────────────────
-- Does the caller reach this ARTIST-org project as a member of the
-- connected LABEL? An active connection whose artist org owns the project, the
-- project shared under it (mode `all`, or listed in connection_projects), the
-- caller holding catalog.read in the label and, if limited to some artists,
-- the connection's roster contact among them (can_see_artist). False for a
-- producer project, a project outside the share, an ended / requested / declined
-- connection, a deleted org on either side, and everyone else. The route rule
-- is the TypeScript twin (lib/labelos/connections#connectionReachesProject).
-- Not used by any policy: label members read the artist org's rows only
-- through the service-role routes, never with their own JWT.

CREATE OR REPLACE FUNCTION public.can_see_via_connection(p_project uuid)
RETURNS boolean
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
  SELECT EXISTS (
    SELECT 1
    FROM public.projects p
    JOIN public.org_connections c ON c.artist_org_id = p.org_id AND c.status = 'active'
    JOIN public.organizations ao ON ao.id = c.artist_org_id AND ao.deleted_at IS NULL
    JOIN public.organizations lo ON lo.id = c.label_org_id AND lo.deleted_at IS NULL
    WHERE p.id = p_project
      AND p.org_id IS NOT NULL
      AND (
        c.share_mode = 'all'
        OR EXISTS (
          SELECT 1 FROM public.connection_projects cp
          WHERE cp.connection_id = c.id AND cp.project_id = p.id
        )
      )
      AND public.has_org_cap(c.label_org_id, 'catalog.read')
      AND c.label_contact_id IS NOT NULL
      AND public.can_see_artist(c.label_org_id, c.label_contact_id)
  );
$$;

ALTER FUNCTION public.can_see_via_connection(uuid) OWNER TO postgres;
REVOKE ALL ON FUNCTION public.can_see_via_connection(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.can_see_via_connection(uuid) TO authenticated, anon;

-- ── 6. RLS ──────────────────────────────────────────────────────────────

ALTER TABLE public.org_connections ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.connection_projects ENABLE ROW LEVEL SECURITY;

-- The connection row is read by the owners / admins (the people who manage
-- it) of EITHER side, and only one who sees the WHOLE org (scope = 'org'): an
-- admin limited to some artists must not read connections of artists outside
-- their scope. Membership is hashed once per statement.
DROP POLICY IF EXISTS org_connections_manage_read ON public.org_connections;
CREATE POLICY org_connections_manage_read ON public.org_connections
  FOR SELECT
  TO authenticated
  USING (
    label_org_id IN (
      SELECT m.org_id FROM public.org_members m
      WHERE m.user_id = (SELECT auth.uid()) AND m.role IN ('owner', 'admin') AND m.scope = 'org'
    )
    OR artist_org_id IN (
      SELECT m.org_id FROM public.org_members m
      WHERE m.user_id = (SELECT auth.uid()) AND m.role IN ('owner', 'admin') AND m.scope = 'org'
    )
  );

-- What is shared is the ARTIST side's to read; the label learns it through
-- the route that lists the projects it may open.
DROP POLICY IF EXISTS connection_projects_artist_read ON public.connection_projects;
CREATE POLICY connection_projects_artist_read ON public.connection_projects
  FOR SELECT
  TO authenticated
  USING (
    org_id IN (
      SELECT m.org_id FROM public.org_members m
      WHERE m.user_id = (SELECT auth.uid()) AND m.role IN ('owner', 'admin') AND m.scope = 'org'
    )
  );

REVOKE ALL ON public.org_connections FROM anon, authenticated;
REVOKE ALL ON public.connection_projects FROM anon, authenticated;
-- Column-level: each side reads the connection, never the OTHER side's people
-- (requested_by / accepted_by / ended_by are user ids of whoever acted).
GRANT SELECT (id, label_org_id, artist_org_id, status, initiated_by, label_contact_id, share_mode,
              allow_copies, accepted_at, ended_at, ended_side, created_at, updated_at)
  ON public.org_connections TO authenticated;
GRANT SELECT ON public.connection_projects TO authenticated;

-- ── 7. Audit functions ──────────────────────────────────────────────────

-- The two parties' names, for the payloads.
CREATE OR REPLACE FUNCTION public.labelos_connection_payload(p_conn uuid, p_extra jsonb)
RETURNS jsonb
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
  SELECT COALESCE(p_extra, '{}'::jsonb) || jsonb_build_object(
    'connection_id', c.id,
    'label', lo.name,
    'artist', ao.name
  )
  FROM public.org_connections c
  JOIN public.organizations lo ON lo.id = c.label_org_id
  JOIN public.organizations ao ON ao.id = c.artist_org_id
  WHERE c.id = p_conn;
$$;

ALTER FUNCTION public.labelos_connection_payload(uuid, jsonb) OWNER TO postgres;
REVOKE ALL ON FUNCTION public.labelos_connection_payload(uuid, jsonb) FROM PUBLIC, anon, authenticated, service_role;

CREATE OR REPLACE FUNCTION public.labelos_connection_json(p_conn uuid)
RETURNS jsonb
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
  SELECT jsonb_build_object(
    'id', c.id,
    'label_org_id', c.label_org_id,
    'artist_org_id', c.artist_org_id,
    'status', c.status,
    'initiated_by', c.initiated_by,
    'label_contact_id', c.label_contact_id,
    'share_mode', c.share_mode,
    'allow_copies', c.allow_copies,
    'accepted_at', c.accepted_at,
    'ended_at', c.ended_at,
    'created_at', c.created_at
  )
  FROM public.org_connections c WHERE c.id = p_conn;
$$;

ALTER FUNCTION public.labelos_connection_json(uuid) OWNER TO postgres;
REVOKE ALL ON FUNCTION public.labelos_connection_json(uuid) FROM PUBLIC, anon, authenticated, service_role;

-- Ask to connect. p_side is the side of the REQUESTING org (p_org), which
-- must be of that kind; the other side is found by slug or by the email of one
-- of its owners / admins. Answers {"connection": <row>},
-- {"error": "not_found"} (no such org of the other kind — a request for an
-- org that does not exist, is the wrong kind or was deleted all read the
-- same, so the call cannot be used to probe) or {"error": "pending", "id"}
-- (an open connection already exists), or {"error": "bad_contact"}.
CREATE OR REPLACE FUNCTION public.labelos_audit_connection_request(
  p_org uuid,
  p_actor uuid,
  p_side text,
  p_target_slug text,
  p_target_email text,
  p_contact uuid,
  p_payload jsonb
) RETURNS jsonb
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path = public
AS $fn$
DECLARE
  v_other_kind text;
  v_self       public.organizations%ROWTYPE;
  v_target     public.organizations%ROWTYPE;
  v_label      uuid;
  v_artist     uuid;
  v_conn       public.org_connections%ROWTYPE;
  v_open       uuid;
BEGIN
  IF p_side NOT IN ('label', 'artist') THEN
    RAISE EXCEPTION 'unknown side %', p_side USING ERRCODE = '22023';
  END IF;
  v_other_kind := CASE WHEN p_side = 'label' THEN 'artist' ELSE 'label' END;

  SELECT * INTO v_self FROM public.organizations WHERE id = p_org AND kind = p_side AND deleted_at IS NULL;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('error', 'not_found');
  END IF;

  -- Judged on the ASKING org alone and BEFORE the target is looked up, so the
  -- answer cannot reveal whether the target exists (no existence oracle).
  IF p_contact IS NOT NULL AND (
    p_side <> 'label'
    OR NOT EXISTS (SELECT 1 FROM public.contacts c WHERE c.id = p_contact AND c.org_id = p_org)
  ) THEN
    RETURN jsonb_build_object('error', 'bad_contact');
  END IF;

  IF nullif(btrim(p_target_slug), '') IS NOT NULL THEN
    SELECT * INTO v_target FROM public.organizations
    WHERE slug = lower(btrim(p_target_slug)) AND kind = v_other_kind AND deleted_at IS NULL;
  ELSIF nullif(btrim(p_target_email), '') IS NOT NULL THEN
    SELECT o.* INTO v_target FROM public.organizations o
    WHERE o.kind = v_other_kind AND o.deleted_at IS NULL
      AND EXISTS (
        SELECT 1 FROM public.org_members m
        JOIN auth.users u ON u.id = m.user_id
        WHERE m.org_id = o.id AND m.role IN ('owner', 'admin')
          AND lower(u.email) = lower(btrim(p_target_email))
      )
    ORDER BY o.created_at ASC, o.id ASC
    LIMIT 1;
  END IF;
  IF v_target.id IS NULL THEN
    RETURN jsonb_build_object('error', 'not_found');
  END IF;

  v_label  := CASE WHEN p_side = 'label' THEN p_org ELSE v_target.id END;
  v_artist := CASE WHEN p_side = 'label' THEN v_target.id ELSE p_org END;

  PERFORM pg_advisory_xact_lock(hashtextextended(v_label::text || ':' || v_artist::text, 0));

  SELECT c.id INTO v_open FROM public.org_connections c
  WHERE c.label_org_id = v_label AND c.artist_org_id = v_artist AND c.status IN ('requested', 'active')
  LIMIT 1;
  IF v_open IS NOT NULL THEN
    RETURN jsonb_build_object('error', 'pending', 'id', v_open);
  END IF;

  INSERT INTO public.org_connections (label_org_id, artist_org_id, initiated_by, requested_by, label_contact_id)
  VALUES (v_label, v_artist, p_side, p_actor, p_contact)
  RETURNING * INTO v_conn;

  PERFORM public.labelos_audit_insert(v_label, p_actor, 'connection.requested', 'connection', v_conn.id,
    public.labelos_connection_payload(v_conn.id, COALESCE(p_payload, '{}'::jsonb) || jsonb_build_object('side', p_side)));
  PERFORM public.labelos_audit_insert(v_artist, p_actor, 'connection.requested', 'connection', v_conn.id,
    public.labelos_connection_payload(v_conn.id, COALESCE(p_payload, '{}'::jsonb) || jsonb_build_object('side', p_side)));

  RETURN jsonb_build_object('connection', public.labelos_connection_json(v_conn.id));
END;
$fn$;

ALTER FUNCTION public.labelos_audit_connection_request(uuid, uuid, text, text, text, uuid, jsonb) OWNER TO postgres;
REVOKE ALL ON FUNCTION public.labelos_audit_connection_request(uuid, uuid, text, text, text, uuid, jsonb) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.labelos_audit_connection_request(uuid, uuid, text, text, text, uuid, jsonb) TO service_role;

-- Accept a request. p_org is the ACCEPTING org, which must be the side that
-- did NOT start it (the starter cannot approve its own request). The label's
-- roster contact is the one named in the request, else a new one named after
-- the artist org; it then points at the artist org (artist_org_id).
-- Answers {"connection": <row>}, {"error": "not_found"} (no such request for
-- this org) or {"error": "contact_taken"} (the roster contact already stands
-- for another artist org).
CREATE OR REPLACE FUNCTION public.labelos_audit_connection_accept(
  p_org uuid,
  p_actor uuid,
  p_connection uuid,
  p_payload jsonb
) RETURNS jsonb
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path = public
AS $fn$
DECLARE
  v_conn    public.org_connections%ROWTYPE;
  v_contact uuid;
  v_name    text;
BEGIN
  SELECT * INTO v_conn FROM public.org_connections WHERE id = p_connection FOR UPDATE;
  IF NOT FOUND OR v_conn.status <> 'requested' THEN
    RETURN jsonb_build_object('error', 'not_found');
  END IF;
  -- The accepting org is a party and is NOT the one that asked.
  IF NOT (
    (v_conn.initiated_by = 'label' AND p_org = v_conn.artist_org_id)
    OR (v_conn.initiated_by = 'artist' AND p_org = v_conn.label_org_id)
  ) THEN
    RETURN jsonb_build_object('error', 'not_found');
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.organizations o WHERE o.id = v_conn.label_org_id AND o.deleted_at IS NULL)
     OR NOT EXISTS (SELECT 1 FROM public.organizations o WHERE o.id = v_conn.artist_org_id AND o.deleted_at IS NULL) THEN
    RETURN jsonb_build_object('error', 'not_found');
  END IF;

  v_contact := v_conn.label_contact_id;
  IF v_contact IS NULL THEN
    SELECT o.name INTO v_name FROM public.organizations o WHERE o.id = v_conn.artist_org_id;
    INSERT INTO public.contacts (org_id, user_id, name, category)
    VALUES (v_conn.label_org_id, NULL, v_name, 'artist')
    RETURNING id INTO v_contact;
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.contacts c
    WHERE c.id = v_contact AND c.artist_org_id IS NOT NULL AND c.artist_org_id <> v_conn.artist_org_id
  ) OR EXISTS (
    SELECT 1 FROM public.contacts c
    WHERE c.org_id = v_conn.label_org_id AND c.artist_org_id = v_conn.artist_org_id AND c.id <> v_contact
  ) THEN
    RETURN jsonb_build_object('error', 'contact_taken');
  END IF;

  UPDATE public.org_connections
  SET status = 'active', accepted_by = p_actor, accepted_at = now(), label_contact_id = v_contact
  WHERE id = v_conn.id;
  UPDATE public.contacts SET artist_org_id = v_conn.artist_org_id WHERE id = v_contact;

  PERFORM public.labelos_audit_insert(v_conn.label_org_id, p_actor, 'connection.accepted', 'connection', v_conn.id,
    public.labelos_connection_payload(v_conn.id, COALESCE(p_payload, '{}'::jsonb)));
  PERFORM public.labelos_audit_insert(v_conn.artist_org_id, p_actor, 'connection.accepted', 'connection', v_conn.id,
    public.labelos_connection_payload(v_conn.id, COALESCE(p_payload, '{}'::jsonb)));

  RETURN jsonb_build_object('connection', public.labelos_connection_json(v_conn.id));
END;
$fn$;

ALTER FUNCTION public.labelos_audit_connection_accept(uuid, uuid, uuid, jsonb) OWNER TO postgres;
REVOKE ALL ON FUNCTION public.labelos_audit_connection_accept(uuid, uuid, uuid, jsonb) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.labelos_audit_connection_accept(uuid, uuid, uuid, jsonb) TO service_role;

-- End a connection from either side. A pending request ends as `ended` when
-- its starter withdraws it and `declined` when the other side refuses; an
-- active one is `ended`. The shared-project list goes with it and the label's
-- roster contact stops pointing at the artist org (the contact, and anything
-- the label copied, stay the label's). Access is read from `status` on every
-- request, so it ends on the very next one. Answers {"connection": <row>} or
-- {"error": "not_found"}.
CREATE OR REPLACE FUNCTION public.labelos_audit_connection_end(
  p_org uuid,
  p_actor uuid,
  p_connection uuid,
  p_payload jsonb
) RETURNS jsonb
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path = public
AS $fn$
DECLARE
  v_conn  public.org_connections%ROWTYPE;
  v_side  text;
  v_new   text;
BEGIN
  SELECT * INTO v_conn FROM public.org_connections WHERE id = p_connection FOR UPDATE;
  IF NOT FOUND OR v_conn.status NOT IN ('requested', 'active') THEN
    RETURN jsonb_build_object('error', 'not_found');
  END IF;
  v_side := CASE WHEN p_org = v_conn.label_org_id THEN 'label' WHEN p_org = v_conn.artist_org_id THEN 'artist' END;
  IF v_side IS NULL THEN
    RETURN jsonb_build_object('error', 'not_found');
  END IF;

  v_new := CASE WHEN v_conn.status = 'requested' AND v_side <> v_conn.initiated_by THEN 'declined' ELSE 'ended' END;

  UPDATE public.org_connections
  SET status = v_new, ended_by = p_actor, ended_at = now(), ended_side = v_side,
      -- the roster contact is not held by a finished connection (it can be deleted again)
      label_contact_id = NULL
  WHERE id = v_conn.id;
  DELETE FROM public.connection_projects WHERE connection_id = v_conn.id;
  UPDATE public.contacts SET artist_org_id = NULL
  WHERE org_id = v_conn.label_org_id AND artist_org_id = v_conn.artist_org_id;

  PERFORM public.labelos_audit_insert(v_conn.label_org_id, p_actor, 'connection.ended', 'connection', v_conn.id,
    public.labelos_connection_payload(v_conn.id, COALESCE(p_payload, '{}'::jsonb) || jsonb_build_object('was', v_conn.status, 'outcome', v_new, 'by_side', v_side)));
  PERFORM public.labelos_audit_insert(v_conn.artist_org_id, p_actor, 'connection.ended', 'connection', v_conn.id,
    public.labelos_connection_payload(v_conn.id, COALESCE(p_payload, '{}'::jsonb) || jsonb_build_object('was', v_conn.status, 'outcome', v_new, 'by_side', v_side)));

  RETURN jsonb_build_object('connection', public.labelos_connection_json(v_conn.id));
END;
$fn$;

ALTER FUNCTION public.labelos_audit_connection_end(uuid, uuid, uuid, jsonb) OWNER TO postgres;
REVOKE ALL ON FUNCTION public.labelos_audit_connection_end(uuid, uuid, uuid, jsonb) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.labelos_audit_connection_end(uuid, uuid, uuid, jsonb) TO service_role;

-- What the artist shares. ARTIST SIDE ONLY: p_org must be the connection's
-- artist org. p_patch holds only the keys that change (share_mode,
-- allow_copies); p_project_ids, when not NULL, replaces the selected list
-- (every id a project of the artist org, else {"error": "bad_project"}).
-- Allowed while the connection is requested or active, so the artist can
-- decide before accepting. Recorded as share.created when it widens what the
-- label can reach or do (more projects, the whole catalogue, copies ON) and as
-- share.revoked when it narrows it (fewer projects, copies OFF) — both when it
-- does both, nothing when nothing changed — in the ARTIST org (the label org learns nothing it does not read through
-- its own routes). Answers {"connection": <row>, "project_ids": [...]},
-- {"error": "not_found"} or {"error": "bad_project"}.
CREATE OR REPLACE FUNCTION public.labelos_audit_connection_share(
  p_org uuid,
  p_actor uuid,
  p_connection uuid,
  p_patch jsonb,
  p_project_ids uuid[],
  p_payload jsonb
) RETURNS jsonb
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path = public
AS $fn$
DECLARE
  v_conn       public.org_connections%ROWTYPE;
  v_before_set uuid[];
  v_after_set  uuid[];
  v_before_all boolean;
  v_after_all  boolean;
  v_widened    boolean;
  v_narrowed   boolean;
  v_mode       text;
  v_copies     boolean;
BEGIN
  IF p_patch IS NULL OR jsonb_typeof(p_patch) <> 'object' THEN
    RAISE EXCEPTION 'connection share patch must be an object' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_conn FROM public.org_connections WHERE id = p_connection FOR UPDATE;
  IF NOT FOUND OR v_conn.status NOT IN ('requested', 'active') OR v_conn.artist_org_id <> p_org THEN
    RETURN jsonb_build_object('error', 'not_found');
  END IF;

  IF p_project_ids IS NOT NULL AND EXISTS (
    SELECT 1 FROM unnest(p_project_ids) AS pid
    WHERE NOT EXISTS (SELECT 1 FROM public.projects p WHERE p.id = pid AND p.org_id = p_org)
  ) THEN
    RETURN jsonb_build_object('error', 'bad_project');
  END IF;

  SELECT COALESCE(array_agg(cp.project_id ORDER BY cp.project_id), '{}') INTO v_before_set
  FROM public.connection_projects cp WHERE cp.connection_id = v_conn.id;
  v_before_all := v_conn.share_mode = 'all';

  v_mode   := COALESCE(p_patch->>'share_mode', v_conn.share_mode);
  v_copies := CASE WHEN p_patch ? 'allow_copies' THEN (p_patch->>'allow_copies')::boolean ELSE v_conn.allow_copies END;
  IF v_mode NOT IN ('selected', 'all') THEN
    RAISE EXCEPTION 'unknown share mode %', v_mode USING ERRCODE = '22023';
  END IF;

  IF p_project_ids IS NOT NULL THEN
    DELETE FROM public.connection_projects cp
    WHERE cp.connection_id = v_conn.id AND cp.project_id <> ALL (p_project_ids);
    INSERT INTO public.connection_projects (connection_id, project_id, org_id)
    SELECT v_conn.id, pid, p_org FROM (SELECT DISTINCT unnest(p_project_ids) AS pid) ids
    ON CONFLICT DO NOTHING;
  ELSIF v_before_all AND v_mode = 'selected' THEN
    -- Leaving "whole catalogue" without naming projects shares NOTHING: rows left
    -- over from before it must not come back to life.
    DELETE FROM public.connection_projects cp WHERE cp.connection_id = v_conn.id;
  END IF;

  UPDATE public.org_connections SET share_mode = v_mode, allow_copies = v_copies WHERE id = v_conn.id;

  SELECT COALESCE(array_agg(cp.project_id ORDER BY cp.project_id), '{}') INTO v_after_set
  FROM public.connection_projects cp WHERE cp.connection_id = v_conn.id;
  v_after_all := v_mode = 'all';

  -- What the label can reach (or copy) now versus before. Turning copies off
  -- narrows; turning them on widens; an unchanged share records nothing.
  v_widened := (NOT v_before_all AND v_after_all)
    OR (NOT v_before_all AND NOT v_after_all AND EXISTS (SELECT 1 FROM unnest(v_after_set) a WHERE a <> ALL (v_before_set)))
    OR (NOT v_conn.allow_copies AND v_copies);
  v_narrowed := (v_before_all AND NOT v_after_all)
    OR (NOT v_before_all AND NOT v_after_all AND EXISTS (SELECT 1 FROM unnest(v_before_set) b WHERE b <> ALL (v_after_set)))
    OR (v_conn.allow_copies AND NOT v_copies);

  IF v_narrowed THEN
    PERFORM public.labelos_audit_insert(
      p_org, p_actor, 'share.revoked', 'connection', v_conn.id,
      public.labelos_connection_payload(v_conn.id, COALESCE(p_payload, '{}'::jsonb) || jsonb_build_object(
        'via', 'connection', 'share_mode', v_mode, 'projects', cardinality(v_after_set), 'allow_copies', v_copies
      ))
    );
  END IF;
  IF v_widened THEN
    PERFORM public.labelos_audit_insert(
      p_org, p_actor, 'share.created', 'connection', v_conn.id,
      public.labelos_connection_payload(v_conn.id, COALESCE(p_payload, '{}'::jsonb) || jsonb_build_object(
        'via', 'connection', 'share_mode', v_mode, 'projects', cardinality(v_after_set), 'allow_copies', v_copies
      ))
    );
  END IF;

  RETURN jsonb_build_object('connection', public.labelos_connection_json(v_conn.id), 'project_ids', to_jsonb(v_after_set));
END;
$fn$;

ALTER FUNCTION public.labelos_audit_connection_share(uuid, uuid, uuid, jsonb, uuid[], jsonb) OWNER TO postgres;
REVOKE ALL ON FUNCTION public.labelos_audit_connection_share(uuid, uuid, uuid, jsonb, uuid[], jsonb) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.labelos_audit_connection_share(uuid, uuid, uuid, jsonb, uuid[], jsonb) TO service_role;

NOTIFY pgrst, 'reload schema';


-- ═════════════ 155_labelos_split_sheets.sql ═════════════
-- 155_labelos_split_sheets.sql
-- Label OS (LABEL-28): versioned composition / master split sheets that must
-- add up to exactly 100.0000 before they can leave `draft`.
--
-- LABEL OS — NOT APPLIED. Apply at the final merge of the Label OS branch
-- into main, after 153 (and 154). Never part of supabase/apply/pending.sql.
--
-- 1. `split_sheets` — one row per (song, kind, version). `track_id` is the
--    song (an org track, type 'song'); `kind` composition | master;
--    `status` draft | circulated | signed | superseded | disputed.
--    At most ONE draft and ONE live (circulated | signed | disputed) sheet per
--    (song, kind): a new version is a new draft, and circulating it moves the
--    previous live one to `superseded` in the same transaction.
-- 2. `split_lines` — party, role, `share numeric(7,4)` (0 < share <= 100),
--    and the signature of that line: `signed_at`, `signature_method`
--    (upload | acknowledged), `signature_asset_id` (a RESTRICTED
--    `project_assets` row, kind split_sheet — 143 makes that kind always
--    restricted). `org_id` / `track_id` are stamped from the sheet so the read
--    policy never has to join back to it.
--
-- The two rules the backlog names are held HERE, not only in the route:
--   · a sheet leaves `draft` only if it has lines and they sum to exactly 100
--     (numeric arithmetic, no float), every role belongs to its kind, and every
--     party belongs to the org;
--   · from `circulated` on, the lines never change (party, role, share), nor
--     does the sheet's note, kind, version or song. Only signatures are written
--     on a circulated sheet's lines (NULL → set), and a signature's FILE
--     reference may go back to NULL if the file is deleted.
--   A sheet is deleted only while a draft. Legal moves are exactly
--   lib/labelos/splits.ts#canTransition.
--
-- 3. Writes: service role only (141's labelos_org_rows_service_only on both
--    tables). Three SECURITY DEFINER functions, EXECUTE for service_role only:
--      labelos_split_create_draft  a new version (optionally copying a sheet's
--                                  lines), sheet + lines in one transaction;
--      labelos_split_save_draft    replace a draft's note and lines atomically;
--      labelos_audit_split_circulate / labelos_audit_split_sign
--                                  the audit transitions (146 / 153 pattern):
--                                  the change AND its `activity_events` row in
--                                  ONE transaction. Circulating also supersedes
--                                  the previous live version, and records
--                                  `split_sheet.superseded` for it.
-- 4. Reads (RLS, SELECT): `rights.read` AND (a whole-org member, or the song is
--    in the caller's artist scope — labelos_scoped_tracks(), 149), OR the line
--    is the caller's OWN (D2) on a sheet that has been circulated (a draft is
--    still being negotiated). The own-line set comes from ONE uncorrelated call
--    to labelos_my_split_lines() (R-08: no per-row SECURITY DEFINER call), which
--    is also what keeps the two policies from reading each other.
--
-- Idempotent: IF NOT EXISTS, CREATE OR REPLACE, DROP ... IF EXISTS first.

-- ── 1. split_sheets ──────────────────────────────────────────────────────

CREATE TABLE IF NOT EXISTS public.split_sheets (
  id                uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  org_id            uuid NOT NULL REFERENCES public.organizations(id) ON DELETE CASCADE,
  track_id          uuid NOT NULL REFERENCES public.tracks(id),
  kind              text NOT NULL,
  version           int  NOT NULL,
  status            text NOT NULL DEFAULT 'draft',
  note              text,
  document_asset_id uuid REFERENCES public.project_assets(id) ON DELETE SET NULL,
  created_by        uuid REFERENCES auth.users(id) ON DELETE SET NULL,
  circulated_by     uuid REFERENCES auth.users(id) ON DELETE SET NULL,
  circulated_at     timestamptz,
  signed_at         timestamptz,
  superseded_at     timestamptz,
  superseded_by     uuid REFERENCES public.split_sheets(id) ON DELETE SET NULL,
  created_at        timestamptz NOT NULL DEFAULT now(),
  updated_at        timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT split_sheets_kind_check CHECK (kind IN ('composition', 'master')),
  CONSTRAINT split_sheets_status_check CHECK (status IN ('draft', 'circulated', 'signed', 'superseded', 'disputed')),
  CONSTRAINT split_sheets_version_check CHECK (version >= 1),
  CONSTRAINT split_sheets_note_check CHECK (note IS NULL OR length(note) <= 2000),
  CONSTRAINT split_sheets_version_uniq UNIQUE (track_id, kind, version)
);

CREATE UNIQUE INDEX IF NOT EXISTS idx_split_sheets_one_draft
  ON public.split_sheets (track_id, kind) WHERE status = 'draft';
CREATE UNIQUE INDEX IF NOT EXISTS idx_split_sheets_one_live
  ON public.split_sheets (track_id, kind) WHERE status IN ('circulated', 'signed', 'disputed');
CREATE INDEX IF NOT EXISTS idx_split_sheets_org_track ON public.split_sheets (org_id, track_id);

ALTER TABLE public.split_sheets ENABLE ROW LEVEL SECURITY;

-- ── 2. split_lines ───────────────────────────────────────────────────────

CREATE TABLE IF NOT EXISTS public.split_lines (
  id                 uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  split_sheet_id     uuid NOT NULL REFERENCES public.split_sheets(id) ON DELETE CASCADE,
  org_id             uuid NOT NULL REFERENCES public.organizations(id) ON DELETE CASCADE,
  track_id           uuid NOT NULL REFERENCES public.tracks(id),
  party_id           uuid NOT NULL REFERENCES public.parties(id),
  role               text NOT NULL,
  share              numeric(7,4) NOT NULL,
  -- The order the sheet is written in (rows of one statement share a created_at).
  position           int NOT NULL DEFAULT 0,
  signed_at          timestamptz,
  signature_method   text,
  signature_asset_id uuid REFERENCES public.project_assets(id) ON DELETE SET NULL,
  signed_by          uuid REFERENCES auth.users(id) ON DELETE SET NULL,
  created_at         timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT split_lines_role_check CHECK (role IN ('writer', 'composer', 'writer_composer', 'publisher', 'master_owner')),
  CONSTRAINT split_lines_share_check CHECK (share > 0 AND share <= 100),
  CONSTRAINT split_lines_method_check CHECK (signature_method IS NULL OR signature_method IN ('upload', 'acknowledged')),
  CONSTRAINT split_lines_signature_pair CHECK ((signed_at IS NULL) = (signature_method IS NULL)),
  CONSTRAINT split_lines_party_role_uniq UNIQUE (split_sheet_id, party_id, role)
);

CREATE INDEX IF NOT EXISTS idx_split_lines_party ON public.split_lines (party_id);
CREATE INDEX IF NOT EXISTS idx_split_lines_org_track ON public.split_lines (org_id, track_id);

ALTER TABLE public.split_lines ENABLE ROW LEVEL SECURITY;

-- ── 3. Integrity triggers ────────────────────────────────────────────────

-- The roles each kind of sheet may carry (lib/labelos/splits.ts#ROLES_BY_KIND).
CREATE OR REPLACE FUNCTION public.labelos_split_role_ok(p_kind text, p_role text)
RETURNS boolean
LANGUAGE sql
IMMUTABLE
SECURITY DEFINER
SET search_path = public
AS $$
  SELECT CASE p_kind
    WHEN 'composition' THEN p_role IN ('writer', 'composer', 'writer_composer', 'publisher')
    WHEN 'master' THEN p_role = 'master_owner'
    ELSE false
  END;
$$;

ALTER FUNCTION public.labelos_split_role_ok(text, text) OWNER TO postgres;
REVOKE ALL ON FUNCTION public.labelos_split_role_ok(text, text) FROM PUBLIC;

CREATE OR REPLACE FUNCTION public.split_sheets_guard()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_track_org  uuid;
  v_track_type text;
  v_total      numeric;
  v_count      int;
  v_bad        int;
  v_unsigned   int;
BEGIN
  -- 141's labelos_org_rows_service_only is on this table too, but it reads
  -- org_id from the row and a line's is stamped below; refuse the API roles
  -- here first, whatever the row holds. (current_user is the definer in here.)
  IF current_setting('role', true) IN ('authenticated', 'anon') THEN
    RAISE EXCEPTION 'split_sheets: organization rows are written through /api/org only' USING ERRCODE = 'insufficient_privilege';
  END IF;

  IF TG_OP = 'DELETE' THEN
    -- A circulated, signed or disputed sheet is a legal record. It goes only
    -- with its organization (the cascade finds the org already gone).
    IF OLD.status <> 'draft' AND EXISTS (SELECT 1 FROM public.organizations o WHERE o.id = OLD.org_id) THEN
      RAISE EXCEPTION 'split_sheets: a % sheet cannot be deleted', OLD.status USING ERRCODE = 'check_violation';
    END IF;
    RETURN OLD;
  END IF;

  IF TG_OP = 'INSERT' THEN
    SELECT t.org_id, t.type INTO v_track_org, v_track_type FROM public.tracks t WHERE t.id = NEW.track_id;
    IF v_track_org IS NULL OR v_track_org <> NEW.org_id THEN
      RAISE EXCEPTION 'split_sheets: the song must be a song of the same organization' USING ERRCODE = 'check_violation';
    END IF;
    IF v_track_type <> 'song' THEN
      RAISE EXCEPTION 'split_sheets: a split sheet belongs to a song' USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.status <> 'draft' THEN
      RAISE EXCEPTION 'split_sheets: a sheet starts as a draft' USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.version IS NULL THEN
      SELECT COALESCE(MAX(s.version), 0) + 1 INTO NEW.version
      FROM public.split_sheets s WHERE s.track_id = NEW.track_id AND s.kind = NEW.kind;
    END IF;
    NEW.updated_at := now();
    RETURN NEW;
  END IF;

  -- UPDATE
  IF NEW.org_id <> OLD.org_id OR NEW.track_id <> OLD.track_id OR NEW.kind <> OLD.kind OR NEW.version <> OLD.version
     OR NEW.created_by IS DISTINCT FROM OLD.created_by OR NEW.created_at <> OLD.created_at THEN
    RAISE EXCEPTION 'split_sheets: a sheet keeps its organization, song, kind and version' USING ERRCODE = 'check_violation';
  END IF;

  IF OLD.status <> 'draft' AND NEW.note IS DISTINCT FROM OLD.note THEN
    RAISE EXCEPTION 'split_sheets: a circulated sheet cannot be edited' USING ERRCODE = 'check_violation';
  END IF;

  IF NEW.status <> OLD.status THEN
    IF NOT (
      (OLD.status = 'draft'      AND NEW.status = 'circulated')
      OR (OLD.status = 'circulated' AND NEW.status IN ('signed', 'disputed', 'superseded'))
      OR (OLD.status IN ('signed', 'disputed') AND NEW.status = 'superseded')
    ) THEN
      RAISE EXCEPTION 'split_sheets: a sheet cannot go from % to %', OLD.status, NEW.status USING ERRCODE = 'check_violation';
    END IF;

    IF NEW.status = 'circulated' THEN
      -- Leaving draft: the lines are complete and add up to exactly 100.
      SELECT COALESCE(SUM(l.share), 0), COUNT(*),
             COUNT(*) FILTER (WHERE NOT public.labelos_split_role_ok(NEW.kind, l.role))
        INTO v_total, v_count, v_bad
      FROM public.split_lines l WHERE l.split_sheet_id = NEW.id;
      IF v_count = 0 THEN
        RAISE EXCEPTION 'split_sheets: a sheet needs at least one line to circulate' USING ERRCODE = 'check_violation';
      END IF;
      IF v_bad > 0 THEN
        RAISE EXCEPTION 'split_sheets: a % sheet carries a role that does not belong to it', NEW.kind USING ERRCODE = 'check_violation';
      END IF;
      IF v_total <> 100 THEN
        RAISE EXCEPTION 'split_sheets: the shares add up to %, not 100', v_total USING ERRCODE = 'check_violation';
      END IF;
      NEW.circulated_at := COALESCE(NEW.circulated_at, now());
    ELSIF NEW.status = 'signed' THEN
      SELECT COUNT(*) FILTER (WHERE l.signed_at IS NULL) INTO v_unsigned FROM public.split_lines l WHERE l.split_sheet_id = NEW.id;
      IF v_unsigned > 0 THEN
        RAISE EXCEPTION 'split_sheets: every line must be signed first' USING ERRCODE = 'check_violation';
      END IF;
      NEW.signed_at := COALESCE(NEW.signed_at, now());
    ELSIF NEW.status = 'superseded' THEN
      NEW.superseded_at := COALESCE(NEW.superseded_at, now());
    END IF;
  END IF;

  NEW.updated_at := now();
  RETURN NEW;
END;
$$;

ALTER FUNCTION public.split_sheets_guard() OWNER TO postgres;
REVOKE ALL ON FUNCTION public.split_sheets_guard() FROM PUBLIC;

DROP TRIGGER IF EXISTS split_sheets_guard ON public.split_sheets;
CREATE TRIGGER split_sheets_guard BEFORE INSERT OR UPDATE OR DELETE ON public.split_sheets
  FOR EACH ROW EXECUTE FUNCTION public.split_sheets_guard();

CREATE OR REPLACE FUNCTION public.split_lines_guard()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_sheet public.split_sheets%ROWTYPE;
BEGIN
  IF current_setting('role', true) IN ('authenticated', 'anon') THEN
    RAISE EXCEPTION 'split_lines: organization rows are written through /api/org only' USING ERRCODE = 'insufficient_privilege';
  END IF;

  -- FOR SHARE: circulating a sheet takes the row FOR UPDATE, so a line
  -- written at the same moment either lands before the sum is read or waits
  -- and finds a sheet that is no longer a draft.
  SELECT * INTO v_sheet FROM public.split_sheets s
  WHERE s.id = CASE WHEN TG_OP = 'DELETE' THEN OLD.split_sheet_id ELSE NEW.split_sheet_id END
  FOR SHARE;

  IF NOT FOUND THEN
    IF TG_OP = 'DELETE' THEN RETURN OLD; END IF; -- the sheet is going (cascade)
    RAISE EXCEPTION 'split_lines: the sheet does not exist' USING ERRCODE = 'foreign_key_violation';
  END IF;

  IF TG_OP = 'DELETE' THEN
    IF v_sheet.status <> 'draft' THEN
      RAISE EXCEPTION 'split_lines: a circulated sheet cannot be edited' USING ERRCODE = 'check_violation';
    END IF;
    RETURN OLD;
  END IF;

  IF TG_OP = 'INSERT' THEN
    IF v_sheet.status <> 'draft' THEN
      RAISE EXCEPTION 'split_lines: a circulated sheet cannot be edited' USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.signed_at IS NOT NULL OR NEW.signature_method IS NOT NULL OR NEW.signature_asset_id IS NOT NULL THEN
      RAISE EXCEPTION 'split_lines: a new line is not signed' USING ERRCODE = 'check_violation';
    END IF;
  ELSE
    IF NEW.split_sheet_id <> OLD.split_sheet_id OR NEW.org_id <> OLD.org_id OR NEW.track_id <> OLD.track_id THEN
      RAISE EXCEPTION 'split_lines: a line stays on its sheet' USING ERRCODE = 'check_violation';
    END IF;
    IF v_sheet.status <> 'draft' THEN
      -- Only the signature may be written, once; its file may be cleared.
      IF NEW.party_id <> OLD.party_id OR NEW.role <> OLD.role OR NEW.share <> OLD.share OR NEW.position <> OLD.position THEN
        RAISE EXCEPTION 'split_lines: a circulated sheet cannot be edited' USING ERRCODE = 'check_violation';
      END IF;
      IF OLD.signed_at IS NOT NULL AND (NEW.signed_at IS DISTINCT FROM OLD.signed_at OR NEW.signature_method IS DISTINCT FROM OLD.signature_method
         OR NEW.signed_by IS DISTINCT FROM OLD.signed_by) THEN
        RAISE EXCEPTION 'split_lines: a signature cannot be changed' USING ERRCODE = 'check_violation';
      END IF;
      IF OLD.signed_at IS NULL AND NEW.signed_at IS NOT NULL AND v_sheet.status <> 'circulated' THEN
        RAISE EXCEPTION 'split_lines: this version is not open for signatures' USING ERRCODE = 'check_violation';
      END IF;
      IF OLD.signature_asset_id IS NOT NULL AND NEW.signature_asset_id IS NOT NULL AND NEW.signature_asset_id <> OLD.signature_asset_id THEN
        RAISE EXCEPTION 'split_lines: a signature cannot be changed' USING ERRCODE = 'check_violation';
      END IF;
      RETURN NEW;
    END IF;
    IF NEW.signed_at IS NOT NULL OR NEW.signature_method IS NOT NULL OR NEW.signature_asset_id IS NOT NULL THEN
      RAISE EXCEPTION 'split_lines: a draft is not signed' USING ERRCODE = 'check_violation';
    END IF;
  END IF;

  -- Draft insert / update: the line belongs to its sheet's org, song and kind.
  NEW.org_id := v_sheet.org_id;
  NEW.track_id := v_sheet.track_id;
  IF NOT public.labelos_split_role_ok(v_sheet.kind, NEW.role) THEN
    RAISE EXCEPTION 'split_lines: % is not a role of a % sheet', NEW.role, v_sheet.kind USING ERRCODE = 'check_violation';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.parties p WHERE p.id = NEW.party_id AND p.org_id = v_sheet.org_id) THEN
    RAISE EXCEPTION 'split_lines: the party must belong to the same organization' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;

ALTER FUNCTION public.split_lines_guard() OWNER TO postgres;
REVOKE ALL ON FUNCTION public.split_lines_guard() FROM PUBLIC;

DROP TRIGGER IF EXISTS split_lines_guard ON public.split_lines;
CREATE TRIGGER split_lines_guard BEFORE INSERT OR UPDATE OR DELETE ON public.split_lines
  FOR EACH ROW EXECUTE FUNCTION public.split_lines_guard();

DROP TRIGGER IF EXISTS labelos_org_rows_service_only ON public.split_sheets;
CREATE TRIGGER labelos_org_rows_service_only BEFORE INSERT OR UPDATE OR DELETE ON public.split_sheets
  FOR EACH ROW EXECUTE FUNCTION public.labelos_org_rows_service_only('self', 'org_id');
DROP TRIGGER IF EXISTS labelos_org_rows_service_only ON public.split_lines;
CREATE TRIGGER labelos_org_rows_service_only BEFORE INSERT OR UPDATE OR DELETE ON public.split_lines
  FOR EACH ROW EXECUTE FUNCTION public.labelos_org_rows_service_only('self', 'org_id');

-- ── 4. Reads ─────────────────────────────────────────────────────────────
-- The caller's own lines on sheets that have left draft (D2). One call, no
-- argument that varies by row: a hashed subplan in the policies below.

CREATE OR REPLACE FUNCTION public.labelos_my_split_lines()
RETURNS TABLE (sheet_id uuid, line_id uuid)
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
  SELECT l.split_sheet_id, l.id
  FROM public.split_lines l
  JOIN public.split_sheets s ON s.id = l.split_sheet_id
  JOIN public.parties p ON p.id = l.party_id
  WHERE p.user_id = auth.uid()
    AND s.status <> 'draft'
    AND s.org_id IN (SELECT m.org_id FROM public.org_members m WHERE m.user_id = auth.uid());
$$;

ALTER FUNCTION public.labelos_my_split_lines() OWNER TO postgres;
REVOKE ALL ON FUNCTION public.labelos_my_split_lines() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.labelos_my_split_lines() TO authenticated, anon;

DROP POLICY IF EXISTS split_sheets_member_read ON public.split_sheets;
CREATE POLICY split_sheets_member_read ON public.split_sheets
  FOR SELECT
  USING (
    (
      org_id IN (
        SELECT cm.org_id
        FROM public.org_members cm
        WHERE cm.user_id = (SELECT auth.uid())
          AND public.has_org_cap(cm.org_id, 'rights.read')
      )
      AND (
        org_id IN (
          SELECT om.org_id
          FROM public.org_members om
          WHERE om.user_id = (SELECT auth.uid())
            AND om.scope = 'org'
            AND om.role <> 'artist'
        )
        OR (org_id, track_id) IN (SELECT st.org_id, st.track_id FROM public.labelos_scoped_tracks() st)
      )
    )
    OR id IN (SELECT ml.sheet_id FROM public.labelos_my_split_lines() ml)
  );

DROP POLICY IF EXISTS split_lines_member_read ON public.split_lines;
CREATE POLICY split_lines_member_read ON public.split_lines
  FOR SELECT
  USING (
    (
      org_id IN (
        SELECT cm.org_id
        FROM public.org_members cm
        WHERE cm.user_id = (SELECT auth.uid())
          AND public.has_org_cap(cm.org_id, 'rights.read')
      )
      AND (
        org_id IN (
          SELECT om.org_id
          FROM public.org_members om
          WHERE om.user_id = (SELECT auth.uid())
            AND om.scope = 'org'
            AND om.role <> 'artist'
        )
        OR (org_id, track_id) IN (SELECT st.org_id, st.track_id FROM public.labelos_scoped_tracks() st)
      )
    )
    OR id IN (SELECT ml.line_id FROM public.labelos_my_split_lines() ml)
  );

-- ── 5. Writes: create / save a draft ─────────────────────────────────────
-- p_lines: [{ "party_id": uuid, "role": text, "share": "33.3333" }, ...]

CREATE OR REPLACE FUNCTION public.labelos_split_create_draft(
  p_org uuid,
  p_actor uuid,
  p_track uuid,
  p_kind text,
  p_note text,
  p_lines jsonb,
  p_copy_from uuid
) RETURNS jsonb
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path = public
AS $fn$
DECLARE
  v_sheet public.split_sheets%ROWTYPE;
  v_src   public.split_sheets%ROWTYPE;
BEGIN
  IF p_kind NOT IN ('composition', 'master') THEN
    RAISE EXCEPTION 'unknown split kind %', p_kind USING ERRCODE = '22023';
  END IF;
  IF p_lines IS NOT NULL AND jsonb_typeof(p_lines) <> 'array' THEN
    RAISE EXCEPTION 'lines must be an array' USING ERRCODE = '22023';
  END IF;

  IF NOT EXISTS (SELECT 1 FROM public.tracks t WHERE t.id = p_track AND t.org_id = p_org AND t.type = 'song') THEN
    RETURN jsonb_build_object('error', 'not_found');
  END IF;
  IF EXISTS (SELECT 1 FROM public.split_sheets s WHERE s.track_id = p_track AND s.kind = p_kind AND s.status = 'draft') THEN
    RETURN jsonb_build_object('error', 'draft_exists');
  END IF;

  IF p_copy_from IS NOT NULL THEN
    SELECT * INTO v_src FROM public.split_sheets s
    WHERE s.id = p_copy_from AND s.org_id = p_org AND s.track_id = p_track AND s.kind = p_kind;
    IF NOT FOUND THEN
      RETURN jsonb_build_object('error', 'not_found');
    END IF;
  END IF;

  BEGIN
    INSERT INTO public.split_sheets (org_id, track_id, kind, version, status, note, created_by)
    VALUES (p_org, p_track, p_kind, NULL, 'draft', COALESCE(p_note, v_src.note), p_actor)
    RETURNING * INTO v_sheet;
  EXCEPTION WHEN unique_violation THEN
    RETURN jsonb_build_object('error', 'draft_exists');
  END;

  IF p_copy_from IS NOT NULL THEN
    INSERT INTO public.split_lines (split_sheet_id, org_id, track_id, party_id, role, share, position)
    SELECT v_sheet.id, p_org, p_track, l.party_id, l.role, l.share, l.position
    FROM public.split_lines l WHERE l.split_sheet_id = p_copy_from;
  ELSIF p_lines IS NOT NULL THEN
    INSERT INTO public.split_lines (split_sheet_id, org_id, track_id, party_id, role, share, position)
    SELECT v_sheet.id, p_org, p_track, (e.value->>'party_id')::uuid, e.value->>'role', (e.value->>'share')::numeric, (e.ord - 1)::int
    FROM jsonb_array_elements(p_lines) WITH ORDINALITY AS e(value, ord);
  END IF;

  RETURN jsonb_build_object('sheet', to_jsonb(v_sheet));
END;
$fn$;

ALTER FUNCTION public.labelos_split_create_draft(uuid, uuid, uuid, text, text, jsonb, uuid) OWNER TO postgres;
REVOKE ALL ON FUNCTION public.labelos_split_create_draft(uuid, uuid, uuid, text, text, jsonb, uuid) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.labelos_split_create_draft(uuid, uuid, uuid, text, text, jsonb, uuid) TO service_role;

-- Replace a draft's note and/or its whole set of lines in one transaction.
-- p_set_note / p_set_lines say which of the two the caller names (a NULL note
-- is "clear it", so the flag is separate).
CREATE OR REPLACE FUNCTION public.labelos_split_save_draft(
  p_org uuid,
  p_sheet uuid,
  p_set_note boolean,
  p_note text,
  p_set_lines boolean,
  p_lines jsonb
) RETURNS jsonb
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path = public
AS $fn$
DECLARE
  v_sheet public.split_sheets%ROWTYPE;
BEGIN
  IF p_set_lines AND (p_lines IS NULL OR jsonb_typeof(p_lines) <> 'array') THEN
    RAISE EXCEPTION 'lines must be an array' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_sheet FROM public.split_sheets s WHERE s.id = p_sheet AND s.org_id = p_org FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('error', 'not_found');
  END IF;
  IF v_sheet.status <> 'draft' THEN
    RETURN jsonb_build_object('error', 'not_draft');
  END IF;

  IF p_set_lines THEN
    DELETE FROM public.split_lines WHERE split_sheet_id = p_sheet;
    INSERT INTO public.split_lines (split_sheet_id, org_id, track_id, party_id, role, share, position)
    SELECT p_sheet, v_sheet.org_id, v_sheet.track_id, (e.value->>'party_id')::uuid, e.value->>'role', (e.value->>'share')::numeric, (e.ord - 1)::int
    FROM jsonb_array_elements(p_lines) WITH ORDINALITY AS e(value, ord);
  END IF;
  IF p_set_note THEN
    UPDATE public.split_sheets SET note = p_note WHERE id = p_sheet;
  ELSE
    UPDATE public.split_sheets SET updated_at = now() WHERE id = p_sheet;
  END IF;

  SELECT * INTO v_sheet FROM public.split_sheets s WHERE s.id = p_sheet;
  RETURN jsonb_build_object('sheet', to_jsonb(v_sheet));
END;
$fn$;

ALTER FUNCTION public.labelos_split_save_draft(uuid, uuid, boolean, text, boolean, jsonb) OWNER TO postgres;
REVOKE ALL ON FUNCTION public.labelos_split_save_draft(uuid, uuid, boolean, text, boolean, jsonb) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.labelos_split_save_draft(uuid, uuid, boolean, text, boolean, jsonb) TO service_role;

-- ── 6. Audit transitions ─────────────────────────────────────────────────

-- Shared payload guard (146's rule: an object, no secret-looking key, small).
CREATE OR REPLACE FUNCTION public.labelos_split_check_payload(p_payload jsonb)
RETURNS void
LANGUAGE plpgsql
IMMUTABLE
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  IF p_payload IS NULL OR jsonb_typeof(p_payload) <> 'object' THEN
    RAISE EXCEPTION 'audit payload must be an object' USING ERRCODE = '22023';
  END IF;
  IF p_payload::text ~* '"[^"]*(token|password|secret)[^"]*"\s*:' THEN
    RAISE EXCEPTION 'audit payload carries a secret-looking key' USING ERRCODE = '22023';
  END IF;
  IF pg_column_size(p_payload) > 16384 THEN
    RAISE EXCEPTION 'audit payload is too large' USING ERRCODE = '22023';
  END IF;
END;
$$;

ALTER FUNCTION public.labelos_split_check_payload(jsonb) OWNER TO postgres;
REVOKE ALL ON FUNCTION public.labelos_split_check_payload(jsonb) FROM PUBLIC;

-- Circulate a draft. Answers {"sheet": <row>, "superseded": <id>|null},
-- {"error": "not_found" | "not_draft" | "no_lines" | "bad_total", "total"?}.
-- The previous live version of the same song and kind becomes `superseded`
-- first (the one-live index would otherwise refuse the move), with its own
-- `split_sheet.superseded` event, in the same transaction.
CREATE OR REPLACE FUNCTION public.labelos_audit_split_circulate(
  p_org uuid,
  p_actor uuid,
  p_sheet uuid,
  p_subject jsonb,
  p_payload jsonb
) RETURNS jsonb
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path = public
AS $fn$
DECLARE
  v_sheet public.split_sheets%ROWTYPE;
  v_old   public.split_sheets%ROWTYPE;
  v_total numeric;
  v_count int;
  v_art   uuid;
  v_proj  uuid;
  v_song  uuid;
BEGIN
  PERFORM public.labelos_split_check_payload(p_payload);

  SELECT * INTO v_sheet FROM public.split_sheets s WHERE s.id = p_sheet AND s.org_id = p_org FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('error', 'not_found');
  END IF;
  IF v_sheet.status <> 'draft' THEN
    RETURN jsonb_build_object('error', 'not_draft');
  END IF;

  SELECT COALESCE(SUM(l.share), 0), COUNT(*) INTO v_total, v_count FROM public.split_lines l WHERE l.split_sheet_id = p_sheet;
  IF v_count = 0 THEN
    RETURN jsonb_build_object('error', 'no_lines');
  END IF;
  IF v_total <> 100 THEN
    RETURN jsonb_build_object('error', 'bad_total', 'total', v_total);
  END IF;

  v_art  := NULLIF(p_subject->>'artist_id', '')::uuid;
  v_proj := NULLIF(p_subject->>'project_id', '')::uuid;
  v_song := NULLIF(p_subject->>'song_id', '')::uuid;

  SELECT * INTO v_old FROM public.split_sheets s
  WHERE s.track_id = v_sheet.track_id AND s.kind = v_sheet.kind AND s.id <> p_sheet
    AND s.status IN ('circulated', 'signed', 'disputed')
  FOR UPDATE;
  IF FOUND THEN
    UPDATE public.split_sheets SET status = 'superseded', superseded_by = p_sheet WHERE id = v_old.id;
    INSERT INTO public.activity_events (org_id, actor_id, verb, subject_type, subject_id, artist_id, project_id, song_id, payload, audit, visibility)
    VALUES (p_org, p_actor, 'split_sheet.superseded', 'split_sheet', v_old.id, v_art, v_proj, v_song,
            jsonb_build_object('kind', v_old.kind, 'version', v_old.version, 'by_version', v_sheet.version), true, 'internal');
  END IF;

  UPDATE public.split_sheets
  SET status = 'circulated', circulated_by = p_actor, circulated_at = now()
  WHERE id = p_sheet
  RETURNING * INTO v_sheet;

  INSERT INTO public.activity_events (org_id, actor_id, verb, subject_type, subject_id, artist_id, project_id, song_id, payload, audit, visibility)
  VALUES (p_org, p_actor, 'split_sheet.circulated', 'split_sheet', v_sheet.id, v_art, v_proj, v_song,
          CASE WHEN v_old.id IS NULL THEN p_payload ELSE p_payload || jsonb_build_object('supersedes_version', v_old.version) END,
          true, 'internal');

  RETURN jsonb_build_object('sheet', to_jsonb(v_sheet), 'superseded', v_old.id);
END;
$fn$;

ALTER FUNCTION public.labelos_audit_split_circulate(uuid, uuid, uuid, jsonb, jsonb) OWNER TO postgres;
REVOKE ALL ON FUNCTION public.labelos_audit_split_circulate(uuid, uuid, uuid, jsonb, jsonb) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.labelos_audit_split_circulate(uuid, uuid, uuid, jsonb, jsonb) TO service_role;

-- Record a signature. p_line NULL = every unsigned line of the sheet (a signed
-- PDF covering the whole sheet, method 'upload' only). p_asset: the restricted
-- split_sheet file, required for 'upload'. When the last line is signed the
-- sheet becomes `signed`. Answers {"sheet": <row>, "complete": bool, "signed": n},
-- {"error": "not_found" | "not_circulated" | "no_line" | "already_signed" | "bad_asset" | "bad_method"}.
CREATE OR REPLACE FUNCTION public.labelos_audit_split_sign(
  p_org uuid,
  p_actor uuid,
  p_sheet uuid,
  p_line uuid,
  p_method text,
  p_asset uuid,
  p_subject jsonb,
  p_payload jsonb
) RETURNS jsonb
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path = public
AS $fn$
DECLARE
  v_sheet    public.split_sheets%ROWTYPE;
  v_signed   int;
  v_unsigned int;
  v_complete boolean := false;
  v_art      uuid;
  v_proj     uuid;
  v_song     uuid;
BEGIN
  PERFORM public.labelos_split_check_payload(p_payload);
  IF p_method NOT IN ('upload', 'acknowledged') THEN
    RETURN jsonb_build_object('error', 'bad_method');
  END IF;
  IF p_method = 'acknowledged' AND (p_line IS NULL OR p_asset IS NOT NULL) THEN
    RETURN jsonb_build_object('error', 'bad_method');
  END IF;
  IF p_method = 'upload' AND p_asset IS NULL THEN
    RETURN jsonb_build_object('error', 'bad_asset');
  END IF;
  IF p_asset IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.project_assets a
    WHERE a.id = p_asset AND a.org_id = p_org AND a.kind = 'split_sheet' AND a.sensitivity = 'restricted'
  ) THEN
    RETURN jsonb_build_object('error', 'bad_asset');
  END IF;

  SELECT * INTO v_sheet FROM public.split_sheets s WHERE s.id = p_sheet AND s.org_id = p_org FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('error', 'not_found');
  END IF;
  IF v_sheet.status <> 'circulated' THEN
    RETURN jsonb_build_object('error', 'not_circulated');
  END IF;

  IF p_line IS NOT NULL THEN
    IF NOT EXISTS (SELECT 1 FROM public.split_lines l WHERE l.id = p_line AND l.split_sheet_id = p_sheet) THEN
      RETURN jsonb_build_object('error', 'no_line');
    END IF;
    IF EXISTS (SELECT 1 FROM public.split_lines l WHERE l.id = p_line AND l.signed_at IS NOT NULL) THEN
      RETURN jsonb_build_object('error', 'already_signed');
    END IF;
    UPDATE public.split_lines
    SET signed_at = now(), signature_method = p_method, signature_asset_id = p_asset, signed_by = p_actor
    WHERE id = p_line;
    v_signed := 1;
  ELSE
    UPDATE public.split_lines
    SET signed_at = now(), signature_method = p_method, signature_asset_id = p_asset, signed_by = p_actor
    WHERE split_sheet_id = p_sheet AND signed_at IS NULL;
    GET DIAGNOSTICS v_signed = ROW_COUNT;
    IF v_signed = 0 THEN
      RETURN jsonb_build_object('error', 'already_signed');
    END IF;
  END IF;

  SELECT COUNT(*) FILTER (WHERE l.signed_at IS NULL) INTO v_unsigned FROM public.split_lines l WHERE l.split_sheet_id = p_sheet;
  IF v_unsigned = 0 THEN
    v_complete := true;
    UPDATE public.split_sheets
    SET status = 'signed', signed_at = now(),
        document_asset_id = CASE WHEN p_line IS NULL THEN p_asset ELSE document_asset_id END
    WHERE id = p_sheet
    RETURNING * INTO v_sheet;
  ELSIF p_line IS NULL THEN
    UPDATE public.split_sheets SET document_asset_id = p_asset WHERE id = p_sheet RETURNING * INTO v_sheet;
  END IF;

  v_art  := NULLIF(p_subject->>'artist_id', '')::uuid;
  v_proj := NULLIF(p_subject->>'project_id', '')::uuid;
  v_song := NULLIF(p_subject->>'song_id', '')::uuid;

  INSERT INTO public.activity_events (org_id, actor_id, verb, subject_type, subject_id, artist_id, project_id, song_id, payload, audit, visibility)
  VALUES (p_org, p_actor, 'split_sheet.signed', 'split_sheet', v_sheet.id, v_art, v_proj, v_song,
          p_payload || jsonb_build_object('complete', v_complete, 'lines', v_signed), true, 'internal');

  RETURN jsonb_build_object('sheet', to_jsonb(v_sheet), 'complete', v_complete, 'signed', v_signed);
END;
$fn$;

ALTER FUNCTION public.labelos_audit_split_sign(uuid, uuid, uuid, uuid, text, uuid, jsonb, jsonb) OWNER TO postgres;
REVOKE ALL ON FUNCTION public.labelos_audit_split_sign(uuid, uuid, uuid, uuid, text, uuid, jsonb, jsonb) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.labelos_audit_split_sign(uuid, uuid, uuid, uuid, text, uuid, jsonb, jsonb) TO service_role;

NOTIFY pgrst, 'reload schema';


-- ═════════════ 156_labelos_samples_declared.sql ═════════════
-- 156_labelos_samples_declared.sql (LABEL-29)
-- Where a song says whether it uses samples, and how they were cleared
-- (05 §3 `samples_declared`; 09 §3.1 L8). Three columns on `tracks`, no new
-- table, no policy change: org songs are written by the service role only
-- (141's labelos_org_rows_service_only is on tracks), and members read the
-- row through the policies 141 already put there.
--
--   samples_declared            'none' | 'yes' | 'unknown'. NOT NULL, default
--                               'unknown', so every existing row (producer
--                               songs included) reads as "not declared" and
--                               nothing in the producer app changes.
--   samples_clearance_note      free text, at most 2000 characters.
--   samples_clearance_asset_id  an optional clearance document: a RESTRICTED
--                               `project_assets` file (143) of the song's own
--                               org. ON DELETE SET NULL, so removing the file
--                               un-clears the song rather than blocking the
--                               delete.
--
-- Producer rows can carry none of it (CHECK tracks_samples_org_only): the
-- declaration is a Label OS fact. A trigger holds the asset to the song's org
-- and to sensitivity 'restricted' (a clearance is a contract, D4); the route
-- additionally requires the file's project to hold the song.
--
-- Idempotent: IF NOT EXISTS, CHECKs dropped and re-added, CREATE OR REPLACE.
-- No DO blocks (pastes into the Supabase SQL editor). Proven in
-- supabase/local/checks/156_labelos_samples_declared.sql.

ALTER TABLE public.tracks ADD COLUMN IF NOT EXISTS samples_declared text NOT NULL DEFAULT 'unknown';
ALTER TABLE public.tracks ADD COLUMN IF NOT EXISTS samples_clearance_note text;
ALTER TABLE public.tracks ADD COLUMN IF NOT EXISTS samples_clearance_asset_id uuid REFERENCES public.project_assets(id) ON DELETE SET NULL;

ALTER TABLE public.tracks DROP CONSTRAINT IF EXISTS tracks_samples_declared_check;
ALTER TABLE public.tracks ADD CONSTRAINT tracks_samples_declared_check
  CHECK (samples_declared IN ('none', 'yes', 'unknown'));

ALTER TABLE public.tracks DROP CONSTRAINT IF EXISTS tracks_samples_note_length;
ALTER TABLE public.tracks ADD CONSTRAINT tracks_samples_note_length
  CHECK (samples_clearance_note IS NULL OR char_length(samples_clearance_note) <= 2000);

ALTER TABLE public.tracks DROP CONSTRAINT IF EXISTS tracks_samples_org_only;
ALTER TABLE public.tracks ADD CONSTRAINT tracks_samples_org_only
  CHECK (org_id IS NOT NULL OR (samples_declared = 'unknown' AND samples_clearance_note IS NULL AND samples_clearance_asset_id IS NULL));

CREATE INDEX IF NOT EXISTS idx_tracks_samples_asset
  ON public.tracks (samples_clearance_asset_id)
  WHERE samples_clearance_asset_id IS NOT NULL;

CREATE OR REPLACE FUNCTION public.tracks_samples_asset_integrity()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE
  v_org uuid;
  v_sens text;
BEGIN
  IF NEW.samples_clearance_asset_id IS NULL THEN
    RETURN NEW;
  END IF;
  SELECT a.org_id, a.sensitivity INTO v_org, v_sens FROM public.project_assets a WHERE a.id = NEW.samples_clearance_asset_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'tracks: clearance file % does not exist', NEW.samples_clearance_asset_id
      USING ERRCODE = 'foreign_key_violation';
  END IF;
  IF v_org IS DISTINCT FROM NEW.org_id THEN
    RAISE EXCEPTION 'tracks: the clearance file must belong to the song''s organization'
      USING ERRCODE = 'check_violation';
  END IF;
  IF v_sens IS DISTINCT FROM 'restricted' THEN
    RAISE EXCEPTION 'tracks: a clearance file must be restricted'
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END $$;

ALTER FUNCTION public.tracks_samples_asset_integrity() OWNER TO postgres;
REVOKE ALL ON FUNCTION public.tracks_samples_asset_integrity() FROM PUBLIC;

DROP TRIGGER IF EXISTS tracks_samples_asset_integrity ON public.tracks;
CREATE TRIGGER tracks_samples_asset_integrity
  BEFORE INSERT OR UPDATE OF samples_clearance_asset_id, org_id ON public.tracks
  FOR EACH ROW EXECUTE FUNCTION public.tracks_samples_asset_integrity();

NOTIFY pgrst, 'reload schema';


-- ═════════════ 157_labelos_approvals.sql ═════════════
-- 157_labelos_approvals.sql
-- Label OS (LABEL-30): approvals — the human decision at a release gate, stored
-- append-only with a snapshot of what was approved.
--
-- LABEL OS — NOT APPLIED. Apply at the final merge of the Label OS branch
-- into main, after 155 and 156. Never part of supabase/apply/pending.sql.
--
-- 1. `approvals` — one row per REQUEST and one per DECISION (05 §3, 09 §3.3).
--    The subject is a song XOR a release; `gate` is master | artwork | legal |
--    marketing | metadata (a song is asked only for `legal`). `decision` is
--    requested | approved | changes_requested. The latest row per (subject,
--    gate) is where the gate stands — nothing is updated to say so.
--      actor_id        who requested / who decided
--      approver_id     on a request: the one person asked (an org member)
--      request_id      on a decision: the request it answers, when there was one
--      subject_snapshot  what was approved (lib/labelos/approvals.ts): the split
--                      sheet versions and credits (legal), the artwork file, the
--                      tracklist. Whether it is still true is DERIVED by comparing
--                      it with the current facts (`isStale`); the row never changes.
--
-- 2. APPEND-ONLY, held here and not in the route:
--      · no UPDATE for anyone (trigger; also no privilege), no DELETE except
--        with the organization or the release it belongs to (the cascade finds
--        the parent already gone), no TRUNCATE;
--      · `created_at` is stamped by the trigger, so a row cannot be backdated;
--      · the API roles have no write privilege and no write policy, and 141's
--        labelos_org_rows_service_only trigger refuses them as well. Rows are
--        written by the two audit functions below, service_role only.
--
-- 3. Writes: two SECURITY DEFINER functions that make the change AND insert the
--    `activity_events` row in one transaction (146's pattern — if the audit
--    insert fails the approval is not there afterwards):
--      labelos_audit_approval_request  approval.requested
--      labelos_audit_approval_decide   approval.decided
--    The decide function re-checks the one rule the database can know for itself:
--    a requester does not approve their own request unless the caller says
--    they are owner or admin (`p_may_self_approve`, decided by the route from
--    the live membership). Everything else (capabilities, scope, readiness) is
--    the route's, because it needs the application's capability model.
--
-- 4. Reads (RLS, SELECT): a member who holds release.write or any
--    release.approve.<gate> in the row's org, AND (a whole-org member, or the
--    song is in the caller's artist scope — labelos_scoped_tracks(), 149, or
--    the release's project is — labelos_scoped_releases(), 151). Every test is
--    an uncorrelated subquery over the caller's few memberships or a
--    set-returning function called once, so the planner hashes it (R-08: no
--    per-row SECURITY DEFINER call).
--
-- Idempotent: IF NOT EXISTS, CREATE OR REPLACE, DROP ... IF EXISTS first.

-- ── 1. approvals ─────────────────────────────────────────────────────────

CREATE TABLE IF NOT EXISTS public.approvals (
  id               uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  org_id           uuid NOT NULL REFERENCES public.organizations(id) ON DELETE CASCADE,
  song_id          uuid REFERENCES public.tracks(id),
  release_id       uuid REFERENCES public.releases(id) ON DELETE CASCADE,
  gate             text NOT NULL,
  decision         text NOT NULL,
  note             text,
  actor_id         uuid REFERENCES auth.users(id) ON DELETE SET NULL,
  approver_id      uuid REFERENCES auth.users(id) ON DELETE SET NULL,
  request_id       uuid REFERENCES public.approvals(id),
  subject_snapshot jsonb NOT NULL DEFAULT '{}'::jsonb,
  created_at       timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT approvals_subject_check CHECK ((song_id IS NULL) <> (release_id IS NULL)),
  CONSTRAINT approvals_gate_check CHECK (gate IN ('master', 'artwork', 'legal', 'marketing', 'metadata')),
  CONSTRAINT approvals_song_gate_check CHECK (song_id IS NULL OR gate = 'legal'),
  CONSTRAINT approvals_decision_check CHECK (decision IN ('requested', 'approved', 'changes_requested')),
  CONSTRAINT approvals_note_check CHECK (note IS NULL OR length(note) <= 2000),
  CONSTRAINT approvals_changes_note_check CHECK (decision <> 'changes_requested' OR length(btrim(coalesce(note, ''))) > 0),
  CONSTRAINT approvals_request_shape_check CHECK (
    (decision = 'requested' AND approver_id IS NOT NULL AND actor_id IS NOT NULL AND request_id IS NULL)
    OR (decision <> 'requested' AND approver_id IS NULL)
  ),
  CONSTRAINT approvals_snapshot_check CHECK (jsonb_typeof(subject_snapshot) = 'object' AND pg_column_size(subject_snapshot) <= 65536)
);

-- The latest row per (subject, gate), newest first.
CREATE INDEX IF NOT EXISTS idx_approvals_song_gate ON public.approvals (song_id, gate, created_at DESC) WHERE song_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_approvals_release_gate ON public.approvals (release_id, gate, created_at DESC) WHERE release_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_approvals_org ON public.approvals (org_id, created_at DESC);
-- "Asked of me" (the legal queue, LABEL-31).
CREATE INDEX IF NOT EXISTS idx_approvals_approver ON public.approvals (approver_id, created_at DESC) WHERE decision = 'requested';

ALTER TABLE public.approvals ENABLE ROW LEVEL SECURITY;

-- ── 2. Append-only ───────────────────────────────────────────────────────

CREATE OR REPLACE FUNCTION public.approvals_guard()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_org   uuid;
  v_type  text;
  v_req   public.approvals%ROWTYPE;
BEGIN
  IF TG_OP = 'UPDATE' THEN
    RAISE EXCEPTION 'approvals are append-only: a decision is never changed' USING ERRCODE = 'check_violation';
  END IF;

  IF TG_OP = 'DELETE' THEN
    -- Only with the organization or the release it belongs to: the cascade
    -- runs after the parent row is gone, so a direct delete (parent present) is refused.
    IF EXISTS (SELECT 1 FROM public.organizations o WHERE o.id = OLD.org_id)
       AND (OLD.release_id IS NULL OR EXISTS (SELECT 1 FROM public.releases r WHERE r.id = OLD.release_id)) THEN
      RAISE EXCEPTION 'approvals are append-only: a decision is never deleted' USING ERRCODE = 'check_violation';
    END IF;
    RETURN OLD;
  END IF;

  -- INSERT. (current_user is the definer in here, so read the session's role.)
  IF current_setting('role', true) IN ('authenticated', 'anon') THEN
    RAISE EXCEPTION 'approvals: organization rows are written through /api/org only' USING ERRCODE = 'insufficient_privilege';
  END IF;

  IF (NEW.song_id IS NULL) = (NEW.release_id IS NULL) THEN
    RAISE EXCEPTION 'approvals: exactly one subject, a song or a release (approvals_subject_check)' USING ERRCODE = 'check_violation';
  END IF;

  IF NEW.song_id IS NOT NULL THEN
    SELECT t.org_id, t.type INTO v_org, v_type FROM public.tracks t WHERE t.id = NEW.song_id;
    IF v_org IS NULL OR v_org <> NEW.org_id THEN
      RAISE EXCEPTION 'approvals: the song must be a song of the same organization' USING ERRCODE = 'check_violation';
    END IF;
    IF v_type <> 'song' THEN
      RAISE EXCEPTION 'approvals: a song is approved, not a %', v_type USING ERRCODE = 'check_violation';
    END IF;
  ELSE
    SELECT r.org_id INTO v_org FROM public.releases r WHERE r.id = NEW.release_id;
    IF v_org IS NULL OR v_org <> NEW.org_id THEN
      RAISE EXCEPTION 'approvals: the release must be a release of the same organization' USING ERRCODE = 'check_violation';
    END IF;
  END IF;

  IF NEW.decision = 'requested' THEN
    IF NOT EXISTS (SELECT 1 FROM public.org_members m WHERE m.org_id = NEW.org_id AND m.user_id = NEW.approver_id) THEN
      RAISE EXCEPTION 'approvals: the approver must be a member of the organization' USING ERRCODE = 'check_violation';
    END IF;
  ELSIF NEW.request_id IS NOT NULL THEN
    SELECT * INTO v_req FROM public.approvals a WHERE a.id = NEW.request_id;
    IF NOT FOUND OR v_req.decision <> 'requested' OR v_req.org_id <> NEW.org_id OR v_req.gate <> NEW.gate
       OR v_req.song_id IS DISTINCT FROM NEW.song_id OR v_req.release_id IS DISTINCT FROM NEW.release_id THEN
      RAISE EXCEPTION 'approvals: a decision answers a request for the same subject and gate' USING ERRCODE = 'check_violation';
    END IF;
  END IF;

  -- Not backdated, not future-dated: the order of rows IS the history.
  NEW.created_at := clock_timestamp();
  RETURN NEW;
END;
$$;

ALTER FUNCTION public.approvals_guard() OWNER TO postgres;
REVOKE ALL ON FUNCTION public.approvals_guard() FROM PUBLIC;

DROP TRIGGER IF EXISTS approvals_guard ON public.approvals;
CREATE TRIGGER approvals_guard BEFORE INSERT OR UPDATE OR DELETE ON public.approvals
  FOR EACH ROW EXECUTE FUNCTION public.approvals_guard();

CREATE OR REPLACE FUNCTION public.approvals_no_truncate()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  RAISE EXCEPTION 'approvals are append-only: the table is never truncated' USING ERRCODE = 'check_violation';
END;
$$;

ALTER FUNCTION public.approvals_no_truncate() OWNER TO postgres;
REVOKE ALL ON FUNCTION public.approvals_no_truncate() FROM PUBLIC;

DROP TRIGGER IF EXISTS approvals_no_truncate ON public.approvals;
CREATE TRIGGER approvals_no_truncate BEFORE TRUNCATE ON public.approvals
  FOR EACH STATEMENT EXECUTE FUNCTION public.approvals_no_truncate();

DROP TRIGGER IF EXISTS labelos_org_rows_service_only ON public.approvals;
CREATE TRIGGER labelos_org_rows_service_only BEFORE INSERT OR UPDATE OR DELETE ON public.approvals
  FOR EACH ROW EXECUTE FUNCTION public.labelos_org_rows_service_only('self', 'org_id');

-- No privilege to change what was said, for anyone. (The triggers above hold it
-- again for a role that regains the privilege.)
REVOKE ALL ON public.approvals FROM anon, authenticated;
GRANT SELECT ON public.approvals TO authenticated;
REVOKE UPDATE, DELETE, TRUNCATE ON public.approvals FROM service_role;
GRANT SELECT, INSERT ON public.approvals TO service_role;

-- ── 3. Reads ─────────────────────────────────────────────────────────────
-- The releases whose project the caller's artist scope reaches come from
-- 151's labelos_scoped_releases() (the release twin of 149's
-- labelos_scoped_tracks()): one set, so the policy stays a hashed subplan.

DROP POLICY IF EXISTS approvals_member_read ON public.approvals;
CREATE POLICY approvals_member_read ON public.approvals
  FOR SELECT
  TO authenticated
  USING (
    org_id IN (
      SELECT cm.org_id
      FROM public.org_members cm
      WHERE cm.user_id = (SELECT auth.uid())
        AND (
          public.has_org_cap(cm.org_id, 'release.write')
          OR public.has_org_cap(cm.org_id, 'release.approve.master')
          OR public.has_org_cap(cm.org_id, 'release.approve.artwork')
          OR public.has_org_cap(cm.org_id, 'release.approve.legal')
          OR public.has_org_cap(cm.org_id, 'release.approve.marketing')
          OR public.has_org_cap(cm.org_id, 'release.approve.metadata')
        )
    )
    AND (
      org_id IN (
        SELECT om.org_id
        FROM public.org_members om
        WHERE om.user_id = (SELECT auth.uid())
          AND om.scope = 'org'
          AND om.role <> 'artist'
      )
      OR (org_id, song_id) IN (SELECT st.org_id, st.track_id FROM public.labelos_scoped_tracks() st)
      OR (org_id, release_id) IN (SELECT sr.org_id, sr.release_id FROM public.labelos_scoped_releases() sr)
    )
  );

-- ── 4. Writes ────────────────────────────────────────────────────────────

-- Shared payload guard (146's rule: an object, no secret-looking key, small).
CREATE OR REPLACE FUNCTION public.labelos_approval_check_payload(p_payload jsonb)
RETURNS void
LANGUAGE plpgsql
IMMUTABLE
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  IF p_payload IS NULL OR jsonb_typeof(p_payload) <> 'object' THEN
    RAISE EXCEPTION 'audit payload must be an object' USING ERRCODE = '22023';
  END IF;
  IF p_payload::text ~* '"[^"]*(token|password|secret)[^"]*"\s*:' THEN
    RAISE EXCEPTION 'audit payload carries a secret-looking key' USING ERRCODE = '22023';
  END IF;
  IF pg_column_size(p_payload) > 16384 THEN
    RAISE EXCEPTION 'audit payload is too large' USING ERRCODE = '22023';
  END IF;
END;
$$;

ALTER FUNCTION public.labelos_approval_check_payload(jsonb) OWNER TO postgres;
REVOKE ALL ON FUNCTION public.labelos_approval_check_payload(jsonb) FROM PUBLIC;

-- Ask one member to decide a gate. p_kind song | release; p_subject_ctx is the
-- subject's context keys { artist_id, project_id, song_id, release_id } the event
-- is filed under. Answers {"approval": <row>},
-- {"error": "not_found" | "bad_gate" | "already_requested" | "approver_not_member"}.
CREATE OR REPLACE FUNCTION public.labelos_audit_approval_request(
  p_org uuid,
  p_actor uuid,
  p_kind text,
  p_subject uuid,
  p_gate text,
  p_approver uuid,
  p_note text,
  p_snapshot jsonb,
  p_ctx jsonb,
  p_payload jsonb
) RETURNS jsonb
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path = public
AS $fn$
DECLARE
  v_last   public.approvals%ROWTYPE;
  v_row    public.approvals%ROWTYPE;
  v_rows   int;
  v_has    boolean;
BEGIN
  PERFORM public.labelos_approval_check_payload(p_payload);
  IF p_kind NOT IN ('song', 'release') THEN
    RAISE EXCEPTION 'unknown approval subject %', p_kind USING ERRCODE = '22023';
  END IF;
  IF p_gate NOT IN ('master', 'artwork', 'legal', 'marketing', 'metadata') OR (p_kind = 'song' AND p_gate <> 'legal') THEN
    RETURN jsonb_build_object('error', 'bad_gate');
  END IF;

  -- Lock the subject: two people asking, or asking and deciding, at once are
  -- serialised, so "the latest row" below is the latest row.
  IF p_kind = 'song' THEN
    PERFORM 1 FROM public.tracks t WHERE t.id = p_subject AND t.org_id = p_org AND t.type = 'song' FOR UPDATE;
  ELSE
    PERFORM 1 FROM public.releases r WHERE r.id = p_subject AND r.org_id = p_org FOR UPDATE;
  END IF;
  GET DIAGNOSTICS v_rows = ROW_COUNT;
  IF v_rows = 0 THEN
    RETURN jsonb_build_object('error', 'not_found');
  END IF;

  IF NOT EXISTS (SELECT 1 FROM public.org_members m WHERE m.org_id = p_org AND m.user_id = p_approver) THEN
    RETURN jsonb_build_object('error', 'approver_not_member');
  END IF;

  SELECT * INTO v_last FROM public.approvals a
  WHERE a.org_id = p_org AND a.gate = p_gate
    AND CASE WHEN p_kind = 'song' THEN a.song_id = p_subject ELSE a.release_id = p_subject END
  ORDER BY a.created_at DESC LIMIT 1;
  IF FOUND AND v_last.decision = 'requested' THEN
    RETURN jsonb_build_object('error', 'already_requested');
  END IF;

  INSERT INTO public.approvals (org_id, song_id, release_id, gate, decision, note, actor_id, approver_id, subject_snapshot)
  VALUES (p_org,
          CASE WHEN p_kind = 'song' THEN p_subject END,
          CASE WHEN p_kind = 'release' THEN p_subject END,
          p_gate, 'requested', NULLIF(btrim(coalesce(p_note, '')), ''), p_actor, p_approver, coalesce(p_snapshot, '{}'::jsonb))
  RETURNING * INTO v_row;

  INSERT INTO public.activity_events (org_id, actor_id, verb, subject_type, subject_id, artist_id, project_id, song_id, release_id, payload, audit, visibility)
  VALUES (p_org, p_actor, 'approval.requested', 'approval', v_row.id,
          NULLIF(p_ctx->>'artist_id', '')::uuid, NULLIF(p_ctx->>'project_id', '')::uuid,
          NULLIF(p_ctx->>'song_id', '')::uuid, NULLIF(p_ctx->>'release_id', '')::uuid,
          p_payload || jsonb_build_object('gate', p_gate), true, 'internal');

  RETURN jsonb_build_object('approval', to_jsonb(v_row));
END;
$fn$;

ALTER FUNCTION public.labelos_audit_approval_request(uuid, uuid, text, uuid, text, uuid, text, jsonb, jsonb, jsonb) OWNER TO postgres;
REVOKE ALL ON FUNCTION public.labelos_audit_approval_request(uuid, uuid, text, uuid, text, uuid, text, jsonb, jsonb, jsonb) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.labelos_audit_approval_request(uuid, uuid, text, uuid, text, uuid, text, jsonb, jsonb, jsonb) TO service_role;

-- Record a decision. p_may_self_approve: the caller is owner or admin (the
-- route reads the live membership). Answers {"approval": <row>},
-- {"error": "not_found" | "bad_gate" | "bad_decision" | "note_required" | "self_approval"}.
CREATE OR REPLACE FUNCTION public.labelos_audit_approval_decide(
  p_org uuid,
  p_actor uuid,
  p_kind text,
  p_subject uuid,
  p_gate text,
  p_decision text,
  p_note text,
  p_snapshot jsonb,
  p_may_self_approve boolean,
  p_ctx jsonb,
  p_payload jsonb
) RETURNS jsonb
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path = public
AS $fn$
DECLARE
  v_last  public.approvals%ROWTYPE;
  v_row   public.approvals%ROWTYPE;
  v_rows  int;
  v_has   boolean;
  v_note  text := NULLIF(btrim(coalesce(p_note, '')), '');
BEGIN
  PERFORM public.labelos_approval_check_payload(p_payload);
  IF p_kind NOT IN ('song', 'release') THEN
    RAISE EXCEPTION 'unknown approval subject %', p_kind USING ERRCODE = '22023';
  END IF;
  IF p_gate NOT IN ('master', 'artwork', 'legal', 'marketing', 'metadata') OR (p_kind = 'song' AND p_gate <> 'legal') THEN
    RETURN jsonb_build_object('error', 'bad_gate');
  END IF;
  IF p_decision NOT IN ('approved', 'changes_requested') THEN
    RETURN jsonb_build_object('error', 'bad_decision');
  END IF;
  IF p_decision = 'changes_requested' AND v_note IS NULL THEN
    RETURN jsonb_build_object('error', 'note_required');
  END IF;

  IF p_kind = 'song' THEN
    PERFORM 1 FROM public.tracks t WHERE t.id = p_subject AND t.org_id = p_org AND t.type = 'song' FOR UPDATE;
  ELSE
    PERFORM 1 FROM public.releases r WHERE r.id = p_subject AND r.org_id = p_org FOR UPDATE;
  END IF;
  GET DIAGNOSTICS v_rows = ROW_COUNT;
  IF v_rows = 0 THEN
    RETURN jsonb_build_object('error', 'not_found');
  END IF;

  SELECT * INTO v_last FROM public.approvals a
  WHERE a.org_id = p_org AND a.gate = p_gate
    AND CASE WHEN p_kind = 'song' THEN a.song_id = p_subject ELSE a.release_id = p_subject END
  ORDER BY a.created_at DESC LIMIT 1;
  v_has := FOUND;

  IF v_has AND v_last.decision = 'requested' AND p_decision = 'approved'
     AND v_last.actor_id = p_actor AND NOT coalesce(p_may_self_approve, false) THEN
    RETURN jsonb_build_object('error', 'self_approval');
  END IF;

  INSERT INTO public.approvals (org_id, song_id, release_id, gate, decision, note, actor_id, request_id, subject_snapshot)
  VALUES (p_org,
          CASE WHEN p_kind = 'song' THEN p_subject END,
          CASE WHEN p_kind = 'release' THEN p_subject END,
          p_gate, p_decision, v_note, p_actor,
          CASE WHEN v_has AND v_last.decision = 'requested' THEN v_last.id END,
          coalesce(p_snapshot, '{}'::jsonb))
  RETURNING * INTO v_row;

  INSERT INTO public.activity_events (org_id, actor_id, verb, subject_type, subject_id, artist_id, project_id, song_id, release_id, payload, audit, visibility)
  VALUES (p_org, p_actor, 'approval.decided', 'approval', v_row.id,
          NULLIF(p_ctx->>'artist_id', '')::uuid, NULLIF(p_ctx->>'project_id', '')::uuid,
          NULLIF(p_ctx->>'song_id', '')::uuid, NULLIF(p_ctx->>'release_id', '')::uuid,
          p_payload || jsonb_build_object('gate', p_gate, 'decision', p_decision), true, 'internal');

  RETURN jsonb_build_object('approval', to_jsonb(v_row));
END;
$fn$;

ALTER FUNCTION public.labelos_audit_approval_decide(uuid, uuid, text, uuid, text, text, text, jsonb, boolean, jsonb, jsonb) OWNER TO postgres;
REVOKE ALL ON FUNCTION public.labelos_audit_approval_decide(uuid, uuid, text, uuid, text, text, text, jsonb, boolean, jsonb, jsonb) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.labelos_audit_approval_decide(uuid, uuid, text, uuid, text, text, text, jsonb, boolean, jsonb, jsonb) TO service_role;

NOTIFY pgrst, 'reload schema';


-- ═════════════ 158_labelos_release_store_playback.sql ═════════════
-- 158_labelos_release_store_playback.sql
-- Label OS (LABEL-42): the storefront bridge for released music.
--
-- 144 already holds everything a listing needs (`store_listed`,
-- `store_listed_at`, `imported_released` and the CHECKs that a release is
-- listed only when it is delivered or imported). The one thing LABEL-42 adds
-- is how a listed release PLAYS to a visitor, which is a per-release choice
-- (14, LABEL-42 §2): the 75 s preview clip, or the full recording.
--
--   releases.store_playback  'preview' (default) | 'full'
--
-- Plus one trigger (below) that holds a listed release's tracklist.
-- Nothing else changes: no policy, no grant. `releases` stays org-only with
-- service-role writes; the public store reads it through server routes that
-- check `store_listed` themselves, so no anon policy is added here.
--
-- Idempotent: IF NOT EXISTS, DROP CONSTRAINT IF EXISTS first.

ALTER TABLE public.releases
  ADD COLUMN IF NOT EXISTS store_playback text NOT NULL DEFAULT 'preview';

ALTER TABLE public.releases DROP CONSTRAINT IF EXISTS releases_store_playback_check;
ALTER TABLE public.releases ADD CONSTRAINT releases_store_playback_check
  CHECK (store_playback IN ('preview', 'full'));

-- ── A tracklist on the store is held in the database too ─────────────────
-- Each item's public preview is promoted for the exact tracklist that was
-- listed, so while a release is on the store its items do not change: not
-- added, not edited, not removed, not reordered — by any path, including a
-- request that raced the route's own lock. The release row itself being
-- deleted (or its organization purged) removes its items by cascade, and by
-- then the parent is gone, so the check finds nothing to hold them for.
CREATE OR REPLACE FUNCTION public.release_items_store_lock()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE
  v_release uuid := COALESCE(NEW.release_id, OLD.release_id);
BEGIN
  -- The organization's own purge deletes its items by cascade, possibly before its releases: a release
  -- whose organization is already gone holds nothing.
  IF EXISTS (
    SELECT 1 FROM public.releases r
    JOIN public.organizations o ON o.id = r.org_id
    WHERE r.id = v_release AND r.store_listed
  ) THEN
    RAISE EXCEPTION 'release_items: take the release off the store to change its tracklist' USING ERRCODE = 'check_violation';
  END IF;
  RETURN COALESCE(NEW, OLD);
END $$;

ALTER FUNCTION public.release_items_store_lock() OWNER TO postgres;
REVOKE ALL ON FUNCTION public.release_items_store_lock() FROM PUBLIC;

DROP TRIGGER IF EXISTS release_items_store_lock ON public.release_items;
CREATE TRIGGER release_items_store_lock BEFORE INSERT OR UPDATE OR DELETE ON public.release_items
  FOR EACH ROW EXECUTE FUNCTION public.release_items_store_lock();

NOTIFY pgrst, 'reload schema';


-- ═════════════ 159_labelos_org_search.sql ═════════════
-- 159_labelos_org_search.sql — LABEL-36: org full-text search (08 §A3).
--
-- Expand only: ONE generated, STORED tsvector column per searchable table, each
-- with a GIN index. No policy, trigger, grant or function changes — the search
-- route reads with the service role and applies the member's artist scope and
-- D4 itself (lib/labelos/org-search*.ts), so nothing here widens a read.
--
--   tracks         search_tsv  title                      (songs and every other org track)
--   contacts       search_tsv  name, email, label
--   projects       search_tsv  name, description
--   project_assets search_tsv  label, file_name
--   releases       search_tsv  title, label_name
--   parties        search_tsv  display_name, legal_name
--
-- Configuration `simple` (08 §A3): titles and names are never stemmed, so
-- "Runnin" matches "Runnin". Track notes are deliberately NOT indexed: the
-- route would show the title of a hit whose match was a private note.
--
-- The four tables a producer also owns (tracks, contacts, projects,
-- project_assets) compute the vector ONLY for org rows (org_id IS NOT NULL);
-- a producer row's vector is NULL, so no tsquery can ever match it and the
-- producer's data costs no index space. `releases` and `parties` exist only
-- for orgs.
--
-- Immutable on purpose: `to_tsvector('simple'::regconfig, text)` is IMMUTABLE
-- (the one-argument form is not), which a generated column requires.
--
-- ADD COLUMN ... GENERATED STORED rewrites the table once. Idempotent: every
-- statement is IF NOT EXISTS, and a re-run changes nothing.

ALTER TABLE public.tracks ADD COLUMN IF NOT EXISTS search_tsv tsvector
  GENERATED ALWAYS AS (
    CASE WHEN org_id IS NULL THEN NULL
         ELSE to_tsvector('simple'::regconfig, coalesce(title, '')) END
  ) STORED;
CREATE INDEX IF NOT EXISTS tracks_search_tsv_idx ON public.tracks USING gin (search_tsv)
  WHERE org_id IS NOT NULL;

ALTER TABLE public.contacts ADD COLUMN IF NOT EXISTS search_tsv tsvector
  GENERATED ALWAYS AS (
    CASE WHEN org_id IS NULL THEN NULL
         ELSE to_tsvector('simple'::regconfig, coalesce(name, '') || ' ' || coalesce(email, '') || ' ' || coalesce(label, '')) END
  ) STORED;
CREATE INDEX IF NOT EXISTS contacts_search_tsv_idx ON public.contacts USING gin (search_tsv)
  WHERE org_id IS NOT NULL;

ALTER TABLE public.projects ADD COLUMN IF NOT EXISTS search_tsv tsvector
  GENERATED ALWAYS AS (
    CASE WHEN org_id IS NULL THEN NULL
         ELSE to_tsvector('simple'::regconfig, coalesce(name, '') || ' ' || coalesce(description, '')) END
  ) STORED;
CREATE INDEX IF NOT EXISTS projects_search_tsv_idx ON public.projects USING gin (search_tsv)
  WHERE org_id IS NOT NULL;

ALTER TABLE public.project_assets ADD COLUMN IF NOT EXISTS search_tsv tsvector
  GENERATED ALWAYS AS (
    CASE WHEN org_id IS NULL THEN NULL
         ELSE to_tsvector('simple'::regconfig, coalesce(label, '') || ' ' || coalesce(file_name, '')) END
  ) STORED;
CREATE INDEX IF NOT EXISTS project_assets_search_tsv_idx ON public.project_assets USING gin (search_tsv)
  WHERE org_id IS NOT NULL;

ALTER TABLE public.releases ADD COLUMN IF NOT EXISTS search_tsv tsvector
  GENERATED ALWAYS AS (
    to_tsvector('simple'::regconfig, coalesce(title, '') || ' ' || coalesce(label_name, ''))
  ) STORED;
CREATE INDEX IF NOT EXISTS releases_search_tsv_idx ON public.releases USING gin (search_tsv);

ALTER TABLE public.parties ADD COLUMN IF NOT EXISTS search_tsv tsvector
  GENERATED ALWAYS AS (
    to_tsvector('simple'::regconfig, coalesce(display_name, '') || ' ' || coalesce(legal_name, ''))
  ) STORED;
CREATE INDEX IF NOT EXISTS parties_search_tsv_idx ON public.parties USING gin (search_tsv);

NOTIFY pgrst, 'reload schema';


-- ═════════════ 160_labelos_weekly_digest.sql ═════════════
-- 160_labelos_weekly_digest.sql
-- Label OS (LABEL-38): the opt-in weekly owner digest.
--
-- LABEL OS — NOT APPLIED. Apply at the final merge of the Label OS branch
-- into main. Never part of supabase/apply/pending.sql.
--
-- 1. `org_digest_members` — one row per (org, member) who has switched the
--    digest on or off. `last_sent_week` is the ISO week ('2026-W42', '' =
--    never) of the last digest CLAIMED for that member: the cron claims with
--    `UPDATE … WHERE last_sent_week <> $week RETURNING`, a compare-and-set,
--    so two concurrent runs cannot both send. A failed send puts the previous
--    value back.
--
-- 2. `org_digest_channels` — one row per org with the Slack incoming-webhook
--    URL, stored only as `slack_webhook_cipher` (AES-256-GCM, versioned
--    format, see lib/labelos/webhook-secret.ts). `organizations.settings` is
--    readable by every member, so the secret cannot live there. `slack_last_week`
--    is that channel's own once-a-week claim.
--
-- 3. Both tables are SERVICE-ROLE ONLY: row level security on, NO policy, and
--    no privilege for anon or authenticated. The routes enforce who may touch
--    what (a member their own row; org.manage the channel) and never return
--    the cipher. Both cascade from the organization (LABEL-39's hard delete)
--    and neither is in the org export (the cipher must never leave).
--
-- Idempotent: IF NOT EXISTS, DROP … IF EXISTS first.

CREATE TABLE IF NOT EXISTS public.org_digest_members (
  org_id         uuid NOT NULL REFERENCES public.organizations(id) ON DELETE CASCADE,
  user_id        uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  enabled        boolean NOT NULL DEFAULT false,
  last_sent_week text NOT NULL DEFAULT '' CHECK (last_sent_week = '' OR last_sent_week ~ '^[0-9]{4}-W[0-9]{2}$'),
  updated_at     timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (org_id, user_id)
);

CREATE INDEX IF NOT EXISTS org_digest_members_enabled_idx ON public.org_digest_members (org_id) WHERE enabled;

CREATE TABLE IF NOT EXISTS public.org_digest_channels (
  org_id              uuid PRIMARY KEY REFERENCES public.organizations(id) ON DELETE CASCADE,
  slack_webhook_cipher text,
  slack_last_week     text NOT NULL DEFAULT '' CHECK (slack_last_week = '' OR slack_last_week ~ '^[0-9]{4}-W[0-9]{2}$'),
  configured_by       uuid,
  updated_at          timestamptz NOT NULL DEFAULT now()
);

ALTER TABLE public.org_digest_members ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.org_digest_channels ENABLE ROW LEVEL SECURITY;

REVOKE ALL ON public.org_digest_members FROM PUBLIC, anon, authenticated;
REVOKE ALL ON public.org_digest_channels FROM PUBLIC, anon, authenticated;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.org_digest_members TO service_role;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.org_digest_channels TO service_role;

NOTIFY pgrst, 'reload schema';


-- ═════════════ 161_labelos_saved_views.sql ═════════════
-- 161_labelos_saved_views.sql
-- Label OS (LABEL-37): saved views — a named, shareable filter DEFINITION over
-- an org's songs or releases (08 §A3.5, 14 LABEL-37).
--
-- LABEL OS — NOT APPLIED. Apply at the final merge of the Label OS branch
-- into main, after 157. Never part of supabase/apply/pending.sql.
--
-- 1. `org_saved_views` — org-only (org_id NOT NULL, ON DELETE CASCADE from
--    `organizations`, so LABEL-39's hard delete removes it with the org and its
--    all-tables sweep in supabase/local/checks/labelos_org_hard_delete.sql
--    covers it by the `org_id` column). No `user_id`: the author is
--    `created_by` (ON DELETE CASCADE — a person's own views go with them).
--      subject     songs | releases
--      name        1–80 characters
--      definition  the versioned filter DEFINITION (lib/labelos/filters.ts):
--                  ids and enums only, never names, never results; a JSON
--                  object of at most 4000 bytes whose `subject` is this row's
--                  and whose `v` is a number. Validated again by the route.
--      shared      false = the author's own; true = every member who can run
--                  the view (the route decides; see 2.)
--
-- 2. NO ACCESS for the API roles — the table is read and written by the
--    service role through /api/org/[orgId]/views. That is the point: a
--    definition carries artist, party and project ids, and a member limited to
--    some artists must not be able to read those ids with their own JWT
--    (PostgREST would hand them the row whole). The route drops what the
--    viewer cannot see and hides a shared view that refers to anything outside
--    their reach, and results are recomputed per viewer on every run, so the
--    database never holds anything that is true only for one viewer. RLS is on
--    with ONE policy that says no (`USING (false)`, so the repo's "every
--    Label OS table has a policy" guard stays strict and the intent is written
--    down), the API roles' privileges are revoked, and 141's service-only
--    trigger refuses a write from them as well — three independent layers,
--    none of them a per-row SECURITY DEFINER call (R-08 has nothing to say
--    about a policy that reads no row).
--
-- 3. One name per author per subject (case-insensitive); two authors may both
--    have a "Needs artwork". The route caps views per author and per org.
--
-- Idempotent. Rollback: supabase/rollback/161_labelos_saved_views.down.sql.

CREATE TABLE IF NOT EXISTS public.org_saved_views (
  id          uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  org_id      uuid NOT NULL REFERENCES public.organizations(id) ON DELETE CASCADE,
  created_by  uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  subject     text NOT NULL CHECK (subject IN ('songs', 'releases')),
  name        text NOT NULL CHECK (char_length(btrim(name)) BETWEEN 1 AND 80),
  definition  jsonb NOT NULL,
  shared      boolean NOT NULL DEFAULT false,
  created_at  timestamptz NOT NULL DEFAULT now(),
  updated_at  timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT org_saved_views_definition_shape CHECK (
    jsonb_typeof(definition) = 'object'
    AND octet_length(definition::text) <= 4000
    AND definition ->> 'subject' = subject
    AND (definition ->> 'v') ~ '^[0-9]{1,4}$'
  )
);

CREATE UNIQUE INDEX IF NOT EXISTS idx_org_saved_views_author_name
  ON public.org_saved_views (org_id, subject, created_by, lower(btrim(name)));
CREATE INDEX IF NOT EXISTS idx_org_saved_views_org_subject
  ON public.org_saved_views (org_id, subject, created_at);

ALTER TABLE public.org_saved_views ENABLE ROW LEVEL SECURITY;

-- The author and the organization never change (a view is not moved between orgs or people).
CREATE OR REPLACE FUNCTION public.labelos_saved_views_guard()
RETURNS trigger
LANGUAGE plpgsql
SET search_path = public
AS $$
BEGIN
  IF NEW.org_id <> OLD.org_id OR NEW.created_by <> OLD.created_by OR NEW.subject <> OLD.subject THEN
    RAISE EXCEPTION 'org_saved_views: the organization, the author and the subject of a view never change'
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS org_saved_views_guard ON public.org_saved_views;
CREATE TRIGGER org_saved_views_guard BEFORE UPDATE ON public.org_saved_views
  FOR EACH ROW EXECUTE FUNCTION public.labelos_saved_views_guard();

-- Writes are the service role's (141): the API roles can neither forge nor edit.
DROP TRIGGER IF EXISTS labelos_org_rows_service_only ON public.org_saved_views;
CREATE TRIGGER labelos_org_rows_service_only BEFORE INSERT OR UPDATE OR DELETE ON public.org_saved_views
  FOR EACH ROW EXECUTE FUNCTION public.labelos_org_rows_service_only('self', 'org_id');

-- Nobody reads or writes through PostgREST, whatever the privileges say.
DROP POLICY IF EXISTS org_saved_views_no_direct_access ON public.org_saved_views;
CREATE POLICY org_saved_views_no_direct_access ON public.org_saved_views
  FOR ALL TO anon, authenticated
  USING (false) WITH CHECK (false);

REVOKE ALL ON public.org_saved_views FROM anon, authenticated;

NOTIFY pgrst, 'reload schema';


-- ═════════════ 162_labelos_split_sheets_column_grants.sql ═════════════
-- 162_labelos_split_sheets_column_grants.sql
-- Label OS (LABEL-43, review G6 F1 — the D2 breach): an own-line reader must
-- not read a split sheet's negotiation note with their own JWT.
--
-- LABEL OS — NOT APPLIED. Apply at the final merge of the Label OS branch
-- into main, after 155. Never part of supabase/apply/pending.sql.
--
-- 155's `split_sheets_member_read` lets a member whose ability is
-- `rights.read.own_line` (a producer / engineer function) read the SHEET row
-- of a circulated sheet they have a line on, so they can see its status. RLS
-- is per row, not per column, so that row came with every column: the
-- `note` (the negotiation note, D2 says they never read it), who created and
-- circulated it, and the signed document's asset id. The app never shows
-- them those (`sheetView` builds their view field by field), but PostgREST
-- answered `split_sheets?select=note` on their own JWT.
--
-- The fix is a column grant: the API roles lose the table-wide SELECT and
-- get back only the columns a status needs. Every server route reads
-- split_sheets with the service role (lib/labelos/splits-store.ts,
-- filters-store.ts, org-export.ts — none through a user client), so no route
-- changes; a whole-org rights reader loses nothing the app gives them.
--
-- Not readable by anon / authenticated after this, whatever the row rule
-- says: note, document_asset_id, created_by, circulated_by, superseded_by,
-- updated_at. Asking for one is `permission denied` (PostgREST 401/403), and
-- `select=*` is refused too — name the columns.
--
-- anon keeps the same column list so an anonymous read still answers an
-- empty list (RLS) rather than a permission error, exactly as before.
--
-- No policy changes. Writes are untouched (no write policy exists; 141's
-- service-only trigger and 155's guards still refuse them).
--
-- Idempotent: REVOKE on the table also revokes its column grants, so a
-- replay starts from nothing and grants the same list again.

REVOKE SELECT ON public.split_sheets FROM anon, authenticated;
GRANT SELECT (id, org_id, track_id, kind, version, status, circulated_at, signed_at, superseded_at, created_at)
  ON public.split_sheets TO authenticated;
GRANT SELECT (id, org_id, track_id, kind, version, status, circulated_at, signed_at, superseded_at, created_at)
  ON public.split_sheets TO anon;

NOTIFY pgrst, 'reload schema';


-- ═════════════ 163_labelos_audit_events_immutable.sql ═════════════
-- 163_labelos_audit_events_immutable.sql
-- Label OS (LABEL-43, review G1 F6): "an audit event is never changed or
-- deleted" becomes a database fact, for every role — the service role too.
--
-- LABEL OS — NOT APPLIED. Apply at the final merge of the Label OS branch
-- into main, after 136 (and 146). Never part of supabase/apply/pending.sql.
--
-- 136 made activity_events append-only for the API roles (no UPDATE/DELETE
-- policy or grant). The service role bypasses both, so until now only code
-- review kept a route from rewriting or deleting an audit row. This trigger
-- refuses, for an `audit = true` row:
--
--   · every UPDATE, except the one Postgres itself makes when an account is
--     deleted: `actor_id … REFERENCES auth.users ON DELETE SET NULL`. That
--     update changes `actor_id` to NULL and nothing else, and the user row is
--     already gone. Refusing it would make every account with an audit event
--     impossible to delete (erasure), so it is let through — the event stays,
--     without the person;
--   · every DELETE, except the cascade from deleting the organization: the
--     LABEL-39 purge (`purge-deleted-orgs`) deletes the one `organizations`
--     row and its whole history goes with it (D10). By the time the cascade
--     reaches an event, its organization row is gone, which a direct DELETE
--     can never see (the FK holds while the org exists) — the test 136's
--     `org_members_keep_an_owner` uses for the same cascade.
--
-- An everyday row may not be turned into an audit one (that would forge an
-- immutable, back-dated record); otherwise everyday (`audit = false`) rows
-- are untouched, so `prune-org-events`
-- (which deletes only `audit = false` rows older than 24 months, D9) keeps
-- working. Nothing in the app updates an event; the only app delete is that
-- prune, and no erasure flow anonymises events (checked for LABEL-43).
--
-- Nothing reads a role, a GUC or a session setting, so nothing short of
-- dropping the trigger (a migration) turns it off. TRUNCATE is not covered
-- (no route can issue it; see the LABEL-43 PR, "Found, not fixed").
--
-- Idempotent: CREATE OR REPLACE, DROP TRIGGER IF EXISTS first.

CREATE OR REPLACE FUNCTION public.activity_events_audit_immutable()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  IF NOT OLD.audit THEN
    IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
    -- An event is audit-class from its INSERT on; promoting an everyday row
    -- would forge (and back-date) an audit record that could then never change.
    IF NEW.audit THEN
      RAISE EXCEPTION 'activity_events: an everyday event never becomes an audit event (event %)', OLD.id
        USING ERRCODE = 'insufficient_privilege';
    END IF;
    RETURN NEW;
  END IF;

  IF TG_OP = 'DELETE' THEN
    IF NOT EXISTS (SELECT 1 FROM public.organizations o WHERE o.id = OLD.org_id) THEN
      RETURN OLD; -- the organization is being purged
    END IF;
    RAISE EXCEPTION 'activity_events: an audit event is never deleted (event %)', OLD.id
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  IF OLD.actor_id IS NOT NULL
     AND NEW.actor_id IS NULL
     AND (to_jsonb(NEW) - 'actor_id') = (to_jsonb(OLD) - 'actor_id')
     AND NOT EXISTS (SELECT 1 FROM auth.users u WHERE u.id = OLD.actor_id) THEN
    RETURN NEW; -- the actor's account was deleted
  END IF;
  RAISE EXCEPTION 'activity_events: an audit event is never changed (event %)', OLD.id
    USING ERRCODE = 'insufficient_privilege';
END;
$$;

ALTER FUNCTION public.activity_events_audit_immutable() OWNER TO postgres;
REVOKE ALL ON FUNCTION public.activity_events_audit_immutable() FROM PUBLIC;

DROP TRIGGER IF EXISTS activity_events_audit_immutable ON public.activity_events;
CREATE TRIGGER activity_events_audit_immutable
  BEFORE UPDATE OR DELETE ON public.activity_events
  FOR EACH ROW EXECUTE FUNCTION public.activity_events_audit_immutable();

NOTIFY pgrst, 'reload schema';


-- ═════════════ 164_labelos_member_read_scope.sql ═════════════
-- 164_labelos_member_read_scope.sql
-- Label OS (LABEL-43, review G1 F1): who a member sees in their org's people,
-- on their OWN JWT, follows the same rule as GET /api/org/[orgId]/members.
--
-- LABEL OS — NOT APPLIED. Apply at the final merge of the Label OS branch
-- into main, after 139 (member_artist_scopes). Never part of
-- supabase/apply/pending.sql.
--
-- 136's `org_members_member_read` and `user_profiles_self_or_co_member_read`
-- let every member read every co-member's row and profile. The route was
-- fixed (G1, G10: `mayListMember`, lib/labelos/artist-scope.ts), but a roster
-- artist's own JWT still listed every other artist of the label, with their
-- name and `last_seen_overview_at`, straight from PostgREST. Both policies
-- now read one helper that is the SQL twin of `mayListMember`. A caller sees,
-- in each org where they hold a live membership (org not soft-deleted):
--
--   · their own row;
--   · every row whose role is not `artist` (owners, admins and staff are
--     always listed — a roster artist still sees the team);
--   · an artist's row only when the caller is staff (role is not `artist`)
--     AND either sees the whole org (`scope = 'org'`) or has, in their own
--     artist list, a contact that artist login stands for
--     (`member_artist_scopes`). Another roster artist never sees it.
--
-- A profile is visible to its user and to whoever sees one of that user's
-- membership rows.
--
-- R-08: `labelos_visible_members()` takes no argument from the row, so each
-- policy runs it ONCE per statement as a hashed subplan — no per-row
-- SECURITY DEFINER call (136's policies called `org_role(org_id)` per row).
-- It is SECURITY DEFINER because a policy on org_members cannot read
-- org_members without recursing into itself. The caller's own rows take a
-- cheaper first disjunct (`labelos_my_live_orgs()`, also one hashed subplan):
-- most Label OS policies read org_members only for the caller's own rows, and
-- OR stops there, so they never build the whole visible set.
--
-- Every other Label OS policy that reads org_members as the caller asks only
-- for the caller's own rows (`… WHERE cm.user_id = auth.uid()`), which this
-- keeps visible, so none of them changes. The routes use the service role.
-- The write policies (136) are untouched.
--
-- Idempotent: CREATE OR REPLACE, DROP POLICY IF EXISTS first.

CREATE OR REPLACE FUNCTION public.labelos_visible_members()
RETURNS TABLE (org_id uuid, user_id uuid)
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
  WITH me AS (
    SELECT m.org_id, m.role, m.scope
    FROM public.org_members m
    JOIN public.organizations o ON o.id = m.org_id
    WHERE m.user_id = auth.uid()
      AND o.deleted_at IS NULL
  )
  SELECT them.org_id, them.user_id
  FROM public.org_members them
  JOIN me ON me.org_id = them.org_id
  WHERE them.user_id = auth.uid()
     OR them.role <> 'artist'
     OR (me.role <> 'artist' AND me.scope = 'org')
     OR (
       me.role <> 'artist'
       AND EXISTS (
         SELECT 1
         FROM public.member_artist_scopes theirs
         JOIN public.member_artist_scopes mine
           ON mine.org_id = theirs.org_id AND mine.contact_id = theirs.contact_id
         WHERE theirs.org_id = them.org_id
           AND theirs.user_id = them.user_id
           AND mine.user_id = auth.uid()
       )
     );
$$;

-- The caller's own live memberships' orgs: the fast path for the many
-- policies that read only the caller's own org_members rows, so they never
-- need the whole visible set above.
CREATE OR REPLACE FUNCTION public.labelos_my_live_orgs()
RETURNS TABLE (org_id uuid)
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
  SELECT m.org_id
  FROM public.org_members m
  JOIN public.organizations o ON o.id = m.org_id
  WHERE m.user_id = auth.uid()
    AND o.deleted_at IS NULL;
$$;

ALTER FUNCTION public.labelos_my_live_orgs() OWNER TO postgres;
REVOKE ALL ON FUNCTION public.labelos_my_live_orgs() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.labelos_my_live_orgs() TO authenticated, anon;

ALTER FUNCTION public.labelos_visible_members() OWNER TO postgres;
REVOKE ALL ON FUNCTION public.labelos_visible_members() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.labelos_visible_members() TO authenticated, anon;

DROP POLICY IF EXISTS org_members_member_read ON public.org_members;
CREATE POLICY org_members_member_read ON public.org_members
  FOR SELECT
  USING (
    (user_id = (SELECT auth.uid()) AND org_id IN (SELECT lo.org_id FROM public.labelos_my_live_orgs() lo))
    OR (org_id, user_id) IN (SELECT v.org_id, v.user_id FROM public.labelos_visible_members() v)
  );

DROP POLICY IF EXISTS user_profiles_self_or_co_member_read ON public.user_profiles;
CREATE POLICY user_profiles_self_or_co_member_read ON public.user_profiles
  FOR SELECT
  USING (
    user_id = (SELECT auth.uid())
    OR user_id IN (SELECT v.user_id FROM public.labelos_visible_members() v)
  );

NOTIFY pgrst, 'reload schema';


-- ═════════════ 165_labelos_playlist_tracks_same_owner.sql ═════════════
-- 165_labelos_playlist_tracks_same_owner.sql
-- Label OS (LABEL-44, review G3): `playlist_tracks` gets the same-owner
-- trigger every other junction has (122/123/133, 142's project_tracks).
--
-- LABEL OS — NOT APPLIED. Apply at the final merge of the Label OS branch
-- into main, after 136–164. Never part of supabase/apply/pending.sql.
--
-- Why: a playlist is the producer's (owned by playlists.user_id; no org_id),
-- and the public store reads a featured playlist's tracks by id. G3 found
-- that POST /api/playlists/[id]/tracks accepted any track id, so an org song
-- (ownerless since 142) could be put in a producer playlist and read back
-- through the store. #117 fixed the route (the caller's own tracks only);
-- this makes it a database fact for every writer — the upload attach paths,
-- a future route, a script with the service key.
--
-- The rule: the track and the playlist have the same (non-null) owner, and
-- the track is not an organization's. 002 dropped NOT NULL from
-- playlists.user_id; an ownerless playlist (none since 053's reconcile)
-- takes no track, since NULL never equals an owner. Playlists have no
-- organization, so the org case of 142 does not exist here: an org track
-- never joins a playlist, and no two producers' rows ever meet. That is
-- exactly what the route already allows (`tracks.user_id = caller`), so the
-- producer's own playlists behave as before.
--
-- Fires on INSERT and on an UPDATE that changes which playlist or track a
-- row joins; a reorder (`position`) does not fire it. Existing rows are not
-- re-checked (a trigger cannot), so a cross-owner row written before this
-- migration stays until removed; supabase/local/checks/165_* shows the query
-- that lists them.
--
-- Idempotent: CREATE OR REPLACE, DROP TRIGGER IF EXISTS first.

CREATE OR REPLACE FUNCTION public.playlist_tracks_same_owner()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
BEGIN
  IF NOT EXISTS (
    SELECT 1
    FROM public.playlists p
    JOIN public.tracks t ON t.id = NEW.track_id AND t.user_id = p.user_id AND t.org_id IS NULL
    WHERE p.id = NEW.playlist_id
  ) THEN
    RAISE EXCEPTION 'playlist_tracks: track % and playlist % must have the same owner', NEW.track_id, NEW.playlist_id
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END $$;

ALTER FUNCTION public.playlist_tracks_same_owner() OWNER TO postgres;
REVOKE ALL ON FUNCTION public.playlist_tracks_same_owner() FROM PUBLIC;

DROP TRIGGER IF EXISTS playlist_tracks_same_owner ON public.playlist_tracks;
CREATE TRIGGER playlist_tracks_same_owner
  BEFORE INSERT OR UPDATE OF playlist_id, track_id ON public.playlist_tracks
  FOR EACH ROW EXECUTE FUNCTION public.playlist_tracks_same_owner();

NOTIFY pgrst, 'reload schema';


-- ═════════════ 166_labelos_one_artist_per_artist_org.sql ═════════════
-- 166_labelos_one_artist_per_artist_org.sql
-- Label OS (LABEL-44, review G2 D1): an artist-kind organization has at most
-- ONE artist contact, held by a unique index rather than by the routes alone.
--
-- LABEL OS — NOT APPLIED. Apply at the final merge of the Label OS branch
-- into main, after 136–165. Never part of supabase/apply/pending.sql.
--
-- Why: D1 says an artist org's roster is the artist themselves (139 creates
-- that contact with the org). The contacts routes enforce it with
-- `artistOrgRosterError` (lib/labelos/roster.ts) — read the org's contacts,
-- then insert — so two requests at the same moment both pass the check and
-- the org ends up with two artists. A unique index is the only rule
-- Postgres enforces across concurrent transactions.
--
-- A partial index cannot look at another table, and "artist-kind org" lives
-- on `organizations`. So:
--   - contacts.org_self_artist boolean: true exactly for an artist contact
--     (category or secondary_category in the artist group,
--     `groupOfCategory`) of an artist-kind org. Kept by a BEFORE trigger
--     from the row and its org, never from what the writer sent, so no
--     caller can set or clear it. Producer contacts (org_id NULL) are always
--     false and cost no query.
--   - an org whose kind changes has its contacts' flags recomputed (no
--     route changes a kind; this keeps the flag true if SQL ever does).
--   - CREATE UNIQUE INDEX contacts_one_artist_per_artist_org ON contacts
--     (org_id) WHERE org_self_artist. The second artist is a 23505 naming
--     the index, which the routes answer as their own 409 (`ONE_ARTIST`).
--
-- Existing data: before building the index, the migration counts artist
-- orgs that already hold more than one artist contact. If there are any, it
-- RAISES naming them before any table is touched (only the helper function
-- above it exists by then). It never picks which artist to demote — that is the
-- owner's call: set the extra contacts' category to something else (or
-- delete them) and run it again. Today no route creates an artist org and
-- 139's backfill makes exactly one contact per artist org, so on every
-- database this has been run on the count is zero.
--
-- The `artist` group's categories are written once here, in
-- labelos_is_artist_category (trimmed of any whitespace and lower-cased, as
-- groupOfCategory does), and src/lib/labelos/roster.test.ts holds them
-- equal to lib/contacts/roles.ts#ARTIST_GROUP_CATEGORIES.
--
-- Idempotent: ADD COLUMN IF NOT EXISTS, CREATE OR REPLACE, IF NOT EXISTS.

CREATE OR REPLACE FUNCTION public.labelos_is_artist_category(p text)
RETURNS boolean LANGUAGE sql IMMUTABLE SET search_path = public AS $$
  SELECT COALESCE(lower(regexp_replace(p, '^\s+|\s+$', '', 'g')) = ANY (ARRAY['artist', 'rapper', 'singer', 'songwriter', 'topliner']), false)
$$;

ALTER FUNCTION public.labelos_is_artist_category(text) OWNER TO postgres;
REVOKE ALL ON FUNCTION public.labelos_is_artist_category(text) FROM PUBLIC;

-- Refuse first, on data as it stands: nothing below runs if an artist org
-- already breaks the rule.
DO $$
DECLARE
  v_orgs text;
BEGIN
  SELECT string_agg(org_id::text, ', ' ORDER BY org_id) INTO v_orgs
  FROM (
    SELECT c.org_id
    FROM public.contacts c
    JOIN public.organizations o ON o.id = c.org_id AND o.kind = 'artist'
    WHERE public.labelos_is_artist_category(c.category) OR public.labelos_is_artist_category(c.secondary_category)
    GROUP BY c.org_id
    HAVING count(*) > 1
  ) dup;
  IF v_orgs IS NOT NULL THEN
    RAISE EXCEPTION 'migration 166: these artist organizations have more than one artist contact: %. Give the extra contacts another role (or delete them), then run 166 again.', v_orgs
      USING ERRCODE = 'unique_violation';
  END IF;
END $$;

ALTER TABLE public.contacts
  ADD COLUMN IF NOT EXISTS org_self_artist boolean NOT NULL DEFAULT false;

CREATE OR REPLACE FUNCTION public.contacts_org_self_artist()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
BEGIN
  IF NEW.org_id IS NULL THEN
    NEW.org_self_artist := false;
  ELSE
    NEW.org_self_artist := (public.labelos_is_artist_category(NEW.category) OR public.labelos_is_artist_category(NEW.secondary_category))
      AND EXISTS (SELECT 1 FROM public.organizations o WHERE o.id = NEW.org_id AND o.kind = 'artist');
  END IF;
  RETURN NEW;
END $$;

ALTER FUNCTION public.contacts_org_self_artist() OWNER TO postgres;
REVOKE ALL ON FUNCTION public.contacts_org_self_artist() FROM PUBLIC;

DROP TRIGGER IF EXISTS contacts_org_self_artist ON public.contacts;
CREATE TRIGGER contacts_org_self_artist
  BEFORE INSERT OR UPDATE OF org_id, category, secondary_category, org_self_artist ON public.contacts
  FOR EACH ROW EXECUTE FUNCTION public.contacts_org_self_artist();

-- An org's kind changing recomputes its contacts (the trigger above does the
-- work: setting the column fires it, and it ignores the value written).
CREATE OR REPLACE FUNCTION public.organizations_kind_self_artist()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
BEGIN
  UPDATE public.contacts SET org_self_artist = false WHERE org_id = NEW.id;
  RETURN NULL;
END $$;

ALTER FUNCTION public.organizations_kind_self_artist() OWNER TO postgres;
REVOKE ALL ON FUNCTION public.organizations_kind_self_artist() FROM PUBLIC;

DROP TRIGGER IF EXISTS organizations_kind_self_artist ON public.organizations;
CREATE TRIGGER organizations_kind_self_artist
  AFTER UPDATE OF kind ON public.organizations
  FOR EACH ROW WHEN (OLD.kind IS DISTINCT FROM NEW.kind)
  EXECUTE FUNCTION public.organizations_kind_self_artist();

-- Backfill the flag on existing org contacts (the trigger computes it).
UPDATE public.contacts SET org_self_artist = false WHERE org_id IS NOT NULL;

CREATE UNIQUE INDEX IF NOT EXISTS contacts_one_artist_per_artist_org
  ON public.contacts (org_id)
  WHERE org_self_artist;

NOTIFY pgrst, 'reload schema';


-- ═════════════ 167_labelos_release_items_lock_member_cas.sql ═════════════
-- 167_labelos_release_items_lock_member_cas.sql
-- Label OS (LABEL-44, reviews G4 / G7 / G10): two writes that a stale read
-- could get wrong are held in the database, and every tracklist write takes
-- its locks in one order.
--
-- LABEL OS — NOT APPLIED. Apply at the final merge of the Label OS branch
-- into main, after 136–166. Never part of supabase/apply/pending.sql.
--
-- ── 1. A tracklist changes only while the release is a draft ───────────────
-- `tracklistLocked` (src/app/api/org/[orgId]/releases/access.ts) refuses an
-- item add / edit / reorder / remove on a release that is not a draft, but
-- it judges a row the route read EARLIER. An add that read `draft` could
-- land after `POST …/deliver` claimed the release: a delivered release with
-- a tracklist nobody evaluated (20-review-G7-atomic-deliver.md, point 2).
-- The FK from release_items to releases only takes FOR KEY SHARE, which a
-- state UPDATE does not wait for.
--
-- 158's `release_items_store_lock` is replaced (same name, same trigger) by
-- one that, for every INSERT / UPDATE / DELETE of an item:
--   - takes FOR SHARE on the release row. Delivering is an UPDATE of that
--     row, which FOR SHARE blocks (and which blocks FOR SHARE): an item
--     write and a delivery are serialised. An item write that waited reads
--     the release as the delivery left it and is refused; a delivery that
--     waited goes through after the item write committed.
--   - refuses a listed release (158's rule and message, unchanged);
--   - refuses any release that is not a draft, except one IMPORTED as
--     already out and not on the store (LABEL-42: its tracklist is the very
--     thing being entered). That is `tracklistLocked`, as SQL.
-- What this does NOT close: deliver evaluates readiness BEFORE its claim, so
-- an item that commits between that read and the claim is delivered with
-- the release (the claim waits for it, then goes through). That window is
-- the atomic-deliver function's (20-review-G7-atomic-deliver.md: lock the
-- release and compare a fingerprint under the lock), not this trigger's;
-- the same holds for store listing, which reads the tracklist before it
-- sets store_listed.
--
-- A release (or its organization) being deleted removes its items by
-- cascade; by then the parent row is gone, the lookup finds nothing and the
-- cascade goes through, as in 158.
--
-- Error: check_violation (23514) with a message starting `release_items:`;
-- the routes answer it as a 409 in their own words (access.ts#writeError).
--
-- ── 2. A member change compares what the plan was made from ───────────────
-- `PATCH /api/org/[orgId]/members` reads the member, plans the change with
-- `planMemberChange` (which looks at the whole row), then calls
-- labelos_audit_member_update. A second admin's change landing in between
-- was overwritten by a plan made from the old row (G4). The function gains
-- `p_expect jsonb` — the row as the route read it (role, functions, scope,
-- cap_grants, cap_revokes; lib/labelos/members#memberExpectation) — and,
-- under its row lock, answers {"error": "changed"} and writes nothing (no
-- change, no event) when any key it names differs. A NULL p_expect skips the
-- comparison, so 146's local check (which calls it with six arguments)
-- still runs; the route always sends it.
--
-- The six-argument function is dropped and the seven-argument one created
-- (an overload would make PostgREST's choice ambiguous). EXECUTE stays
-- service_role only.
--
-- ── 3. Every item write locks the release FIRST ───────────────────────────
-- 144's reorder / remove functions (and a release DELETE cascading to its
-- items) take FOR UPDATE on the release and then touch item rows. A plain
-- UPDATE of an item locks the item row before section 1's trigger asks for
-- the release, so `PATCH …/items/[itemId]` racing a reorder took the two
-- locks in the opposite order and could deadlock (40P01). The PATCH now goes
-- through labelos_release_item_update, which locks the release FOR UPDATE
-- before it touches the item — the same order as 144's functions, so the
-- two queue instead. (An INSERT holds no item lock when the trigger runs.)
-- service_role only. Answers the updated row as jsonb, or NULL when the
-- release or the item is not there (the route's 404).
--
-- Rollback: supabase/rollback/167_*.down.sql puts back 158's trigger body
-- and 146's six-argument function, and drops labelos_release_item_update.
--
-- Idempotent: CREATE OR REPLACE, DROP ... IF EXISTS first.

-- ── 1 ────────────────────────────────────────────────────────────────────

CREATE OR REPLACE FUNCTION public.release_items_store_lock()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE
  v_release  uuid := COALESCE(NEW.release_id, OLD.release_id);
  v_state    text;
  v_imported boolean;
  v_listed   boolean;
BEGIN
  -- The organization's own purge deletes its items by cascade, possibly
  -- before its releases: a release whose organization is already gone holds
  -- nothing. FOR SHARE OF r: the release row only, never the organization.
  SELECT r.state, r.imported_released, r.store_listed
    INTO v_state, v_imported, v_listed
  FROM public.releases r
  JOIN public.organizations o ON o.id = r.org_id
  WHERE r.id = v_release
  FOR SHARE OF r;
  IF NOT FOUND THEN
    RETURN COALESCE(NEW, OLD);
  END IF;

  IF v_listed THEN
    RAISE EXCEPTION 'release_items: take the release off the store to change its tracklist' USING ERRCODE = 'check_violation';
  END IF;
  IF v_state = 'draft' OR (v_imported AND v_state = 'delivered') THEN
    RETURN COALESCE(NEW, OLD);
  END IF;
  RAISE EXCEPTION 'release_items: a % release keeps its tracklist', v_state USING ERRCODE = 'check_violation';
END $$;

ALTER FUNCTION public.release_items_store_lock() OWNER TO postgres;
REVOKE ALL ON FUNCTION public.release_items_store_lock() FROM PUBLIC;

DROP TRIGGER IF EXISTS release_items_store_lock ON public.release_items;
CREATE TRIGGER release_items_store_lock BEFORE INSERT OR UPDATE OR DELETE ON public.release_items
  FOR EACH ROW EXECUTE FUNCTION public.release_items_store_lock();

-- ── 2 ────────────────────────────────────────────────────────────────────

DROP FUNCTION IF EXISTS public.labelos_audit_member_update(uuid, uuid, uuid, jsonb, text, jsonb);

CREATE OR REPLACE FUNCTION public.labelos_audit_member_update(
  p_org uuid,
  p_actor uuid,
  p_user uuid,
  p_patch jsonb,
  p_verb text,
  p_payload jsonb,
  p_expect jsonb DEFAULT NULL
) RETURNS jsonb
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path = public
AS $fn$
DECLARE
  v_row     public.org_members%ROWTYPE;
  v_now     jsonb;
  v_key     text;
  v_cleared uuid[] := '{}';
  v_payload jsonb := p_payload;
BEGIN
  IF p_verb NOT IN ('member.role_changed', 'member.capabilities_changed', 'member.scope_changed') THEN
    RAISE EXCEPTION 'unknown member verb %', p_verb USING ERRCODE = '22023';
  END IF;
  IF p_patch IS NULL OR jsonb_typeof(p_patch) <> 'object' OR p_patch = '{}'::jsonb THEN
    RAISE EXCEPTION 'empty member patch' USING ERRCODE = '22023';
  END IF;
  IF p_expect IS NOT NULL AND jsonb_typeof(p_expect) <> 'object' THEN
    RAISE EXCEPTION 'member expectation must be an object' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_row FROM public.org_members WHERE org_id = p_org AND user_id = p_user FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('error', 'not_found');
  END IF;

  -- The plan was made from p_expect; if the row moved since, nothing happens.
  IF p_expect IS NOT NULL THEN
    v_now := jsonb_build_object(
      'role', v_row.role,
      'functions', to_jsonb(v_row.functions),
      'scope', v_row.scope,
      'cap_grants', to_jsonb(v_row.cap_grants),
      'cap_revokes', to_jsonb(v_row.cap_revokes)
    );
    FOR v_key IN SELECT jsonb_object_keys(p_expect) LOOP
      IF NOT (v_now ? v_key) THEN
        RAISE EXCEPTION 'unknown member expectation key %', v_key USING ERRCODE = '22023';
      END IF;
      IF v_now->v_key IS DISTINCT FROM p_expect->v_key THEN
        RETURN jsonb_build_object('error', 'changed');
      END IF;
    END LOOP;
  END IF;

  UPDATE public.org_members m
  SET role        = COALESCE(p_patch->>'role', m.role),
      functions   = CASE WHEN p_patch ? 'functions'   THEN ARRAY(SELECT jsonb_array_elements_text(p_patch->'functions'))   ELSE m.functions END,
      scope       = COALESCE(p_patch->>'scope', m.scope),
      cap_grants  = CASE WHEN p_patch ? 'cap_grants'  THEN ARRAY(SELECT jsonb_array_elements_text(p_patch->'cap_grants'))  ELSE m.cap_grants END,
      cap_revokes = CASE WHEN p_patch ? 'cap_revokes' THEN ARRAY(SELECT jsonb_array_elements_text(p_patch->'cap_revokes')) ELSE m.cap_revokes END
  WHERE m.org_id = p_org AND m.user_id = p_user
  RETURNING m.* INTO v_row;

  IF v_row.role <> 'artist' AND v_row.scope <> 'artists' THEN
    WITH gone AS (
      DELETE FROM public.member_artist_scopes s
      WHERE s.org_id = p_org AND s.user_id = p_user
      RETURNING s.contact_id
    )
    SELECT COALESCE(array_agg(contact_id ORDER BY contact_id), '{}') INTO v_cleared FROM gone;
    IF cardinality(v_cleared) > 0 THEN
      v_payload := v_payload || jsonb_build_object('contact_ids', jsonb_build_object('from', to_jsonb(v_cleared), 'to', '[]'::jsonb));
    END IF;
  END IF;

  PERFORM public.labelos_audit_insert(p_org, p_actor, p_verb, 'member', p_user, v_payload);

  RETURN jsonb_build_object('member', jsonb_build_object(
    'user_id', v_row.user_id,
    'role', v_row.role,
    'functions', to_jsonb(v_row.functions),
    'scope', v_row.scope,
    'cap_grants', to_jsonb(v_row.cap_grants),
    'cap_revokes', to_jsonb(v_row.cap_revokes),
    'joined_at', v_row.joined_at,
    'invited_by', v_row.invited_by
  ));
END;
$fn$;

ALTER FUNCTION public.labelos_audit_member_update(uuid, uuid, uuid, jsonb, text, jsonb, jsonb) OWNER TO postgres;
REVOKE ALL ON FUNCTION public.labelos_audit_member_update(uuid, uuid, uuid, jsonb, text, jsonb, jsonb) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.labelos_audit_member_update(uuid, uuid, uuid, jsonb, text, jsonb, jsonb) TO service_role;

-- ── 3 ────────────────────────────────────────────────────────────────────

CREATE OR REPLACE FUNCTION public.labelos_release_item_update(p_org uuid, p_release uuid, p_item uuid, p_patch jsonb)
RETURNS jsonb
LANGUAGE plpgsql
SET search_path = public
AS $$
DECLARE
  v_row public.release_items%ROWTYPE;
  v_key text;
BEGIN
  IF p_patch IS NULL OR jsonb_typeof(p_patch) <> 'object' OR p_patch = '{}'::jsonb THEN
    RAISE EXCEPTION 'empty item patch' USING ERRCODE = 'invalid_parameter_value';
  END IF;
  FOR v_key IN SELECT jsonb_object_keys(p_patch) LOOP
    IF v_key NOT IN ('master_track_id', 'version_title', 'explicit') THEN
      RAISE EXCEPTION 'unknown item field %', v_key USING ERRCODE = 'invalid_parameter_value';
    END IF;
  END LOOP;

  -- The release first, as 144's reorder / remove do.
  PERFORM 1 FROM public.releases WHERE id = p_release AND org_id = p_org FOR UPDATE;
  IF NOT FOUND THEN
    RETURN NULL;
  END IF;

  UPDATE public.release_items ri
  SET master_track_id = CASE WHEN p_patch ? 'master_track_id' THEN (p_patch->>'master_track_id')::uuid ELSE ri.master_track_id END,
      version_title   = CASE WHEN p_patch ? 'version_title' THEN p_patch->>'version_title' ELSE ri.version_title END,
      explicit        = CASE WHEN p_patch ? 'explicit' THEN (p_patch->>'explicit')::boolean ELSE ri.explicit END
  WHERE ri.id = p_item AND ri.release_id = p_release AND ri.org_id = p_org
  RETURNING ri.* INTO v_row;
  IF NOT FOUND THEN
    RETURN NULL;
  END IF;
  RETURN to_jsonb(v_row);
END;
$$;

ALTER FUNCTION public.labelos_release_item_update(uuid, uuid, uuid, jsonb) OWNER TO postgres;
REVOKE ALL ON FUNCTION public.labelos_release_item_update(uuid, uuid, uuid, jsonb) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.labelos_release_item_update(uuid, uuid, uuid, jsonb) TO service_role;

NOTIFY pgrst, 'reload schema';


-- ═════════════ 168_labelos_search_tokenization.sql ═════════════
-- 168_labelos_search_tokenization.sql — LABEL-45: org search tokenization (G8 F2).
--
-- 159's generated `search_tsv` columns fed Postgres' `simple` parser the raw
-- text. Its default parser keeps a file name, a host and an address in one
-- piece: `final_mix.wav` is one token, `a@x.com` is one `email` token. So the
-- word a person types ("mix", "x com") matched nothing inside them.
--
-- The fix is on the index side: `translate(normalize(text, NFKC), '_.-@/',
-- '     ')` turns the five joiners into spaces BEFORE `to_tsvector`, in every searchable column of
-- all six tables (one rule, so a title like "Runnin_Home.v2" and a label
-- "x-ray" behave like a file name). The query side (lib/labelos/org-search.ts)
-- already splits a typed query on the same characters and, from this task on,
-- keeps combining marks (\p{M}) inside a word so Hindi and Thai words stay
-- whole. `normalize(…, NFKC)` is the same normal form the query is read in, so
-- a name stored decomposed (macOS hands over 'Café.wav' as 'Cafe' + U+0301)
-- is indexed as the word a person types. (normalize() is IMMUTABLE, needs a
-- UTF8 database — Supabase's is — and passes ASCII through unchanged.)
--
-- A generated column's expression cannot be altered, so each column is dropped
-- and added again (its GIN index goes with it and is recreated). Nothing else
-- depends on it: no policy, view, trigger or function reads `search_tsv`.
--
-- Same shape as 159 otherwise:
--   * tracks / contacts / projects / project_assets keep the vector NULL for a
--     producer row (org_id IS NULL), so a producer's data is never searchable
--     and costs no index space; releases and parties exist only for orgs;
--   * 'simple', immutable: translate() and to_tsvector('simple'::regconfig, …)
--     are IMMUTABLE, which a generated column requires;
--   * track notes are still NOT indexed (a hit would show the title of a row
--     matched on a private note).
--
-- Replay-safe (db:local:reset applies every migration twice): a column whose
-- generation expression already contains translate() and normalize() is left alone, so the
-- second run neither rewrites the table nor rebuilds the index. If 159 was
-- never applied, this creates the columns itself.
--
-- ADD COLUMN ... GENERATED STORED rewrites the table once and takes an
-- ACCESS EXCLUSIVE lock while it does: apply at the final merge like the rest
-- of Label OS, not under load.

DO $$
DECLARE
  spec record;
  current_expr text;
BEGIN
  FOR spec IN
    SELECT * FROM (VALUES
      ('tracks',
       $e$CASE WHEN org_id IS NULL THEN NULL
            ELSE to_tsvector('simple'::regconfig, translate(normalize(coalesce(title, ''), NFKC), '_.-@/', '     ')) END$e$,
       ' WHERE org_id IS NOT NULL'),
      ('contacts',
       $e$CASE WHEN org_id IS NULL THEN NULL
            ELSE to_tsvector('simple'::regconfig, translate(normalize(coalesce(name, '') || ' ' || coalesce(email, '') || ' ' || coalesce(label, ''), NFKC), '_.-@/', '     ')) END$e$,
       ' WHERE org_id IS NOT NULL'),
      ('projects',
       $e$CASE WHEN org_id IS NULL THEN NULL
            ELSE to_tsvector('simple'::regconfig, translate(normalize(coalesce(name, '') || ' ' || coalesce(description, ''), NFKC), '_.-@/', '     ')) END$e$,
       ' WHERE org_id IS NOT NULL'),
      ('project_assets',
       $e$CASE WHEN org_id IS NULL THEN NULL
            ELSE to_tsvector('simple'::regconfig, translate(normalize(coalesce(label, '') || ' ' || coalesce(file_name, ''), NFKC), '_.-@/', '     ')) END$e$,
       ' WHERE org_id IS NOT NULL'),
      ('releases',
       $e$to_tsvector('simple'::regconfig, translate(normalize(coalesce(title, '') || ' ' || coalesce(label_name, ''), NFKC), '_.-@/', '     '))$e$,
       ''),
      ('parties',
       $e$to_tsvector('simple'::regconfig, translate(normalize(coalesce(display_name, '') || ' ' || coalesce(legal_name, ''), NFKC), '_.-@/', '     '))$e$,
       '')
    ) AS v(tbl, expr, idx_where)
  LOOP
    SELECT pg_get_expr(d.adbin, d.adrelid) INTO current_expr
      FROM pg_attrdef d
      JOIN pg_attribute a ON a.attrelid = d.adrelid AND a.attnum = d.adnum
     WHERE d.adrelid = ('public.' || spec.tbl)::regclass AND a.attname = 'search_tsv';

    IF current_expr IS NULL OR current_expr NOT LIKE '%translate(%' OR current_expr NOT ILIKE '%normalize(%' THEN
      EXECUTE format('ALTER TABLE public.%I DROP COLUMN IF EXISTS search_tsv', spec.tbl);
      EXECUTE format('ALTER TABLE public.%I ADD COLUMN search_tsv tsvector GENERATED ALWAYS AS (%s) STORED', spec.tbl, spec.expr);
    END IF;
    EXECUTE format('CREATE INDEX IF NOT EXISTS %I ON public.%I USING gin (search_tsv)%s',
                   spec.tbl || '_search_tsv_idx', spec.tbl, spec.idx_where);
  END LOOP;
END $$;

NOTIFY pgrst, 'reload schema';


-- ═════════════ 169_labelos_overview_seen_per_org.sql ═════════════
-- 169_labelos_overview_seen_per_org.sql
-- Label OS (LABEL-46, review finding G5): "since your last visit" per org.
--
-- LABEL OS — NOT APPLIED. Apply at the final merge of the Label OS branch
-- into main. Never part of supabase/apply/pending.sql.
--
-- 136 put `last_seen_overview_at` on user_profiles: ONE value per user, so
-- opening org A's Overview marked every other org's digest seen as well.
-- This table holds one mark per (org, user).
--
--  * Read by the member on their own JWT (their own rows, live orgs they
--    still belong to); written ONLY by POST /api/org/[orgId]/overview/seen
--    through the service role. The API roles hold no INSERT / UPDATE /
--    DELETE privilege and there is no write policy.
--  * Cascades from the organization (LABEL-39's hard delete) and from the
--    user. A personal read marker: not in the org export.
--  * Backfill: every existing membership starts from the member's user-level
--    value, so nobody's feed reopens to a week of already-read events. The
--    user-level column stays (it is that backfill's source and the fallback
--    the code uses while this migration is unapplied); it is no longer written.
--
-- Idempotent: IF NOT EXISTS, DROP POLICY/TRIGGER IF EXISTS, ON CONFLICT DO NOTHING.

CREATE TABLE IF NOT EXISTS public.org_overview_seen (
  org_id       uuid NOT NULL REFERENCES public.organizations(id) ON DELETE CASCADE,
  user_id      uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  last_seen_at timestamptz NOT NULL,
  updated_at   timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (org_id, user_id)
);

CREATE INDEX IF NOT EXISTS org_overview_seen_user_idx ON public.org_overview_seen (user_id);

ALTER TABLE public.org_overview_seen ENABLE ROW LEVEL SECURITY;

REVOKE ALL ON public.org_overview_seen FROM PUBLIC, anon, authenticated;
GRANT SELECT ON public.org_overview_seen TO authenticated;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.org_overview_seen TO service_role;

DROP POLICY IF EXISTS org_overview_seen_self_read ON public.org_overview_seen;
CREATE POLICY org_overview_seen_self_read ON public.org_overview_seen
  FOR SELECT TO authenticated
  USING (
    user_id = (SELECT auth.uid())
    AND (SELECT public.org_role(org_overview_seen.org_id)) IS NOT NULL
  );

-- A mark does not outlive the membership: leaving an org removes it, so a
-- member who is invited back starts from the default window, not from a
-- months-old mark. (The cascade from organizations needs no trigger.)
CREATE OR REPLACE FUNCTION public.org_overview_seen_forget()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  DELETE FROM public.org_overview_seen WHERE org_id = OLD.org_id AND user_id = OLD.user_id;
  RETURN OLD;
END $$;
REVOKE ALL ON FUNCTION public.org_overview_seen_forget() FROM PUBLIC, anon, authenticated;

DROP TRIGGER IF EXISTS org_overview_seen_forget ON public.org_members;
CREATE TRIGGER org_overview_seen_forget
  AFTER DELETE ON public.org_members
  FOR EACH ROW EXECUTE FUNCTION public.org_overview_seen_forget();

-- Backfill from the user-level value. (One value per user is all that was
-- stored, so every membership starts from it: that is what the member had
-- "seen" under the old scheme, and it cannot be told apart per org.)
INSERT INTO public.org_overview_seen (org_id, user_id, last_seen_at)
SELECT om.org_id, om.user_id, up.last_seen_overview_at
FROM public.org_members om
JOIN public.user_profiles up ON up.user_id = om.user_id
WHERE up.last_seen_overview_at IS NOT NULL
ON CONFLICT (org_id, user_id) DO NOTHING;

NOTIFY pgrst, 'reload schema';


-- ═════════════ 170_labelos_entitlements_platform.sql ═════════════
-- 170_labelos_entitlements_platform.sql
-- Label OS (LABEL-47): account faces, entitlements, the platform console.
--
-- LABEL OS — NOT APPLIED. Apply at the final merge of the Label OS branch
-- into main. Never part of supabase/apply/pending.sql.
--
-- The platform operator (the owner of the software) licenses Label OS to an
-- independent artist/producer (org kind `artist`) or to a label (kind
-- `label`) and decides what each licensee gets. No kind is renamed; the face
-- is derived from the kind (src/lib/labelos/account.ts).
--
--  * platform_admins(user_id) — who may use /platform. NEVER self-service:
--    no route, function or API role writes it (service_role may only read).
--    The owner adds themself once, by hand, in the SQL editor:
--        INSERT INTO public.platform_admins (user_id, note)
--        SELECT id, 'owner' FROM auth.users WHERE email = '<your sign-in email>';
--    (docs: supabase/MIGRATIONS.md, 170). No email is seeded here.
--  * org_entitlements(org_id, modules, max_seats, max_artists, setup_done,
--    granted_by, granted_at) — one row per licensee org. NO ROW = everything
--    the org's face allows (src/lib/labelos/entitlements.ts#orgEntitlements),
--    so every org that exists today keeps working unchanged. Members read
--    their own org's row; nobody but the functions below writes it.
--    Cascades from the organization (LABEL-39's hard delete). Not in the org
--    export: it is the operator's licence for the org, not the org's data.
--  * has_org_cap gains step 6: a capability a module owns (contracts.read →
--    contracts, finance.read → finance) needs the module. The rest of the
--    function is 136's, word for word; capabilities.sql.test.ts parses the
--    LATEST definition and holds both the old and the new data equal to the
--    TypeScript tables.
--  * labelos_accept_invitation (148's, word for word, plus two changes): an
--    `owner` invitation is honoured when its sender is a platform operator
--    (the console's first owner of a licensee), and the seat cap is enforced
--    under a lock on the org's entitlement row ({"error": "seat_limit"}).
--  * labelos_platform_create_licensee / labelos_platform_set_entitlements —
--    the console's two writes, each WITH its audit event in the affected org
--    (`org.entitlements_changed`; the new org also gets `org.created`). The
--    owner invitation reuses 146's labelos_audit_invitation_create
--    (`invitation.created`). Platform-level actions are therefore recorded in
--    the activity log of the org they act on, with the operator as actor;
--    there is no platform-wide log (every console write has an affected org).
--    service_role EXECUTE only; each re-checks that the actor is an operator.
--
-- Idempotent: IF NOT EXISTS, CREATE OR REPLACE, DROP POLICY IF EXISTS.

-- ── platform_admins ──────────────────────────────────────────────────────

CREATE TABLE IF NOT EXISTS public.platform_admins (
  user_id    uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE,
  note       text,
  created_at timestamptz NOT NULL DEFAULT now()
);

ALTER TABLE public.platform_admins ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.platform_admins FROM PUBLIC, anon, authenticated, service_role;
GRANT SELECT ON public.platform_admins TO authenticated, service_role;

-- An operator reads their own row (nothing else reads it but the service role).
DROP POLICY IF EXISTS platform_admins_self_read ON public.platform_admins;
CREATE POLICY platform_admins_self_read ON public.platform_admins
  FOR SELECT TO authenticated
  USING (user_id = (SELECT auth.uid()));

-- ── org_entitlements ─────────────────────────────────────────────────────

CREATE TABLE IF NOT EXISTS public.org_entitlements (
  org_id      uuid PRIMARY KEY REFERENCES public.organizations(id) ON DELETE CASCADE,
  modules     text[] NOT NULL DEFAULT '{}',
  max_seats   int CHECK (max_seats IS NULL OR max_seats >= 1),
  max_artists int CHECK (max_artists IS NULL OR max_artists >= 0),
  setup_done  boolean NOT NULL DEFAULT false,
  granted_by  uuid REFERENCES auth.users(id) ON DELETE SET NULL,
  granted_at  timestamptz NOT NULL DEFAULT now()
);

ALTER TABLE public.org_entitlements ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.org_entitlements FROM PUBLIC, anon, authenticated, service_role;
GRANT SELECT ON public.org_entitlements TO authenticated, service_role;

-- Members of a live org read its licence (the shell hides what it does not
-- include). `org_role(org_id)` takes the row's column, so it is evaluated per
-- row, not once per query; the table holds one row per org, so a member's read
-- touches only the rows of their orgs and the cost stays trivial.
DROP POLICY IF EXISTS org_entitlements_member_read ON public.org_entitlements;
CREATE POLICY org_entitlements_member_read ON public.org_entitlements
  FOR SELECT TO authenticated
  USING ((SELECT public.org_role(org_id)) IS NOT NULL);

-- ── has_org_cap(org, cap): 136 + step 6 (entitlements) ───────────────────

CREATE OR REPLACE FUNCTION public.has_org_cap(p_org uuid, p_cap text)
RETURNS boolean
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = public
AS $fn$
DECLARE
  -- labelos:mapping:start
  all_capabilities constant text[] := ARRAY[
    'catalog.read', 'catalog.write', 'audio.finished', 'audio.working',
    'review.write', 'review.comment', 'rights.read', 'rights.read.own_line',
    'rights.write', 'contracts.read', 'release.write',
    'release.approve.master', 'release.approve.artwork',
    'release.approve.legal', 'release.approve.marketing',
    'release.approve.metadata', 'tasks.write', 'share.external',
    'members.manage', 'org.manage', 'finance.read', 'business.read.internal'
  ];
  org_kinds constant text[] := ARRAY['artist', 'producer', 'label'];
  roles_by_org_kind constant text[] := ARRAY[
    ['artist', 'owner'], ['artist', 'admin'], ['artist', 'member'],
    ['producer', 'owner'], ['producer', 'admin'], ['producer', 'member'],
    ['label', 'owner'], ['label', 'admin'], ['label', 'member'], ['label', 'artist']
  ];
  functions_by_org_kind constant text[] := ARRAY[
    ['artist', 'artist_manager'], ['artist', 'producer'], ['artist', 'engineer'],
    ['artist', 'marketing'], ['artist', 'legal'], ['artist', 'operations'],
    ['producer', 'producer'], ['producer', 'engineer'],
    ['producer', 'artist_manager'], ['producer', 'operations'],
    ['label', 'a_and_r'], ['label', 'project_manager'], ['label', 'marketing'],
    ['label', 'legal'], ['label', 'finance'], ['label', 'artist_manager'],
    ['label', 'producer'], ['label', 'engineer'], ['label', 'operations']
  ];
  -- KIND_CEILING: kinds whose ceiling is every capability. No kind has a
  -- partial ceiling in the MVP; the parity test fails if one appears.
  kinds_with_full_ceiling constant text[] := ARRAY['artist', 'producer', 'label'];
  -- ROLE_GRANTS: roles granted every capability, then the rest as pairs.
  roles_granted_everything constant text[] := ARRAY['owner', 'admin'];
  role_grants constant text[] := ARRAY[
    ['artist', 'catalog.write'], ['artist', 'audio.finished'],
    ['artist', 'audio.working'], ['artist', 'review.comment'],
    ['artist', 'rights.read']
  ];
  roles_using_functions constant text[] := ARRAY['member'];
  roles_taking_overrides constant text[] := ARRAY['member', 'artist'];
  function_presets constant text[] := ARRAY[
    ['a_and_r', 'catalog.write'], ['a_and_r', 'audio.finished'],
    ['a_and_r', 'audio.working'], ['a_and_r', 'review.write'],
    ['a_and_r', 'rights.read'], ['a_and_r', 'release.write'],
    ['a_and_r', 'release.approve.master'], ['a_and_r', 'share.external'],
    ['a_and_r', 'tasks.write'],
    ['project_manager', 'catalog.write'], ['project_manager', 'audio.finished'],
    ['project_manager', 'audio.working'], ['project_manager', 'review.write'],
    ['project_manager', 'rights.read'], ['project_manager', 'release.write'],
    ['project_manager', 'release.approve.metadata'],
    ['project_manager', 'share.external'],
    ['project_manager', 'business.read.internal'],
    ['project_manager', 'tasks.write'],
    ['marketing', 'catalog.read'], ['marketing', 'audio.finished'],
    ['marketing', 'release.approve.artwork'],
    ['marketing', 'release.approve.marketing'],
    ['marketing', 'business.read.internal'], ['marketing', 'tasks.write'],
    ['legal', 'catalog.read'], ['legal', 'audio.finished'],
    ['legal', 'rights.write'], ['legal', 'contracts.read'],
    ['legal', 'release.approve.legal'], ['legal', 'business.read.internal'],
    ['legal', 'tasks.write'],
    ['artist_manager', 'catalog.write'], ['artist_manager', 'audio.finished'],
    ['artist_manager', 'audio.working'], ['artist_manager', 'review.write'],
    ['artist_manager', 'rights.read'], ['artist_manager', 'tasks.write'],
    ['producer', 'catalog.write'], ['producer', 'audio.finished'],
    ['producer', 'audio.working'], ['producer', 'rights.read.own_line'],
    ['producer', 'tasks.write'],
    ['engineer', 'catalog.write'], ['engineer', 'audio.finished'],
    ['engineer', 'audio.working'], ['engineer', 'rights.read.own_line'],
    ['engineer', 'tasks.write']
  ];
  -- IMPLIES: [wider, narrower].
  implies constant text[] := ARRAY[
    ['catalog.write', 'catalog.read'], ['audio.finished', 'catalog.read'],
    ['audio.working', 'catalog.read'], ['review.comment', 'catalog.read'],
    ['rights.read.own_line', 'catalog.read'], ['contracts.read', 'catalog.read'],
    ['release.write', 'catalog.read'], ['release.approve.master', 'catalog.read'],
    ['release.approve.artwork', 'catalog.read'],
    ['release.approve.legal', 'catalog.read'],
    ['release.approve.marketing', 'catalog.read'],
    ['release.approve.metadata', 'catalog.read'], ['tasks.write', 'catalog.read'],
    ['share.external', 'catalog.read'], ['business.read.internal', 'catalog.read'],
    ['rights.write', 'rights.read'], ['rights.read', 'rights.read.own_line'],
    ['review.write', 'review.comment']
  ];
  never_grantable constant text[] := ARRAY[
    ['member', 'members.manage'], ['member', 'org.manage'],
    ['artist', 'members.manage'], ['artist', 'org.manage'],
    ['artist', 'business.read.internal'], ['artist', 'contracts.read']
  ];
  -- ENTITLEMENTS (170, LABEL-47): src/lib/labelos/entitlements.ts + account.ts.
  -- CAPABILITY_MODULE: [capability, module]. A capability a module owns needs
  -- the module; every other capability is core and needs nothing.
  capability_modules constant text[] := ARRAY[
    ['contracts.read', 'contracts'], ['finance.read', 'finance']
  ];
  -- MODULES: the ceiling of an org kind with no face (the producer's own org).
  modules constant text[] := ARRAY[
    'contracts', 'finance', 'marketing', 'pr', 'executive', 'artistic',
    'store', 'search', 'digest', 'export'
  ];
  -- FACE_KIND, read as [kind, face].
  kind_faces constant text[] := ARRAY[
    ['artist', 'independent'], ['label', 'label']
  ];
  -- FACE_MODULES: [face, module].
  face_modules constant text[] := ARRAY[
    ['independent', 'contracts'], ['independent', 'finance'],
    ['independent', 'marketing'], ['independent', 'pr'],
    ['independent', 'executive'], ['independent', 'artistic'],
    ['independent', 'store'], ['independent', 'search'],
    ['independent', 'digest'], ['independent', 'export'],
    ['label', 'contracts'], ['label', 'finance'],
    ['label', 'marketing'], ['label', 'pr'],
    ['label', 'executive'], ['label', 'artistic'],
    ['label', 'store'], ['label', 'search'],
    ['label', 'digest'], ['label', 'export']
  ];
  -- labelos:mapping:end

  v_kind      text;
  v_role      text;
  v_functions text[];
  v_grants    text[];
  v_revokes   text[];
  granted     text[] := '{}';
  revoked     text[] := '{}';
  pair        text[];
  preset      text[];
  fn          text;
  ok          boolean;
  grown       boolean;
  v_module    text;
  v_face      text;
  v_entitled  text[];
BEGIN
  IF p_org IS NULL OR p_cap IS NULL OR NOT (p_cap = ANY (all_capabilities)) THEN
    RETURN false;
  END IF;

  SELECT o.kind, om.role, om.functions, om.cap_grants, om.cap_revokes
    INTO v_kind, v_role, v_functions, v_grants, v_revokes
  FROM public.org_members om
  JOIN public.organizations o ON o.id = om.org_id
  WHERE om.org_id = p_org
    AND om.user_id = auth.uid()
    AND o.deleted_at IS NULL;
  IF NOT FOUND OR NOT (v_kind = ANY (org_kinds)) THEN
    RETURN false;
  END IF;

  -- 1. The role must be one the org kind offers.
  ok := false;
  FOREACH pair SLICE 1 IN ARRAY roles_by_org_kind LOOP
    IF pair[1] = v_kind AND pair[2] = v_role THEN ok := true; END IF;
  END LOOP;
  IF NOT ok THEN RETURN false; END IF;

  -- 2. Role grants, function presets, per-member grants.
  IF v_role = ANY (roles_granted_everything) THEN
    granted := all_capabilities;
  ELSE
    FOREACH pair SLICE 1 IN ARRAY role_grants LOOP
      IF pair[1] = v_role THEN granted := granted || pair[2]; END IF;
    END LOOP;
  END IF;

  IF v_role = ANY (roles_using_functions) THEN
    FOREACH fn IN ARRAY coalesce(v_functions, '{}') LOOP
      FOREACH pair SLICE 1 IN ARRAY functions_by_org_kind LOOP
        IF pair[1] = v_kind AND pair[2] = fn THEN
          FOREACH preset SLICE 1 IN ARRAY function_presets LOOP
            IF preset[1] = fn THEN granted := granted || preset[2]; END IF;
          END LOOP;
        END IF;
      END LOOP;
    END LOOP;
  END IF;

  IF v_role = ANY (roles_taking_overrides) THEN
    granted := granted || ARRAY(
      SELECT c FROM unnest(coalesce(v_grants, '{}')) AS c WHERE c = ANY (all_capabilities)
    );
    revoked := ARRAY(
      SELECT c FROM unnest(coalesce(v_revokes, '{}')) AS c WHERE c = ANY (all_capabilities)
    );
    -- 3. Revoking a capability also revokes everything that needs it.
    LOOP
      grown := false;
      FOREACH pair SLICE 1 IN ARRAY implies LOOP
        IF pair[2] = ANY (revoked) AND NOT (pair[1] = ANY (revoked)) THEN
          revoked := revoked || pair[1];
          grown := true;
        END IF;
      END LOOP;
      EXIT WHEN NOT grown;
    END LOOP;
  END IF;

  -- 4. Close the grants under IMPLIES.
  LOOP
    grown := false;
    FOREACH pair SLICE 1 IN ARRAY implies LOOP
      IF pair[1] = ANY (granted) AND NOT (pair[2] = ANY (granted)) THEN
        granted := granted || pair[2];
        grown := true;
      END IF;
    END LOOP;
    EXIT WHEN NOT grown;
  END LOOP;

  -- 5. Granted, inside the ceiling, not a hard limit, not revoked.
  IF NOT (p_cap = ANY (granted)) OR NOT (v_kind = ANY (kinds_with_full_ceiling)) THEN
    RETURN false;
  END IF;
  FOREACH pair SLICE 1 IN ARRAY never_grantable LOOP
    IF pair[1] = v_role AND pair[2] = p_cap THEN RETURN false; END IF;
  END LOOP;
  IF p_cap = ANY (revoked) THEN
    RETURN false;
  END IF;

  -- 6. Entitlements (170): a capability a module owns needs the module. The
  --    module must be inside the face's ceiling, and, when the operator has
  --    written an org_entitlements row, in that row. No row = the ceiling.
  v_module := NULL;
  FOREACH pair SLICE 1 IN ARRAY capability_modules LOOP
    IF pair[1] = p_cap THEN v_module := pair[2]; END IF;
  END LOOP;
  IF v_module IS NULL THEN
    RETURN true;
  END IF;
  v_face := NULL;
  FOREACH pair SLICE 1 IN ARRAY kind_faces LOOP
    IF pair[1] = v_kind THEN v_face := pair[2]; END IF;
  END LOOP;
  ok := false;
  IF v_face IS NULL THEN
    ok := v_module = ANY (modules);
  ELSE
    FOREACH pair SLICE 1 IN ARRAY face_modules LOOP
      IF pair[1] = v_face AND pair[2] = v_module THEN ok := true; END IF;
    END LOOP;
  END IF;
  IF NOT ok THEN
    RETURN false;
  END IF;
  SELECT e.modules INTO v_entitled FROM public.org_entitlements e WHERE e.org_id = p_org;
  IF NOT FOUND THEN
    RETURN true;
  END IF;
  RETURN v_module = ANY (coalesce(v_entitled, '{}'));
END;
$fn$;
ALTER FUNCTION public.has_org_cap(uuid, text) OWNER TO postgres;
REVOKE ALL ON FUNCTION public.has_org_cap(uuid, text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.has_org_cap(uuid, text) TO authenticated, anon;

-- ── labelos_accept_invitation: 148 + owner invitations + seat cap ────────

CREATE OR REPLACE FUNCTION public.labelos_accept_invitation(p_token_hash text, p_user uuid)
RETURNS jsonb
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path = public
AS $fn$
DECLARE
  v_email     text;
  v_confirmed timestamptz;
  v_inv       public.org_invitations%ROWTYPE;
  v_rows      int;
  v_scope     text;
  v_scoped    uuid[] := '{}';
  v_renewed   boolean := false;
  v_max_seats int;
BEGIN
  IF p_token_hash IS NULL OR p_token_hash !~ '^[0-9a-f]{64}$' OR p_user IS NULL THEN
    RETURN jsonb_build_object('error', 'not_found');
  END IF;

  SELECT lower(btrim(u.email)), u.email_confirmed_at INTO v_email, v_confirmed
  FROM auth.users u WHERE u.id = p_user;
  IF v_email IS NULL OR v_email = '' THEN
    RETURN jsonb_build_object('error', 'email_mismatch');
  END IF;

  SELECT i.* INTO v_inv
  FROM public.org_invitations i
  JOIN public.organizations o ON o.id = i.org_id
  WHERE i.token_hash = p_token_hash
    AND o.deleted_at IS NULL
  FOR UPDATE OF i;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('error', 'not_found');
  END IF;

  IF v_inv.email <> v_email THEN
    RETURN jsonb_build_object('error', 'email_mismatch');
  END IF;
  IF v_confirmed IS NULL THEN
    RETURN jsonb_build_object('error', 'email_unverified');
  END IF;
  -- 170: an owner invitation exists only for the platform console's first
  -- owner of a licensee org, and is honoured only while its sender is still
  -- a platform operator. Any other owner invitation stays unsupported.
  IF v_inv.role = 'owner' AND (
       v_inv.project_id IS NOT NULL
       OR v_inv.invited_by IS NULL
       OR NOT EXISTS (SELECT 1 FROM public.platform_admins pa WHERE pa.user_id = v_inv.invited_by)
     ) THEN
    RETURN jsonb_build_object('error', 'unsupported');
  END IF;
  IF v_inv.revoked_at IS NOT NULL THEN
    RETURN jsonb_build_object('error', 'revoked');
  END IF;

  -- ── A project invitation: a project_members row, never org_members ────
  IF v_inv.project_id IS NOT NULL THEN
    IF v_inv.accepted_at IS NOT NULL THEN
      -- Only a LIVE membership is "already a member": someone whose access has
      -- expired and who clicks the spent link again is told it is used, not
      -- that they still have access.
      IF EXISTS (
        SELECT 1 FROM public.project_members
        WHERE project_id = v_inv.project_id AND user_id = p_user AND (expires_at IS NULL OR expires_at > now())
      ) THEN
        RETURN jsonb_build_object('status', 'already_member', 'org_id', v_inv.org_id, 'project_id', v_inv.project_id);
      END IF;
      RETURN jsonb_build_object('error', 'used');
    END IF;
    IF v_inv.expires_at <= now() THEN
      RETURN jsonb_build_object('error', 'expired');
    END IF;
    -- The inviter must still be able to share outside the org, and the
    -- project must still be a project of it.
    IF v_inv.invited_by IS NULL
       OR NOT public.labelos_user_has_cap(v_inv.org_id, v_inv.invited_by, 'share.external')
       OR NOT EXISTS (SELECT 1 FROM public.projects p WHERE p.id = v_inv.project_id AND p.org_id = v_inv.org_id) THEN
      RETURN jsonb_build_object('error', 'revoked');
    END IF;

    v_renewed := EXISTS (SELECT 1 FROM public.project_members WHERE project_id = v_inv.project_id AND user_id = p_user);
    -- A person who is already on the project keeps what they have (an
    -- invitation never changes a live membership), EXCEPT one whose access
    -- has EXPIRED: a new invitation is how the producer brings them back, so
    -- it renews the row with the invited role and downloads setting and
    -- clears the expiry. v_rows = 1 then, and the event says `renewed`.
    INSERT INTO public.project_members (org_id, project_id, user_id, role, allow_downloads, invited_by, invitation_id)
    VALUES (v_inv.org_id, v_inv.project_id, p_user, v_inv.project_role, v_inv.project_allow_downloads, v_inv.invited_by, v_inv.id)
    ON CONFLICT (project_id, user_id) DO UPDATE
      SET role = EXCLUDED.role,
          allow_downloads = EXCLUDED.allow_downloads,
          expires_at = NULL,
          invited_by = EXCLUDED.invited_by,
          invitation_id = EXCLUDED.invitation_id
      WHERE public.project_members.expires_at IS NOT NULL
        AND public.project_members.expires_at <= now();
    GET DIAGNOSTICS v_rows = ROW_COUNT;

    UPDATE public.org_invitations SET accepted_at = now() WHERE id = v_inv.id;

    IF v_rows = 0 THEN
      RETURN jsonb_build_object('status', 'already_member', 'org_id', v_inv.org_id, 'project_id', v_inv.project_id);
    END IF;

    PERFORM public.labelos_audit_insert_project(
      v_inv.org_id, p_user, 'project.member_added', 'member', p_user, v_inv.project_id,
      jsonb_build_object(
        'invitation_id', v_inv.id,
        'role', v_inv.project_role,
        'allow_downloads', v_inv.project_allow_downloads,
        'invited_by', v_inv.invited_by,
        'renewed', v_renewed
      )
    );
    RETURN jsonb_build_object('status', 'joined', 'org_id', v_inv.org_id, 'project_id', v_inv.project_id);
  END IF;

  -- ── An org invitation: 139's function, unchanged ──────────────────────
  IF v_inv.accepted_at IS NOT NULL THEN
    IF EXISTS (SELECT 1 FROM public.org_members WHERE org_id = v_inv.org_id AND user_id = p_user) THEN
      RETURN jsonb_build_object('status', 'already_member', 'org_id', v_inv.org_id);
    END IF;
    RETURN jsonb_build_object('error', 'used');
  END IF;
  IF v_inv.expires_at <= now() THEN
    RETURN jsonb_build_object('error', 'expired');
  END IF;
  -- An owner invitation's sender was checked above (a platform operator);
  -- every other invitation's sender must still run the org.
  IF v_inv.role <> 'owner' AND (v_inv.invited_by IS NULL OR NOT EXISTS (
    SELECT 1 FROM public.org_members m
    WHERE m.org_id = v_inv.org_id AND m.user_id = v_inv.invited_by AND m.role IN ('owner', 'admin')
  )) THEN
    RETURN jsonb_build_object('error', 'revoked');
  END IF;

  -- 170: the seat cap. A staff seat is a membership whose role is not
  -- `artist` (a roster artist's login is bounded by the artist cap, where the
  -- contact is added). Decided under a lock on the org's entitlement row, so
  -- two invitees accepting at once cannot both take the last seat. Someone who
  -- is already a member is not refused: the insert below answers already_member.
  IF v_inv.role <> 'artist' THEN
    SELECT e.max_seats INTO v_max_seats
    FROM public.org_entitlements e
    WHERE e.org_id = v_inv.org_id
    FOR UPDATE;
    IF v_max_seats IS NOT NULL
       AND NOT EXISTS (SELECT 1 FROM public.org_members WHERE org_id = v_inv.org_id AND user_id = p_user)
       AND (SELECT count(*) FROM public.org_members WHERE org_id = v_inv.org_id AND role <> 'artist') >= v_max_seats THEN
      RETURN jsonb_build_object('error', 'seat_limit');
    END IF;
  END IF;

  v_scope := CASE WHEN v_inv.role = 'artist' OR cardinality(v_inv.artist_ids) > 0 THEN 'artists' ELSE 'org' END;

  INSERT INTO public.org_members (org_id, user_id, role, functions, scope, invited_by)
  VALUES (
    v_inv.org_id,
    p_user,
    v_inv.role,
    CASE WHEN v_inv.role = 'member' THEN v_inv.functions ELSE '{}'::text[] END,
    v_scope,
    v_inv.invited_by
  )
  ON CONFLICT (org_id, user_id) DO NOTHING;
  GET DIAGNOSTICS v_rows = ROW_COUNT;

  UPDATE public.org_invitations SET accepted_at = now() WHERE id = v_inv.id;

  IF v_rows = 0 THEN
    RETURN jsonb_build_object('status', 'already_member', 'org_id', v_inv.org_id);
  END IF;

  IF v_scope = 'artists' AND cardinality(v_inv.artist_ids) > 0 THEN
    WITH written AS (
      INSERT INTO public.member_artist_scopes (org_id, user_id, contact_id)
      SELECT v_inv.org_id, p_user, c.id
      FROM public.contacts c
      WHERE c.id = ANY (v_inv.artist_ids)
        AND c.org_id = v_inv.org_id
      ON CONFLICT DO NOTHING
      RETURNING contact_id
    )
    SELECT coalesce(array_agg(contact_id ORDER BY contact_id), '{}') INTO v_scoped FROM written;
  END IF;

  INSERT INTO public.activity_events (org_id, actor_id, verb, subject_type, subject_id, payload, audit, visibility)
  VALUES (
    v_inv.org_id,
    p_user,
    'member.joined',
    'member',
    p_user,
    jsonb_build_object(
      'invitation_id', v_inv.id,
      'role', v_inv.role,
      'functions', to_jsonb(CASE WHEN v_inv.role = 'member' THEN v_inv.functions ELSE '{}'::text[] END),
      'contact_ids', to_jsonb(v_scoped),
      'invited_by', v_inv.invited_by
    ),
    true,
    'internal'
  );

  RETURN jsonb_build_object('status', 'joined', 'org_id', v_inv.org_id);
END;
$fn$;
ALTER FUNCTION public.labelos_accept_invitation(text, uuid) OWNER TO postgres;
REVOKE ALL ON FUNCTION public.labelos_accept_invitation(text, uuid) FROM PUBLIC;
REVOKE ALL ON FUNCTION public.labelos_accept_invitation(text, uuid) FROM anon, authenticated;
GRANT EXECUTE ON FUNCTION public.labelos_accept_invitation(text, uuid) TO service_role;

-- ── console writes ───────────────────────────────────────────────────────
-- Modules are passed already normalised by the route (known names, inside
-- the face's ceiling: lib/labelos/entitlements#normalizeModules); unknown
-- names would grant nothing anyway, since every reader intersects.

CREATE OR REPLACE FUNCTION public.labelos_platform_create_licensee(
  p_actor uuid,
  p_name text,
  p_slug text,
  p_kind text,
  p_modules text[],
  p_max_seats int,
  p_max_artists int,
  p_payload jsonb
) RETURNS jsonb
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path = public
AS $fn$
DECLARE
  v_org public.organizations%ROWTYPE;
BEGIN
  IF p_actor IS NULL OR NOT EXISTS (SELECT 1 FROM public.platform_admins WHERE user_id = p_actor) THEN
    RETURN jsonb_build_object('error', 'not_operator');
  END IF;
  IF p_kind IS NULL OR p_kind NOT IN ('artist', 'label') THEN
    RAISE EXCEPTION 'a licensee is an artist or a label org' USING ERRCODE = '22023';
  END IF;
  IF EXISTS (SELECT 1 FROM public.organizations WHERE slug = p_slug) THEN
    RETURN jsonb_build_object('error', 'slug_taken');
  END IF;

  -- created_by stays NULL: the operator is not a member, and 139's trigger
  -- would otherwise give an artist org's own artist contact the operator's email.
  BEGIN
    INSERT INTO public.organizations (name, slug, kind, created_by)
    VALUES (p_name, p_slug, p_kind, NULL)
    RETURNING * INTO v_org;
  EXCEPTION WHEN unique_violation THEN
    RETURN jsonb_build_object('error', 'slug_taken');
  END;

  INSERT INTO public.org_entitlements (org_id, modules, max_seats, max_artists, setup_done, granted_by, granted_at)
  VALUES (v_org.id, coalesce(p_modules, '{}'), p_max_seats, p_max_artists, false, p_actor, now());

  -- org.created is an everyday event (recordEvent's class), like every other org's.
  INSERT INTO public.activity_events (org_id, actor_id, verb, subject_type, subject_id, payload, audit, visibility)
  VALUES (v_org.id, p_actor, 'org.created', 'org', v_org.id,
          jsonb_build_object('source', 'platform', 'kind', v_org.kind), false, 'internal');
  PERFORM public.labelos_audit_insert(v_org.id, p_actor, 'org.entitlements_changed', 'org', v_org.id, p_payload);

  RETURN jsonb_build_object('org', jsonb_build_object(
    'id', v_org.id, 'name', v_org.name, 'slug', v_org.slug, 'kind', v_org.kind, 'created_at', v_org.created_at
  ));
END;
$fn$;

ALTER FUNCTION public.labelos_platform_create_licensee(uuid, text, text, text, text[], int, int, jsonb) OWNER TO postgres;
REVOKE ALL ON FUNCTION public.labelos_platform_create_licensee(uuid, text, text, text, text[], int, int, jsonb) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.labelos_platform_create_licensee(uuid, text, text, text, text[], int, int, jsonb) TO service_role;

-- Set an existing licensee's modules and caps. Writes the row if the org had
-- none (an org that predates its licence: setup_done = true, it is running).
-- Only live artist / label orgs: the producer's own org is not a licensee.
CREATE OR REPLACE FUNCTION public.labelos_platform_set_entitlements(
  p_actor uuid,
  p_org uuid,
  p_modules text[],
  p_max_seats int,
  p_max_artists int,
  p_payload jsonb
) RETURNS jsonb
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path = public
AS $fn$
DECLARE
  v_row public.org_entitlements%ROWTYPE;
BEGIN
  IF p_actor IS NULL OR NOT EXISTS (SELECT 1 FROM public.platform_admins WHERE user_id = p_actor) THEN
    RETURN jsonb_build_object('error', 'not_operator');
  END IF;
  PERFORM 1 FROM public.organizations o
  WHERE o.id = p_org AND o.kind IN ('artist', 'label') AND o.deleted_at IS NULL
  FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('error', 'not_found');
  END IF;

  INSERT INTO public.org_entitlements AS e (org_id, modules, max_seats, max_artists, setup_done, granted_by, granted_at)
  VALUES (p_org, coalesce(p_modules, '{}'), p_max_seats, p_max_artists, true, p_actor, now())
  ON CONFLICT (org_id) DO UPDATE
    SET modules = EXCLUDED.modules,
        max_seats = EXCLUDED.max_seats,
        max_artists = EXCLUDED.max_artists,
        granted_by = EXCLUDED.granted_by,
        granted_at = EXCLUDED.granted_at
  RETURNING * INTO v_row;

  PERFORM public.labelos_audit_insert(p_org, p_actor, 'org.entitlements_changed', 'org', p_org, p_payload);

  RETURN jsonb_build_object('entitlements', jsonb_build_object(
    'modules', to_jsonb(v_row.modules), 'max_seats', v_row.max_seats, 'max_artists', v_row.max_artists,
    'setup_done', v_row.setup_done, 'granted_at', v_row.granted_at
  ));
END;
$fn$;

ALTER FUNCTION public.labelos_platform_set_entitlements(uuid, uuid, text[], int, int, jsonb) OWNER TO postgres;
REVOKE ALL ON FUNCTION public.labelos_platform_set_entitlements(uuid, uuid, text[], int, int, jsonb) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.labelos_platform_set_entitlements(uuid, uuid, text[], int, int, jsonb) TO service_role;

NOTIFY pgrst, 'reload schema';


-- ═════════════ 171_labelos_departments_capabilities.sql ═════════════
-- 171_labelos_departments_capabilities.sql
-- Label OS (LABEL-49): departments and their capabilities.
--
-- LABEL OS — NOT APPLIED. Apply at the final merge of the Label OS branch
-- into main. Never part of supabase/apply/pending.sql.
--
-- Doc 22 §8 (5): finance, PR, the CEO ("executive"), artistic direction and
-- contracts exist on day one. This migration only teaches has_org_cap the new
-- vocabulary; the department pages are later tasks (LABEL-57 … LABEL-67).
--
--  * Functions: `pr`, `executive`, `artistic_director`, `contracts` are new;
--    `finance` (136, empty "not for now") gets a preset. Label orgs offer all
--    of them; an artist org (the independent face) also offers finance, pr
--    and contracts. The producer's own org is unchanged.
--  * Capabilities: finance.write, finance.approve, pr.read, pr.write,
--    exec.read, creative.read, creative.approve, contracts.write,
--    contracts.sign. The contracts department REUSES 136's contracts.read
--    (already checked by 143's restricted files, the legal queue and the legal
--    pack) instead of adding a second near-identical `contract.read`.
--  * Every one of them is owned by a module (step 6, 170): finance.* →
--    finance, pr.* → pr, exec.read → executive, creative.* → artistic,
--    contracts.* → contracts.
--  * Role `artist` (the roster artist) can hold none of them, nor 136's
--    finance.read: NEVER_GRANTABLE, so no override lifts it.
--  * 136's finance.read now implies catalog.read, like every other read of a
--    catalogue object, so revoking catalog.read still leaves nothing.
--  * `legal` also drafts contracts (contracts.write). No preset approves money
--    or signs for the org; that is the owner's / admin's, or one member's
--    switch.
--
-- The function is 170's word for word; only the constants between the
-- labelos:mapping markers changed. capabilities.sql.test.ts parses this, the
-- LATEST definition, and holds it equal to src/lib/labelos/capabilities.ts +
-- entitlements.ts; scripts/local-db/capability-parity.ts runs it in Postgres.
--
-- org_members.functions / cap_grants carry no CHECK on their values (136), so
-- no constraint changes. Idempotent: CREATE OR REPLACE.

-- ── has_org_cap(org, cap): 170 + LABEL-49 vocabulary ─────────────────────

CREATE OR REPLACE FUNCTION public.has_org_cap(p_org uuid, p_cap text)
RETURNS boolean
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = public
AS $fn$
DECLARE
  -- labelos:mapping:start
  all_capabilities constant text[] := ARRAY[
    'catalog.read', 'catalog.write', 'audio.finished', 'audio.working',
    'review.write', 'review.comment', 'rights.read', 'rights.read.own_line',
    'rights.write', 'contracts.read', 'release.write',
    'release.approve.master', 'release.approve.artwork',
    'release.approve.legal', 'release.approve.marketing',
    'release.approve.metadata', 'tasks.write', 'share.external',
    'members.manage', 'org.manage', 'finance.read', 'business.read.internal',
    'finance.write', 'finance.approve', 'pr.read', 'pr.write', 'exec.read',
    'creative.read', 'creative.approve', 'contracts.write', 'contracts.sign'
  ];
  org_kinds constant text[] := ARRAY['artist', 'producer', 'label'];
  roles_by_org_kind constant text[] := ARRAY[
    ['artist', 'owner'], ['artist', 'admin'], ['artist', 'member'],
    ['producer', 'owner'], ['producer', 'admin'], ['producer', 'member'],
    ['label', 'owner'], ['label', 'admin'], ['label', 'member'], ['label', 'artist']
  ];
  functions_by_org_kind constant text[] := ARRAY[
    ['artist', 'artist_manager'], ['artist', 'producer'],
    ['artist', 'engineer'], ['artist', 'marketing'], ['artist', 'legal'],
    ['artist', 'operations'], ['artist', 'finance'], ['artist', 'pr'],
    ['artist', 'contracts'], ['producer', 'producer'],
    ['producer', 'engineer'], ['producer', 'artist_manager'],
    ['producer', 'operations'], ['label', 'a_and_r'],
    ['label', 'project_manager'], ['label', 'marketing'], ['label', 'legal'],
    ['label', 'finance'], ['label', 'artist_manager'], ['label', 'producer'],
    ['label', 'engineer'], ['label', 'operations'], ['label', 'pr'],
    ['label', 'executive'], ['label', 'artistic_director'],
    ['label', 'contracts']
  ];
  -- KIND_CEILING: kinds whose ceiling is every capability. No kind has a
  -- partial ceiling in the MVP; the parity test fails if one appears.
  kinds_with_full_ceiling constant text[] := ARRAY['artist', 'producer', 'label'];
  -- ROLE_GRANTS: roles granted every capability, then the rest as pairs.
  roles_granted_everything constant text[] := ARRAY['owner', 'admin'];
  role_grants constant text[] := ARRAY[
    ['artist', 'catalog.write'], ['artist', 'audio.finished'],
    ['artist', 'audio.working'], ['artist', 'review.comment'],
    ['artist', 'rights.read']
  ];
  roles_using_functions constant text[] := ARRAY['member'];
  roles_taking_overrides constant text[] := ARRAY['member', 'artist'];
  function_presets constant text[] := ARRAY[
    ['a_and_r', 'catalog.write'], ['a_and_r', 'audio.finished'],
    ['a_and_r', 'audio.working'], ['a_and_r', 'review.write'],
    ['a_and_r', 'rights.read'], ['a_and_r', 'release.write'],
    ['a_and_r', 'release.approve.master'], ['a_and_r', 'share.external'],
    ['a_and_r', 'tasks.write'], ['project_manager', 'catalog.write'],
    ['project_manager', 'audio.finished'],
    ['project_manager', 'audio.working'], ['project_manager', 'review.write'],
    ['project_manager', 'rights.read'], ['project_manager', 'release.write'],
    ['project_manager', 'release.approve.metadata'],
    ['project_manager', 'share.external'],
    ['project_manager', 'business.read.internal'],
    ['project_manager', 'tasks.write'], ['marketing', 'catalog.read'],
    ['marketing', 'audio.finished'], ['marketing', 'release.approve.artwork'],
    ['marketing', 'release.approve.marketing'],
    ['marketing', 'business.read.internal'], ['marketing', 'tasks.write'],
    ['legal', 'catalog.read'], ['legal', 'audio.finished'],
    ['legal', 'rights.write'], ['legal', 'contracts.read'],
    ['legal', 'contracts.write'], ['legal', 'release.approve.legal'],
    ['legal', 'business.read.internal'], ['legal', 'tasks.write'],
    ['artist_manager', 'catalog.write'], ['artist_manager', 'audio.finished'],
    ['artist_manager', 'audio.working'], ['artist_manager', 'review.write'],
    ['artist_manager', 'rights.read'], ['artist_manager', 'tasks.write'],
    ['producer', 'catalog.write'], ['producer', 'audio.finished'],
    ['producer', 'audio.working'], ['producer', 'rights.read.own_line'],
    ['producer', 'tasks.write'], ['engineer', 'catalog.write'],
    ['engineer', 'audio.finished'], ['engineer', 'audio.working'],
    ['engineer', 'rights.read.own_line'], ['engineer', 'tasks.write'],
    ['finance', 'catalog.read'], ['finance', 'finance.write'],
    ['finance', 'business.read.internal'], ['finance', 'tasks.write'],
    ['pr', 'catalog.read'], ['pr', 'audio.finished'], ['pr', 'pr.write'],
    ['pr', 'business.read.internal'], ['pr', 'tasks.write'],
    ['executive', 'catalog.read'], ['executive', 'audio.finished'],
    ['executive', 'exec.read'], ['executive', 'rights.read'],
    ['executive', 'contracts.read'], ['executive', 'finance.read'],
    ['executive', 'pr.read'], ['executive', 'creative.read'],
    ['executive', 'business.read.internal'],
    ['artistic_director', 'catalog.write'],
    ['artistic_director', 'audio.finished'],
    ['artistic_director', 'audio.working'],
    ['artistic_director', 'review.write'],
    ['artistic_director', 'creative.approve'],
    ['artistic_director', 'tasks.write'], ['contracts', 'catalog.read'],
    ['contracts', 'rights.read'], ['contracts', 'contracts.write'],
    ['contracts', 'business.read.internal'], ['contracts', 'tasks.write']
  ];
  -- IMPLIES: [wider, narrower].
  implies constant text[] := ARRAY[
    ['catalog.write', 'catalog.read'], ['audio.finished', 'catalog.read'],
    ['audio.working', 'catalog.read'], ['review.comment', 'catalog.read'],
    ['rights.read.own_line', 'catalog.read'],
    ['contracts.read', 'catalog.read'], ['release.write', 'catalog.read'],
    ['release.approve.master', 'catalog.read'],
    ['release.approve.artwork', 'catalog.read'],
    ['release.approve.legal', 'catalog.read'],
    ['release.approve.marketing', 'catalog.read'],
    ['release.approve.metadata', 'catalog.read'],
    ['tasks.write', 'catalog.read'], ['share.external', 'catalog.read'],
    ['business.read.internal', 'catalog.read'],
    ['rights.write', 'rights.read'], ['rights.read', 'rights.read.own_line'],
    ['review.write', 'review.comment'], ['finance.read', 'catalog.read'],
    ['finance.write', 'finance.read'], ['finance.approve', 'finance.read'],
    ['pr.read', 'catalog.read'], ['pr.write', 'pr.read'],
    ['exec.read', 'catalog.read'], ['creative.read', 'catalog.read'],
    ['creative.approve', 'creative.read'],
    ['contracts.write', 'contracts.read'],
    ['contracts.sign', 'contracts.read']
  ];
  never_grantable constant text[] := ARRAY[
    ['member', 'members.manage'], ['member', 'org.manage'],
    ['artist', 'members.manage'], ['artist', 'org.manage'],
    ['artist', 'business.read.internal'], ['artist', 'contracts.read'],
    ['artist', 'contracts.write'], ['artist', 'contracts.sign'],
    ['artist', 'finance.read'], ['artist', 'finance.write'],
    ['artist', 'finance.approve'], ['artist', 'pr.read'],
    ['artist', 'pr.write'], ['artist', 'exec.read'],
    ['artist', 'creative.read'], ['artist', 'creative.approve']
  ];
  -- ENTITLEMENTS (170, LABEL-47; department capabilities added by 171,
  -- LABEL-49): src/lib/labelos/entitlements.ts + account.ts.
  -- CAPABILITY_MODULE: [capability, module]. A capability a module owns needs
  -- the module; every other capability is core and needs nothing.
  capability_modules constant text[] := ARRAY[
    ['contracts.read', 'contracts'], ['contracts.write', 'contracts'],
    ['contracts.sign', 'contracts'], ['finance.read', 'finance'],
    ['finance.write', 'finance'], ['finance.approve', 'finance'],
    ['pr.read', 'pr'], ['pr.write', 'pr'], ['exec.read', 'executive'],
    ['creative.read', 'artistic'], ['creative.approve', 'artistic']
  ];
  -- MODULES: the ceiling of an org kind with no face (the producer's own org).
  modules constant text[] := ARRAY[
    'contracts', 'finance', 'marketing', 'pr', 'executive', 'artistic',
    'store', 'search', 'digest', 'export'
  ];
  -- FACE_KIND, read as [kind, face].
  kind_faces constant text[] := ARRAY[
    ['artist', 'independent'], ['label', 'label']
  ];
  -- FACE_MODULES: [face, module].
  face_modules constant text[] := ARRAY[
    ['independent', 'contracts'], ['independent', 'finance'],
    ['independent', 'marketing'], ['independent', 'pr'],
    ['independent', 'executive'], ['independent', 'artistic'],
    ['independent', 'store'], ['independent', 'search'],
    ['independent', 'digest'], ['independent', 'export'],
    ['label', 'contracts'], ['label', 'finance'],
    ['label', 'marketing'], ['label', 'pr'],
    ['label', 'executive'], ['label', 'artistic'],
    ['label', 'store'], ['label', 'search'],
    ['label', 'digest'], ['label', 'export']
  ];
  -- labelos:mapping:end

  v_kind      text;
  v_role      text;
  v_functions text[];
  v_grants    text[];
  v_revokes   text[];
  granted     text[] := '{}';
  revoked     text[] := '{}';
  pair        text[];
  preset      text[];
  fn          text;
  ok          boolean;
  grown       boolean;
  v_module    text;
  v_face      text;
  v_entitled  text[];
BEGIN
  IF p_org IS NULL OR p_cap IS NULL OR NOT (p_cap = ANY (all_capabilities)) THEN
    RETURN false;
  END IF;

  SELECT o.kind, om.role, om.functions, om.cap_grants, om.cap_revokes
    INTO v_kind, v_role, v_functions, v_grants, v_revokes
  FROM public.org_members om
  JOIN public.organizations o ON o.id = om.org_id
  WHERE om.org_id = p_org
    AND om.user_id = auth.uid()
    AND o.deleted_at IS NULL;
  IF NOT FOUND OR NOT (v_kind = ANY (org_kinds)) THEN
    RETURN false;
  END IF;

  -- 1. The role must be one the org kind offers.
  ok := false;
  FOREACH pair SLICE 1 IN ARRAY roles_by_org_kind LOOP
    IF pair[1] = v_kind AND pair[2] = v_role THEN ok := true; END IF;
  END LOOP;
  IF NOT ok THEN RETURN false; END IF;

  -- 2. Role grants, function presets, per-member grants.
  IF v_role = ANY (roles_granted_everything) THEN
    granted := all_capabilities;
  ELSE
    FOREACH pair SLICE 1 IN ARRAY role_grants LOOP
      IF pair[1] = v_role THEN granted := granted || pair[2]; END IF;
    END LOOP;
  END IF;

  IF v_role = ANY (roles_using_functions) THEN
    FOREACH fn IN ARRAY coalesce(v_functions, '{}') LOOP
      FOREACH pair SLICE 1 IN ARRAY functions_by_org_kind LOOP
        IF pair[1] = v_kind AND pair[2] = fn THEN
          FOREACH preset SLICE 1 IN ARRAY function_presets LOOP
            IF preset[1] = fn THEN granted := granted || preset[2]; END IF;
          END LOOP;
        END IF;
      END LOOP;
    END LOOP;
  END IF;

  IF v_role = ANY (roles_taking_overrides) THEN
    granted := granted || ARRAY(
      SELECT c FROM unnest(coalesce(v_grants, '{}')) AS c WHERE c = ANY (all_capabilities)
    );
    revoked := ARRAY(
      SELECT c FROM unnest(coalesce(v_revokes, '{}')) AS c WHERE c = ANY (all_capabilities)
    );
    -- 3. Revoking a capability also revokes everything that needs it.
    LOOP
      grown := false;
      FOREACH pair SLICE 1 IN ARRAY implies LOOP
        IF pair[2] = ANY (revoked) AND NOT (pair[1] = ANY (revoked)) THEN
          revoked := revoked || pair[1];
          grown := true;
        END IF;
      END LOOP;
      EXIT WHEN NOT grown;
    END LOOP;
  END IF;

  -- 4. Close the grants under IMPLIES.
  LOOP
    grown := false;
    FOREACH pair SLICE 1 IN ARRAY implies LOOP
      IF pair[1] = ANY (granted) AND NOT (pair[2] = ANY (granted)) THEN
        granted := granted || pair[2];
        grown := true;
      END IF;
    END LOOP;
    EXIT WHEN NOT grown;
  END LOOP;

  -- 5. Granted, inside the ceiling, not a hard limit, not revoked.
  IF NOT (p_cap = ANY (granted)) OR NOT (v_kind = ANY (kinds_with_full_ceiling)) THEN
    RETURN false;
  END IF;
  FOREACH pair SLICE 1 IN ARRAY never_grantable LOOP
    IF pair[1] = v_role AND pair[2] = p_cap THEN RETURN false; END IF;
  END LOOP;
  IF p_cap = ANY (revoked) THEN
    RETURN false;
  END IF;

  -- 6. Entitlements (170): a capability a module owns needs the module. The
  --    module must be inside the face's ceiling, and, when the operator has
  --    written an org_entitlements row, in that row. No row = the ceiling.
  v_module := NULL;
  FOREACH pair SLICE 1 IN ARRAY capability_modules LOOP
    IF pair[1] = p_cap THEN v_module := pair[2]; END IF;
  END LOOP;
  IF v_module IS NULL THEN
    RETURN true;
  END IF;
  v_face := NULL;
  FOREACH pair SLICE 1 IN ARRAY kind_faces LOOP
    IF pair[1] = v_kind THEN v_face := pair[2]; END IF;
  END LOOP;
  ok := false;
  IF v_face IS NULL THEN
    ok := v_module = ANY (modules);
  ELSE
    FOREACH pair SLICE 1 IN ARRAY face_modules LOOP
      IF pair[1] = v_face AND pair[2] = v_module THEN ok := true; END IF;
    END LOOP;
  END IF;
  IF NOT ok THEN
    RETURN false;
  END IF;
  SELECT e.modules INTO v_entitled FROM public.org_entitlements e WHERE e.org_id = p_org;
  IF NOT FOUND THEN
    RETURN true;
  END IF;
  RETURN v_module = ANY (coalesce(v_entitled, '{}'));
END;
$fn$;
ALTER FUNCTION public.has_org_cap(uuid, text) OWNER TO postgres;
REVOKE ALL ON FUNCTION public.has_org_cap(uuid, text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.has_org_cap(uuid, text) TO authenticated, anon;

NOTIFY pgrst, 'reload schema';


-- ═════════════ 172_labelos_org_settings.sql ═════════════
-- 172_labelos_org_settings.sql (LABEL-51, doc 21 §2 item 3, §5.2 #5)
--
-- The organization settings screen's write: `organizations.settings` changes
-- WITH its audit event in one transaction.
--
--  * labelos_audit_org_settings(p_org, p_actor, p_patch, p_payload) —
--    SECURITY DEFINER, service_role EXECUTE only, like 146's functions. It
--    re-checks what the database can know for itself: the org is live and the
--    actor holds role `owner` in it (a capability does not stand in: owner-only
--    is a role, 06 §2.1). It merges `p_patch` into `settings` under a row lock
--    (a key not in the patch is left as it is) and records `org.settings_changed`
--    (an audit event, internal) in the same transaction, so if the event cannot
--    be written the change is not there.
--
--    The patch is validated here as well as in the route, so the function is
--    safe to call from anywhere: only the six owner-editable keys are accepted
--    (legal_gate / marketing_gate 'on'|'off', require_signed_master_split a
--    boolean, attention_release_days / attention_stalled_days whole days 1..365,
--    departments_off an array of known department names). Anything else raises
--    22023. The route checks that a department switched off is part of the
--    org's licence (org_entitlements); a department switch only narrows what the
--    licence grants, it never widens it.
--
--    Answers {"settings": <merged jsonb>} or {"error": "not_found" | "not_owner"}.
--
--  * labelos_org_asset_allowed (143) is REPLACED so that "Contracts & legal
--    off" also closes the one RLS path that reads a contracts-module object
--    on a member's own JWT: a restricted project file (contract / split sheet
--    kinds). Body identical to 143's except the sensitivity branch, which now
--    also needs `settings -> 'departments_off'` NOT to contain 'contracts'.
--    `has_org_cap` is deliberately NOT redefined here: the other RLS paths of
--    a switched-off department (e.g. finance.* tables when they land) will need
--    that change in their own migration.
--
-- No table, no policy, no column: `organizations.settings` exists since 136 and
-- its readers (release readiness, Needs attention) are total over it.
--
-- Idempotent: CREATE OR REPLACE.

CREATE OR REPLACE FUNCTION public.labelos_audit_org_settings(
  p_org uuid,
  p_actor uuid,
  p_patch jsonb,
  p_payload jsonb
) RETURNS jsonb
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path = public
AS $fn$
DECLARE
  v_key text;
  v_val jsonb;
  v_elem jsonb;
  v_modules constant text[] := ARRAY['contracts', 'finance', 'marketing', 'pr', 'executive', 'artistic', 'store', 'search', 'digest'];
  v_settings jsonb;
BEGIN
  IF p_patch IS NULL OR jsonb_typeof(p_patch) <> 'object' THEN
    RAISE EXCEPTION 'settings patch must be an object' USING ERRCODE = '22023';
  END IF;
  IF p_payload IS NULL OR jsonb_typeof(p_payload) <> 'object' THEN
    RAISE EXCEPTION 'audit payload must be an object' USING ERRCODE = '22023';
  END IF;

  FOR v_key, v_val IN SELECT key, value FROM jsonb_each(p_patch) LOOP
    IF v_key IN ('legal_gate', 'marketing_gate') THEN
      IF v_val NOT IN ('"on"'::jsonb, '"off"'::jsonb) THEN
        RAISE EXCEPTION '% must be "on" or "off"', v_key USING ERRCODE = '22023';
      END IF;
    ELSIF v_key = 'require_signed_master_split' THEN
      IF jsonb_typeof(v_val) <> 'boolean' THEN
        RAISE EXCEPTION '% must be a boolean', v_key USING ERRCODE = '22023';
      END IF;
    ELSIF v_key IN ('attention_release_days', 'attention_stalled_days') THEN
      IF jsonb_typeof(v_val) <> 'number' OR (v_val #>> '{}') !~ '^[0-9]{1,3}$'
         OR (v_val #>> '{}')::int NOT BETWEEN 1 AND 365 THEN
        RAISE EXCEPTION '% must be a whole number of days from 1 to 365', v_key USING ERRCODE = '22023';
      END IF;
    ELSIF v_key = 'departments_off' THEN
      IF jsonb_typeof(v_val) <> 'array' THEN
        RAISE EXCEPTION 'departments_off must be an array' USING ERRCODE = '22023';
      END IF;
      FOR v_elem IN SELECT value FROM jsonb_array_elements(v_val) LOOP
        IF jsonb_typeof(v_elem) <> 'string' OR NOT ((v_elem #>> '{}') = ANY (v_modules)) THEN
          RAISE EXCEPTION 'departments_off holds an unknown department' USING ERRCODE = '22023';
        END IF;
      END LOOP;
    ELSE
      RAISE EXCEPTION 'unknown setting %', v_key USING ERRCODE = '22023';
    END IF;
  END LOOP;

  SELECT o.settings INTO v_settings
  FROM public.organizations o
  WHERE o.id = p_org AND o.deleted_at IS NULL
  FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('error', 'not_found');
  END IF;
  IF p_actor IS NULL OR NOT EXISTS (
    SELECT 1 FROM public.org_members m WHERE m.org_id = p_org AND m.user_id = p_actor AND m.role = 'owner'
  ) THEN
    RETURN jsonb_build_object('error', 'not_owner');
  END IF;

  v_settings := coalesce(v_settings, '{}'::jsonb) || p_patch;
  UPDATE public.organizations SET settings = v_settings WHERE id = p_org;

  PERFORM public.labelos_audit_insert(p_org, p_actor, 'org.settings_changed', 'org', p_org, p_payload);

  RETURN jsonb_build_object('settings', v_settings);
END;
$fn$;

ALTER FUNCTION public.labelos_audit_org_settings(uuid, uuid, jsonb, jsonb) OWNER TO postgres;
REVOKE ALL ON FUNCTION public.labelos_audit_org_settings(uuid, uuid, jsonb, jsonb) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.labelos_audit_org_settings(uuid, uuid, jsonb, jsonb) TO service_role;

-- ── labelos_org_asset_allowed: Contracts off closes restricted files ─────

CREATE OR REPLACE FUNCTION public.labelos_org_asset_allowed(p_org uuid, p_kind text, p_sensitivity text)
RETURNS boolean
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_visual text[] := ARRAY['artwork', 'lyrics', 'photo', 'video'];
  v_legal text[] := ARRAY['contract', 'split_sheet'];
BEGIN
  IF p_org IS NULL OR NOT public.has_org_cap(p_org, 'catalog.read') THEN
    RETURN false;
  END IF;
  IF NOT (p_kind = ANY (v_visual) OR p_kind = ANY (v_legal))
     AND NOT public.has_org_cap(p_org, 'audio.working') THEN
    RETURN false;
  END IF;
  IF p_sensitivity IS DISTINCT FROM 'normal' AND NOT public.has_org_cap(p_org, 'contracts.read') THEN
    RETURN false;
  END IF;
  -- LABEL-51: the owner switched the Contracts & legal department off.
  IF p_sensitivity IS DISTINCT FROM 'normal' AND EXISTS (
    SELECT 1 FROM public.organizations o
    WHERE o.id = p_org
      AND jsonb_typeof(o.settings -> 'departments_off') = 'array'
      AND (o.settings -> 'departments_off') ? 'contracts'
  ) THEN
    RETURN false;
  END IF;
  RETURN true;
END;
$$;

ALTER FUNCTION public.labelos_org_asset_allowed(uuid, text, text) OWNER TO postgres;
REVOKE ALL ON FUNCTION public.labelos_org_asset_allowed(uuid, text, text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.labelos_org_asset_allowed(uuid, text, text) TO authenticated, anon;

NOTIFY pgrst, 'reload schema';


-- ═════════════ 173_labelos_track_metadata.sql ═════════════
-- 173_labelos_track_metadata.sql (LABEL-53, doc 22 §music business data)
--
-- The recording / song metadata editor's columns on `tracks`. Already there and
-- NOT added again: title, bpm, key, notes (001), isrc (141), iswc (140).
-- Missing, added here, all NULLABLE and for ORG rows only:
--
--   version_label    "Radio edit", "Instrumental" (a label, not a counter)
--   language         BCP-47-ish language code of the vocal, ASCII ("en", "pt-BR")
--   explicit         true | false | NULL (not stated)
--   genre            one primary genre, free text
--   recorded_on      the recording date
--   p_line           the ℗ line of the recording ("℗ 2026 Label")
--   master_owner     who owns the master recording
--   metadata_updated_at  compare-and-set token of the editor: bumped only by
--                    the editor's own writes (never by processing, stage moves
--                    or peaks), so a background job cannot make an edit 409.
--
-- A producer row (org_id IS NULL) must keep all of them NULL: the producer's
-- routes never name them, and `tracks_org_metadata_only` makes that a rule of
-- the database rather than of the routes.
--
-- Identifiers stay as 141 (`tracks_isrc_format`) and 140 (`tracks_iswc_format`)
-- left them, ASCII by their character classes; the editor additionally refuses
-- non-ASCII before it writes (lib/labelos/identifiers). No second constraint is
-- added on them: 140's check pins "exactly one iswc CHECK on tracks".
--
-- Idempotent: ADD COLUMN IF NOT EXISTS, DROP CONSTRAINT IF EXISTS first.

ALTER TABLE public.tracks ADD COLUMN IF NOT EXISTS version_label text;
ALTER TABLE public.tracks ADD COLUMN IF NOT EXISTS language text;
ALTER TABLE public.tracks ADD COLUMN IF NOT EXISTS explicit boolean;
ALTER TABLE public.tracks ADD COLUMN IF NOT EXISTS genre text;
ALTER TABLE public.tracks ADD COLUMN IF NOT EXISTS recorded_on date;
ALTER TABLE public.tracks ADD COLUMN IF NOT EXISTS p_line text;
ALTER TABLE public.tracks ADD COLUMN IF NOT EXISTS master_owner text;
ALTER TABLE public.tracks ADD COLUMN IF NOT EXISTS metadata_updated_at timestamptz;

ALTER TABLE public.tracks DROP CONSTRAINT IF EXISTS tracks_metadata_format;
ALTER TABLE public.tracks ADD CONSTRAINT tracks_metadata_format CHECK (
  (version_label IS NULL OR char_length(version_label) BETWEEN 1 AND 80)
  AND (genre IS NULL OR char_length(genre) BETWEEN 1 AND 80)
  AND (p_line IS NULL OR char_length(p_line) BETWEEN 1 AND 200)
  AND (master_owner IS NULL OR char_length(master_owner) BETWEEN 1 AND 200)
  AND (language IS NULL OR language ~ '^[a-z]{2,3}(-[A-Za-z0-9]{2,8})*$')
);

ALTER TABLE public.tracks DROP CONSTRAINT IF EXISTS tracks_org_metadata_only;
ALTER TABLE public.tracks ADD CONSTRAINT tracks_org_metadata_only CHECK (
  org_id IS NOT NULL
  OR (version_label IS NULL AND language IS NULL AND explicit IS NULL AND genre IS NULL
      AND recorded_on IS NULL AND p_line IS NULL AND master_owner IS NULL
      AND metadata_updated_at IS NULL)
);


NOTIFY pgrst, 'reload schema';


-- ═════════════ 189_labelos_setup_org.sql ═════════════
-- 189_labelos_setup_org.sql
-- Label OS (LABEL-48, first slice): self-service organization setup.
--
-- LABEL OS — NOT APPLIED. Apply at the final merge of the Label OS branch
-- into main, after 136–169 (docs/bstudio-label-os/16-execution-runbook.md).
-- Numbered 189 because 162–188 are reserved for the phase 2 tasks (doc 23).
--
-- A new account that is neither the producer nor a member of anything used
-- to land on the buyer account page with no way to an organization. /setup
-- now asks what it is and calls this function through POST /api/org/setup
-- (src/lib/labelos/setup.ts):
--   - 'artist' (the "independent artist / producer" face): the org and the
--     caller as owner. Its one roster artist (named after the org, with the
--     caller's email) is made by 139's AFTER INSERT trigger
--     `labelos_artist_org_self_contact`, inside the same insert (D1);
--   - 'label': the org and the caller as owner.
-- All of it in this one transaction, so a failure leaves nothing half-made.
--
-- One self-served org per account: a caller who already CREATED a live
-- artist or label org gets that org back ({"created": false}), so a double
-- click or a retried request never makes two. The `producer` kind is never
-- self-served (migration 137 owns it). A per-user advisory lock serialises
-- concurrent calls.
--
-- Only service_role may execute it; the route authenticates the session and
-- passes the caller's own id. Like 137, it runs as postgres, so 136's
-- column grants and the absence of an org_members INSERT policy do not apply.
-- The `org.created` activity event is written by the route (recordEvent).
--
-- Idempotent: CREATE OR REPLACE. No table is created or altered.

CREATE OR REPLACE FUNCTION public.labelos_setup_org(
  p_user  uuid,
  p_kind  text,
  p_name  text
)
RETURNS jsonb
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path = public
AS $fn$
DECLARE
  v_name  text := btrim(regexp_replace(coalesce(p_name, ''), '\s+', ' ', 'g'));
  v_org   uuid;
  v_slug  text;
  v_kind  text;
  v_base  text;
  v_try   int := 1;
BEGIN
  IF p_user IS NULL THEN
    RAISE EXCEPTION 'labelos_setup_org: user required' USING ERRCODE = '22023';
  END IF;
  IF p_kind IS NULL OR p_kind NOT IN ('artist', 'label') THEN
    RAISE EXCEPTION 'labelos_setup_org: kind must be artist or label' USING ERRCODE = '22023';
  END IF;
  IF v_name = '' OR length(v_name) > 80 THEN
    RAISE EXCEPTION 'labelos_setup_org: name must be 1 to 80 characters' USING ERRCODE = '22023';
  END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended('labelos.setup_org:' || p_user::text, 0));

  -- Already set up: answer the org this account created.
  SELECT o.id, o.slug, o.kind INTO v_org, v_slug, v_kind
  FROM public.organizations o
  WHERE o.created_by = p_user
    AND o.kind IN ('artist', 'label')
    AND o.deleted_at IS NULL
  ORDER BY o.created_at, o.id
  LIMIT 1;
  IF FOUND THEN
    RETURN jsonb_build_object('org_id', v_org, 'slug', v_slug, 'kind', v_kind, 'created', false);
  END IF;

  v_base := coalesce(nullif(public.labelos_slugify(v_name), ''), CASE WHEN p_kind = 'label' THEN 'label' ELSE 'artist' END);

  -- organizations.slug is unique across every org (same loop as 137).
  LOOP
    v_slug := CASE WHEN v_try = 1 THEN v_base ELSE left(v_base, 35) || '-' || v_try END;
    IF NOT EXISTS (SELECT 1 FROM public.organizations WHERE slug = v_slug) THEN
      BEGIN
        INSERT INTO public.organizations (name, slug, kind, created_by)
        VALUES (v_name, v_slug, p_kind, p_user)
        RETURNING id INTO v_org;
        EXIT;
      EXCEPTION WHEN unique_violation THEN
        NULL; -- taken meanwhile: next candidate
      END;
    END IF;
    v_try := v_try + 1;
    IF v_try > 1000 THEN
      RAISE EXCEPTION 'no free organization slug for base %', v_base;
    END IF;
  END LOOP;

  INSERT INTO public.org_members (org_id, user_id, role, scope)
  VALUES (v_org, p_user, 'owner', 'org');

  RETURN jsonb_build_object('org_id', v_org, 'slug', v_slug, 'kind', p_kind, 'created', true);
END;
$fn$;

ALTER FUNCTION public.labelos_setup_org(uuid, text, text) OWNER TO postgres;
REVOKE ALL ON FUNCTION public.labelos_setup_org(uuid, text, text) FROM PUBLIC;
REVOKE ALL ON FUNCTION public.labelos_setup_org(uuid, text, text) FROM anon, authenticated;
GRANT EXECUTE ON FUNCTION public.labelos_setup_org(uuid, text, text) TO service_role;

NOTIFY pgrst, 'reload schema';


-- ═════════════ 190_labelos_team_accounts.sql ═════════════
-- 190_labelos_team_accounts.sql
-- Label OS: team accounts an organization creates for its people
-- (docs/bstudio-label-os/25-team-accounts.md, phase 1).
--
-- LABEL OS — NOT APPLIED. Apply at the final merge of the Label OS branch
-- into main, after 170 and 189. Never part of supabase/apply/pending.sql.
-- Numbered 190: 171–188 are doc 23's phase-2 reservations, 189 is /setup.
--
-- An owner or admin (`members.manage`) creates a login for a person — the
-- auth user is made by the route with the Supabase admin API, email
-- confirmed, with a password the creator chose — and this migration records
-- that the ORG made it:
--
--  * org_managed_accounts(org_id, user_id, …) — one row per account an org
--    created. UNIQUE (user_id): an account is managed by exactly one org.
--    `must_change_password` sends the person to /account/password until they
--    set their own; `disabled_at` mirrors the auth ban the route sets.
--    Service-role only (no policy); nobody but the functions below writes.
--  * labelos_audit_team_account_create — the membership (role, functions,
--    scope, artist list), the managed row and `member.account_created` in one
--    transaction, seat cap under the lock 170 uses for invitations.
--  * labelos_team_account_target — may THIS org reset / switch off THIS
--    account? Only one it created, that is in nothing else: no other org,
--    no shared project, not the producer, not a platform operator, never the
--    actor themselves, and an owner or an admin only by an owner (peer admins
--    cannot reset each other and sign in as each other). The route asks it
--    before touching the auth user, so an org can never take over somebody's
--    own account. (The setup and join routes refuse a managed account, so it
--    cannot become "in something else" and slip out of its org's control.)
--  * labelos_audit_team_account_reset / _set_disabled — the flag change and
--    its audit event (`member.password_reset`, `member.account_disabled` /
--    `member.account_enabled`), re-checking the same rule under a row lock,
--    and revoking every session the person has (`labelos_revoke_auth_sessions`)
--    in the same transaction, so a reset or a switch-off ends their sign-ins.
--  * labelos_team_account_password_changed — the person's own change clears
--    the flag and revokes their OTHER sessions (the current one is kept; the
--    route records `member.password_changed`).
--  * labelos_revoke_auth_sessions — deletes auth.sessions rows (refresh tokens
--    go with them, and Supabase refuses an access token whose session is
--    gone). If this database does not let it (no table, no privilege) it
--    warns and answers false instead of failing the act; the route logs that.
--  * labelos_my_password_pending — the ONE function the API roles may call:
--    does the CALLER (auth.uid()) still have to choose their own password?
--    It answers about the caller only, so the proxy can refuse every other
--    Label OS request on the caller's own session.
--
-- No password, hash or temporary value is ever written here or to an event.
-- All functions: SECURITY DEFINER, owner postgres, service_role EXECUTE only,
-- except labelos_my_password_pending (authenticated, about oneself).
-- Idempotent: IF NOT EXISTS, CREATE OR REPLACE, DROP POLICY IF EXISTS.

CREATE TABLE IF NOT EXISTS public.org_managed_accounts (
  org_id               uuid NOT NULL REFERENCES public.organizations(id) ON DELETE CASCADE,
  user_id              uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  created_by           uuid REFERENCES auth.users(id) ON DELETE SET NULL,
  created_at           timestamptz NOT NULL DEFAULT now(),
  must_change_password boolean NOT NULL DEFAULT true,
  password_changed_at  timestamptz,
  password_reset_at    timestamptz,
  disabled_at          timestamptz,
  PRIMARY KEY (org_id, user_id),
  CONSTRAINT org_managed_accounts_one_org UNIQUE (user_id)
);

-- Service-role only, like 160's digest tables: RLS on, NO policy, no grant to
-- anon or authenticated. Every read is a server route or page (the members
-- list for managers, the person's own row for the password page).
ALTER TABLE public.org_managed_accounts ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.org_managed_accounts FROM PUBLIC, anon, authenticated, service_role;
GRANT SELECT ON public.org_managed_accounts TO service_role;
-- An earlier draft of 190 had a self-read policy; a replay drops it.
DROP POLICY IF EXISTS org_managed_accounts_self_read ON public.org_managed_accounts;

-- ── create ───────────────────────────────────────────────────────────────
-- Returns {"ok": true} or {"error": "seat_limit" | "already_member" | "bad_role"}.

CREATE OR REPLACE FUNCTION public.labelos_audit_team_account_create(
  p_org        uuid,
  p_actor      uuid,
  p_user       uuid,
  p_role       text,
  p_functions  text[],
  p_artist_ids uuid[],
  p_payload    jsonb
) RETURNS jsonb
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path = public
AS $fn$
DECLARE
  v_max_seats int;
  v_scope     text;
BEGIN
  IF p_role IS NULL OR p_role NOT IN ('admin', 'member', 'artist') THEN
    RETURN jsonb_build_object('error', 'bad_role');
  END IF;
  IF EXISTS (SELECT 1 FROM public.org_members WHERE org_id = p_org AND user_id = p_user) THEN
    RETURN jsonb_build_object('error', 'already_member');
  END IF;

  -- 170's seat cap, under the same lock as an invitation being accepted.
  IF p_role <> 'artist' THEN
    SELECT e.max_seats INTO v_max_seats
    FROM public.org_entitlements e
    WHERE e.org_id = p_org
    FOR UPDATE;
    IF v_max_seats IS NOT NULL
       AND (SELECT count(*) FROM public.org_members WHERE org_id = p_org AND role <> 'artist') >= v_max_seats THEN
      RETURN jsonb_build_object('error', 'seat_limit');
    END IF;
  END IF;

  v_scope := CASE WHEN p_role = 'artist' OR cardinality(coalesce(p_artist_ids, '{}')) > 0 THEN 'artists' ELSE 'org' END;

  INSERT INTO public.org_members (org_id, user_id, role, functions, scope, invited_by)
  VALUES (p_org, p_user, p_role, coalesce(p_functions, '{}'), v_scope, p_actor);

  IF cardinality(coalesce(p_artist_ids, '{}')) > 0 THEN
    INSERT INTO public.member_artist_scopes (org_id, user_id, contact_id)
    SELECT p_org, p_user, c.id
    FROM public.contacts c
    WHERE c.id = ANY (p_artist_ids) AND c.org_id = p_org;
  END IF;

  INSERT INTO public.org_managed_accounts (org_id, user_id, created_by)
  VALUES (p_org, p_user, p_actor);

  PERFORM public.labelos_audit_insert(p_org, p_actor, 'member.account_created', 'member', p_user, coalesce(p_payload, '{}'::jsonb));
  RETURN jsonb_build_object('ok', true);
END;
$fn$;

-- ── who may be reset / switched off ──────────────────────────────────────
-- NULL = allowed; otherwise the reason (the route answers 404 / 403 / 409).

CREATE OR REPLACE FUNCTION public.labelos_team_account_target(
  p_org   uuid,
  p_actor uuid,
  p_user  uuid
) RETURNS text
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = public
AS $fn$
DECLARE
  v_role       text;
  v_actor_role text;
BEGIN
  IF p_user = p_actor THEN
    RETURN 'self';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.org_managed_accounts WHERE org_id = p_org AND user_id = p_user) THEN
    RETURN 'not_managed';
  END IF;
  SELECT role INTO v_role FROM public.org_members WHERE org_id = p_org AND user_id = p_user;
  IF NOT FOUND THEN
    RETURN 'not_member';
  END IF;
  SELECT role INTO v_actor_role FROM public.org_members WHERE org_id = p_org AND user_id = p_actor;
  -- An owner or an admin only by an owner: otherwise two admins could reset
  -- each other and sign in as each other.
  IF v_role IN ('owner', 'admin') AND v_actor_role IS DISTINCT FROM 'owner' THEN
    RETURN 'owner_only';
  END IF;
  IF EXISTS (SELECT 1 FROM public.org_members WHERE user_id = p_user AND org_id <> p_org)
     OR EXISTS (SELECT 1 FROM public.project_members WHERE user_id = p_user)
     OR EXISTS (SELECT 1 FROM public.creator_profiles WHERE user_id = p_user)
     OR EXISTS (SELECT 1 FROM public.platform_admins WHERE user_id = p_user) THEN
    RETURN 'shared';
  END IF;
  RETURN NULL;
END;
$fn$;

-- ── session revocation ───────────────────────────────────────────────────
-- Every session of p_user except p_keep (the caller's current one, on their
-- own change). True when done; false, with a warning, when this database does
-- not let it, so a reset or switch-off never fails for want of it.

CREATE OR REPLACE FUNCTION public.labelos_revoke_auth_sessions(p_user uuid, p_keep uuid DEFAULT NULL)
RETURNS boolean
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path = public
AS $fn$
BEGIN
  DELETE FROM auth.sessions WHERE user_id = p_user AND (p_keep IS NULL OR id <> p_keep);
  RETURN true;
EXCEPTION WHEN undefined_table OR insufficient_privilege THEN
  RAISE WARNING 'labelos_revoke_auth_sessions: sessions not revoked: %', SQLERRM;
  RETURN false;
END;
$fn$;

-- ── reset ────────────────────────────────────────────────────────────────

CREATE OR REPLACE FUNCTION public.labelos_audit_team_account_reset(
  p_org   uuid,
  p_actor uuid,
  p_user  uuid
) RETURNS jsonb
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path = public
AS $fn$
DECLARE
  v_reason text;
BEGIN
  PERFORM 1 FROM public.org_managed_accounts WHERE org_id = p_org AND user_id = p_user FOR UPDATE;
  v_reason := public.labelos_team_account_target(p_org, p_actor, p_user);
  IF v_reason IS NOT NULL THEN
    RETURN jsonb_build_object('error', v_reason);
  END IF;
  UPDATE public.org_managed_accounts
  SET must_change_password = true, password_reset_at = now()
  WHERE org_id = p_org AND user_id = p_user;
  PERFORM public.labelos_audit_insert(p_org, p_actor, 'member.password_reset', 'member', p_user, '{}'::jsonb);
  RETURN jsonb_build_object('ok', true, 'sessions_revoked', public.labelos_revoke_auth_sessions(p_user));
END;
$fn$;

-- ── switch off / on ──────────────────────────────────────────────────────

CREATE OR REPLACE FUNCTION public.labelos_audit_team_account_set_disabled(
  p_org      uuid,
  p_actor    uuid,
  p_user     uuid,
  p_disabled boolean
) RETURNS jsonb
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path = public
AS $fn$
DECLARE
  v_reason text;
BEGIN
  PERFORM 1 FROM public.org_managed_accounts WHERE org_id = p_org AND user_id = p_user FOR UPDATE;
  v_reason := public.labelos_team_account_target(p_org, p_actor, p_user);
  IF v_reason IS NOT NULL THEN
    RETURN jsonb_build_object('error', v_reason);
  END IF;
  UPDATE public.org_managed_accounts
  SET disabled_at = CASE WHEN p_disabled THEN now() ELSE NULL END
  WHERE org_id = p_org AND user_id = p_user;
  PERFORM public.labelos_audit_insert(
    p_org, p_actor,
    CASE WHEN p_disabled THEN 'member.account_disabled' ELSE 'member.account_enabled' END,
    'member', p_user, '{}'::jsonb);
  -- Switching off ends every sign-in; switching back on has nothing to end.
  RETURN jsonb_build_object('ok', true, 'sessions_revoked',
    CASE WHEN p_disabled THEN public.labelos_revoke_auth_sessions(p_user) ELSE true END);
END;
$fn$;

-- ── the person's own change ──────────────────────────────────────────────
-- Returns the org id of their managed row, or NULL when they have none, and
-- revokes their other sessions (p_keep_session = the one they changed it from).
-- An earlier draft took (p_user) only; a replay drops that signature.

DROP FUNCTION IF EXISTS public.labelos_team_account_password_changed(uuid);

CREATE OR REPLACE FUNCTION public.labelos_team_account_password_changed(p_user uuid, p_keep_session uuid DEFAULT NULL)
RETURNS uuid
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path = public
AS $fn$
DECLARE
  v_org uuid;
BEGIN
  UPDATE public.org_managed_accounts
  SET must_change_password = false, password_changed_at = now()
  WHERE user_id = p_user
  RETURNING org_id INTO v_org;
  IF v_org IS NOT NULL THEN
    PERFORM public.labelos_revoke_auth_sessions(p_user, p_keep_session);
  END IF;
  RETURN v_org;
END;
$fn$;

-- ── the caller's own pending change ──────────────────────────────────────
-- For src/proxy.ts on the caller's session: may answer only about auth.uid().

CREATE OR REPLACE FUNCTION public.labelos_my_password_pending()
RETURNS boolean
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public
AS $fn$
  SELECT EXISTS (
    SELECT 1 FROM public.org_managed_accounts
    WHERE user_id = auth.uid() AND must_change_password AND disabled_at IS NULL
  );
$fn$;

ALTER FUNCTION public.labelos_audit_team_account_create(uuid, uuid, uuid, text, text[], uuid[], jsonb) OWNER TO postgres;
REVOKE ALL ON FUNCTION public.labelos_audit_team_account_create(uuid, uuid, uuid, text, text[], uuid[], jsonb) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.labelos_audit_team_account_create(uuid, uuid, uuid, text, text[], uuid[], jsonb) TO service_role;

ALTER FUNCTION public.labelos_team_account_target(uuid, uuid, uuid) OWNER TO postgres;
REVOKE ALL ON FUNCTION public.labelos_team_account_target(uuid, uuid, uuid) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.labelos_team_account_target(uuid, uuid, uuid) TO service_role;

ALTER FUNCTION public.labelos_audit_team_account_reset(uuid, uuid, uuid) OWNER TO postgres;
REVOKE ALL ON FUNCTION public.labelos_audit_team_account_reset(uuid, uuid, uuid) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.labelos_audit_team_account_reset(uuid, uuid, uuid) TO service_role;

ALTER FUNCTION public.labelos_audit_team_account_set_disabled(uuid, uuid, uuid, boolean) OWNER TO postgres;
REVOKE ALL ON FUNCTION public.labelos_audit_team_account_set_disabled(uuid, uuid, uuid, boolean) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.labelos_audit_team_account_set_disabled(uuid, uuid, uuid, boolean) TO service_role;

ALTER FUNCTION public.labelos_team_account_password_changed(uuid, uuid) OWNER TO postgres;
REVOKE ALL ON FUNCTION public.labelos_team_account_password_changed(uuid, uuid) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.labelos_team_account_password_changed(uuid, uuid) TO service_role;

ALTER FUNCTION public.labelos_revoke_auth_sessions(uuid, uuid) OWNER TO postgres;
REVOKE ALL ON FUNCTION public.labelos_revoke_auth_sessions(uuid, uuid) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.labelos_revoke_auth_sessions(uuid, uuid) TO service_role;

ALTER FUNCTION public.labelos_my_password_pending() OWNER TO postgres;
REVOKE ALL ON FUNCTION public.labelos_my_password_pending() FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.labelos_my_password_pending() TO authenticated, service_role;

NOTIFY pgrst, 'reload schema';


-- ═════════════ 192_labelos_setup_wizard.sql ═════════════
-- 192_labelos_setup_wizard.sql
-- Label OS (LABEL-48): the setup wizard creates the organization WITH its
-- settings in one transaction.
--
-- LABEL OS — NOT APPLIED. Apply at the final merge of the Label OS branch
-- into main, after 189 (docs/bstudio-label-os/16-execution-runbook.md).
-- Numbered 192: 191 is PR #135's, 173–187 belong to other tasks.
--
-- The wizard (/setup) keeps its state in the browser and creates nothing
-- until its last step. That step is ONE call: POST /api/org/setup now carries
-- the choices it collected (gates, departments off, contract types) and
-- `labelos_setup_org` stores them with the organization row, so a setup never
-- leaves an org with the defaults it was meant to replace. Roster artists,
-- invitations, team logins and the first draft release reuse their own routes
-- afterwards; none of their rules is copied here.
--
--  * labelos_validate_org_settings_patch(p_patch) — the ONE copy of the
--    rules for the owner-editable keys of `organizations.settings`, taken out
--    of 172's `labelos_audit_org_settings` so the settings screen and the
--    setup call it cannot disagree. Same rules as 172 plus the new key
--    `contract_types` (LABEL-48: an array of known contract type ids; only the
--    choice is stored, templates are LABEL-57). Raises 22023.
--  * labelos_audit_org_settings is replaced: identical to 172 except that it
--    calls the validator instead of carrying the rules inline.
--  * labelos_setup_org(p_user, p_kind, p_name, p_settings) replaces 189's
--    three-argument function (dropped first so a call is never ambiguous):
--    same behaviour, and the validated settings are written on the INSERT.
--    A caller that already has a self-served org still gets it back
--    ({"created": false}); the settings are ignored then, they are not an
--    edit. `p_settings` defaults to '{}', so the old call shape keeps working.
--
-- No table, no policy, no column. Only service_role executes any of it.
--
-- Idempotent: CREATE OR REPLACE / DROP IF EXISTS.

CREATE OR REPLACE FUNCTION public.labelos_validate_org_settings_patch(p_patch jsonb)
RETURNS void
LANGUAGE plpgsql
IMMUTABLE
SET search_path = public
AS $fn$
DECLARE
  v_key text;
  v_val jsonb;
  v_elem jsonb;
  v_modules constant text[] := ARRAY['contracts', 'finance', 'marketing', 'pr', 'executive', 'artistic', 'store', 'search', 'digest'];
  v_contract_types constant text[] := ARRAY['recording', 'distribution', 'licence', 'deal_360', 'producer', 'feature', 'co_publishing', 'management'];
BEGIN
  IF p_patch IS NULL OR jsonb_typeof(p_patch) <> 'object' THEN
    RAISE EXCEPTION 'settings patch must be an object' USING ERRCODE = '22023';
  END IF;

  FOR v_key, v_val IN SELECT key, value FROM jsonb_each(p_patch) LOOP
    IF v_key IN ('legal_gate', 'marketing_gate') THEN
      IF v_val NOT IN ('"on"'::jsonb, '"off"'::jsonb) THEN
        RAISE EXCEPTION '% must be "on" or "off"', v_key USING ERRCODE = '22023';
      END IF;
    ELSIF v_key = 'require_signed_master_split' THEN
      IF jsonb_typeof(v_val) <> 'boolean' THEN
        RAISE EXCEPTION '% must be a boolean', v_key USING ERRCODE = '22023';
      END IF;
    ELSIF v_key IN ('attention_release_days', 'attention_stalled_days') THEN
      IF jsonb_typeof(v_val) <> 'number' OR (v_val #>> '{}') !~ '^[0-9]{1,3}$'
         OR (v_val #>> '{}')::int NOT BETWEEN 1 AND 365 THEN
        RAISE EXCEPTION '% must be a whole number of days from 1 to 365', v_key USING ERRCODE = '22023';
      END IF;
    ELSIF v_key = 'departments_off' THEN
      IF jsonb_typeof(v_val) <> 'array' THEN
        RAISE EXCEPTION 'departments_off must be an array' USING ERRCODE = '22023';
      END IF;
      FOR v_elem IN SELECT value FROM jsonb_array_elements(v_val) LOOP
        IF jsonb_typeof(v_elem) <> 'string' OR NOT ((v_elem #>> '{}') = ANY (v_modules)) THEN
          RAISE EXCEPTION 'departments_off holds an unknown department' USING ERRCODE = '22023';
        END IF;
      END LOOP;
    ELSIF v_key = 'contract_types' THEN
      IF jsonb_typeof(v_val) <> 'array' THEN
        RAISE EXCEPTION 'contract_types must be an array' USING ERRCODE = '22023';
      END IF;
      FOR v_elem IN SELECT value FROM jsonb_array_elements(v_val) LOOP
        IF jsonb_typeof(v_elem) <> 'string' OR NOT ((v_elem #>> '{}') = ANY (v_contract_types)) THEN
          RAISE EXCEPTION 'contract_types holds an unknown contract type' USING ERRCODE = '22023';
        END IF;
      END LOOP;
    ELSE
      RAISE EXCEPTION 'unknown setting %', v_key USING ERRCODE = '22023';
    END IF;
  END LOOP;
END;
$fn$;

ALTER FUNCTION public.labelos_validate_org_settings_patch(jsonb) OWNER TO postgres;
REVOKE ALL ON FUNCTION public.labelos_validate_org_settings_patch(jsonb) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.labelos_validate_org_settings_patch(jsonb) TO service_role;

-- ── 172's audit function, now calling the shared validator ───────────────

CREATE OR REPLACE FUNCTION public.labelos_audit_org_settings(
  p_org uuid,
  p_actor uuid,
  p_patch jsonb,
  p_payload jsonb
) RETURNS jsonb
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path = public
AS $fn$
DECLARE
  v_settings jsonb;
BEGIN
  PERFORM public.labelos_validate_org_settings_patch(p_patch);
  IF p_payload IS NULL OR jsonb_typeof(p_payload) <> 'object' THEN
    RAISE EXCEPTION 'audit payload must be an object' USING ERRCODE = '22023';
  END IF;

  SELECT o.settings INTO v_settings
  FROM public.organizations o
  WHERE o.id = p_org AND o.deleted_at IS NULL
  FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('error', 'not_found');
  END IF;
  IF p_actor IS NULL OR NOT EXISTS (
    SELECT 1 FROM public.org_members m WHERE m.org_id = p_org AND m.user_id = p_actor AND m.role = 'owner'
  ) THEN
    RETURN jsonb_build_object('error', 'not_owner');
  END IF;

  v_settings := coalesce(v_settings, '{}'::jsonb) || p_patch;
  UPDATE public.organizations SET settings = v_settings WHERE id = p_org;

  PERFORM public.labelos_audit_insert(p_org, p_actor, 'org.settings_changed', 'org', p_org, p_payload);

  RETURN jsonb_build_object('settings', v_settings);
END;
$fn$;

ALTER FUNCTION public.labelos_audit_org_settings(uuid, uuid, jsonb, jsonb) OWNER TO postgres;
REVOKE ALL ON FUNCTION public.labelos_audit_org_settings(uuid, uuid, jsonb, jsonb) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.labelos_audit_org_settings(uuid, uuid, jsonb, jsonb) TO service_role;

-- ── 189's setup function, with the wizard's settings ────────────────────

DROP FUNCTION IF EXISTS public.labelos_setup_org(uuid, text, text);

CREATE OR REPLACE FUNCTION public.labelos_setup_org(
  p_user     uuid,
  p_kind     text,
  p_name     text,
  p_settings jsonb DEFAULT '{}'::jsonb
)
RETURNS jsonb
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path = public
AS $fn$
DECLARE
  v_name     text := btrim(regexp_replace(coalesce(p_name, ''), '\s+', ' ', 'g'));
  v_settings jsonb := coalesce(p_settings, '{}'::jsonb);
  v_org      uuid;
  v_slug     text;
  v_kind     text;
  v_base     text;
  v_try      int := 1;
BEGIN
  IF p_user IS NULL THEN
    RAISE EXCEPTION 'labelos_setup_org: user required' USING ERRCODE = '22023';
  END IF;
  IF p_kind IS NULL OR p_kind NOT IN ('artist', 'label') THEN
    RAISE EXCEPTION 'labelos_setup_org: kind must be artist or label' USING ERRCODE = '22023';
  END IF;
  IF v_name = '' OR length(v_name) > 80 THEN
    RAISE EXCEPTION 'labelos_setup_org: name must be 1 to 80 characters' USING ERRCODE = '22023';
  END IF;
  -- Before the lock and before anything is written: a bad value is a refusal, not a half-made org.
  PERFORM public.labelos_validate_org_settings_patch(v_settings);

  PERFORM pg_advisory_xact_lock(hashtextextended('labelos.setup_org:' || p_user::text, 0));

  -- Already set up: answer the org this account created. Settings are not an edit.
  SELECT o.id, o.slug, o.kind INTO v_org, v_slug, v_kind
  FROM public.organizations o
  WHERE o.created_by = p_user
    AND o.kind IN ('artist', 'label')
    AND o.deleted_at IS NULL
  ORDER BY o.created_at, o.id
  LIMIT 1;
  IF FOUND THEN
    RETURN jsonb_build_object('org_id', v_org, 'slug', v_slug, 'kind', v_kind, 'created', false);
  END IF;

  v_base := coalesce(nullif(public.labelos_slugify(v_name), ''), CASE WHEN p_kind = 'label' THEN 'label' ELSE 'artist' END);

  -- organizations.slug is unique across every org (same loop as 137).
  LOOP
    v_slug := CASE WHEN v_try = 1 THEN v_base ELSE left(v_base, 35) || '-' || v_try END;
    IF NOT EXISTS (SELECT 1 FROM public.organizations WHERE slug = v_slug) THEN
      BEGIN
        INSERT INTO public.organizations (name, slug, kind, created_by, settings)
        VALUES (v_name, v_slug, p_kind, p_user, v_settings)
        RETURNING id INTO v_org;
        EXIT;
      EXCEPTION WHEN unique_violation THEN
        NULL; -- taken meanwhile: next candidate
      END;
    END IF;
    v_try := v_try + 1;
    IF v_try > 1000 THEN
      RAISE EXCEPTION 'no free organization slug for base %', v_base;
    END IF;
  END LOOP;

  INSERT INTO public.org_members (org_id, user_id, role, scope)
  VALUES (v_org, p_user, 'owner', 'org');

  RETURN jsonb_build_object('org_id', v_org, 'slug', v_slug, 'kind', p_kind, 'created', true);
END;
$fn$;

ALTER FUNCTION public.labelos_setup_org(uuid, text, text, jsonb) OWNER TO postgres;
REVOKE ALL ON FUNCTION public.labelos_setup_org(uuid, text, text, jsonb) FROM PUBLIC;
REVOKE ALL ON FUNCTION public.labelos_setup_org(uuid, text, text, jsonb) FROM anon, authenticated;
GRANT EXECUTE ON FUNCTION public.labelos_setup_org(uuid, text, text, jsonb) TO service_role;

NOTIFY pgrst, 'reload schema';


-- ═════════════ platform operator: the producer ═════════════
-- Chosen by the creator_profiles row, never by a typed email. The guard above
-- has already proved there is exactly one.
INSERT INTO public.platform_admins (user_id, note)
SELECT user_id, 'owner (producer)' FROM public.creator_profiles
ON CONFLICT DO NOTHING;

COMMIT;

-- ═════════════ check: every row must read 'applied' ═════════════
-- Read-only: which migrations of the Label OS go-live bundle are in effect on
-- this database (112-135 + 139_buyer_offer_email_verified from main's ledger,
-- then every Label OS migration 136-172, 189, 190, then the operator row).
-- Run it on its own any time; supabase/apply/labelos-go-live.sql also ends
-- with it. Every row must read 'applied'. Hand-maintained: one row per
-- migration, keyed on an object the migration creates (a table, column, trigger,
-- policy, or a marker in a redefined function's body).
SELECT m.migration,
       CASE WHEN m.ok THEN 'applied' ELSE 'MISSING' END AS status
FROM (VALUES
  ('112_backfill_buyer_contacts',    NOT EXISTS (
     SELECT 1 FROM public.license_purchases lp
     WHERE lp.status = 'paid' AND lp.seller_user_id IS NOT NULL AND lp.buyer_email IS NOT NULL
       AND lower(btrim(lp.buyer_email)) <> 'unknown@invalid' AND position('@' in lp.buyer_email) > 1
       AND NOT EXISTS (SELECT 1 FROM public.contacts c WHERE c.user_id = lp.seller_user_id AND lower(btrim(c.email)) = lower(btrim(lp.buyer_email))))),
  ('113_store_layout',               EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'creator_profiles' AND column_name = 'store_layout')),
  ('115_track_collaborators',        to_regclass('public.track_collaborators') IS NOT NULL),
  ('116_notifications_realtime',     EXISTS (SELECT 1 FROM pg_publication_tables WHERE pubname = 'supabase_realtime' AND schemaname = 'public' AND tablename = 'notifications')),
  ('121_share_full_playback',        EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'project_shares' AND column_name = 'full_playback')),
  ('122_project_contacts',           to_regclass('public.project_contacts') IS NOT NULL),
  ('123_contact_track_states',       to_regclass('public.contact_track_states') IS NOT NULL),
  ('124_song_beat_and_credit_links', EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'tracks' AND column_name = 'beat_track_id')),
  ('125_artist_portals',             to_regclass('public.artist_portals') IS NOT NULL),
  ('126_project_shares_contact',     EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'project_shares' AND column_name = 'contact_id')),
  ('127_project_assets',             to_regclass('public.project_assets') IS NOT NULL),
  ('128_portal_comments',            EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'project_comments' AND column_name = 'contact_id')),
  ('129_artist_portal_auto_digest',  EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'artist_portals' AND column_name = 'auto_digest')),
  ('130_artist_messages',            to_regclass('public.artist_messages') IS NOT NULL),
  ('131_portal_sign_in',             EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'artist_portals' AND column_name = 'require_sign_in')),
  ('132_song_beats',                 to_regclass('public.song_beats') IS NOT NULL),
  ('134_contact_secondary_role',     EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'contacts' AND column_name = 'secondary_category')),
  ('135_portal_pitch_note',          EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'project_contacts' AND column_name = 'pitch_note')),
  ('139_buyer_offer_email_verified', EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'buyer_offers' AND column_name = 'buyer_email_verified')),
  ('133_track_links',                to_regclass('public.track_links') IS NOT NULL
                                     AND pg_get_constraintdef((SELECT oid FROM pg_constraint WHERE conname = 'tracks_type_check' AND conrelid = 'public.tracks'::regclass)) LIKE '%topline%'
                                     AND (SELECT count(*) FROM pg_constraint WHERE conrelid = 'public.tracks'::regclass AND contype = 'c' AND pg_get_constraintdef(oid) LIKE '%instrumental%') = 1),
  ('136_labelos_org_core', to_regclass('public.organizations') IS NOT NULL AND to_regclass('public.org_members') IS NOT NULL AND to_regclass('public.org_invitations') IS NOT NULL AND to_regclass('public.user_profiles') IS NOT NULL AND to_regclass('public.activity_events') IS NOT NULL),
  ('137_labelos_producer_org', EXISTS (SELECT 1 FROM pg_proc p JOIN pg_namespace s ON s.oid = p.pronamespace WHERE s.nspname = 'public' AND p.proname = 'labelos_ensure_producer_org') AND NOT EXISTS (SELECT 1 FROM public.creator_profiles cp WHERE NOT EXISTS (SELECT 1 FROM public.organizations o WHERE o.kind = 'producer' AND o.created_by = cp.user_id))),
  ('138_labelos_invitation_accept', EXISTS (SELECT 1 FROM pg_proc p JOIN pg_namespace s ON s.oid = p.pronamespace WHERE s.nspname = 'public' AND p.proname = 'labelos_accept_invitation')),
  ('139_labelos_org_contacts', EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'contacts' AND column_name = 'org_id') AND to_regclass('public.member_artist_scopes') IS NOT NULL),
  ('140_labelos_song_fields', EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'tracks' AND column_name = 'song_stage') AND EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'tracks' AND column_name = 'iswc')),
  ('141_labelos_org_catalog', EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'tracks' AND column_name = 'org_id') AND EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'projects' AND column_name = 'org_id') AND EXISTS (SELECT 1 FROM pg_proc p JOIN pg_namespace s ON s.oid = p.pronamespace WHERE s.nspname = 'public' AND p.proname = 'can_read_org_track')),
  ('142_labelos_project_tracks_same_org', EXISTS (SELECT 1 FROM pg_trigger WHERE tgname = 'project_tracks_same_owner' AND NOT tgisinternal)),
  ('143_labelos_org_assets', EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'project_assets' AND column_name = 'org_id') AND EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'project_assets' AND column_name = 'sensitivity')),
  ('144_labelos_releases', to_regclass('public.releases') IS NOT NULL AND to_regclass('public.release_items') IS NOT NULL),
  ('145_labelos_ownerless_workspace_rows', EXISTS (SELECT 1 FROM pg_proc p JOIN pg_namespace s ON s.oid = p.pronamespace WHERE s.nspname = 'public' AND p.proname = 'artist_portals_same_owner')),
  ('146_labelos_audit_rpc', EXISTS (SELECT 1 FROM pg_proc p JOIN pg_namespace s ON s.oid = p.pronamespace WHERE s.nspname = 'public' AND p.proname = 'labelos_audit_member_remove')),
  ('147_labelos_activity_feeds', EXISTS (SELECT 1 FROM pg_policies WHERE schemaname = 'public' AND tablename = 'activity_events' AND policyname = 'activity_events_member_read')),
  ('148_labelos_project_members', to_regclass('public.project_members') IS NOT NULL),
  ('149_labelos_song_reviews', to_regclass('public.song_reviews') IS NOT NULL),
  ('150_labelos_org_comments', EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'project_comments' AND column_name = 'org_id') AND EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'project_comments' AND column_name = 'visibility')),
  ('151_labelos_tasks_notifications', to_regclass('public.tasks') IS NOT NULL AND EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'notifications' AND column_name = 'org_id')),
  ('152_labelos_creative_direction', to_regclass('public.artist_direction') IS NOT NULL AND to_regclass('public.artist_references') IS NOT NULL),
  ('153_labelos_parties_credits', to_regclass('public.parties') IS NOT NULL AND EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'track_collaborators' AND column_name = 'party_id')),
  ('154_labelos_artist_label_connection', to_regclass('public.org_connections') IS NOT NULL AND to_regclass('public.connection_projects') IS NOT NULL AND EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'tracks' AND column_name = 'provenance')),
  ('155_labelos_split_sheets', to_regclass('public.split_sheets') IS NOT NULL AND to_regclass('public.split_lines') IS NOT NULL),
  ('156_labelos_samples_declared', EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'tracks' AND column_name = 'samples_declared')),
  ('157_labelos_approvals', to_regclass('public.approvals') IS NOT NULL AND EXISTS (SELECT 1 FROM pg_proc p JOIN pg_namespace s ON s.oid = p.pronamespace WHERE s.nspname = 'public' AND p.proname = 'approvals_guard')),
  ('158_labelos_release_store_playback', EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'releases' AND column_name = 'store_playback') AND EXISTS (SELECT 1 FROM pg_trigger WHERE tgname = 'release_items_store_lock' AND NOT tgisinternal)),
  ('159_labelos_org_search', EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'tracks' AND column_name = 'search_tsv') AND EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'contacts' AND column_name = 'search_tsv') AND EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'projects' AND column_name = 'search_tsv')),
  ('160_labelos_weekly_digest', to_regclass('public.org_digest_members') IS NOT NULL AND to_regclass('public.org_digest_channels') IS NOT NULL),
  ('161_labelos_saved_views', to_regclass('public.org_saved_views') IS NOT NULL),
  ('162_labelos_split_sheets_column_grants', has_column_privilege('authenticated', 'public.split_sheets', 'circulated_at', 'SELECT') AND NOT has_table_privilege('authenticated', 'public.split_sheets', 'SELECT')),
  ('163_labelos_audit_events_immutable', EXISTS (SELECT 1 FROM pg_trigger WHERE tgname = 'activity_events_audit_immutable' AND NOT tgisinternal)),
  ('164_labelos_member_read_scope', EXISTS (SELECT 1 FROM pg_policies WHERE schemaname = 'public' AND tablename = 'org_members' AND policyname = 'org_members_member_read') AND EXISTS (SELECT 1 FROM pg_proc p JOIN pg_namespace s ON s.oid = p.pronamespace WHERE s.nspname = 'public' AND p.proname = 'labelos_my_live_orgs')),
  ('165_labelos_playlist_tracks_same_owner', EXISTS (SELECT 1 FROM pg_trigger WHERE tgname = 'playlist_tracks_same_owner' AND NOT tgisinternal)),
  ('166_labelos_one_artist_per_artist_org', EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'contacts' AND column_name = 'org_self_artist') AND EXISTS (SELECT 1 FROM pg_trigger WHERE tgname = 'contacts_org_self_artist' AND NOT tgisinternal)),
  ('167_labelos_release_items_lock_member_cas', EXISTS (SELECT 1 FROM pg_proc p JOIN pg_namespace s ON s.oid = p.pronamespace WHERE s.nspname = 'public' AND p.proname = 'labelos_release_item_update')),
  ('168_labelos_search_tokenization', EXISTS (SELECT 1 FROM pg_attribute a WHERE a.attrelid = 'public.tracks'::regclass AND a.attname = 'search_tsv' AND a.attgenerated = 's')),
  ('169_labelos_overview_seen_per_org', to_regclass('public.org_overview_seen') IS NOT NULL),
  ('170_labelos_entitlements_platform', to_regclass('public.platform_admins') IS NOT NULL AND to_regclass('public.org_entitlements') IS NOT NULL),
  ('171_labelos_departments_capabilities', EXISTS (SELECT 1 FROM pg_proc p JOIN pg_namespace s ON s.oid = p.pronamespace WHERE s.nspname = 'public' AND p.proname = 'has_org_cap' AND pg_get_functiondef(p.oid) LIKE '%finance.approve%')),
  ('172_labelos_org_settings', EXISTS (SELECT 1 FROM pg_proc p JOIN pg_namespace s ON s.oid = p.pronamespace WHERE s.nspname = 'public' AND p.proname = 'labelos_audit_org_settings')),
  ('173_labelos_track_metadata', EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'tracks' AND column_name = 'metadata_updated_at')),
  ('189_labelos_setup_org', EXISTS (SELECT 1 FROM pg_proc p JOIN pg_namespace s ON s.oid = p.pronamespace WHERE s.nspname = 'public' AND p.proname = 'labelos_setup_org')),
  ('190_labelos_team_accounts', to_regclass('public.org_managed_accounts') IS NOT NULL AND EXISTS (SELECT 1 FROM pg_proc p JOIN pg_namespace s ON s.oid = p.pronamespace WHERE s.nspname = 'public' AND p.proname = 'labelos_revoke_auth_sessions')),
  ('192_labelos_setup_wizard', EXISTS (SELECT 1 FROM pg_proc p JOIN pg_namespace s ON s.oid = p.pronamespace WHERE s.nspname = 'public' AND p.proname = 'labelos_validate_org_settings_patch')),
  ('operator: producer is a platform admin', EXISTS (SELECT 1 FROM public.creator_profiles) AND NOT EXISTS (SELECT 1 FROM public.creator_profiles cp WHERE NOT EXISTS (SELECT 1 FROM public.platform_admins pa WHERE pa.user_id = cp.user_id)))
) AS m(migration, ok)
ORDER BY m.migration;
